import React from 'react';
import { Tab } from '../types';
import { CandlestickChart, Briefcase, List, Wallet } from 'lucide-react';

interface BottomNavProps {
  currentTab: Tab;
  onTabChange: (tab: Tab) => void;
  ordersCount: number;
  positionsCount: number;
}

export const BottomNav: React.FC<BottomNavProps> = ({ currentTab, onTabChange, ordersCount, positionsCount }) => {
  const navItems = [
    { id: Tab.TRADE, label: 'Trade', icon: CandlestickChart },
    { id: Tab.POSITIONS, label: 'Positions', icon: Briefcase, count: positionsCount },
    { id: Tab.ORDERS, label: 'Orders', icon: List, count: ordersCount },
    { id: Tab.ACCOUNT, label: 'Assets', icon: Wallet },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-slate-900 border-t border-slate-800 safe-area-bottom z-50">
      <div className="flex justify-around items-center h-16 max-w-md mx-auto">
        {navItems.map((item) => {
          const isActive = currentTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id)}
              className="relative flex flex-col items-center justify-center w-full h-full space-y-1"
            >
              <item.icon 
                size={22} 
                className={`transition-colors duration-200 ${isActive ? 'text-indigo-400' : 'text-slate-500'}`} 
              />
              <span className={`text-[10px] font-medium transition-colors duration-200 ${isActive ? 'text-indigo-400' : 'text-slate-500'}`}>
                {item.label}
              </span>
              {item.count ? (
                <span className="absolute top-2 right-4 min-w-[16px] h-4 flex items-center justify-center bg-rose-500 text-white text-[9px] font-bold rounded-full px-1 border border-slate-900">
                  {item.count}
                </span>
              ) : null}
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Tab, Side, Position, Order, Candle } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);

  // Market Data State
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50));
  const [currentPrice, setCurrentPrice] = useState<number>(candles[candles.length - 1].close);

  // User Data State
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // Simulation Loop
  useEffect(() => {
    const interval = setInterval(() => {
      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const now = new Date();
        const lastTime = new Date();
        // Simple mock: If same minute, update last candle, else new candle (simplified to update every tick for demo visual)

        const volatility = 0.8; // USD movement
        const move = (Math.random() - 0.5) * volatility;
        const newPrice = Math.max(0.01, lastCandle.close + move);

        setCurrentPrice(newPrice); // Update global current price

        // Update positions PnL visual doesn't change state but calculation relies on this price

        const updatedLastCandle = {
          ...lastCandle,
          close: newPrice,
          high: Math.max(lastCandle.high, newPrice),
          low: Math.min(lastCandle.low, newPrice)
        };

        // Very simple logic: every 10 ticks create new candle to make graph move
        if (Math.random() > 0.95) {
           const newCandle: Candle = {
             time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
             open: newPrice,
             close: newPrice,
             high: newPrice,
             low: newPrice
           };
           return [...prevCandles.slice(1), newCandle];
        } else {
           return [...prevCandles.slice(0, -1), updatedLastCandle];
        }
      });
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  // Trading Logic
  const handlePlaceOrder = (side: Side, size: number, price: number) => {
    // Immediate execution for Market Orders (simplification)
    const requiredMargin = (price * size) / 20; // Assuming 20x fixed for logic simplicity in root

    if (requiredMargin > balance) {
      alert("Insufficient Balance");
      return;
    }

    setBalance(prev => prev - requiredMargin); // Deduct margin from available balance

    const newPosition: Position = {
      id: Date.now().toString(),
      symbol: SYMBOL,
      side,
      size,
      entryPrice: price,
      leverage: 20,
      unrealizedPnL: 0
    };

    setPositions(prev => [newPosition, ...prev]);
    // Switch to positions tab for better UX
    // setActiveTab(Tab.POSITIONS); 
  };

  const handleClosePosition = (id: string) => {
    const position = positions.find(p => p.id === id);
    if (!position) return;

    const priceDiff = currentPrice - position.entryPrice;
    const pnl = position.side === Side.LONG ? priceDiff * position.size : -priceDiff * position.size;
    const margin = (position.entryPrice * position.size) / position.leverage;

    setBalance(prev => prev + margin + pnl);
    setPositions(prev => prev.filter(p => p.id !== id));
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => prev.filter(o => o.id !== id));
  };

  // Calculate Equity
  const totalUnrealizedPnL = positions.reduce((acc, pos) => {
    const diff = currentPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? diff * pos.size : -diff * pos.size;
    return acc + pnl;
  }, 0);

  // Margin locked in positions needs to be considered for "Balance" definition
  // Here: Balance = Available Cash. Equity = Balance + Margin + PnL.
  // When opening position, we deducted margin from Balance.
  // So Equity = Balance + MarginLocked + PnL.
  const marginLocked = positions.reduce((acc, pos) => acc + ((pos.entryPrice * pos.size) / pos.leverage), 0);
  const equity = balance + marginLocked + totalUnrealizedPnL;

  return (
    <div className="bg-slate-900 min-h-screen text-slate-100 font-sans max-w-md mx-auto border-x border-slate-800 shadow-2xl overflow-hidden relative">

      {/* Main Content Area */}
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance}
            onPlaceOrder={handlePlaceOrder}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView 
            positions={positions} 
            currentPrice={currentPrice} 
            onClosePosition={handleClosePosition}
          />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView 
            orders={orders} 
            onCancelOrder={handleCancelOrder}
          />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView 
            balance={balance}
            equity={equity}
          />
        )}
      </main>

      {/* Navigation */}
      <BottomNav 
        currentTab={activeTab} 
        onTabChange={setActiveTab} 
        ordersCount={orders.length}
        positionsCount={positions.length}
      />
    </div>
  );
};

export default App;

