import React, { useState, useEffect } from 'react';
import { Sparkles, Settings2 } from 'lucide-react';
import { CandleChart } from './CandleChart';
import { OrderBook } from './OrderBook';
import { Candle, Side, MarginMode } from '../types';
import { analyzeMarket } from '../services/geminiService';

interface TradeViewProps {
  candles: Candle[];
  currentPrice: number;
  balance: number;
  onPlaceOrder: (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => void;
}

export const TradeView: React.FC<TradeViewProps> = ({ candles, currentPrice, balance, onPlaceOrder }) => {
  const [orderType, setOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [amount, setAmount] = useState<string>('1.00');
  const [limitPrice, setLimitPrice] = useState<string>(currentPrice.toFixed(2));
  const [leverage, setLeverage] = useState<number>(20);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Update limit price default when switching to limit if empty, but usually keep it static if user typed
  useEffect(() => {
    if (orderType === 'LIMIT' && !limitPrice) {
      setLimitPrice(currentPrice.toFixed(2));
    }
  }, [currentPrice, orderType]);

  const handleTrade = (side: Side) => {
    const size = parseFloat(amount);
    const price = orderType === 'LIMIT' ? parseFloat(limitPrice) : currentPrice;

    if (isNaN(size) || size <= 0) return;
    if (orderType === 'LIMIT' && (isNaN(price) || price <= 0)) return;

    onPlaceOrder(side, size, price, orderType, marginMode);
  };

  const runAnalysis = async () => {
    setIsAnalyzing(true);
    setAiAnalysis("Analyzing market structure...");
    try {
      const result = await analyzeMarket(candles, currentPrice);
      setAiAnalysis(result);
    } catch (e) {
      setAiAnalysis("Analysis failed.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const executionPrice = orderType === 'LIMIT' ? parseFloat(limitPrice) || currentPrice : currentPrice;
  const maxBuy = (balance * leverage) / executionPrice;

  return (
    <div className="flex flex-col h-full pb-20 overflow-y-auto no-scrollbar bg-slate-900">
      {/* Header */}
      <div className="px-4 py-3 flex justify-between items-center border-b border-slate-800 bg-slate-900 sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-yellow-500/20 flex items-center justify-center border border-yellow-500/30">
            <span className="text-yellow-500 font-bold text-xs">XAU</span>
          </div>
          <div>
            <h1 className="text-lg font-bold text-white leading-tight">XAU/USDC</h1>
            <span className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">Perpetual</span>
          </div>
        </div>
        <div className="text-right">
          <div className={`text-lg font-mono font-bold ${candles[candles.length-1]?.close >= candles[0]?.open ? 'text-emerald-400' : 'text-rose-400'}`}>
            {currentPrice.toFixed(2)}
          </div>
          <div className="text-[10px] text-slate-400">Mark Price</div>
        </div>
      </div>

      {/* Chart */}
      <div className="relative border-b border-slate-800 bg-slate-900">
        <CandleChart data={candles} />
        <button 
          onClick={runAnalysis}
          disabled={isAnalyzing}
          className="absolute top-2 left-2 flex items-center gap-1.5 px-3 py-1.5 bg-indigo-600/90 hover:bg-indigo-500 text-white text-[10px] font-bold uppercase tracking-wider rounded-full shadow-lg backdrop-blur transition-all border border-indigo-500/50"
        >
          <Sparkles size={10} className={isAnalyzing ? "animate-pulse" : ""} />
          {isAnalyzing ? "AI Thinking..." : "AI Insight"}
        </button>
        {aiAnalysis && (
            <div className="absolute top-12 left-2 right-12 bg-slate-800/95 backdrop-blur-md border border-slate-700 p-3 rounded-lg text-xs text-slate-200 shadow-xl z-20 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-start mb-2 border-b border-slate-700 pb-2">
                 <span className="font-bold text-indigo-400 flex items-center gap-1">
                   <Sparkles size={12} /> Gemini Analysis
                 </span>
                 <button onClick={() => setAiAnalysis(null)} className="text-slate-500 hover:text-white p-1">×</button>
               </div>
               <p className="leading-relaxed opacity-90">{aiAnalysis}</p>
            </div>
        )}
      </div>

      {/* Order Book */}
      <OrderBook currentPrice={currentPrice} />

      {/* Order Controls */}
      <div className="p-4 space-y-4 bg-slate-900">

        {/* Margin Mode & Order Type Row */}
        <div className="flex gap-2">
            <div className="relative">
                <select 
                    value={marginMode}
                    onChange={(e) => setMarginMode(e.target.value as MarginMode)}
                    className="appearance-none bg-slate-800 text-xs font-bold text-white py-2 pl-3 pr-8 rounded-lg border border-slate-700 focus:outline-none focus:border-indigo-500 h-full"
                >
                    <option value={MarginMode.CROSS}>Cross</option>
                    <option value={MarginMode.ISOLATED}>Isolated</option>
                </select>
                <Settings2 size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            <div className="flex-1 flex bg-slate-800 rounded-lg p-1">
                <button 
                    onClick={() => setOrderType('MARKET')}
                    className={`flex-1 py-1 text-xs font-bold rounded transition-all ${orderType === 'MARKET' ? 'bg-slate-600 text-white shadow' : 'text-slate-400 hover:text-slate-300'}`}
                >
                    Market
                </button>
                <button 
                    onClick={() => {
                        setOrderType('LIMIT');
                        setLimitPrice(currentPrice.toFixed(2));
                    }}
                    className={`flex-1 py-1 text-xs font-bold rounded transition-all ${orderType === 'LIMIT' ? 'bg-slate-600 text-white shadow' : 'text-slate-400 hover:text-slate-300'}`}
                >
                    Limit
                </button>
            </div>
        </div>

        {/* Leverage Slider */}
        <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-800">
          <div className="flex justify-between text-xs text-slate-400 mb-2">
            <span>Leverage</span>
            <span className="text-white font-mono">{leverage}x</span>
          </div>
          <input 
            type="range" 
            min="1" 
            max="100" 
            step="1" 
            value={leverage} 
            onChange={(e) => setLeverage(parseInt(e.target.value))}
            className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
          />
          <div className="flex justify-between text-[10px] text-slate-500 mt-1 font-mono">
            <span>1x</span>
            <span>20x</span>
            <span>50x</span>
            <span>100x</span>
          </div>
        </div>

        {/* Inputs */}
        <div className="grid grid-cols-2 gap-4">

          {/* Price Input (Only for Limit) */}
          {orderType === 'LIMIT' && (
            <div className="col-span-2">
              <div className="relative group">
                  <label className="absolute -top-2 left-2 bg-slate-900 px-1 text-[10px] text-slate-400 group-focus-within:text-indigo-400 transition-colors">Price (USDC)</label>
                  <input 
                    type="number" 
                    value={limitPrice}
                    onChange={(e) => setLimitPrice(e.target.value)}
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg py-3 px-4 text-white font-mono focus:outline-none focus:border-indigo-500 transition-colors"
                  />
              </div>
            </div>
          )}

          {/* Amount Input */}
          <div className="col-span-2">
             <div className="relative group">
                <label className="absolute -top-2 left-2 bg-slate-900 px-1 text-[10px] text-slate-400 group-focus-within:text-indigo-400 transition-colors">Size (XAU)</label>
                <input 
                  type="number" 
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg py-3 px-4 text-white font-mono focus:outline-none focus:border-indigo-500 transition-colors"
                />
                <span className="absolute right-4 top-3.5 text-xs text-slate-500 font-mono">
                  ≈ ${(parseFloat(amount || '0') * executionPrice).toLocaleString()}
                </span>
             </div>
             <div className="flex justify-between text-[10px] text-slate-500 mt-1 px-1">
               <span>Max Buy: {maxBuy.toFixed(2)} XAU</span>
               <span>Avail: ${balance.toFixed(2)}</span>
             </div>
          </div>
        </div>

        {/* Buttons */}
        <div className="grid grid-cols-2 gap-3 mt-4">
          <button 
            onClick={() => handleTrade(Side.LONG)}
            className="flex flex-col items-center justify-center py-3 rounded-lg bg-emerald-600 active:bg-emerald-700 text-white shadow-lg shadow-emerald-900/20 transition-transform active:scale-95"
          >
            <span className="font-bold text-sm">Buy / Long</span>
            <span className="text-[10px] opacity-80 font-mono">
               {orderType === 'LIMIT' ? `@ ${parseFloat(limitPrice).toFixed(2)}` : 'Market'}
            </span>
          </button>
          <button 
            onClick={() => handleTrade(Side.SHORT)}
            className="flex flex-col items-center justify-center py-3 rounded-lg bg-rose-600 active:bg-rose-700 text-white shadow-lg shadow-rose-900/20 transition-transform active:scale-95"
          >
            <span className="font-bold text-sm">Sell / Short</span>
            <span className="text-[10px] opacity-80 font-mono">
               {orderType === 'LIMIT' ? `@ ${parseFloat(limitPrice).toFixed(2)}` : 'Market'}
            </span>
          </button>
        </div>

        {/* Info */}
        <div className="bg-slate-800/30 rounded-lg p-3 text-xs space-y-2 border border-slate-800/50">
          <div className="flex justify-between">
             <span className="text-slate-500">Mode</span>
             <span className="text-indigo-400 font-mono font-bold uppercase">{marginMode}</span>
          </div>
          <div className="flex justify-between">
             <span className="text-slate-500">Liquidation Price (Est)</span>
             <span className="text-orange-400 font-mono">
               {amount ? (parseFloat(amount) > 0 ? (executionPrice * (1 - 1/leverage)).toFixed(2) : '--') : '--'}
             </span>
          </div>
          <div className="flex justify-between">
             <span className="text-slate-500">Margin Required</span>
             <span className="text-slate-200 font-mono">
                ${amount ? ((parseFloat(amount) * executionPrice) / leverage).toFixed(2) : '0.00'}
             </span>
          </div>
        </div>

      </div>
    </div>
  );
};

import React from 'react';
import { Position, Side, MarginMode } from '../types';
import { TrendingUp, TrendingDown, AlertTriangle } from 'lucide-react';

interface PositionsViewProps {
  positions: Position[];
  currentPrice: number;
  equity: number;
  maintenanceMargin: number;
  marginRatio: number;
  onClosePosition: (id: string) => void;
}

export const PositionsView: React.FC<PositionsViewProps> = ({ 
  positions, 
  currentPrice, 
  equity,
  maintenanceMargin,
  marginRatio,
  onClosePosition 
}) => {

  // Risk Dashboard
  const renderRiskHeader = () => (
    <div className="bg-slate-800/50 border-b border-slate-800 p-4 sticky top-0 backdrop-blur-md z-10">
      <div className="grid grid-cols-3 gap-2">
        <div className="bg-slate-800 rounded-lg p-2 border border-slate-700">
           <div className="text-[10px] text-slate-500 mb-1">Margin Ratio</div>
           <div className={`font-mono font-bold text-sm ${marginRatio > 80 ? 'text-rose-500' : 'text-emerald-400'}`}>
             {marginRatio.toFixed(2)}%
           </div>
        </div>
        <div className="bg-slate-800 rounded-lg p-2 border border-slate-700">
           <div className="text-[10px] text-slate-500 mb-1">Maint. Margin</div>
           <div className="font-mono font-bold text-sm text-slate-200">
             ${maintenanceMargin.toFixed(2)}
           </div>
        </div>
        <div className="bg-slate-800 rounded-lg p-2 border border-slate-700">
           <div className="text-[10px] text-slate-500 mb-1">Margin Bal.</div>
           <div className="font-mono font-bold text-sm text-slate-200">
             ${equity.toFixed(2)}
           </div>
        </div>
      </div>
      {marginRatio > 80 && (
         <div className="flex items-center gap-2 mt-3 text-rose-500 text-xs bg-rose-500/10 p-2 rounded-lg border border-rose-500/20">
           <AlertTriangle size={14} />
           <span>Warning: High liquidation risk!</span>
         </div>
      )}
    </div>
  );

  if (positions.length === 0) {
    return (
      <div className="h-full flex flex-col">
        {renderRiskHeader()}
        <div className="flex-1 flex flex-col items-center justify-center text-slate-500">
          <div className="bg-slate-800 p-4 rounded-full mb-4">
             <TrendingUp size={32} className="opacity-50" />
          </div>
          <p>No active positions</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col bg-slate-900">
      {renderRiskHeader()}
      <div className="flex-1 p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar">
        <h2 className="text-slate-400 text-xs uppercase font-bold tracking-wider mb-2">Open Positions ({positions.length})</h2>
        {positions.map((pos) => {
          // Calculate dynamic PnL for display
          const priceDiff = currentPrice - pos.entryPrice;
          const pnl = pos.side === Side.LONG ? priceDiff * pos.size : -priceDiff * pos.size;
          const initialMargin = (pos.entryPrice * pos.size) / pos.leverage;
          const pnlPercent = (pnl / initialMargin) * 100;
          const isProfit = pnl >= 0;

          return (
            <div key={pos.id} className="bg-slate-800 border border-slate-700 rounded-xl p-4 shadow-sm">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded ${pos.side === Side.LONG ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                    {pos.side === Side.LONG ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                  </div>
                  <div>
                    <h3 className="font-bold text-white flex items-center gap-2">
                      {pos.symbol}
                      <span className="text-[9px] bg-slate-700 text-slate-300 px-1.5 py-0.5 rounded uppercase font-normal tracking-wide border border-slate-600">
                        {pos.marginMode === MarginMode.ISOLATED ? 'Isolated' : 'Cross'}
                      </span>
                    </h3>
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 inline-block ${pos.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                      {pos.leverage}x {pos.side}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-lg font-mono font-bold ${isProfit ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {isProfit ? '+' : ''}{pnl.toFixed(2)}
                  </div>
                  <div className={`text-xs ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {isProfit ? '+' : ''}{pnlPercent.toFixed(2)}%
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-y-2 text-xs mb-4">
                <div className="text-slate-400">Size (XAU)</div>
                <div className="text-right text-slate-200 font-mono">{pos.size.toFixed(4)}</div>

                <div className="text-slate-400">Entry Price</div>
                <div className="text-right text-slate-200 font-mono">{pos.entryPrice.toFixed(2)}</div>

                <div className="text-slate-400">Mark Price</div>
                <div className="text-right text-slate-200 font-mono">{currentPrice.toFixed(2)}</div>

                <div className="text-slate-400">Margin</div>
                <div className="text-right text-slate-200 font-mono">{initialMargin.toFixed(2)}</div>
              </div>

              <button 
                onClick={() => onClosePosition(pos.id)}
                className="w-full py-2.5 bg-slate-700 hover:bg-slate-600 active:bg-slate-600 rounded-lg text-sm font-medium text-slate-200 transition-colors flex items-center justify-center gap-2"
              >
                Close Position
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

