import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, TradeRecord, TransferRecord, MarginMode } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);

  // Auth State
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);

  // Market Data State
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50));
  const [currentPrice, setCurrentPrice] = useState<number>(candles[candles.length - 1].close);

  // User Data State
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // History State
  const [tradeHistory, setTradeHistory] = useState<TradeRecord[]>([]);
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([]);

  // Simulation Loop: Market Data & Limit Order Matching
  useEffect(() => {
    const interval = setInterval(() => {
      // 1. Update Candles & Price
      let newPrice = currentPrice;

      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const now = new Date();

        const volatility = 0.8; // USD movement per tick
        const move = (Math.random() - 0.5) * volatility;
        newPrice = Math.max(0.01, lastCandle.close + move);

        // Update High/Low of last candle
        const updatedLastCandle = {
          ...lastCandle,
          close: newPrice,
          high: Math.max(lastCandle.high, newPrice),
          low: Math.min(lastCandle.low, newPrice)
        };

        // 5% chance to start a new candle
        if (Math.random() > 0.95) {
           const newCandle: Candle = {
             time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
             open: newPrice,
             close: newPrice,
             high: newPrice,
             low: newPrice
           };
           return [...prevCandles.slice(1), newCandle];
        } else {
           return [...prevCandles.slice(0, -1), updatedLastCandle];
        }
      });

      setCurrentPrice(newPrice);

      // 2. Check Limit Orders for Execution
      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;

        prevOrders.forEach(order => {
          let executed = false;
          // Buy Limit: Fill if current price <= limit price
          if (order.side === Side.LONG && newPrice <= order.price) {
            executed = true;
          }
          // Sell Limit: Fill if current price >= limit price
          else if (order.side === Side.SHORT && newPrice >= order.price) {
            executed = true;
          }

          if (executed) {
            ordersExecuted = true;
            // Create Position
            // Note: Margin was already deducted from balance when order was placed.
            const newPosition: Position = {
              id: Date.now().toString() + Math.random(),
              symbol: SYMBOL,
              side: order.side,
              size: order.amount,
              entryPrice: order.price, // Fill at Limit Price for simplicity
              leverage: 20, // Hardcoded for this demo matching the creation
              unrealizedPnL: 0,
              marginMode: order.marginMode
            };
            setPositions(prev => [newPosition, ...prev]);
            // Optional: Notify user
            console.log(`Order ${order.id} executed at ${newPrice}`);
          } else {
            remainingOrders.push(order);
          }
        });

        return ordersExecuted ? remainingOrders : prevOrders;
      });

    }, 1000);

    return () => clearInterval(interval);
  }, [currentPrice]); // Dependency on currentPrice ensures loop has latest price reference.

  // Trading Logic
  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) {
      alert("Please connect your wallet in the Assets tab first.");
      setActiveTab(Tab.ACCOUNT);
      return;
    }

    const leverage = 20; // Fixed for demo
    const requiredMargin = (price * size) / leverage; 

    if (requiredMargin > balance) {
      alert("Insufficient Balance");
      return;
    }

    // Deduct margin immediately (Frozen for Limit, Used for Position)
    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPosition: Position = {
        id: Date.now().toString(),
        symbol: SYMBOL,
        side,
        size,
        entryPrice: price,
        leverage,
        unrealizedPnL: 0,
        marginMode
      };
      setPositions(prev => [newPosition, ...prev]);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: SYMBOL,
        side,
        type: 'LIMIT',
        price,
        amount: size,
        timestamp: Date.now(),
        marginMode
      };
      setOrders(prev => [newOrder, ...prev]);
      // Optional: switch to Orders tab or show toast
    }
  };

  const handleClosePosition = (id: string) => {
    const position = positions.find(p => p.id === id);
    if (!position) return;

    const priceDiff = currentPrice - position.entryPrice;
    const pnl = position.side === Side.LONG ? priceDiff * position.size : -priceDiff * position.size;
    const margin = (position.entryPrice * position.size) / position.leverage;

    setBalance(prev => prev + margin + pnl);

    // Add to history
    const record: TradeRecord = {
      id: position.id,
      symbol: position.symbol,
      side: position.side,
      size: position.size,
      entryPrice: position.entryPrice,
      closePrice: currentPrice,
      pnl: pnl,
      timestamp: Date.now()
    };
    setTradeHistory(prev => [record, ...prev]);

    setPositions(prev => prev.filter(p => p.id !== id));
  };

  const handleCancelOrder = (id: string) => {
    const order = orders.find(o => o.id === id);
    if (!order) return;

    // Refund frozen margin
    const leverage = 20;
    const margin = (order.price * order.amount) / leverage;
    setBalance(prev => prev + margin);

    setOrders(prev => prev.filter(o => o.id !== id));
  };

  const handleDeposit = (amount: number) => {
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{
      id: Date.now().toString(),
      type: 'DEPOSIT',
      amount,
      timestamp: Date.now(),
      status: 'COMPLETED'
    }, ...prev]);
  };

  const handleWithdraw = (amount: number) => {
    if (balance < amount) return false;
    setBalance(prev => prev - amount);
    setTransferHistory(prev => [{
      id: Date.now().toString(),
      type: 'WITHDRAW',
      amount,
      timestamp: Date.now(),
      status: 'COMPLETED'
    }, ...prev]);
    return true;
  };

  // Calculate Equity
  // Equity = Available Balance + Margin (Locked in Orders + Locked in Positions) + Unrealized PnL
  const posMargin = positions.reduce((acc, pos) => acc + ((pos.entryPrice * pos.size) / pos.leverage), 0);
  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0); // Assuming 20x

  const totalUnrealizedPnL = positions.reduce((acc, pos) => {
    const diff = currentPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? diff * pos.size : -diff * pos.size;
    return acc + pnl;
  }, 0);

  const equity = balance + posMargin + orderMargin + totalUnrealizedPnL;

  // Calculate Risk Metrics for Positions View
  // Maintenance Margin: Assuming 1% of total position value for simplicity
  const totalPositionValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPositionValue * 0.01; 
  // Margin Ratio: Maintenance Margin / Margin Balance (Equity)
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;


  return (
    <div className="bg-slate-900 min-h-screen text-slate-100 font-sans max-w-md mx-auto border-x border-slate-800 shadow-2xl overflow-hidden relative">

      {/* Main Content Area */}
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance}
            onPlaceOrder={handlePlaceOrder}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView 
            positions={positions} 
            currentPrice={currentPrice}
            equity={equity}
            maintenanceMargin={maintenanceMargin}
            marginRatio={marginRatio}
            onClosePosition={handleClosePosition}
          />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView 
            orders={orders} 
            onCancelOrder={handleCancelOrder}
          />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView 
            balance={balance}
            equity={equity}
            tradeHistory={tradeHistory}
            transferHistory={transferHistory}
            onDeposit={handleDeposit}
            onWithdraw={handleWithdraw}
            isConnected={isWalletConnected}
            onConnect={() => setIsWalletConnected(true)}
            onDisconnect={() => setIsWalletConnected(false)}
          />
        )}
      </main>

      {/* Navigation */}
      <BottomNav 
        currentTab={activeTab} 
        onTabChange={setActiveTab} 
        ordersCount={orders.length}
        positionsCount={positions.length}
      />
    </div>
  );
};

export default App;

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number; // Specific margin for isolated positions
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

export interface TradeRecord {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  closePrice: number;
  pnl: number;
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING';
}

export interface FundingRecord {
  id: string;
  symbol: string;
  rate: number;
  amount: number;
  timestamp: number;
}

