          <Shield size={100} />
        </div>
        <div className="relative z-10">
          <p className="text-indigo-200 text-sm mb-1">{t.totalEquity} (USD)</p>
          <h1 className="text-3xl font-mono font-bold tracking-tight mb-4">${equity.toFixed(2)}</h1>

          <div className="flex gap-4 border-t border-white/10 pt-4">
             <div>
                <p className="text-indigo-200 text-xs">{t.avail} Balance</p>
                <p className="font-mono font-medium">${balance.toFixed(2)}</p>
             </div>
             <div>
                <p className="text-indigo-200 text-xs">{t.unrealizedPnL}</p>
                <p className={`font-mono font-medium ${(equity - balance) >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>
                  {(equity - balance) >= 0 ? '+' : ''}{(equity - balance).toFixed(2)}
                </p>
