import React, { useState } from 'react';
import { Position, Side, MarginMode, Language } from '../types';
import { TrendingUp, TrendingDown, AlertTriangle, Plus, Minus, X } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface PositionsViewProps {
  positions: Position[];
  currentPrice: number;
  equity: number;
  maintenanceMargin: number;
  marginRatio: number;
  onClosePosition: (id: string) => void;
  onUpdateMargin: (id: string, amount: number, type: 'ADD' | 'REMOVE') => void;
  lang: Language;
}

export const PositionsView: React.FC<PositionsViewProps> = ({ 
  positions, 
  currentPrice, 
  equity,
  maintenanceMargin,
  marginRatio,
  onClosePosition,
  onUpdateMargin,
  lang
}) => {
  const t = TRANSLATIONS[lang];
  const [editingPosId, setEditingPosId] = useState<string | null>(null);
  const [marginAction, setMarginAction] = useState<'ADD' | 'REMOVE'>('ADD');
  const [marginInput, setMarginInput] = useState<string>('');

  const handleConfirmMargin = () => {
    if (editingPosId && marginInput) {
        onUpdateMargin(editingPosId, parseFloat(marginInput), marginAction);
        setEditingPosId(null);
        setMarginInput('');
    }
  };

  // Risk Dashboard
  const renderRiskHeader = () => (
    <div className="dark:bg-slate-800/50 bg-white/80 border-b dark:border-slate-800 border-slate-200 p-4 sticky top-0 backdrop-blur-md z-10">
      <div className="grid grid-cols-3 gap-2">
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginRatio}</div>
           <div className={`font-mono font-bold text-sm ${marginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>
             {marginRatio.toFixed(2)}%
           </div>
        </div>
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.maintMargin}</div>
           <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">
             ${maintenanceMargin.toFixed(2)}
           </div>
        </div>
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginBal}</div>
           <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">
             ${equity.toFixed(2)}
           </div>
        </div>
      </div>
      {marginRatio > 80 && (
         <div className="flex items-center gap-2 mt-3 text-rose-500 text-xs bg-rose-500/10 p-2 rounded-lg border border-rose-500/20">
           <AlertTriangle size={14} />
           <span>{t.riskWarning}</span>
         </div>
      )}
    </div>
  );

  if (positions.length === 0) {
    return (
      <div className="h-full flex flex-col">
        {renderRiskHeader()}
        <div className="flex-1 flex flex-col items-center justify-center dark:text-slate-500 text-slate-400">
          <div className="dark:bg-slate-800 bg-white p-4 rounded-full mb-4 shadow-sm border dark:border-slate-700 border-slate-200">
             <TrendingUp size={32} className="opacity-50" />
          </div>
          <p>{t.noPositions}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col dark:bg-slate-900 bg-slate-50 relative">
      {renderRiskHeader()}
      <div className="flex-1 p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar">
        <h2 className="dark:text-slate-400 text-slate-500 text-xs uppercase font-bold tracking-wider mb-2">{t.openPositions} ({positions.length})</h2>
        {positions.map((pos) => {
          // Calculate dynamic PnL for display
          const priceDiff = currentPrice - pos.entryPrice;
          const pnl = pos.side === Side.LONG ? priceDiff * pos.size : -priceDiff * pos.size;

          let marginUsed = 0;
          let liquidationPrice = 0;

          if (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) {
             marginUsed = pos.isolatedMargin;
             // Liq Price logic for Isolated:
             // Long: Entry - (Margin / Size)
             // Short: Entry + (Margin / Size)
             if (pos.side === Side.LONG) {
                liquidationPrice = pos.entryPrice - (marginUsed / pos.size);
             } else {
                liquidationPrice = pos.entryPrice + (marginUsed / pos.size);
             }
          } else {
             marginUsed = (pos.entryPrice * pos.size) / pos.leverage;
             // Standard approximate cross liq (simplified)
             if (pos.side === Side.LONG) liquidationPrice = pos.entryPrice * (1 - 1/pos.leverage);
             else liquidationPrice = pos.entryPrice * (1 + 1/pos.leverage);
          }

          const pnlPercent = (pnl / marginUsed) * 100;
          const isProfit = pnl >= 0;

          return (
            <div key={pos.id} className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded ${pos.side === Side.LONG ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                    {pos.side === Side.LONG ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                  </div>
                  <div>
                    <h3 className="font-bold dark:text-white text-slate-900 flex items-center gap-2">
                      {pos.symbol}
                      <span className="text-[9px] dark:bg-slate-700 bg-slate-200 dark:text-slate-300 text-slate-600 px-1.5 py-0.5 rounded uppercase font-normal tracking-wide border dark:border-slate-600 border-slate-300">
                        {pos.marginMode === MarginMode.ISOLATED ? t.isolated : t.cross}
                      </span>
                    </h3>
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 inline-block ${pos.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                      {pos.leverage}x {pos.side === Side.LONG ? t.long.split('/')[1] : t.short.split('/')[1]}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-lg font-mono font-bold ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {isProfit ? '+' : ''}{pnl.toFixed(2)}
                  </div>
                  <div className={`text-xs ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {isProfit ? '+' : ''}{pnlPercent.toFixed(2)}%
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-y-2 text-xs mb-4">
                <div className="dark:text-slate-400 text-slate-500">{t.size} (XAU)</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.size.toFixed(4)}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.price}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.entryPrice.toFixed(2)}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.liqPrice}</div>
                <div className="text-right text-orange-500 font-mono font-bold">{liquidationPrice > 0 ? liquidationPrice.toFixed(2) : '0.00'}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.margin}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono flex items-center justify-end gap-2">
                    {marginUsed.toFixed(2)}
                    {pos.marginMode === MarginMode.ISOLATED && (
                        <button 
                            onClick={() => { setEditingPosId(pos.id); setMarginAction('ADD'); }}
                            className="bg-indigo-500/20 text-indigo-500 p-0.5 rounded hover:bg-indigo-500/30"
                        >
                            <Plus size={10} />
                        </button>
                    )}
                </div>
              </div>

              <button 
                onClick={() => onClosePosition(pos.id)}
                className="w-full py-2.5 dark:bg-slate-700 bg-slate-100 dark:hover:bg-slate-600 hover:bg-slate-200 active:bg-slate-200 rounded-lg text-sm font-medium dark:text-slate-200 text-slate-700 transition-colors flex items-center justify-center gap-2"
              >
                {t.closePos}
              </button>
            </div>
          );
        })}
      </div>

      {/* Margin Modal */}
      {editingPosId && (
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4 animate-in fade-in duration-200">
             <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-2xl p-4 shadow-2xl animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg dark:text-white text-slate-900">{t.addMargin}</h3>
                    <button onClick={() => setEditingPosId(null)} className="dark:text-slate-400 text-slate-500"><X size={20}/></button>
                </div>

                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1 mb-4">
                    <button 
                        onClick={() => setMarginAction('ADD')}
                        className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'ADD' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}
                    >
                        {t.add}
                    </button>
                    <button 
                        onClick={() => setMarginAction('REMOVE')}
                        className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'REMOVE' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}
                    >
                        {t.remove}
                    </button>
                </div>

                <div className="mb-4">
                    <label className="text-xs text-slate-500 mb-1 block">{t.amount} (USDC)</label>
                    <input 
                        type="number" 
                        value={marginInput}
                        onChange={(e) => setMarginInput(e.target.value)}
                        className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-3 font-mono text-lg outline-none focus:border-indigo-500"
                        autoFocus
                    />
                </div>

                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setEditingPosId(null)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">
                        {t.cancel}
                    </button>
                    <button onClick={handleConfirmMargin} className="py-3 rounded-xl bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-500/20">
                        {t.confirmAction}
                    </button>
                </div>
             </div>
          </div>
      )}

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sparkles, Settings2 } from 'lucide-react';
import { CandleChart } from './CandleChart';
import { OrderBook } from './OrderBook';
import { Candle, Side, MarginMode, Language } from '../types';
import { analyzeMarket } from '../services/geminiService';
import { TRANSLATIONS } from '../constants';

interface TradeViewProps {
  candles: Candle[];
  currentPrice: number;
  balance: number;
  onPlaceOrder: (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => void;
  lang: Language;
}

export const TradeView: React.FC<TradeViewProps> = ({ candles, currentPrice, balance, onPlaceOrder, lang }) => {
  const t = TRANSLATIONS[lang];
  const [orderType, setOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [amount, setAmount] = useState<string>('1.00');
  const [limitPrice, setLimitPrice] = useState<string>(currentPrice.toFixed(2));
  const [leverage, setLeverage] = useState<number>(20);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Update limit price default when switching to limit if empty, but usually keep it static if user typed
  useEffect(() => {
    if (orderType === 'LIMIT' && !limitPrice) {
      setLimitPrice(currentPrice.toFixed(2));
    }
  }, [currentPrice, orderType]);

  const handleTrade = (side: Side) => {
    const size = parseFloat(amount);
    const price = orderType === 'LIMIT' ? parseFloat(limitPrice) : currentPrice;

    if (isNaN(size) || size <= 0) return;
    if (orderType === 'LIMIT' && (isNaN(price) || price <= 0)) return;

    onPlaceOrder(side, size, price, orderType, marginMode);
  };

  const runAnalysis = async () => {
    setIsAnalyzing(true);
    setAiAnalysis("Analyzing market structure...");
    try {
      const result = await analyzeMarket(candles, currentPrice);
      setAiAnalysis(result);
    } catch (e) {
      setAiAnalysis("Analysis failed.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const executionPrice = orderType === 'LIMIT' ? parseFloat(limitPrice) || currentPrice : currentPrice;
  const maxBuy = (balance * leverage) / executionPrice;

  return (
    <div className="flex flex-col h-full pb-20 overflow-y-auto no-scrollbar dark:bg-slate-900 bg-slate-50">
      {/* Header */}
      <div className="px-4 py-3 flex justify-between items-center border-b dark:border-slate-800 border-slate-200 dark:bg-slate-900 bg-slate-50 sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-yellow-500/20 flex items-center justify-center border border-yellow-500/30">
            <span className="text-yellow-500 font-bold text-xs">XAU</span>
          </div>
          <div>
            <h1 className="text-lg font-bold dark:text-white text-slate-900 leading-tight">XAU/USDC</h1>
            <span className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">Perpetual</span>
          </div>
        </div>
        <div className="text-right">
          <div className={`text-lg font-mono font-bold ${candles[candles.length-1]?.close >= candles[0]?.open ? 'text-emerald-500' : 'text-rose-500'}`}>
            {currentPrice.toFixed(2)}
          </div>
          <div className="text-[10px] text-slate-400">Mark Price</div>
        </div>
      </div>

      {/* Chart */}
      <div className="relative border-b dark:border-slate-800 border-slate-200 dark:bg-slate-900 bg-white">
        <CandleChart data={candles} />
        <button 
          onClick={runAnalysis}
          disabled={isAnalyzing}
          className="absolute top-2 left-2 flex items-center gap-1.5 px-3 py-1.5 bg-indigo-600/90 hover:bg-indigo-500 text-white text-[10px] font-bold uppercase tracking-wider rounded-full shadow-lg backdrop-blur transition-all border border-indigo-500/50"
        >
          <Sparkles size={10} className={isAnalyzing ? "animate-pulse" : ""} />
          {isAnalyzing ? "AI Thinking..." : "AI Insight"}
        </button>
        {aiAnalysis && (
            <div className="absolute top-12 left-2 right-12 dark:bg-slate-800/95 bg-white/95 backdrop-blur-md border dark:border-slate-700 border-slate-200 p-3 rounded-lg text-xs dark:text-slate-200 text-slate-800 shadow-xl z-20 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-start mb-2 border-b dark:border-slate-700 border-slate-200 pb-2">
                 <span className="font-bold text-indigo-500 flex items-center gap-1">
                   <Sparkles size={12} /> Gemini Analysis
                 </span>
                 <button onClick={() => setAiAnalysis(null)} className="text-slate-500 hover:text-slate-800 dark:hover:text-white p-1">×</button>
               </div>
               <p className="leading-relaxed opacity-90">{aiAnalysis}</p>
            </div>
        )}
      </div>

      {/* Order Book */}
      <OrderBook currentPrice={currentPrice} />

      {/* Order Controls */}
      <div className="p-4 space-y-4 dark:bg-slate-900 bg-slate-50">

        {/* Margin Mode & Order Type Row */}
        <div className="flex gap-2">
            <div className="relative">
                <select 
                    value={marginMode}
                    onChange={(e) => setMarginMode(e.target.value as MarginMode)}
                    className="appearance-none dark:bg-slate-800 bg-white text-xs font-bold dark:text-white text-slate-900 py-2 pl-3 pr-8 rounded-lg border dark:border-slate-700 border-slate-200 focus:outline-none focus:border-indigo-500 h-full shadow-sm"
                >
                    <option value={MarginMode.CROSS}>{t.cross}</option>
                    <option value={MarginMode.ISOLATED}>{t.isolated}</option>
                </select>
                <Settings2 size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            <div className="flex-1 flex dark:bg-slate-800 bg-slate-200 rounded-lg p-1">
                <button 
                    onClick={() => setOrderType('MARKET')}
                    className={`flex-1 py-1 text-xs font-bold rounded transition-all ${orderType === 'MARKET' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                    {t.market}
                </button>
                <button 
                    onClick={() => {
                        setOrderType('LIMIT');
                        setLimitPrice(currentPrice.toFixed(2));
                    }}
                    className={`flex-1 py-1 text-xs font-bold rounded transition-all ${orderType === 'LIMIT' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                    {t.limit}
                </button>
            </div>
        </div>

        {/* Leverage Slider */}
        <div className="dark:bg-slate-800/50 bg-white p-3 rounded-xl border dark:border-slate-800 border-slate-200 shadow-sm">
          <div className="flex justify-between text-xs text-slate-400 mb-2">
            <span>{t.leverage}</span>
            <span className="dark:text-white text-slate-900 font-mono">{leverage}x</span>
          </div>
          <input 
            type="range" 
            min="1" 
            max="100" 
            step="1" 
            value={leverage} 
            onChange={(e) => setLeverage(parseInt(e.target.value))}
            className="w-full h-1 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
          />
          <div className="flex justify-between text-[10px] text-slate-500 mt-1 font-mono">
            <span>1x</span>
            <span>20x</span>
            <span>50x</span>
            <span>100x</span>
          </div>
        </div>

        {/* Inputs */}
        <div className="grid grid-cols-2 gap-4">

          {/* Price Input (Only for Limit) */}
          {orderType === 'LIMIT' && (
            <div className="col-span-2">
              <div className="relative group">
                  <label className="absolute -top-2 left-2 dark:bg-slate-900 bg-slate-50 px-1 text-[10px] text-slate-400 group-focus-within:text-indigo-500 transition-colors">{t.price} (USDC)</label>
                  <input 
                    type="number" 
                    value={limitPrice}
                    onChange={(e) => setLimitPrice(e.target.value)}
                    className="w-full dark:bg-slate-900 bg-slate-50 border dark:border-slate-700 border-slate-200 rounded-lg py-3 px-4 dark:text-white text-slate-900 font-mono focus:outline-none focus:border-indigo-500 transition-colors"
                  />
              </div>
            </div>
          )}

          {/* Amount Input */}
          <div className="col-span-2">
             <div className="relative group">
                <label className="absolute -top-2 left-2 dark:bg-slate-900 bg-slate-50 px-1 text-[10px] text-slate-400 group-focus-within:text-indigo-500 transition-colors">{t.size} (XAU)</label>
                <input 
                  type="number" 
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  className="w-full dark:bg-slate-900 bg-slate-50 border dark:border-slate-700 border-slate-200 rounded-lg py-3 px-4 dark:text-white text-slate-900 font-mono focus:outline-none focus:border-indigo-500 transition-colors"
                />
                <span className="absolute right-4 top-3.5 text-xs text-slate-500 font-mono">
                  ≈ ${(parseFloat(amount || '0') * executionPrice).toLocaleString()}
                </span>
             </div>
             <div className="flex justify-between text-[10px] text-slate-500 mt-1 px-1">
               <span>Max: {maxBuy.toFixed(2)} XAU</span>
               <span>{t.avail}: ${balance.toFixed(2)}</span>
             </div>
          </div>
        </div>

        {/* Buttons */}
        <div className="grid grid-cols-2 gap-3 mt-4">
          <button 
            onClick={() => handleTrade(Side.LONG)}
            className="flex flex-col items-center justify-center py-3 rounded-lg bg-emerald-600 active:bg-emerald-700 text-white shadow-lg shadow-emerald-900/20 transition-transform active:scale-95"
          >
            <span className="font-bold text-sm">{t.long}</span>
            <span className="text-[10px] opacity-80 font-mono">
               {orderType === 'LIMIT' ? `@ ${parseFloat(limitPrice).toFixed(2)}` : t.market}
            </span>
          </button>
          <button 
            onClick={() => handleTrade(Side.SHORT)}
            className="flex flex-col items-center justify-center py-3 rounded-lg bg-rose-600 active:bg-rose-700 text-white shadow-lg shadow-rose-900/20 transition-transform active:scale-95"
          >
            <span className="font-bold text-sm">{t.short}</span>
            <span className="text-[10px] opacity-80 font-mono">
               {orderType === 'LIMIT' ? `@ ${parseFloat(limitPrice).toFixed(2)}` : t.market}
            </span>
          </button>
        </div>

        {/* Info */}
        <div className="dark:bg-slate-800/30 bg-white/50 rounded-lg p-3 text-xs space-y-2 border dark:border-slate-800/50 border-slate-200">
          <div className="flex justify-between">
             <span className="text-slate-500">Mode</span>
             <span className="text-indigo-500 font-mono font-bold uppercase">{marginMode}</span>
          </div>
          <div className="flex justify-between">
             <span className="text-slate-500">{t.liqPrice} (Est)</span>
             <span className="text-orange-500 font-mono">
               {amount ? (parseFloat(amount) > 0 ? (executionPrice * (1 - 1/leverage)).toFixed(2) : '--') : '--'}
             </span>
          </div>
          <div className="flex justify-between">
             <span className="text-slate-500">Margin Required</span>
             <span className="dark:text-slate-200 text-slate-800 font-mono">
                ${amount ? ((parseFloat(amount) * executionPrice) / leverage).toFixed(2) : '0.00'}
             </span>
          </div>
        </div>

      </div>
    </div>
  );
};

import React from 'react';
import { Order, Side, Language } from '../types';
import { Clock, X } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface OrdersViewProps {
  orders: Order[];
  onCancelOrder: (id: string) => void;
  lang: Language;
}

export const OrdersView: React.FC<OrdersViewProps> = ({ orders, onCancelOrder, lang }) => {
   const t = TRANSLATIONS[lang];

   if (orders.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full dark:text-slate-500 text-slate-400">
        <div className="dark:bg-slate-800 bg-white p-4 rounded-full mb-4 shadow-sm border dark:border-slate-700 border-slate-200">
           <Clock size={32} className="opacity-50" />
        </div>
        <p>{t.noOrders}</p>
