    );
  }

  return (
    <div className="p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar h-full dark:bg-slate-900 bg-slate-50">
      <h2 className="dark:text-slate-400 text-slate-500 text-xs uppercase font-bold tracking-wider mb-2">{t.openOrders} ({orders.length})</h2>
      {orders.map((order) => (
        <div key={order.id} className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-xl p-4 flex justify-between items-center shadow-sm">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className={`text-sm font-bold ${order.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}`}>
                {order.side === Side.LONG ? t.long.split('/')[0] : t.short.split('/')[0]} {order.symbol}
              </span>
              <span className="text-[10px] dark:bg-slate-700 bg-slate-200 dark:text-slate-300 text-slate-600 px-1.5 py-0.5 rounded">{t.limit.toUpperCase()}</span>
            </div>
            <div className="text-xs dark:text-slate-400 text-slate-500">
              <span className="mr-3">{t.size}: <span className="dark:text-white text-slate-900 font-mono">{order.amount}</span></span>
              <span>{t.price}: <span className="dark:text-white text-slate-900 font-mono">{order.price.toFixed(2)}</span></span>
            </div>
            <div className="text-[10px] dark:text-slate-600 text-slate-400 mt-1">
              {new Date(order.timestamp).toLocaleString()}
            </div>
          </div>
          <button 
            onClick={() => onCancelOrder(order.id)}
            className="p-2 text-slate-400 hover:text-rose-500 dark:hover:text-white dark:bg-slate-700/50 bg-slate-100 rounded-lg"
          >
            <X size={16} />
          </button>
        </div>
      ))}
    </div>
  );
};

import React from 'react';
import { Tab, Language } from '../types';
import { CandlestickChart, Briefcase, List, Wallet } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface BottomNavProps {
  currentTab: Tab;
  onTabChange: (tab: Tab) => void;
  ordersCount: number;
  positionsCount: number;
  lang: Language;
}

export const BottomNav: React.FC<BottomNavProps> = ({ currentTab, onTabChange, ordersCount, positionsCount, lang }) => {
  const t = TRANSLATIONS[lang];

  const navItems = [
    { id: Tab.TRADE, label: t.trade, icon: CandlestickChart },
    { id: Tab.POSITIONS, label: t.positions, icon: Briefcase, count: positionsCount },
    { id: Tab.ORDERS, label: t.orders, icon: List, count: ordersCount },
    { id: Tab.ACCOUNT, label: t.assets, icon: Wallet },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 dark:bg-slate-900 bg-white border-t dark:border-slate-800 border-slate-200 safe-area-bottom z-50">
      <div className="flex justify-around items-center h-16 max-w-md mx-auto">
        {navItems.map((item) => {
          const isActive = currentTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id)}
              className="relative flex flex-col items-center justify-center w-full h-full space-y-1"
            >
              <item.icon 
                size={22} 
                className={`transition-colors duration-200 ${isActive ? 'text-indigo-500' : 'dark:text-slate-500 text-slate-400'}`} 
              />
              <span className={`text-[10px] font-medium transition-colors duration-200 ${isActive ? 'text-indigo-500' : 'dark:text-slate-500 text-slate-400'}`}>
                {item.label}
              </span>
              {item.count ? (
                <span className="absolute top-2 right-4 min-w-[16px] h-4 flex items-center justify-center bg-rose-500 text-white text-[9px] font-bold rounded-full px-1 border dark:border-slate-900 border-white">
                  {item.count}
                </span>
              ) : null}
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';

interface OrderBookProps {
  currentPrice: number;
}

export const OrderBook: React.FC<OrderBookProps> = ({ currentPrice }) => {
  // Generate mock data for asks (sellers) and bids (buyers)
  const { asks, bids } = useMemo(() => {
    const asksArr = [];
    const bidsArr = [];
    // Generate 5 levels
    for (let i = 1; i <= 5; i++) {
      // Asks are higher than current price
      asksArr.push({
        price: currentPrice + i * 0.15 + (Math.random() * 0.1),
        size: (Math.random() * 5 + 0.1).toFixed(3),
        total: Math.random() * 100 // Visual bar width %
      });
      // Bids are lower than current price
      bidsArr.push({
        price: currentPrice - i * 0.15 - (Math.random() * 0.1),
        size: (Math.random() * 5 + 0.1).toFixed(3),
        total: Math.random() * 100
      });
    }
    // Standard Vertical Order Book: Asks (High -> Low) on top, Bids (High -> Low) on bottom
    return { asks: asksArr.reverse(), bids: bidsArr };
  }, [currentPrice]); // Re-generate when price changes for "live" feel

  return (
    <div className="dark:bg-slate-900 bg-white border-b dark:border-slate-800 border-slate-200 p-3">
      <div className="grid grid-cols-2 gap-4">
        {/* Asks */}
        <div>
           <div className="flex justify-between text-[10px] dark:text-slate-500 text-slate-400 mb-1 uppercase tracking-wider">
             <span>Price</span>
             <span>Qty</span>
          </div>
          <div className="flex flex-col-reverse space-y-reverse space-y-0.5">
            {asks.map((ask, i) => (
                <div key={`ask-${i}`} className="flex justify-between items-center text-[10px] font-mono relative h-4">
                    <span className="text-rose-500 z-10">{ask.price.toFixed(2)}</span>
                    <span className="dark:text-slate-300 text-slate-700 z-10">{ask.size}</span>
                     <div className="absolute top-0 right-0 bottom-0 bg-rose-500/10 rounded-sm transition-all duration-300" style={{ width: `${ask.total}%`}}></div>
                </div>
            ))}
          </div>
        </div>

        {/* Bids */}
        <div>
           <div className="flex justify-between text-[10px] dark:text-slate-500 text-slate-400 mb-1 uppercase tracking-wider">
             <span>Price</span>
             <span>Qty</span>
          </div>
          <div className="space-y-0.5">
            {bids.map((bid, i) => (
                <div key={`bid-${i}`} className="flex justify-between items-center text-[10px] font-mono relative h-4">
                    <span className="text-emerald-500 z-10">{bid.price.toFixed(2)}</span>
                    <span className="dark:text-slate-300 text-slate-700 z-10">{bid.size}</span>
                    <div className="absolute top-0 right-0 bottom-0 bg-emerald-500/10 rounded-sm transition-all duration-300" style={{ width: `${bid.total}%`}}></div>
                </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Sparkles, Settings2 } from 'lucide-react';
import { CandleChart } from './CandleChart';
import { OrderBook } from './OrderBook';
import { Candle, Side, MarginMode, Language } from '../types';
import { analyzeMarket } from '../services/geminiService';
import { TRANSLATIONS } from '../constants';

interface TradeViewProps {
  candles: Candle[];
  currentPrice: number;
  balance: number;
  onPlaceOrder: (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => void;
  lang: Language;
}

export const TradeView: React.FC<TradeViewProps> = ({ candles, currentPrice, balance, onPlaceOrder, lang }) => {
  const t = TRANSLATIONS[lang];
  const [orderType, setOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [amount, setAmount] = useState<string>('1.00');
  const [limitPrice, setLimitPrice] = useState<string>(currentPrice.toFixed(2));
  const [leverage, setLeverage] = useState<number>(20);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Market Stats State
  const [countdown, setCountdown] = useState<string>('07:59:59');

  // Update limit price default when switching to limit if empty, but usually keep it static if user typed
  useEffect(() => {
    if (orderType === 'LIMIT' && !limitPrice) {
      setLimitPrice(currentPrice.toFixed(2));
    }
  }, [currentPrice, orderType]);

  // Countdown timer simulation
  useEffect(() => {
    const timer = setInterval(() => {
        const now = new Date();
        const nextFunding = new Date(now);
        nextFunding.setHours(Math.ceil(now.getHours() / 8) * 8, 0, 0, 0);
        if (nextFunding <= now) nextFunding.setTime(nextFunding.getTime() + 8 * 60 * 60 * 1000);

        const diff = nextFunding.getTime() - now.getTime();
        const h = Math.floor((diff / (1000 * 60 * 60)) % 24).toString().padStart(2, '0');
        const m = Math.floor((diff / (1000 * 60)) % 60).toString().padStart(2, '0');
        const s = Math.floor((diff / 1000) % 60).toString().padStart(2, '0');
        setCountdown(`${h}:${m}:${s}`);
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const handleTrade = (side: Side) => {
    const size = parseFloat(amount);
    const price = orderType === 'LIMIT' ? parseFloat(limitPrice) : currentPrice;

    if (isNaN(size) || size <= 0) return;
    if (orderType === 'LIMIT' && (isNaN(price) || price <= 0)) return;

    onPlaceOrder(side, size, price, orderType, marginMode);
  };

  const runAnalysis = async () => {
    setIsAnalyzing(true);
    setAiAnalysis("Analyzing market structure...");
    try {
      const result = await analyzeMarket(candles, currentPrice);
      setAiAnalysis(result);
    } catch (e) {
      setAiAnalysis("Analysis failed.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const executionPrice = orderType === 'LIMIT' ? parseFloat(limitPrice) || currentPrice : currentPrice;
  const maxBuy = (balance * leverage) / executionPrice;

  // Mock Data
  const markPrice = currentPrice * 1.0001;
  const fundingRate = 0.0042; // 0.0042%

  return (
    <div className="flex flex-col h-full pb-20 overflow-y-auto no-scrollbar dark:bg-slate-900 bg-slate-50">
      {/* Header */}
      <div className="dark:bg-slate-900 bg-white border-b dark:border-slate-800 border-slate-200 sticky top-0 z-10 shadow-sm">
          <div className="px-4 py-3 flex justify-between items-center">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-yellow-500/20 flex items-center justify-center border border-yellow-500/30">
                <span className="text-yellow-500 font-bold text-xs">XAU</span>
              </div>
              <div>
                <h1 className="text-lg font-bold dark:text-white text-slate-900 leading-tight">XAU/USDC</h1>
                <span className="text-[10px] text-slate-400 font-medium uppercase tracking-wider">Perpetual</span>
              </div>
            </div>
            <div className="text-right">
              <div className={`text-xl font-mono font-bold ${candles[candles.length-1]?.close >= candles[0]?.open ? 'text-emerald-500' : 'text-rose-500'}`}>
                {currentPrice.toFixed(2)}
              </div>
              <div className="text-[10px] text-slate-400">{t.lastPrice}</div>
            </div>
          </div>

          {/* Ticker Info Bar */}
          <div className="px-4 py-2 flex justify-between items-center text-[10px] dark:bg-slate-800/50 bg-slate-50 border-t dark:border-slate-800 border-slate-100">
             <div className="flex flex-col">
                <span className="text-slate-400 mb-0.5">{t.markPrice}</span>
                <span className="font-mono dark:text-slate-200 text-slate-700">{markPrice.toFixed(2)}</span>
             </div>
             <div className="flex flex-col text-center">
                <span className="text-slate-400 mb-0.5">{t.fundingRate}</span>
                <span className="font-mono text-orange-400">{fundingRate.toFixed(4)}%</span>
             </div>
             <div className="flex flex-col text-right">
                <span className="text-slate-400 mb-0.5">{t.countdown}</span>
                <span className="font-mono dark:text-slate-200 text-slate-700">{countdown}</span>
             </div>
          </div>
      </div>

      {/* Chart */}
      <div className="relative border-b dark:border-slate-800 border-slate-200 dark:bg-slate-900 bg-white">
        <CandleChart data={candles} />
        <button 
          onClick={runAnalysis}
          disabled={isAnalyzing}
          className="absolute top-2 left-2 flex items-center gap-1.5 px-3 py-1.5 bg-indigo-600/90 hover:bg-indigo-500 text-white text-[10px] font-bold uppercase tracking-wider rounded-full shadow-lg backdrop-blur transition-all border border-indigo-500/50"
        >
          <Sparkles size={10} className={isAnalyzing ? "animate-pulse" : ""} />
          {isAnalyzing ? "AI Thinking..." : "AI Insight"}
        </button>
        {aiAnalysis && (
            <div className="absolute top-12 left-2 right-12 dark:bg-slate-800/95 bg-white/95 backdrop-blur-md border dark:border-slate-700 border-slate-200 p-3 rounded-lg text-xs dark:text-slate-200 text-slate-800 shadow-xl z-20 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-start mb-2 border-b dark:border-slate-700 border-slate-200 pb-2">
                 <span className="font-bold text-indigo-500 flex items-center gap-1">
                   <Sparkles size={12} /> Gemini Analysis
                 </span>
                 <button onClick={() => setAiAnalysis(null)} className="text-slate-500 hover:text-slate-800 dark:hover:text-white p-1">×</button>
               </div>
               <p className="leading-relaxed opacity-90">{aiAnalysis}</p>
            </div>
        )}
      </div>

      {/* Order Book */}
      <OrderBook currentPrice={currentPrice} />

      {/* Order Controls */}
      <div className="p-4 space-y-4 dark:bg-slate-900 bg-slate-50">

        {/* Margin Mode & Order Type Row */}
        <div className="flex gap-2">
            <div className="relative">
                <select 
                    value={marginMode}
                    onChange={(e) => setMarginMode(e.target.value as MarginMode)}
                    className="appearance-none dark:bg-slate-800 bg-white text-xs font-bold dark:text-white text-slate-900 py-2 pl-3 pr-8 rounded-lg border dark:border-slate-700 border-slate-200 focus:outline-none focus:border-indigo-500 h-full shadow-sm"
                >
                    <option value={MarginMode.CROSS}>{t.cross}</option>
                    <option value={MarginMode.ISOLATED}>{t.isolated}</option>
                </select>
                <Settings2 size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
            </div>

            <div className="flex-1 flex dark:bg-slate-800 bg-slate-200 rounded-lg p-1">
                <button 
                    onClick={() => setOrderType('MARKET')}
                    className={`flex-1 py-1 text-xs font-bold rounded transition-all ${orderType === 'MARKET' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                    {t.market}
                </button>
                <button 
                    onClick={() => {
                        setOrderType('LIMIT');
                        setLimitPrice(currentPrice.toFixed(2));
                    }}
                    className={`flex-1 py-1 text-xs font-bold rounded transition-all ${orderType === 'LIMIT' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'}`}
                >
                    {t.limit}
                </button>
            </div>
        </div>

        {/* Leverage Slider */}
        <div className="dark:bg-slate-800/50 bg-white p-3 rounded-xl border dark:border-slate-800 border-slate-200 shadow-sm">
          <div className="flex justify-between text-xs text-slate-400 mb-2">
            <span>{t.leverage}</span>
            <span className="dark:text-white text-slate-900 font-mono">{leverage}x</span>
          </div>
          <input 
            type="range" 
            min="1" 
            max="100" 
            step="1" 
            value={leverage} 
            onChange={(e) => setLeverage(parseInt(e.target.value))}
            className="w-full h-1 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
          />
          <div className="flex justify-between text-[10px] text-slate-500 mt-1 font-mono">
            <span>1x</span>
            <span>20x</span>
            <span>50x</span>
            <span>100x</span>
          </div>
        </div>

        {/* Inputs */}
        <div className="grid grid-cols-2 gap-4">

          {/* Price Input (Only for Limit) */}
          {orderType === 'LIMIT' && (
            <div className="col-span-2">
              <div className="relative group">
                  <label className="absolute -top-2 left-2 dark:bg-slate-900 bg-slate-50 px-1 text-[10px] text-slate-400 group-focus-within:text-indigo-500 transition-colors">{t.price} (USDC)</label>
                  <input 
                    type="number" 
                    value={limitPrice}
                    onChange={(e) => setLimitPrice(e.target.value)}
                    className="w-full dark:bg-slate-900 bg-slate-50 border dark:border-slate-700 border-slate-200 rounded-lg py-3 px-4 dark:text-white text-slate-900 font-mono focus:outline-none focus:border-indigo-500 transition-colors"
                  />
              </div>
            </div>
          )}

          {/* Amount Input */}
          <div className="col-span-2">
             <div className="relative group">
                <label className="absolute -top-2 left-2 dark:bg-slate-900 bg-slate-50 px-1 text-[10px] text-slate-400 group-focus-within:text-indigo-500 transition-colors">{t.size} (XAU)</label>
                <input 
                  type="number" 
                  value={amount}
                  onChange={(e) => setAmount(e.target.value)}
                  className="w-full dark:bg-slate-900 bg-slate-50 border dark:border-slate-700 border-slate-200 rounded-lg py-3 px-4 dark:text-white text-slate-900 font-mono focus:outline-none focus:border-indigo-500 transition-colors"
                />
                <span className="absolute right-4 top-3.5 text-xs text-slate-500 font-mono">
                  ≈ ${(parseFloat(amount || '0') * executionPrice).toLocaleString()}
                </span>
             </div>
             <div className="flex justify-between text-[10px] text-slate-500 mt-1 px-1">
               <span>Max: {maxBuy.toFixed(2)} XAU</span>
               <span>{t.avail}: ${balance.toFixed(2)}</span>
             </div>
          </div>
        </div>

        {/* Buttons */}
        <div className="grid grid-cols-2 gap-3 mt-4">
          <button 
            onClick={() => handleTrade(Side.LONG)}
            className="flex flex-col items-center justify-center py-3 rounded-lg bg-emerald-600 active:bg-emerald-700 text-white shadow-lg shadow-emerald-900/20 transition-transform active:scale-95"
          >
            <span className="font-bold text-sm">{t.long}</span>
            <span className="text-[10px] opacity-80 font-mono">
               {orderType === 'LIMIT' ? `@ ${parseFloat(limitPrice).toFixed(2)}` : t.market}
            </span>
          </button>
          <button 
            onClick={() => handleTrade(Side.SHORT)}
            className="flex flex-col items-center justify-center py-3 rounded-lg bg-rose-600 active:bg-rose-700 text-white shadow-lg shadow-rose-900/20 transition-transform active:scale-95"
          >
            <span className="font-bold text-sm">{t.short}</span>
            <span className="text-[10px] opacity-80 font-mono">
               {orderType === 'LIMIT' ? `@ ${parseFloat(limitPrice).toFixed(2)}` : t.market}
            </span>
          </button>
        </div>

        {/* Info */}
        <div className="dark:bg-slate-800/30 bg-white/50 rounded-lg p-3 text-xs space-y-2 border dark:border-slate-800/50 border-slate-200">
          <div className="flex justify-between">
             <span className="text-slate-500">Mode</span>
             <span className="text-indigo-500 font-mono font-bold uppercase">{marginMode}</span>
          </div>
          <div className="flex justify-between">
             <span className="text-slate-500">{t.liqPrice} (Est)</span>
             <span className="text-orange-500 font-mono">
               {amount ? (parseFloat(amount) > 0 ? (executionPrice * (1 - 1/leverage)).toFixed(2) : '--') : '--'}
             </span>
          </div>
          <div className="flex justify-between">
             <span className="text-slate-500">Margin Required</span>
             <span className="dark:text-slate-200 text-slate-800 font-mono">
                ${amount ? ((parseFloat(amount) * executionPrice) / leverage).toFixed(2) : '0.00'}
             </span>
          </div>
        </div>

      </div>
    </div>
  );
};

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';
export type ChartType = 'line' | 'candle';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number; // Specific margin for isolated positions
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

export interface TradeRecord {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  closePrice: number;
  pnl: number;
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING';
}

export interface FundingRecord {
  id: string;
  symbol: string;
  rate: number;
  amount: number;
  timestamp: number;
}

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, TradeRecord, TransferRecord, MarginMode, Language, Theme, FundingRecord } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);

  // Settings State
  const [language, setLanguage] = useState<Language>('en');
  const [theme, setTheme] = useState<Theme>('dark');

  // Auth State
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);

  // Market Data State
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50));
  const [currentPrice, setCurrentPrice] = useState<number>(candles[candles.length - 1].close);

  // User Data State
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // History State
  const [tradeHistory, setTradeHistory] = useState<TradeRecord[]>([]);
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([]);
  const [fundingHistory, setFundingHistory] = useState<FundingRecord[]>([]);

  // Initial Mock Data
  useEffect(() => {
    // Generate some funding history
    const mockFunding: FundingRecord[] = [];
    const now = Date.now();
    for(let i=1; i<=15; i++) {
        mockFunding.push({
            id: `funding-${i}`,
            symbol: SYMBOL,
            rate: 0.0001 + (Math.random() * 0.00005),
            amount: - (Math.random() * 2).toFixed(4) as unknown as number,
            timestamp: now - (i * 3600 * 1000) // 1 hour intervals
        });
    }
    setFundingHistory(mockFunding);
  }, []);

  // Apply Theme
  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  // Simulation Loop: Market Data & Limit Order Matching
  useEffect(() => {
    const interval = setInterval(() => {
      // 1. Update Candles & Price
      let newPrice = currentPrice;

      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const now = new Date();

        const volatility = 0.8; // USD movement per tick
        const move = (Math.random() - 0.5) * volatility;
        newPrice = Math.max(0.01, lastCandle.close + move);

        // Update High/Low of last candle
        const updatedLastCandle = {
          ...lastCandle,
          close: newPrice,
          high: Math.max(lastCandle.high, newPrice),
          low: Math.min(lastCandle.low, newPrice)
        };

        // 5% chance to start a new candle
        if (Math.random() > 0.95) {
           const newCandle: Candle = {
             time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
             open: newPrice,
             close: newPrice,
             high: newPrice,
             low: newPrice
           };
           return [...prevCandles.slice(1), newCandle];
        } else {
           return [...prevCandles.slice(0, -1), updatedLastCandle];
        }
      });

      setCurrentPrice(newPrice);

      // Randomly generate funding fee (Mock)
      if (Math.random() > 0.999) { // Rare event for demo
        setFundingHistory(prev => [{
            id: Date.now().toString(),
            symbol: SYMBOL,
            rate: 0.0001,
            amount: -0.5, // Mock deduction
            timestamp: Date.now()
        }, ...prev]);
        setBalance(prev => prev - 0.5);
      }

      // 2. Check Limit Orders for Execution
      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;

        prevOrders.forEach(order => {
          let executed = false;
          // Buy Limit: Fill if current price <= limit price
          if (order.side === Side.LONG && newPrice <= order.price) {
            executed = true;
          }
          // Sell Limit: Fill if current price >= limit price
          else if (order.side === Side.SHORT && newPrice >= order.price) {
            executed = true;
          }

          if (executed) {
            ordersExecuted = true;

            // Calculate initial isolated margin if applicable
            const leverage = 20;
            const initialMargin = (order.amount * order.price) / leverage;

            const newPosition: Position = {
              id: Date.now().toString() + Math.random(),
              symbol: SYMBOL,
              side: order.side,
              size: order.amount,
              entryPrice: order.price, 
              leverage: 20, 
              unrealizedPnL: 0,
              marginMode: order.marginMode,
              isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined
            };
            setPositions(prev => [newPosition, ...prev]);
            console.log(`Order ${order.id} executed at ${newPrice}`);
          } else {
            remainingOrders.push(order);
          }
        });

        return ordersExecuted ? remainingOrders : prevOrders;
      });

    }, 1000);

    return () => clearInterval(interval);
  }, [currentPrice]); 

  // Trading Logic
  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) {
      alert("Please connect your wallet in the Assets tab first.");
      setActiveTab(Tab.ACCOUNT);
      return;
    }

    const leverage = 20; // Fixed for demo
    const requiredMargin = (price * size) / leverage; 

    if (requiredMargin > balance) {
      alert("Insufficient Balance");
      return;
    }

    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPosition: Position = {
        id: Date.now().toString(),
        symbol: SYMBOL,
        side,
        size,
        entryPrice: price,
        leverage,
        unrealizedPnL: 0,
        marginMode,
        isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined
      };
      setPositions(prev => [newPosition, ...prev]);
    } else {
      const newOrder: Order = {
        id: Date.now().toString(),
        symbol: SYMBOL,
        side,
        type: 'LIMIT',
        price,
        amount: size,
        timestamp: Date.now(),
        marginMode
      };
      setOrders(prev => [newOrder, ...prev]);
    }
  };

  const handleClosePosition = (id: string) => {
    const position = positions.find(p => p.id === id);
    if (!position) return;

    const priceDiff = currentPrice - position.entryPrice;
    const pnl = position.side === Side.LONG ? priceDiff * position.size : -priceDiff * position.size;

    // For isolated margin, we return the specific isolated margin + pnl
    // For cross margin, we return standard calculated margin + pnl
    let marginToReturn = 0;
    if (position.marginMode === MarginMode.ISOLATED && position.isolatedMargin) {
      marginToReturn = position.isolatedMargin;
    } else {
      marginToReturn = (position.entryPrice * position.size) / position.leverage;
    }

    setBalance(prev => prev + marginToReturn + pnl);

    const record: TradeRecord = {
      id: position.id,
      symbol: position.symbol,
      side: position.side,
      size: position.size,
      entryPrice: position.entryPrice,
      closePrice: currentPrice,
      pnl: pnl,
      timestamp: Date.now()
    };
    setTradeHistory(prev => [record, ...prev]);

    setPositions(prev => prev.filter(p => p.id !== id));
  };

  const handleUpdateMargin = (id: string, amount: number, type: 'ADD' | 'REMOVE') => {
    setPositions(prev => prev.map(pos => {
        if (pos.id === id && pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin !== undefined) {
            if (type === 'ADD') {
                if (balance >= amount) {
                    setBalance(b => b - amount);
                    return { ...pos, isolatedMargin: pos.isolatedMargin! + amount };
                }
            } else {
                // Should check if removal causes immediate liquidation risk, simplified here
                if (pos.isolatedMargin! > amount) {
                    setBalance(b => b + amount);
                    return { ...pos, isolatedMargin: pos.isolatedMargin! - amount };
                }
            }
        }
        return pos;
    }));
  };

  const handleCancelOrder = (id: string) => {
    const order = orders.find(o => o.id === id);
    if (!order) return;

    const leverage = 20;
    const margin = (order.price * order.amount) / leverage;
    setBalance(prev => prev + margin);

    setOrders(prev => prev.filter(o => o.id !== id));
  };

  const handleDeposit = (amount: number) => {
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{
      id: Date.now().toString(),
      type: 'DEPOSIT',
      amount,
      timestamp: Date.now(),
      status: 'COMPLETED'
    }, ...prev]);
  };

  const handleWithdraw = (amount: number) => {
    if (balance < amount) return false;
    setBalance(prev => prev - amount);
    setTransferHistory(prev => [{
      id: Date.now().toString(),
      type: 'WITHDRAW',
      amount,
      timestamp: Date.now(),
      status: 'COMPLETED'
    }, ...prev]);
    return true;
  };

  // Calculate Equity
  const totalUnrealizedPnL = positions.reduce((acc, pos) => {
    const diff = currentPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? diff * pos.size : -diff * pos.size;
    return acc + pnl;
  }, 0);

  const isolatedMarginLocked = positions
    .filter(p => p.marginMode === MarginMode.ISOLATED)
    .reduce((acc, p) => acc + (p.isolatedMargin || 0), 0);

  const crossMarginLocked = positions
    .filter(p => p.marginMode === MarginMode.CROSS)
    .reduce((acc, p) => acc + ((p.entryPrice * p.size) / p.leverage), 0);

  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0);

  const equity = balance + isolatedMarginLocked + crossMarginLocked + orderMargin + totalUnrealizedPnL;

  const totalPositionValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPositionValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>

      {/* Main Content Area */}
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance}
            onPlaceOrder={handlePlaceOrder}
            lang={language}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView 
            positions={positions} 
            currentPrice={currentPrice}
            equity={equity}
            maintenanceMargin={maintenanceMargin}
            marginRatio={marginRatio}
            onClosePosition={handleClosePosition}
            onUpdateMargin={handleUpdateMargin}
            lang={language}
          />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView 
            orders={orders} 
            onCancelOrder={handleCancelOrder}
            lang={language}
          />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView 
            balance={balance}
            equity={equity}
            tradeHistory={tradeHistory}
            transferHistory={transferHistory}
            fundingHistory={fundingHistory}
            onDeposit={handleDeposit}
            onWithdraw={handleWithdraw}
            isConnected={isWalletConnected}
            onConnect={() => setIsWalletConnected(true)}
            onDisconnect={() => setIsWalletConnected(false)}
            language={language}
            setLanguage={setLanguage}
            theme={theme}
            setTheme={setTheme}
          />
        )}
      </main>

      {/* Navigation */}
      <BottomNav 
        currentTab={activeTab} 
        onTabChange={setActiveTab} 
        ordersCount={orders.length}
        positionsCount={positions.length}
        lang={language}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { ResponsiveContainer, AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip } from 'recharts';
import { Candle, ChartType } from '../types';

interface CandleChartProps {
  data: Candle[];
  type?: ChartType;
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    return (
      <div className="bg-slate-800 border border-slate-700 p-2 rounded shadow-lg text-xs z-50">
        <p className="text-slate-400">{data.time}</p>
        <p className="text-emerald-400">H: {data.high.toFixed(2)}</p>
        <p className="text-rose-400">L: {data.low.toFixed(2)}</p>
        <p className="text-white">O: {data.open.toFixed(2)}</p>
        <p className="text-white">C: {data.close.toFixed(2)}</p>
      </div>
    );
  }
  return null;
};

// Custom shape for candlestick bar
const CandlestickShape = (props: any) => {
  const { x, y, width, height, payload } = props;
  const { open, close, high, low } = payload;
  const isUp = close >= open;
  const color = isUp ? '#10b981' : '#f43f5e';

  // Calculate y coordinates relative to the chart area
  // We need to map values to pixels. 
  // props.y is the coordinate for the max value of the bar (which we set to 'high')
  // props.height is the pixel height of the range (high - low)

  // Scale factor: pixels per unit
  const range = high - low;
  const scale = range === 0 ? 0 : height / range;

  const yHigh = y;
  const yLow = y + height;
  const yOpen = yHigh + (high - open) * scale;
  const yClose = yHigh + (high - close) * scale;

  const bodyTop = Math.min(yOpen, yClose);
  const bodyHeight = Math.abs(yOpen - yClose);

  // Ensure minimal height for visibility
  const visibleBodyHeight = Math.max(1, bodyHeight);

  return (
    <g>
      {/* Wick */}
      <line x1={x + width / 2} y1={yHigh} x2={x + width / 2} y2={yLow} stroke={color} strokeWidth={1} />
      {/* Body */}
      <rect 
        x={x} 
        y={bodyTop} 
        width={width} 
        height={visibleBodyHeight} 
        fill={color} 
      />
    </g>
  );
};

export const CandleChart: React.FC<CandleChartProps> = ({ data, type = 'line' }) => {
  const min = Math.min(...data.map(d => d.low));
  const max = Math.max(...data.map(d => d.high));
  const padding = (max - min) * 0.1;
  const domainMin = min - padding;
  const domainMax = max + padding;

  // Determine chart color based on last movement for Area Chart
  const isPositive = data.length > 1 && data[data.length - 1].close >= data[0].close;
  const strokeColor = isPositive ? '#10b981' : '#f43f5e';
  const fillColor = isPositive ? 'url(#colorUp)' : 'url(#colorDown)';

  // Pre-process data for BarChart (Range)
  // We use a Bar to represent the full range [low, high] and draw inside it
  const candleData = data.map(d => ({
    ...d,
    range: [d.low, d.high]
  }));

  return (
    <div className="w-full h-64 select-none touch-none">
      <ResponsiveContainer width="100%" height="100%">
        {type === 'line' ? (
            <AreaChart data={data}>
            <defs>
                <linearGradient id="colorUp" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#10b981" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                </linearGradient>
                <linearGradient id="colorDown" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#f43f5e" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#f43f5e" stopOpacity={0}/>
                </linearGradient>
            </defs>
            <XAxis dataKey="time" hide={true} axisLine={false} tickLine={false} />
            <YAxis 
                domain={[domainMin, domainMax]} 
                orientation="right" 
                tick={{fill: '#64748b', fontSize: 10}} 
                axisLine={false} 
                tickLine={false}
                tickFormatter={(value) => value.toFixed(1)}
                width={40}
            />
            <Tooltip content={<CustomTooltip />} cursor={{ stroke: '#64748b', strokeWidth: 1, strokeDasharray: '3 3' }} />
            <Area 
                type="monotone" 
                dataKey="close" 
                stroke={strokeColor} 
                fill={fillColor} 
                strokeWidth={2}
                isAnimationActive={false}
            />
            </AreaChart>
        ) : (
            <BarChart data={candleData}>
                <XAxis dataKey="time" hide={true} axisLine={false} tickLine={false} />
                <YAxis 
                    domain={[domainMin, domainMax]} 
                    orientation="right" 
                    tick={{fill: '#64748b', fontSize: 10}} 
                    axisLine={false} 
                    tickLine={false}
                    tickFormatter={(value) => value.toFixed(1)}
                    width={40}
                />
                <Tooltip content={<CustomTooltip />} cursor={{ stroke: '#64748b', strokeWidth: 1 }} />
                <Bar 
                    dataKey="range" 
                    shape={<CandlestickShape />} 
                    isAnimationActive={false}
                />
            </BarChart>
        )}
      </ResponsiveContainer>
    </div>
  );
};

