  // --- Main View ---

  if (view === 'DEPOSIT') return <DepositView />;
  if (view === 'WITHDRAW') return <WithdrawView />;
  if (view === 'TRADE_HISTORY') return <TradeHistoryView />;
  if (view === 'TRANSFER_HISTORY') return <TransferHistoryView />;
  if (view === 'SETTINGS') return <SettingsView />;
  if (view === 'FUNDING_HISTORY') return <FundingHistoryView />;

  return (
    <div className="p-4 h-full pb-24 overflow-y-auto no-scrollbar animate-in fade-in duration-200 bg-slate-50 dark:bg-slate-900">

      {/* Profile Header */}
      <div className="flex items-center justify-between mb-6 pt-2">
