                  <div className="flex items-center gap-3">
                     <span className="text-xl">🇭🇰</span>
                     <span className="dark:text-white text-slate-900">繁體中文</span>
                  </div>
                  {language === 'zh-TW' && <CheckCircle size={18} className="text-emerald-500" />}
