                     </div>
                 </div>
                 <button 
                    onClick={() => setShowFundingModal(false)}
                    className="w-full mt-6 py-3 bg-indigo-600 text-white font-bold rounded-lg shadow-lg shadow-indigo-500/20"
                 >
                    {t.confirmAction}
