                      </div>
                      <div className="flex-1 text-center">
                         <div className="text-indigo-400 text-[10px] mb-0.5">{t.marginRatio}</div>
                         <div className="font-mono font-bold dark:text-white text-slate-900">{metrics.newRatio.toFixed(2)}%</div>
