            const calculatedAmount = (maxBuyXAU * val) / 100;
            setAmount(calculatedAmount.toFixed(4));
        } else {
            const calculatedAmount = (maxBuyUSDC * val) / 100;
            setAmount(calculatedAmount.toFixed(2));
        }
    }
