export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, 
  equity, 
  totalPositionValue,
  externalWalletBalance,
  tradeHistory, 
  transferHistory,
  cashFlowHistory,
  onDeposit,
  onWithdraw,
  isConnected,
  onConnect,
  onDisconnect,
  language,
  setLanguage,
  theme,
  setTheme
