      {/* Trading Panel */}
      <div className="flex flex-1 min-h-[420px] dark:bg-slate-900 bg-white">
          <div className="w-[42%] border-r dark:border-slate-800 border-slate-200 flex flex-col">
             <div className="flex border-b dark:border-slate-800 border-slate-200">
                <button onClick={() => setActiveBookTab('book')} className={`flex-1 py-2 text-[10px] font-bold transition-colors border-b-2 ${activeBookTab === 'book' ? 'border-indigo-500 text-indigo-500' : 'border-transparent text-slate-400'}`}>{t.tabOrderBook}</button>
                <button onClick={() => setActiveBookTab('trades')} className={`flex-1 py-2 text-[10px] font-bold transition-colors border-b-2 ${activeBookTab === 'trades' ? 'border-indigo-500 text-indigo-500' : 'border-transparent text-slate-400'}`}>{t.tabRecentTrades}</button>
             </div>
             <div className="flex-1 overflow-hidden p-1">
                {activeBookTab === 'book' ? <OrderBook currentPrice={currentPrice} onPriceSelect={(p) => setLimitPrice(p)} /> : (
                   <div className="h-full overflow-y-auto no-scrollbar px-1">
                      <div className="grid grid-cols-2 text-[9px] dark:text-slate-500 text-slate-400 mb-1"><span>{t.price}</span><span className="text-right">{t.qty}</span></div>
                      {marketTrades.map((trade) => (
                          <div key={trade.id} className="grid grid-cols-2 text-[9px] font-mono py-0.5"><span className={trade.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}>{trade.price.toFixed(2)}</span><span className="text-right dark:text-slate-300 text-slate-700">{trade.size.toFixed(4)}</span></div>
                      ))}
                   </div>
                )}
             </div>
          </div>

          <div className="w-[58%] p-3 flex flex-col">
              <div className="flex gap-2 mb-3">
                 <div className="flex-1 bg-slate-100 dark:bg-slate-800 rounded-md p-0.5 flex">
                    <button onClick={() => setMarginMode(MarginMode.CROSS)} className={`flex-1 text-[10px] font-bold rounded py-1.5 transition-all ${marginMode === MarginMode.CROSS ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}>{t.cross}</button>
                    <button onClick={() => setMarginMode(MarginMode.ISOLATED)} className={`flex-1 text-[10px] font-bold rounded py-1.5 transition-all ${marginMode === MarginMode.ISOLATED ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}>{t.isolated}</button>
                 </div>
                 <button onClick={() => { setTempLeverage(leverage); setShowLeverageModal(true); }} className="flex-1 bg-slate-100 dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-md py-2 text-[10px] font-bold dark:text-white text-slate-900 flex items-center justify-center gap-1">{leverage}x <Edit2 size={8} /></button>
              </div>

              <div className="flex dark:bg-slate-800 bg-slate-100 rounded-lg p-0.5 mb-3">
                 <button onClick={() => setOrderType('MARKET')} className={`flex-1 py-1 text-[10px] font-bold rounded-md ${orderType === 'MARKET' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500'}`}>{t.market}</button>
                 <button onClick={() => setOrderType('LIMIT')} className={`flex-1 py-1 text-[10px] font-bold rounded-md ${orderType === 'LIMIT' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500'}`}>{t.limit}</button>
              </div>

              <div className="mb-3">
                 <label className="text-[10px] text-slate-500 block mb-1">{t.price}</label>
                 <div className="relative">
                     <input type="text" value={orderType === 'MARKET' ? `${t.market}` : limitPrice} onChange={(e) => setLimitPrice(e.target.value)} disabled={orderType === 'MARKET'} className={`w-full dark:bg-slate-800 bg-slate-50 border dark:border-slate-700 border-slate-200 rounded-lg py-2.5 px-3 text-sm font-mono focus:border-indigo-500 outline-none ${orderType === 'MARKET' ? 'text-slate-400' : 'dark:text-white text-slate-900'}`} />
                     {orderType === 'LIMIT' && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-500">USDC</span>}
                 </div>
              </div>

              <div className="mb-6">
                 <div className="flex justify-between mb-1"><label className="text-[10px] text-slate-500">{t.size}</label><span className="text-[10px] text-slate-500">{t.avail}: <span className="dark:text-white text-slate-900 font-mono">{balance.toFixed(2)}</span> USDC</span></div>
                 <div className="relative">
                     <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="数量" className="w-full dark:bg-slate-800 bg-slate-50 border dark:border-slate-700 border-slate-200 rounded-lg py-2.5 pl-3 pr-16 text-sm font-mono dark:text-white text-slate-900 outline-none focus:border-indigo-500" />
                     <div className="absolute right-0 top-0 bottom-0 flex items-center pr-2">
                        <select value={sizeUnit} onChange={(e) => setSizeUnit(e.target.value as any)} className="bg-transparent border-none text-[10px] font-bold focus:ring-0 cursor-pointer dark:text-white text-slate-900"><option value="XAU">XAU</option><option value="USDC">USDC</option></select>
                     </div>
                 </div>
              </div>

              {/* Slider */}
              <div className="mb-4 px-2 relative h-10 flex items-center">
                 <div className="absolute inset-x-0 h-1 bg-slate-200 dark:bg-slate-700 rounded-lg"><div className="h-full bg-indigo-500 rounded-l-lg" style={{ width: `${sizeSliderValue}%` }} /></div>
                 <input type="range" min="0" max="100" step="1" value={sizeSliderValue} onChange={(e) => {
                    const val = parseInt(e.target.value);
                    setSizeSliderValue(val);
                    if (val === 0) setAmount('');
                    else setAmount(((sizeUnit === 'XAU' ? maxBuyXAU : maxBuyUSDC) * val / 100).toFixed(4));
                 }} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
                 <div className="absolute h-8 w-8 bg-white dark:bg-slate-800 border-2 border-indigo-500 shadow-md rounded-full flex items-center justify-center z-10 pointer-events-none transition-transform" style={{ left: `${sizeSliderValue}%`, transform: 'translateX(-50%)' }}><span className="text-[10px] font-bold text-indigo-600 font-mono">{Math.round(sizeSliderValue)}%</span></div>
              </div>

              <div className="flex gap-2 mb-4">
                  <button onClick={() => handleTrade(Side.LONG)} className="flex-1 py-3 rounded-lg bg-emerald-600 text-white font-bold text-sm shadow-lg shadow-emerald-900/10 active:scale-95 transition-transform">{t.long.split('/')[1]}</button>
                  <button onClick={() => handleTrade(Side.SHORT)} className="flex-1 py-3 rounded-lg bg-rose-600 text-white font-bold text-sm shadow-lg shadow-rose-900/10 active:scale-95 transition-transform">{t.short.split('/')[1]}</button>
              </div>

              {/* Data Display Below Buttons */}
              <div className="space-y-2 border-t dark:border-slate-800 border-slate-100 pt-3">
                 <div className="flex justify-between text-[10px]">
                    <span className="text-slate-500">{t.marginRequired}</span>
                    <span className="dark:text-slate-300 text-slate-700 font-mono">{estimatedMargin.toFixed(2)} USDC</span>
                 </div>
                 <div className="flex justify-between text-[10px]">
                    <span className="text-slate-500">最大开仓数量</span>
                    <span className="dark:text-slate-300 text-slate-700 font-mono">{maxBuyXAU.toFixed(4)} XAU</span>
                 </div>
              </div>
          </div>
      </div>
    </div>
  );
};

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export enum PositionMode {
  ONE_WAY = 'ONE_WAY',
  HEDGE = 'HEDGE'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';
export type ChartType = 'line' | 'candle' | 'depth';
export type Timeframe = '1m' | '3m' | '5m' | '15m' | '30m' | '1H' | '2H' | '4H' | '8H' | '12H' | '1D' | '3D' | '1W' | '1M';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  filled: number;
  status: 'OPEN' | 'FILLED' | 'CANCELLED';
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketInfo {
  symbol: string;
  name: string;
  lastPrice: number;
  change24h: number;
  volume24h: number;
  fundingRate: number;
  leverage: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

export interface FillRecord {
  id: string;
  symbol: string;
  side: Side;
  price: number;
  size: number;
  value: number;
  fee: number;
  realizedPnl: number;
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING';
}

export type CashFlowType = 'TRANSACTION_FEE' | 'FUNDING_FEE' | 'REALIZED_PNL' | 'LIQUIDATION_FEE';

export interface CashFlowRecord {
  id: string;
  type: CashFlowType;
  symbol: string;
  amount: number;
  timestamp: number;
}

export interface MarketTrade {
  id: string;
  price: number;
  size: number;
  side: Side;
  time: string;
}

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, FillRecord, TransferRecord, MarginMode, Language, Theme, CashFlowRecord, MarketTrade, Timeframe, PositionMode, MarketInfo } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL, TRANSLATIONS, MOCK_MARKETS } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';
import { CheckCircle, AlertTriangle } from 'lucide-react';

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);

  // Settings State
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);

  // Symbol State
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];

  // Auth State
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 

  // Market Data State
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);

  // User Data State
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // History State
  const [fillHistory, setFillHistory] = useState<FillRecord[]>([]); 
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([]);
  const [cashFlowHistory, setCashFlowHistory] = useState<CashFlowRecord[]>([]);
  const [orderHistory, setOrderHistory] = useState<Order[]>([]);

  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, visible: true, type });
    setTimeout(() => {
        setToast(prev => ({ ...prev, visible: false }));
    }, 3000);
  };

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const m = MOCK_MARKETS.find(mk => mk.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(m.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]);
  };

  useEffect(() => {
    setCandles(generateInitialData(50, timeframe));
  }, [timeframe]);

  useEffect(() => {
    const mockCashFlow: CashFlowRecord[] = [];
    const now = Date.now();
    for(let i=1; i<=10; i++) {
        mockCashFlow.push({
            id: `funding-${i}`,
            type: 'FUNDING_FEE',
            symbol: activeSymbol,
            amount: (Math.random() > 0.5 ? 1 : -1) * (Math.random() * 2),
            timestamp: now - (i * 3600 * 1000)
        });
    }
    setCashFlowHistory(mockCashFlow.sort((a, b) => b.timestamp - a.timestamp));

    const mockFills: FillRecord[] = [];
    for(let i=0; i<15; i++) {
        const isBuy = Math.random() > 0.5;
        const price = currentPrice * (0.98 + Math.random() * 0.04);
        const size = parseFloat((Math.random() * 0.5 + 0.01).toFixed(3));
        const val = price * size;
        const fee = val * 0.001; 
        const isClose = Math.random() > 0.7; 
        const pnl = isClose ? (Math.random() * 50 - 20) : 0;

        mockFills.push({
            id: `fill-${i}`,
            symbol: activeSymbol,
            side: isBuy ? Side.LONG : Side.SHORT,
            price: price,
            size: size,
            value: val,
            fee: -fee,
            realizedPnl: pnl,
            timestamp: now - (i * 10000 * 1000)
        });
    }
    setFillHistory(mockFills.sort((a, b) => b.timestamp - a.timestamp));
  }, [activeSymbol]);

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;
      const now = new Date();

      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const volatility = (currentPrice * 0.0005); 
        const move = (Math.random() - 0.5) * volatility;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), {
          ...lastCandle,
          close: newPrice,
          high: Math.max(lastCandle.high, newPrice),
          low: Math.min(lastCandle.low, newPrice)
        }];
      });
      setCurrentPrice(newPrice);

      const tradeSide = Math.random() > 0.5 ? Side.LONG : Side.SHORT;
      const tradeSize = parseFloat((Math.random() * 2).toFixed(4));
      setMarketTrades(prev => [{
          id: Date.now().toString() + Math.random(),
          price: newPrice,
          size: tradeSize,
          side: tradeSide,
          time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
      }, ...prev].slice(0, 20));

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            setPositions(prev => [{
              id: Date.now().toString() + Math.random(),
              symbol: activeSymbol,
              side: order.side,
              size: order.amount,
              entryPrice: order.price, 
              leverage: 20, 
              unrealizedPnL: 0,
              marginMode: order.marginMode,
              isolatedMargin: order.marginMode === MarginMode.ISOLATED ? (order.amount * order.price / 20) : undefined
            }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);
            const fee = -(order.amount * order.price * 0.001);
            setCashFlowHistory(prev => [{ id: `fee-${Date.now()}`, type: 'TRANSACTION_FEE', symbol: activeSymbol, amount: fee, timestamp: Date.now() }, ...prev]);
            setFillHistory(prev => [{ id: `fill-${Date.now()}`, symbol: activeSymbol, side: order.side, price: order.price, size: order.amount, value: order.amount * order.price, fee: fee, realizedPnl: 0, timestamp: Date.now() }, ...prev]);
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol]); 

  const handleSetPositionMode = (mode: PositionMode) => {
      if (positions.length > 0 || orders.length > 0) {
          showToast(TRANSLATIONS[language].positionModeError, 'error');
          return;
      }
      setPositionMode(mode);
      showToast(TRANSLATIONS[language].notifications.positionModeUpdated, 'success');
  };

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) {
      setActiveTab(Tab.ACCOUNT);
      return;
    }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);
    if (type === 'MARKET') {
      setPositions(prev => [{ id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined }, ...prev]);
      const fee = -(size * price * 0.001);
      setCashFlowHistory(prev => [{ id: `fee-${Date.now()}`, type: 'TRANSACTION_FEE', symbol: activeSymbol, amount: fee, timestamp: Date.now() }, ...prev]);
      setFillHistory(prev => [{ id: `fill-${Date.now()}`, symbol: activeSymbol, side, price, size, value: size * price, fee, realizedPnl: 0, timestamp: Date.now() }, ...prev]);
      showToast(TRANSLATIONS[language].notifications.orderPlaced);
    } else {
      setOrders(prev => [{ id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode }, ...prev]);
      showToast(TRANSLATIONS[language].notifications.orderPlaced);
    }
  };

  const handleClosePosition = (id: string) => {
    const position = positions.find(p => p.id === id);
    if (!position) return;
    const priceDiff = currentPrice - position.entryPrice;
    const pnl = position.side === Side.LONG ? priceDiff * position.size : -priceDiff * position.size;
    let marginToReturn = position.marginMode === MarginMode.ISOLATED ? (position.isolatedMargin || 0) : (position.entryPrice * position.size / position.leverage);
    setBalance(prev => prev + marginToReturn + pnl);
    const fee = -(currentPrice * position.size * 0.001);
    setFillHistory(prev => [{ id: `fill-close-${position.id}`, symbol: position.symbol, side: position.side === Side.LONG ? Side.SHORT : Side.LONG, price: currentPrice, size: position.size, value: currentPrice * position.size, fee, realizedPnl: pnl, timestamp: Date.now() }, ...prev]);
    setCashFlowHistory(prev => [{ id: `pnl-${Date.now()}`, type: 'REALIZED_PNL', symbol: position.symbol, amount: pnl, timestamp: Date.now() }, { id: `fee-${Date.now()}`, type: 'TRANSACTION_FEE', symbol: position.symbol, amount: fee, timestamp: Date.now() }, ...prev]);
    setPositions(prev => prev.filter(p => p.id !== id));
    showToast(TRANSLATIONS[language].notifications.positionClosed);
  };

  const handleCloseAllPositions = () => {
    if (positions.length === 0) return;
    let totalCredit = 0;
    positions.forEach(position => {
        const priceDiff = currentPrice - position.entryPrice;
        const pnl = position.side === Side.LONG ? priceDiff * position.size : -priceDiff * position.size;
        let marginToReturn = position.marginMode === MarginMode.ISOLATED ? (position.isolatedMargin || 0) : (position.entryPrice * position.size / position.leverage);
        totalCredit += (marginToReturn + pnl);
        const fee = -(currentPrice * position.size * 0.001);
        setFillHistory(prev => [{ id: `fill-close-all-${position.id}`, symbol: position.symbol, side: position.side === Side.LONG ? Side.SHORT : Side.LONG, price: currentPrice, size: position.size, value: currentPrice * position.size, fee, realizedPnl: pnl, timestamp: Date.now() }, ...prev]);
        setCashFlowHistory(prev => [{ id: `pnl-${position.id}-${Date.now()}`, type: 'REALIZED_PNL', symbol: position.symbol, amount: pnl, timestamp: Date.now() }, { id: `fee-${position.id}-${Date.now()}`, type: 'TRANSACTION_FEE', symbol: position.symbol, amount: fee, timestamp: Date.now() }, ...prev]);
    });
    setBalance(prev => prev + totalCredit);
    setPositions([]);
    showToast(TRANSLATIONS[language].notifications.positionsClosed);
  };

  const handleUpdateMargin = (id: string, amount: number, type: 'ADD' | 'REMOVE') => {
    setPositions(prev => prev.map(pos => {
        if (pos.id === id && pos.marginMode === MarginMode.ISOLATED) {
            if (type === 'ADD' && balance >= amount) {
                setBalance(b => b - amount);
                return { ...pos, isolatedMargin: (pos.isolatedMargin || 0) + amount };
            } else if (type === 'REMOVE' && (pos.isolatedMargin || 0) > amount) {
                setBalance(b => b + amount);
                return { ...pos, isolatedMargin: (pos.isolatedMargin || 0) - amount };
            }
        }
        return pos;
    }));
    showToast(TRANSLATIONS[language].notifications.marginUpdated);
  };

  const handleCancelOrder = (id: string) => {
    const order = orders.find(o => o.id === id);
    if (!order) return;
    setBalance(prev => prev + (order.price * order.amount / 20));
    setOrders(prev => prev.filter(o => o.id !== id));
    setOrderHistory(prev => [{...order, status: 'CANCELLED'}, ...prev]);
    showToast(TRANSLATIONS[language].notifications.orderCancelled);
  };

  const handleCancelAllOrders = () => {
      orders.forEach(order => {
          setBalance(prev => prev + (order.price * order.amount / 20));
          setOrderHistory(prev => [{...order, status: 'CANCELLED'}, ...prev]);
      });
      setOrders([]);
      showToast(TRANSLATIONS[language].notifications.ordersCancelled);
  };

  const handleDeposit = (amount: number) => {
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: Date.now().toString(), type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED' }, ...prev]);
    showToast(TRANSLATIONS[language].notifications.depositSuccess);
  };

  const handleWithdraw = (amount: number) => {
    if (balance < amount) return false;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: Date.now().toString(), type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED' }, ...prev]);
    showToast(TRANSLATIONS[language].notifications.withdrawSuccess);
    return true;
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);
  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0);
  const equity = balance + marginLocked + orderMargin + totalUnrealizedPnL;
  const totalPositionValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPositionValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            symbol={activeSymbol}
            currentMarket={currentMarket}
            onSymbolChange={handleSymbolChange}
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance}
            marketTrades={marketTrades}
            onPlaceOrder={handlePlaceOrder}
            lang={language}
            timeframe={timeframe}
            onTimeframeChange={setTimeframe}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={handleUpdateMargin} onCloseAllPositions={handleCloseAllPositions} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={handleCancelOrder} onCancelAllOrders={handleCancelAllOrders} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView balance={balance} equity={equity} totalPositionValue={totalPositionValue} externalWalletBalance={externalWalletBalance} fillHistory={fillHistory} transferHistory={transferHistory} cashFlowHistory={cashFlowHistory} onDeposit={handleDeposit} onWithdraw={handleWithdraw} isConnected={isWalletConnected} onConnect={() => setIsWalletConnected(true)} onDisconnect={() => setIsWalletConnected(false)} language={language} setLanguage={setLanguage} theme={theme} setTheme={setTheme} positionMode={positionMode} onSetPositionMode={handleSetPositionMode} />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={setActiveTab} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

export default App;

