import { GoogleGenAI } from "@google/genai";
import { Candle } from "../types";

// Initialize Gemini
// Use named parameter and ensure correct initialization
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

export const analyzeMarket = async (data: Candle[], currentPrice: number): Promise<string> => {
  if (!process.env.API_KEY) {
    return "AI Analysis Unavailable: API Key missing.";
  }

  const recentCandles = data.slice(-10); // Analyze last 10 candles
  const trendDescription = recentCandles.map(c => 
    `Time: ${c.time}, Open: ${c.open.toFixed(2)}, Close: ${c.close.toFixed(2)}`
  ).join('\n');

  const prompt = `
    Act as a senior financial analyst for Gold (XAU/USD).
    Current Price: ${currentPrice.toFixed(2)}

    Recent 15-min candle data:
    ${trendDescription}

    Provide a very concise (max 30 words) technical analysis summary and a sentiment (Bullish/Bearish/Neutral) for a scalping trader. 
    Focus on price action. Do not give financial advice, just technical observation.
  `;

  try {
    // Use gemini-3-pro-preview for complex reasoning task
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    // Access response.text property directly
    return response.text || "Analysis complete.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Market analysis temporarily unavailable.";
  }
};

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export enum PositionMode {
  ONE_WAY = 'ONE_WAY',
  HEDGE = 'HEDGE'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';
export type ChartType = 'line' | 'candle' | 'depth';
export type Timeframe = '1m' | '3m' | '5m' | '15m' | '30m' | '1H' | '2H' | '4H' | '8H' | '12H' | '1D' | '3D' | '1W' | '1M';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number; // Specific margin for isolated positions
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  filled: number;
  status: 'OPEN' | 'FILLED' | 'CANCELLED';
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

// Deprecated: Old TradeRecord, replaced by FillRecord for detailed history
export interface TradeRecord {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  closePrice: number;
  pnl: number;
  timestamp: number;
}

export interface FillRecord {
  id: string;
  symbol: string;
  side: Side;
  price: number;
  size: number;
  value: number; // size * price
  fee: number;
  realizedPnl: number; // 0 for opening trades
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING' | 'REJECTED' | 'CANCELLED';
  network: string;
}

export type CashFlowType = 'TRANSACTION_FEE' | 'FUNDING_FEE' | 'REALIZED_PNL' | 'LIQUIDATION_FEE';

export interface CashFlowRecord {
  id: string;
  type: CashFlowType;
  symbol: string;
  amount: number;
  timestamp: number;
}

export interface MarketTrade {
  id: string;
  price: number;
  size: number;
  side: Side;
  time: string;
}

import React, { useState, useEffect } from 'react';
