                         {fill.side === Side.LONG ? t.long.split('/')[0] : t.short.split('/')[0]}
                      </span>
                    </div>
                    <div className="text-xs dark:text-slate-400 text-slate-500 mt-1 font-mono">
                      {new Date(fill.timestamp).toLocaleString()}
                    </div>
                  </div>
               </div>

               <div className="grid grid-cols-2 gap-y-3 gap-x-4 text-xs dark:text-slate-400 text-slate-500 pt-2 border-t dark:border-slate-700/50 border-slate-100 mt-2">
                 <div className="flex justify-between">
                    <span>{t.tradeHistoryFields.price}</span>
                    <span className="dark:text-slate-200 text-slate-700 font-mono">{fill.price.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between">
                    <span>{t.tradeHistoryFields.qty}</span>
                    <span className="dark:text-slate-200 text-slate-700 font-mono">{fill.size}</span>
                 </div>
                 <div className="flex justify-between">
                    <span>{t.tradeHistoryFields.value}</span>
                    <span className="dark:text-slate-200 text-slate-700 font-mono">{fill.value.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between">
                    <span>{t.tradeHistoryFields.fee}</span>
                    <span className="dark:text-slate-200 text-slate-700 font-mono">{fill.fee.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between col-span-2">
                    <span>{t.tradeHistoryFields.realizedPnl}</span>
                    <span className={`font-mono font-bold ${fill.realizedPnl >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                        {fill.realizedPnl.toFixed(2)}
                    </span>
                 </div>
               </div>
             </div>
           ))
        )}
      </div>
    </div>
  );

  const renderTransferHistoryView = () => (
    <div className="h-full flex flex-col bg-slate-50 dark:bg-slate-900 animate-in slide-in-from-right duration-200">
      <div className="flex items-center gap-3 p-4 border-b dark:border-slate-800 border-slate-200 sticky top-0 bg-slate-50 dark:bg-slate-900 z-10">
        <button onClick={() => setView('MAIN')} className="p-2 -ml-2 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full dark:text-white">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.transfers}</h2>
      </div>
      <div className="flex-1 overflow-y-auto no-scrollbar p-4 space-y-3 pb-24">
        {transferHistory.length === 0 ? (
           <div className="text-center dark:text-slate-500 text-slate-400 mt-10">No records yet</div>
        ) : (
           transferHistory.map((item) => (
             <div key={item.id} className="bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 p-4 rounded-xl shadow-sm">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${item.type === 'DEPOSIT' ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                      {item.type === 'DEPOSIT' ? <ArrowDownLeft size={20} /> : <ArrowUpRight size={20} />}
                    </div>
                    <div>
                      <div className="font-bold dark:text-white text-slate-900 text-sm">
                        {item.type === 'DEPOSIT' ? 'Deposit' : 'Withdraw'} USDC
                      </div>
                      <div className="text-xs dark:text-slate-500 text-slate-400">
                        {new Date(item.timestamp).toLocaleString()}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="font-mono font-bold dark:text-white text-slate-900">
                      {item.type === 'DEPOSIT' ? '+' : '-'}{item.amount.toFixed(2)}
                    </div>
                    <div className={`text-[10px] font-bold tracking-wider mt-0.5 ${
                      item.status === 'COMPLETED' ? 'text-emerald-500' : 
                      item.status === 'PENDING' ? 'text-amber-500' : 
                      'text-slate-500'
                    }`}>
                      {t.transferStatuses[item.status]}
                    </div>
                  </div>
                </div>

                <div className="mt-3 pt-2 border-t dark:border-slate-700/50 border-slate-100 flex items-center justify-between">
                   <div className="flex items-center gap-1.5 px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-700 text-[10px] dark:text-slate-300 text-slate-600 font-medium">
                      {item.network}
                   </div>
                   <a 
                     href={`https://arbiscan.io/tx/${item.id}`} 
                     target="_blank" 
                     rel="noopener noreferrer" 
                     className="text-indigo-500 hover:text-indigo-400 flex items-center gap-1 text-[10px] font-bold"
                   >
                     Explorer <ExternalLink size={10} />
                   </a>
                </div>
             </div>
           ))
        )}
      </div>
    </div>
  );

  if (view === 'DEPOSIT') return renderDepositView();
  if (view === 'WITHDRAW') return renderWithdrawView();
  if (view === 'FILL_HISTORY') return renderFillHistoryView();
  if (view === 'TRANSFER_HISTORY') return renderTransferHistoryView();
  if (view === 'SETTINGS') return renderSettingsView();
  if (view === 'CASH_FLOW_HISTORY') return renderCashFlowHistoryView();

  return (
    <div className="p-4 h-full pb-24 overflow-y-auto no-scrollbar animate-in fade-in duration-200 bg-slate-50 dark:bg-slate-900">

      {/* Profile Header */}
      <div className="flex items-center justify-between mb-6 pt-2">
         <div className="flex items-center gap-3">
             <div className="w-10 h-10 rounded-full dark:bg-slate-700 bg-slate-200 border dark:border-slate-600 border-slate-300 flex items-center justify-center dark:text-slate-300 text-slate-500">
                <User size={20} />
             </div>
             <div>
                <div className="flex items-center gap-2">
                   <span className="font-bold dark:text-white text-slate-900">{walletAddress}</span>
                   <button onClick={handleCopy} className="text-slate-400 hover:text-indigo-500 transition-colors">
                      {copied ? <CheckCircle size={14} className="text-emerald-500" /> : <Copy size={14} />}
                   </button>
                </div>
                <div className="flex items-center gap-1.5 mt-0.5">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] text-emerald-500 font-medium">Connected to {selectedWallet?.name || 'Wallet'}</span>
                </div>
             </div>
         </div>
      </div>

      {/* Total Asset Card */}
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl p-6 shadow-xl mb-6 text-white relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-10">
          <Shield size={100} />
        </div>
        <div className="relative z-10">
          <p className="text-indigo-200 text-sm mb-1">{t.totalEquity} (USD)</p>
          <h1 className="text-3xl font-mono font-bold tracking-tight mb-4">${equity.toFixed(2)}</h1>

          <div className="grid grid-cols-3 gap-2 border-t border-white/10 pt-4">
             <div>
                <p className="text-indigo-200 text-xs whitespace-nowrap">{t.avail}</p>
                <p className="font-mono font-medium text-sm mt-0.5">${balance.toFixed(2)}</p>
             </div>
             <div>
                <p className="text-indigo-200 text-xs whitespace-nowrap">{t.unrealizedPnL}</p>
                <p className={`font-mono font-medium text-sm mt-0.5 ${(equity - balance) >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>
                  {(equity - balance) >= 0 ? '+' : ''}{(equity - balance).toFixed(2)}
                </p>
             </div>
             <div>
                <p className="text-indigo-200 text-xs whitespace-nowrap">{t.totalPerpValue}</p>
                <p className="font-mono font-medium text-sm mt-0.5 text-slate-100">${totalPositionValue.toFixed(2)}</p>
             </div>
          </div>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-4 mb-6">
        <button 
          onClick={() => setView('DEPOSIT')}
          className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white hover:bg-slate-50 dark:hover:bg-slate-700 active:scale-95 py-4 rounded-xl text-sm font-bold border dark:border-slate-700 border-slate-200 transition-all shadow-sm"
        >
          <div className="bg-emerald-500/20 p-1.5 rounded-full text-emerald-500">
             <CreditCard size={18} />
          </div>
          {t.deposit}
        </button>
        <button 
          onClick={() => setView('WITHDRAW')}
          className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white hover:bg-slate-50 dark:hover:bg-slate-700 active:scale-95 py-4 rounded-xl text-sm font-bold border dark:border-slate-700 border-slate-200 transition-all shadow-sm"
        >
           <div className="bg-rose-500/20 p-1.5 rounded-full text-rose-500">
             <ArrowRightLeft size={18} />
          </div>
          {t.withdraw}
        </button>
      </div>

      {/* Menu List */}
      <div className="dark:bg-slate-800 bg-white rounded-xl overflow-hidden border dark:border-slate-700 border-slate-200 shadow-sm">
        <div 
          onClick={() => setView('FILL_HISTORY')}
          className="flex items-center justify-between p-4 dark:hover:bg-slate-700/50 hover:bg-slate-50 cursor-pointer border-b dark:border-slate-700 border-slate-100"
        >
           <div className="flex items-center gap-3">
             <History size={18} className="dark:text-slate-400 text-slate-500" />
             <span className="text-sm font-medium dark:text-slate-200 text-slate-800">{t.history}</span>
           </div>
           <div className="text-slate-400">›</div>
        </div>

        <div 
          onClick={() => setView('TRANSFER_HISTORY')}
          className="flex items-center justify-between p-4 dark:hover:bg-slate-700/50 hover:bg-slate-50 cursor-pointer border-b dark:border-slate-700 border-slate-100"
        >
           <div className="flex items-center gap-3">
             <ArrowRightLeft size={18} className="dark:text-slate-400 text-slate-500" />
             <span className="text-sm font-medium dark:text-slate-200 text-slate-800">{t.transfers}</span>
           </div>
           <div className="text-slate-400">›</div>
        </div>

        <div 
          onClick={() => setView('CASH_FLOW_HISTORY')}
          className="flex items-center justify-between p-4 dark:hover:bg-slate-700/50 hover:bg-slate-50 cursor-pointer border-b dark:border-slate-700 border-slate-100"
        >
           <div className="flex items-center gap-3">
             <Coins size={18} className="dark:text-slate-400 text-slate-500" />
             <span className="text-sm font-medium dark:text-slate-200 text-slate-800">{t.funding}</span>
           </div>
           <div className="text-slate-400">›</div>
        </div>

        <div 
          onClick={() => setView('SETTINGS')}
          className="flex items-center justify-between p-4 dark:hover:bg-slate-700/50 hover:bg-slate-50 cursor-pointer"
        >
           <div className="flex items-center gap-3">
             <Settings size={18} className="dark:text-slate-400 text-slate-500" />
             <span className="text-sm font-medium dark:text-slate-200 text-slate-800">{t.settings}</span>
           </div>
           <div className="text-slate-400">›</div>
        </div>
      </div>

      {/* Logout Button */}
      <div 
         onClick={onDisconnect}
         className="flex items-center justify-center p-4 mt-6 text-rose-500 font-bold cursor-pointer bg-rose-500/5 hover:bg-rose-500/10 border border-rose-500/20 rounded-xl transition-all"
      >
         <LogOut size={18} className="mr-2" />
         {t.disconnect}
      </div>

      <div className="mt-8 text-center">
         <p className="text-xs text-slate-500">GoldenDex Perp v1.0.0</p>
      </div>

    </div>
  );
};

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export enum PositionMode {
  ONE_WAY = 'ONE_WAY',
  HEDGE = 'HEDGE'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';
export type ChartType = 'line' | 'candle' | 'depth';
export type Timeframe = '1m' | '3m' | '5m' | '15m' | '30m' | '1H' | '2H' | '4H' | '8H' | '12H' | '1D' | '3D' | '1W' | '1M';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  filled: number;
  status: 'OPEN' | 'FILLED' | 'CANCELLED';
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketInfo {
  symbol: string;
  name: string;
  lastPrice: number;
  change24h: number;
  volume24h: number;
  fundingRate: number;
  leverage: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

export interface FillRecord {
  id: string;
  symbol: string;
  side: Side;
  price: number;
  size: number;
  value: number;
  fee: number;
  realizedPnl: number;
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING' | 'REJECTED' | 'CANCELLED';
  network: string;
}

export type CashFlowType = 'TRANSACTION_FEE' | 'FUNDING_FEE' | 'REALIZED_PNL' | 'LIQUIDATION_FEE';

export interface CashFlowRecord {
  id: string;
  type: CashFlowType;
  symbol: string;
  amount: number;
  timestamp: number;
}

export interface MarketTrade {
  id: string;
  price: number;
  size: number;
  side: Side;
  time: string;
}

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, FillRecord, TransferRecord, MarginMode, Language, Theme, CashFlowRecord, MarketTrade, Timeframe, PositionMode, MarketInfo } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL, TRANSLATIONS, MOCK_MARKETS } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';
import { CheckCircle, AlertTriangle } from 'lucide-react';

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [fillHistory, setFillHistory] = useState<FillRecord[]>([]); 
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([]);
  const [cashFlowHistory, setCashFlowHistory] = useState<CashFlowRecord[]>([]);
  const [orderHistory, setOrderHistory] = useState<Order[]>([]);
  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, visible: true, type });
    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
  };

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const m = MOCK_MARKETS.find(mk => mk.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(m.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]);
  };

  useEffect(() => {
    setCandles(generateInitialData(50, timeframe));
  }, [timeframe]);

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;
      const now = new Date();
      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const volatility = (currentPrice * 0.0005); 
        const move = (Math.random() - 0.5) * volatility;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), {
          ...lastCandle,
          close: newPrice,
          high: Math.max(lastCandle.high, newPrice),
          low: Math.min(lastCandle.low, newPrice)
        }];
      });
      setCurrentPrice(newPrice);
      const tradeSide = Math.random() > 0.5 ? Side.LONG : Side.SHORT;
      const tradeSize = parseFloat((Math.random() * 2).toFixed(4));
      setMarketTrades(prev => [{
          id: Date.now().toString() + Math.random(),
          price: newPrice,
          size: tradeSize,
          side: tradeSide,
          time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
      }, ...prev].slice(0, 20));

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            setPositions(prev => [{
              id: Date.now().toString() + Math.random(),
              symbol: activeSymbol,
              side: order.side,
              size: order.amount,
              entryPrice: order.price, 
              leverage: 20, 
              unrealizedPnL: 0,
              marginMode: order.marginMode,
              isolatedMargin: order.marginMode === MarginMode.ISOLATED ? (order.amount * order.price / 20) : undefined
            }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);
    if (type === 'MARKET') {
      setPositions(prev => [{ id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined }, ...prev]);
      showToast(TRANSLATIONS[language].notifications.orderPlaced);
    } else {
      setOrders(prev => [{ id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode }, ...prev]);
      showToast(TRANSLATIONS[language].notifications.orderPlaced);
    }
  };

  const handleClosePosition = (id: string) => {
    const position = positions.find(p => p.id === id);
    if (!position) return;
    const priceDiff = currentPrice - position.entryPrice;
    const pnl = position.side === Side.LONG ? priceDiff * position.size : -priceDiff * position.size;
    let marginToReturn = position.marginMode === MarginMode.ISOLATED ? (position.isolatedMargin || 0) : (position.entryPrice * position.size / position.leverage);
    setBalance(prev => prev + marginToReturn + pnl);
    setPositions(prev => prev.filter(p => p.id !== id));
    showToast(TRANSLATIONS[language].notifications.positionClosed);
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);
  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0);
  const equity = balance + marginLocked + orderMargin + totalUnrealizedPnL;
  const totalPositionValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPositionValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            symbol={activeSymbol}
            currentMarket={currentMarket}
            onSymbolChange={handleSymbolChange}
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance}
            marketTrades={marketTrades}
            onPlaceOrder={handlePlaceOrder}
            lang={language}
            timeframe={timeframe}
            onTimeframeChange={setTimeframe}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={() => {}} onCloseAllPositions={() => {}} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={() => {}} onCancelAllOrders={() => {}} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView balance={balance} equity={equity} totalPositionValue={totalPositionValue} externalWalletBalance={externalWalletBalance} fillHistory={[]} transferHistory={[]} cashFlowHistory={[]} onDeposit={() => {}} onWithdraw={() => true} isConnected={isWalletConnected} onConnect={() => setIsWalletConnected(true)} onDisconnect={() => setIsWalletConnected(false)} language={language} setLanguage={setLanguage} theme={theme} setTheme={setTheme} positionMode={positionMode} onSetPositionMode={setPositionMode} />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={setActiveTab} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

