                            {marginAction === 'ADD' ? t.avail : t.maxRemove}: 
                            <span className="dark:text-slate-200 text-slate-800 ml-1 font-mono">
                                {marginAction === 'ADD' ? balance.toFixed(2) : metrics.maxRemove.toFixed(2)}
