import React, { useState, useEffect } from 'react';
import { Position, Side, MarginMode, Language } from '../types';
import { TrendingUp, TrendingDown, AlertTriangle, Plus, Minus, X, Trash2, ArrowRight, ArrowRightLeft } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface PositionsViewProps {
  positions: Position[];
  currentPrice: number;
  equity: number;
  balance: number;
  maintenanceMargin: number;
  marginRatio: number;
  onClosePosition: (id: string, amount: number, price: number, type: 'MARKET' | 'LIMIT') => void;
  onUpdateMargin: (id: string, amount: number, type: 'ADD' | 'REMOVE') => void;
  onCloseAllPositions: () => void;
  lang: Language;
}

export const PositionsView: React.FC<PositionsViewProps> = ({ 
  positions, 
  currentPrice, 
  equity,
  balance,
  maintenanceMargin,
  marginRatio,
  onClosePosition,
  onUpdateMargin,
  onCloseAllPositions,
  lang
}) => {
  const t = TRANSLATIONS[lang];
  const [editingPosId, setEditingPosId] = useState<string | null>(null);
  const [marginAction, setMarginAction] = useState<'ADD' | 'REMOVE'>('ADD');

  // Close Position Modal State
  const [closingPosId, setClosingPosId] = useState<string | null>(null);
  const [closeOrderType, setCloseOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [closePrice, setClosePrice] = useState<string>(currentPrice.toFixed(2));
  const [closeAmount, setCloseAmount] = useState<string>('');
  const [closePercent, setClosePercent] = useState<number>(100);

  // Independent states for Add and Remove inputs
  const [addMarginInput, setAddMarginInput] = useState<string>('');
  const [removeMarginInput, setRemoveMarginInput] = useState<string>('');

  const [showCloseAllConfirm, setShowCloseAllConfirm] = useState(false);

  // Helper to get correct input state
  const currentMarginInput = marginAction === 'ADD' ? addMarginInput : removeMarginInput;
  const setMarginInput = (val: string) => {
      if (marginAction === 'ADD') setAddMarginInput(val);
      else setRemoveMarginInput(val);
  };

  const handleConfirmMargin = () => {
    if (editingPosId && currentMarginInput) {
        onUpdateMargin(editingPosId, parseFloat(currentMarginInput), marginAction);
        setEditingPosId(null);
        setAddMarginInput('');
        setRemoveMarginInput('');
    }
  };

  const handleConfirmCloseAll = () => {
      onCloseAllPositions();
      setShowCloseAllConfirm(false);
  };

  const closingPos = positions.find(p => p.id === closingPosId);

  // Handle Close Modal Price/Amount
  useEffect(() => {
    if (closingPos) {
       setCloseAmount((closingPos.size * closePercent / 100).toFixed(4));
       if (closeOrderType === 'MARKET') setClosePrice(currentPrice.toFixed(2));
    }
  }, [closingPosId, closePercent, closeOrderType, currentPrice]);

  const handleExecuteClose = () => {
    if (closingPosId && closeAmount) {
       onClosePosition(closingPosId, parseFloat(closeAmount), parseFloat(closePrice), closeOrderType);
       setClosingPosId(null);
    }
  };

  const getPositionMetrics = () => {
      const pos = positions.find(p => p.id === editingPosId);
      if (!pos || !pos.isolatedMargin) return null;

      const inputVal = parseFloat(currentMarginInput) || 0;
      const change = marginAction === 'ADD' ? inputVal : -inputVal;
      const currentMargin = pos.isolatedMargin;
      const newMargin = Math.max(0, currentMargin + change);
      const currentLeverage = (pos.entryPrice * pos.size) / currentMargin;
      const newLeverage = newMargin > 0 ? (pos.entryPrice * pos.size) / newMargin : 0;
      let currentLiq = pos.side === Side.LONG ? pos.entryPrice - (currentMargin / pos.size) : pos.entryPrice + (currentMargin / pos.size);
      let newLiq = pos.side === Side.LONG ? pos.entryPrice - (newMargin / pos.size) : pos.entryPrice + (newMargin / pos.size);
      const maintMarginReq = (pos.entryPrice * pos.size) * 0.01; 
      const currentRatio = (maintMarginReq / currentMargin) * 100;
      const newRatio = newMargin > 0 ? (maintMarginReq / newMargin) * 100 : 0;
      const maxRemove = Math.max(0, currentMargin - maintMarginReq);

      return { currentMargin, newMargin, currentLeverage, newLeverage, currentLiq, newLiq, currentRatio, newRatio, maxRemove };
  };

  const metrics = editingPosId ? getPositionMetrics() : null;

  const isMarginInputValid = () => {
      const val = parseFloat(currentMarginInput);
      if (isNaN(val) || val <= 0) return false;
      return marginAction === 'ADD' ? val <= balance : val <= (metrics?.maxRemove || 0);
  };

  const renderRiskHeader = () => (
    <div className="dark:bg-slate-800/50 bg-white/80 border-b dark:border-slate-800 border-slate-200 p-4 sticky top-0 backdrop-blur-md z-10">
      <div className="grid grid-cols-3 gap-2">
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginRatio}</div>
           <div className={`font-mono font-bold text-sm ${marginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>{marginRatio.toFixed(2)}%</div>
        </div>
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.maintMargin}</div>
           <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${maintenanceMargin.toFixed(2)}</div>
        </div>
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginBal}</div>
           <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${equity.toFixed(2)}</div>
        </div>
      </div>
      {marginRatio > 80 && (
         <div className="flex items-center gap-2 mt-3 text-rose-500 text-xs bg-rose-500/10 p-2 rounded-lg border border-rose-500/20">
           <AlertTriangle size={14} /><span>{t.riskWarning}</span>
         </div>
      )}
    </div>
  );

  if (positions.length === 0) {
    return (
      <div className="h-full flex flex-col">
        {renderRiskHeader()}
        <div className="flex-1 flex flex-col items-center justify-center dark:text-slate-500 text-slate-400">
          <div className="dark:bg-slate-800 bg-white p-4 rounded-full mb-4 shadow-sm border dark:border-slate-700 border-slate-200">
             <TrendingUp size={32} className="opacity-50" />
          </div>
          <p>{t.noPositions}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col dark:bg-slate-900 bg-slate-50 relative">
      {renderRiskHeader()}
      <div className="flex-1 p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar">
        <div className="flex justify-between items-center mb-2">
           <h2 className="dark:text-slate-400 text-slate-500 text-xs uppercase font-bold tracking-wider">{t.openPositions} ({positions.length})</h2>
           <button onClick={() => setShowCloseAllConfirm(true)} className="text-xs bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 px-2 py-1 rounded border border-rose-500/20 flex items-center gap-1"><Trash2 size={12} />{t.closeAll}</button>
        </div>

        {positions.map((pos) => {
          const priceDiff = currentPrice - pos.entryPrice;
          const pnl = pos.side === Side.LONG ? priceDiff * pos.size : -priceDiff * pos.size;
          const marginUsed = pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin ? pos.isolatedMargin : (pos.entryPrice * pos.size) / pos.leverage;
          const liquidationPrice = pos.side === Side.LONG ? pos.entryPrice - (marginUsed / pos.size) : pos.entryPrice + (marginUsed / pos.size);
          const pnlPercent = (pnl / marginUsed) * 100;
          const isProfit = pnl >= 0;

          return (
            <div key={pos.id} className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded ${pos.side === Side.LONG ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                    {pos.side === Side.LONG ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                  </div>
                  <div>
                    <h3 className="font-bold dark:text-white text-slate-900 flex items-center gap-2">
                      {pos.symbol}
                      <span className="text-[9px] dark:bg-slate-700 bg-slate-200 dark:text-slate-300 text-slate-600 px-1.5 py-0.5 rounded uppercase font-normal tracking-wide border dark:border-slate-600 border-slate-300">
                        {pos.marginMode === MarginMode.ISOLATED ? t.isolated : t.cross}
                      </span>
                    </h3>
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 inline-block ${pos.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                      {pos.leverage}x {pos.side === Side.LONG ? t.longLabel : t.shortLabel}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-lg font-mono font-bold ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>{isProfit ? '+' : ''}{pnl.toFixed(2)}</div>
                  <div className={`text-xs ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>{isProfit ? '+' : ''}{pnlPercent.toFixed(2)}%</div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-y-2 text-xs mb-4">
                <div className="dark:text-slate-400 text-slate-500">{t.size} (XAU)</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.size.toFixed(4)}</div>
                <div className="dark:text-slate-400 text-slate-500">{t.entryPrice}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.entryPrice.toFixed(2)}</div>
                <div className="dark:text-slate-400 text-slate-500">{t.markPrice}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{currentPrice.toFixed(2)}</div>
                <div className="dark:text-slate-400 text-slate-500">{t.liqPrice}</div>
                <div className="text-right text-orange-500 font-mono font-bold">{liquidationPrice > 0 ? liquidationPrice.toFixed(2) : '0.00'}</div>
                <div className="dark:text-slate-400 text-slate-500">{t.margin}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono flex items-center justify-end gap-2">
                    {marginUsed.toFixed(2)}
                    {pos.marginMode === MarginMode.ISOLATED && (
                        <button onClick={() => { setEditingPosId(pos.id); setMarginAction('ADD'); }} className="bg-indigo-500/20 text-indigo-500 p-0.5 rounded hover:bg-indigo-500/30"><Plus size={10} /></button>
                    )}
                </div>
              </div>
              <button onClick={() => setClosingPosId(pos.id)} className="w-full py-2.5 dark:bg-slate-700 bg-slate-100 dark:hover:bg-slate-600 hover:bg-slate-200 active:bg-slate-200 rounded-lg text-sm font-medium dark:text-slate-200 text-slate-700 transition-colors flex items-center justify-center gap-2">{t.closePos}</button>
            </div>
          );
        })}
      </div>

      {/* Close Position Modal - Styled like the screenshot */}
      {closingPos && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
             <div className="bg-[#1e222d] w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95 duration-200 border border-slate-800">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-xl text-white">{t.closeOperation.title}</h3>
                    <button onClick={() => setClosingPosId(null)} className="text-slate-400 hover:text-white"><X size={24}/></button>
                </div>

                <div className="flex justify-between items-start mb-6">
                    <div className="space-y-1">
                        <div className="text-xs text-slate-500">{t.closeOperation.tradingPair}</div>
                        <div className="font-bold flex items-center gap-2">
                            <span className="text-emerald-500 uppercase">{closingPos.symbol}</span>
                            <span className="text-slate-400">/</span>
                            <span className="text-emerald-500">{closingPos.side === Side.LONG ? t.longLabel : t.shortLabel}</span>
                        </div>
                    </div>
                    <div className="text-right space-y-1">
                        <div className="text-[10px] text-slate-500">{t.entryPrice}: {closingPos.entryPrice.toFixed(2)}</div>
                        <div className="text-[10px] text-slate-500">{t.markPrice}: {currentPrice.toFixed(2)}</div>
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-3 mb-6">
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500">{t.price}</label>
                        <div className="relative">
                           <input 
                             type="text" 
                             value={closeOrderType === 'MARKET' ? t.market : closePrice} 
                             onChange={(e) => setClosePrice(e.target.value)}
                             disabled={closeOrderType === 'MARKET'}
                             className={`w-full bg-[#131722] border border-slate-700 rounded-lg p-2.5 text-sm font-mono outline-none focus:border-[#d4a017] ${closeOrderType === 'MARKET' ? 'text-slate-500 cursor-not-allowed' : 'text-white'}`}
                           />
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500">{t.mode}</label>
                        <div 
                          className="w-full bg-[#131722] border border-slate-700 rounded-lg p-2.5 flex items-center justify-between cursor-pointer"
                          onClick={() => setCloseOrderType(closeOrderType === 'MARKET' ? 'LIMIT' : 'MARKET')}
                        >
                            <span className="text-sm text-white">{closeOrderType === 'MARKET' ? t.market : t.limit}</span>
                            <ArrowRightLeft size={14} className="text-slate-400" />
                        </div>
                    </div>
                </div>

                <div className="space-y-1.5 mb-6">
                    <label className="text-[10px] text-slate-500">{t.size}</label>
                    <div className="relative">
                        <input 
                           type="number" 
                           value={closeAmount} 
                           onChange={(e) => {
                               setCloseAmount(e.target.value);
                               const val = parseFloat(e.target.value);
                               if (!isNaN(val)) setClosePercent(Math.min(100, (val / closingPos.size) * 100));
                           }}
                           className="w-full bg-[#131722] border border-slate-700 rounded-lg p-3 text-sm text-white font-mono outline-none focus:border-[#d4a017]" 
                        />
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1.5 bg-[#1e222d] border border-slate-700 rounded px-2 py-0.5 pointer-events-none">
                            <span className="text-[10px] text-slate-400 font-bold uppercase">XAU</span>
                            <ArrowRightLeft size={10} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                {/* Percentage Slider - Styled like the screenshot */}
                <div className="mb-8 relative pt-6">
                    <div className="absolute top-0 flex flex-col items-center transition-all duration-200" style={{ left: `${closePercent}%`, transform: 'translateX(-50%)' }}>
                        <div className="bg-[#f2c94c] text-black text-[10px] font-bold px-1.5 py-0.5 rounded shadow-lg">{Math.round(closePercent)}%</div>
                    </div>
                    <div className="h-1 bg-slate-700 rounded-full relative overflow-hidden">
                        <div className="h-full bg-[#d4a017]" style={{ width: `${closePercent}%` }} />
                    </div>
                    <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={closePercent} 
                        onChange={(e) => setClosePercent(parseInt(e.target.value))}
                        className="absolute inset-x-0 -top-2 h-8 w-full opacity-0 cursor-pointer z-20"
                    />
                    <div className="absolute left-[calc(closePercent%)] top-1/2 -translate-y-1/2 -translate-x-1/2 w-4 h-4 bg-[#f2c94c] border-2 border-slate-800 rounded-full shadow-lg z-10 pointer-events-none" style={{ left: `${closePercent}%` }} />
                </div>

                <div className="space-y-2 mb-8">
                    <div className="flex justify-between text-xs text-slate-400">
                        <span>{t.closeOperation.positionSize}</span>
                        <span className="font-bold text-white">{closingPos.size} XAU</span>
                    </div>
                    <div className="flex justify-between text-xs text-slate-400">
                        <span>{t.closeOperation.estPnL}</span>
                        <span className={`font-bold ${((parseFloat(closePrice) - closingPos.entryPrice) * parseFloat(closeAmount) * (closingPos.side === Side.LONG ? 1 : -1)) >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                           {((parseFloat(closePrice) - closingPos.entryPrice) * parseFloat(closeAmount) * (closingPos.side === Side.LONG ? 1 : -1)).toFixed(2)} USDC
                        </span>
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setClosingPosId(null)} className="py-3 rounded-xl border border-slate-700 font-bold text-[#d4a017] text-base hover:bg-slate-800">{t.cancel}</button>
                    <button onClick={handleExecuteClose} className="py-3 rounded-xl bg-[#d4a017] text-[#1e222d] font-bold text-base shadow-lg shadow-[#d4a017]/10 active:scale-95 transition-transform">{t.confirm}</button>
                </div>
             </div>
          </div>
      )}

      {/* Existing Confirm Modal */}
      {showCloseAllConfirm && (
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
             <div className="bg-white dark:bg-slate-800 w-full max-w-xs rounded-2xl p-6 shadow-2xl text-center">
                <AlertTriangle size={48} className="text-rose-500 mx-auto mb-4" />
                <h3 className="font-bold text-lg dark:text-white text-slate-900 mb-2">{t.confirmCloseAll}</h3>
                <p className="text-sm dark:text-slate-400 text-slate-500 mb-6">{t.confirmCloseAllMsg}</p>
                <div className="grid grid-cols-2 gap-3">
                    <button onClick={() => setShowCloseAllConfirm(false)} className="py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">{t.cancel}</button>
                    <button onClick={handleConfirmCloseAll} className="py-2.5 rounded-xl bg-rose-600 text-white font-bold shadow-lg shadow-rose-500/20">{t.confirmAction}</button>
                </div>
             </div>
          </div>
      )}

      {/* Existing Margin Adjustment Modal */}
      {editingPosId && metrics && (
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
             <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-2xl p-4 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg dark:text-white text-slate-900">{t.addMargin}</h3>
                    <button onClick={() => setEditingPosId(null)} className="dark:text-slate-400 text-slate-500"><X size={20}/></button>
                </div>
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1 mb-4">
                    <button onClick={() => setMarginAction('ADD')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'ADD' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.add}</button>
                    <button onClick={() => setMarginAction('REMOVE')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'REMOVE' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.remove}</button>
                </div>
                <div className="mb-4">
                    <div className="flex justify-between mb-1">
                        <label className="text-xs text-slate-500 block">{t.amount} (USDC)</label>
                        <span className="text-xs text-slate-500">{marginAction === 'ADD' ? t.avail : t.maxRemove}: <span className="dark:text-slate-200 text-slate-800 ml-1 font-mono">{marginAction === 'ADD' ? balance.toFixed(2) : metrics.maxRemove.toFixed(2)}</span></span>
                    </div>
                    <div className="relative">
                        <input type="number" value={currentMarginInput} onChange={(e) => setMarginInput(e.target.value)} placeholder={t.quantity} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-3 pr-16 font-mono text-lg outline-none focus:border-indigo-500 dark:text-white" autoFocus />
                        <button onClick={() => setMarginInput((marginAction === 'ADD' ? balance : metrics.maxRemove).toFixed(2))} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-indigo-500">{t.max}</button>
                    </div>
                </div>
                <div className="bg-slate-50 dark:bg-slate-900 border dark:border-slate-700 border-slate-200 rounded-xl p-3 mb-4 space-y-3 text-xs">
                   <div className="flex items-center gap-2 mb-2"><span className="text-xs font-bold uppercase text-slate-400 flex-1 text-center">{t.before}</span><ArrowRight size={12} className="text-slate-400" /><span className="text-xs font-bold uppercase text-indigo-500 flex-1 text-center">{t.after}</span></div>
                   <div className="flex items-center"><div className="flex-1 text-center"><div className="text-slate-400 text-[10px]">{t.currentMargin}</div><div className="font-mono">{metrics.currentMargin.toFixed(2)}</div></div><div className="flex-1 text-center"><div className="text-indigo-400 text-[10px]">{t.afterMargin}</div><div className="font-mono font-bold">{metrics.newMargin.toFixed(2)}</div></div></div>
                   <div className="flex items-center"><div className="flex-1 text-center"><div className="text-slate-400 text-[10px]">{t.estLiqPrice}</div><div className="font-mono text-orange-500">{metrics.currentLiq.toFixed(2)}</div></div><div className="flex-1 text-center"><div className="text-indigo-400 text-[10px]">{t.estLiqPrice}</div><div className="font-mono font-bold text-orange-500">{metrics.newLiq.toFixed(2)}</div></div></div>
                </div>
                <div className="grid grid-cols-2 gap-3"><button onClick={() => setEditingPosId(null)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">{t.cancel}</button><button onClick={handleConfirmMargin} disabled={!isMarginInputValid()} className={`py-3 rounded-xl font-bold shadow-lg transition-all ${isMarginInputValid() ? 'bg-indigo-600 text-white shadow-indigo-500/20' : 'bg-slate-300 text-slate-500 cursor-not-allowed shadow-none'}`}>{t.confirmAction}</button></div>
             </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, FillRecord, TransferRecord, MarginMode, Language, Theme, CashFlowRecord, MarketTrade, Timeframe, PositionMode, MarketInfo } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL, TRANSLATIONS, MOCK_MARKETS } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';
import { CheckCircle, AlertTriangle } from 'lucide-react';

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);

  // Settings State
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);

  // Market State
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];

  // Auth State
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 

  // Market Data State
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);

  // User Data State
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // History State
  const [fillHistory, setFillHistory] = useState<FillRecord[]>([]);
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([]);
  const [cashFlowHistory, setCashFlowHistory] = useState<CashFlowRecord[]>([]);
  const [orderHistory, setOrderHistory] = useState<Order[]>([]);

  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, visible: true, type });
    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
  };

  // Populate Mock Data on Mount
  useEffect(() => {
    const now = Date.now();
    setFillHistory([
      { id: 'f1', symbol: 'XAUUSDC', side: Side.LONG, price: 2015.42, size: 0.5, value: 1007.71, fee: -0.50, realizedPnl: 12.50, timestamp: now - 3600000 * 2 },
      { id: 'f2', symbol: 'BTCUSDC', side: Side.SHORT, price: 65200.10, size: 0.01, value: 652.00, fee: -0.32, realizedPnl: -5.20, timestamp: now - 3600000 * 5 },
      { id: 'f3', symbol: 'ETHUSDC', side: Side.LONG, price: 3410.55, size: 0.1, value: 341.05, fee: -0.17, realizedPnl: 8.40, timestamp: now - 3600000 * 24 },
    ]);
    setTransferHistory([
      { id: 't1', type: 'DEPOSIT', amount: 1000.00, timestamp: now - 3600000 * 48, status: 'COMPLETED', network: 'Arbitrum One' },
      { id: 't2', type: 'WITHDRAW', amount: 200.00, timestamp: now - 3600000 * 72, status: 'COMPLETED', network: 'Arbitrum One' },
      { id: 't3', type: 'DEPOSIT', amount: 5000.00, timestamp: now - 3600000 * 120, status: 'COMPLETED', network: 'Arbitrum One' },
    ]);
    setCashFlowHistory([
      { id: 'c1', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.12, timestamp: now - 3600000 * 1 },
      { id: 'c2', type: 'TRANSACTION_FEE', symbol: 'XAUUSDC', amount: -0.50, timestamp: now - 3600000 * 2 },
      { id: 'c3', type: 'REALIZED_PNL', symbol: 'XAUUSDC', amount: 12.50, timestamp: now - 3600000 * 2 },
      { id: 'c4', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.11, timestamp: now - 3600000 * 9 },
    ]);
    setOrderHistory([
      { id: 'h1', symbol: 'XAUUSDC', side: Side.LONG, type: 'LIMIT', price: 2025.50, amount: 0.5, filled: 0.5, status: 'FILLED', timestamp: now - 3600000 * 3, marginMode: MarginMode.CROSS },
      { id: 'h2', symbol: 'BTCUSDC', side: Side.SHORT, type: 'LIMIT', price: 67000.00, amount: 0.1, filled: 0, status: 'CANCELLED', timestamp: now - 3600000 * 6, marginMode: MarginMode.ISOLATED },
    ]);
  }, []);

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const m = MOCK_MARKETS.find(mk => mk.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(m.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]);
  };

  useEffect(() => {
    setCandles(generateInitialData(50, timeframe));
  }, [timeframe]);

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;
      const now = new Date();
      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const volatility = 0.8; 
        const move = (Math.random() - 0.5) * volatility;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), { ...lastCandle, close: newPrice, high: Math.max(lastCandle.high, newPrice), low: Math.min(lastCandle.low, newPrice) }];
      });
      setCurrentPrice(newPrice);

      const tradeSide = Math.random() > 0.5 ? Side.LONG : Side.SHORT;
      const tradeSize = parseFloat((Math.random() * 2).toFixed(4));
      setMarketTrades(prev => [{ id: Date.now().toString() + Math.random(), price: newPrice, size: tradeSize, side: tradeSide, time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) }, ...prev].slice(0, 20));

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            const leverage = 20;
            const initialMargin = (order.amount * order.price) / leverage;
            setPositions(prev => [{ id: Date.now().toString() + Math.random(), symbol: activeSymbol, side: order.side, size: order.amount, entryPrice: order.price, leverage: 20, unrealizedPnL: 0, marginMode: order.marginMode, isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);

            // Log fill
            setFillHistory(prev => [{
               id: `f-${Date.now()}`,
               symbol: order.symbol,
               side: order.side,
               price: order.price,
               size: order.amount,
               value: order.amount * order.price,
               fee: -(order.amount * order.price * 0.0005),
               realizedPnl: 0,
               timestamp: Date.now()
            }, ...prev]);
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);
    if (type === 'MARKET') {
      const newPos: Position = { id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined };
      setPositions(prev => [newPos, ...prev]);
      setFillHistory(prev => [{
        id: `f-${Date.now()}`,
        symbol: activeSymbol,
        side,
        price,
        size,
        value: size * price,
        fee: -(size * price * 0.0005),
        realizedPnl: 0,
        timestamp: Date.now()
      }, ...prev]);
      showToast(TRANSLATIONS[language].notifications.orderPlaced);
    } else {
      const newOrder: Order = { id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode };
      setOrders(prev => [newOrder, ...prev]);
      showToast(TRANSLATIONS[language].notifications.orderPlaced);
    }
  };

  const handleClosePosition = (id: string, amountToClose: number, executionPrice: number, type: 'MARKET' | 'LIMIT') => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === 'LIMIT') {
        const limitOrder: Order = {
            id: `cl-${Date.now()}`,
            symbol: pos.symbol,
            side: pos.side === Side.LONG ? Side.SHORT : Side.LONG,
            type: 'LIMIT',
            price: executionPrice,
            amount: amountToClose,
            filled: 0,
            status: 'OPEN',
            timestamp: Date.now(),
            marginMode: pos.marginMode
        };
        setOrders(prev => [limitOrder, ...prev]);
        showToast(TRANSLATIONS[language].notifications.orderPlaced);
        return;
    }

    const priceDiff = executionPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? priceDiff * amountToClose : -priceDiff * amountToClose;

    let marginToReturn = (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) 
      ? (pos.isolatedMargin * (amountToClose / pos.size)) 
      : (pos.entryPrice * amountToClose) / pos.leverage;

    setBalance(prev => prev + marginToReturn + pnl);

    setFillHistory(prev => [{
      id: `f-close-${Date.now()}`,
      symbol: pos.symbol,
      side: pos.side === Side.LONG ? Side.SHORT : Side.LONG,
      price: executionPrice,
      size: amountToClose,
      value: executionPrice * amountToClose,
      fee: -(executionPrice * amountToClose * 0.0005),
      realizedPnl: pnl,
      timestamp: Date.now()
    }, ...prev]);

    setCashFlowHistory(prev => [{
      id: `cf-pnl-${Date.now()}`,
      type: 'REALIZED_PNL',
      symbol: pos.symbol,
      amount: pnl,
      timestamp: Date.now()
    }, ...prev]);

    if (amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
    } else {
        setPositions(prev => prev.map(p => {
            if (p.id === id) {
                const newSize = p.size - amountToClose;
                return { 
                  ...p, 
                  size: newSize, 
                  isolatedMargin: p.isolatedMargin ? p.isolatedMargin * (newSize / p.size) : undefined 
                };
            }
            return p;
        }));
    }
    showToast(TRANSLATIONS[language].notifications.positionClosed);
  };

  const handleDeposit = (amount: number) => {
    if (amount > externalWalletBalance) return;
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    showToast(TRANSLATIONS[language].notifications.depositSuccess);
  };

  const handleWithdraw = (amount: number) => {
    if (balance < amount) return false;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    showToast(TRANSLATIONS[language].notifications.withdrawSuccess);
    return true;
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);
  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0);
  const equity = balance + marginLocked + orderMargin + totalUnrealizedPnL;
  const totalPosValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPosValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            symbol={activeSymbol} currentMarket={currentMarket} onSymbolChange={handleSymbolChange} candles={candles} currentPrice={currentPrice} balance={balance} marketTrades={marketTrades} onPlaceOrder={handlePlaceOrder} lang={language} timeframe={timeframe} onTimeframeChange={setTimeframe} 
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={() => {}} onCloseAllPositions={() => {}} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))} onCancelAllOrders={() => setOrders([])} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView 
            balance={balance} equity={equity} totalPositionValue={totalPosValue} externalWalletBalance={externalWalletBalance} fillHistory={fillHistory} transferHistory={transferHistory} cashFlowHistory={cashFlowHistory} onDeposit={handleDeposit} onWithdraw={handleWithdraw} isConnected={isWalletConnected} onConnect={() => setIsWalletConnected(true)} onDisconnect={() => setIsWalletConnected(false)} language={language} setLanguage={setLanguage} theme={theme} setTheme={setTheme} positionMode={positionMode} onSetPositionMode={setPositionMode} 
          />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={setActiveTab} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

export default App;

