                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.connection.selectWallet}</h2>
                        <button onClick={() => setLoginStep('INITIAL')} className="p-1 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 dark:text-slate-400">
                            <X size={20} />
                        </button>
                    </div>
                    <div className="space-y-3 pb-8">
                        {WALLETS.map((wallet) => (
                            <button 
                                key={wallet.id}
