            {withdrawStatus === 'IDLE' && t.confirm}
          </button>
        </div>
      </div>
    </div>
  );

  const renderFillHistoryView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-300">
