        <path d="M4.5 2.5L7.5 5.5L3.5 10.5L1.5 4.5L4.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <path d="M16 23.5L9 28.5L23 28.5L16 23.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        <path d="M9 11.5L5 17.5L9 28.5L16 23.5L23 28.5L27 17.5L23 11.5L16 16.5L9 11.5Z" fill="#F6851B" stroke="#F6851B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
      </svg>
    )
  },
  { 
    id: 'walletconnect', 
    name: 'WalletConnect', 
    color: '#3B99FC',
    icon: (
       <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none" xmlns="http://www.w3.org/2000/svg">
         <path d="M26 11C23 8 19 6 16 6C13 6 9 8 6 11" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/>
         <circle cx="8" cy="18" r="3" fill="#3B99FC"/>
         <circle cx="24" cy="18" r="3" fill="#3B99FC"/>
         <path d="M16 21V26" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/>
       </svg>
    )
  },
  { 
    id: 'okx', 
    name: 'OKX Wallet', 
    color: '#000000', 
    icon: (
        <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect width="32" height="32" rx="6" fill="currentColor" className="text-black dark:text-white"/>
            <path d="M8 8H12V12H8V8Z" fill="currentColor" className="text-white dark:text-black"/>
            <path d="M20 8H24V12H20V8Z" fill="currentColor" className="text-white dark:text-black"/>
            <path d="M8 20H12V24H8V20Z" fill="currentColor" className="text-white dark:text-black"/>
            <path d="M20 20H24V24H20V20Z" fill="currentColor" className="text-white dark:text-black"/>
            <path d="M14 14H18V18H14V14Z" fill="currentColor" className="text-white dark:text-black"/>
        </svg>
    )
  },
  { 
    id: 'binance', 
    name: 'Binance Wallet', 
    color: '#F0B90B',
    icon: (
        <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none" xmlns="http://www.w3.org/2000/svg">
             <path d="M16 6L22 12L16 18L10 12L16 6Z" fill="#F0B90B"/>
             <path d="M10 12L4 18L10 24L16 18L10 12Z" fill="#F0B90B"/>
             <path d="M22 12L28 18L22 24L16 18L22 12Z" fill="#F0B90B"/>
             <path d="M16 18L22 24L16 30L10 24L16 18Z" fill="#F0B90B"/>
             <circle cx="16" cy="18" r="2" fill="#1e293b"/>
        </svg>
    )
  },
];

export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, 
  equity, 
  totalPositionValue,
  externalWalletBalance,
  fillHistory, 
  transferHistory,
  cashFlowHistory,
  onDeposit,
  onWithdraw,
  isConnected,
  onConnect,
  onDisconnect,
  language,
  setLanguage,
  theme,
  setTheme,
  positionMode,
  onSetPositionMode
}) => {
  const [view, setView] = useState<ViewState>('MAIN');
  const [loginStep, setLoginStep] = useState<LoginStep>('INITIAL');
  const [selectedWallet, setSelectedWallet] = useState<typeof WALLETS[0] | null>(null);

  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [copied, setCopied] = useState(false);
  const [depositStatus, setDepositStatus] = useState<'IDLE' | 'APPROVING' | 'DEPOSITING' | 'SUCCESS'>('IDLE');
  const [withdrawStatus, setWithdrawStatus] = useState<'IDLE' | 'WITHDRAWING' | 'SUCCESS'>('IDLE');

  // Filter for Cash Flow
  const [cashFlowFilter, setCashFlowFilter] = useState<CashFlowType | 'ALL'>('ALL');

  const t = TRANSLATIONS[language];

  // Mock Wallet Address
  const walletAddress = "0x71C7...9A23";

  // Reset login flow when disconnected
  useEffect(() => {
    if (!isConnected) {
        setLoginStep('INITIAL');
        setSelectedWallet(null);
    }
  }, [isConnected]);

  const handleCopy = () => {
    navigator.clipboard.writeText("0x71C762B34567890123456789A23"); 
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDepositChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) {
      setDepositAmount(value);
    }
  };

  const handleWithdrawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) {
      setWithdrawAmount(value);
    }
  };

  const handleWeb3Deposit = async () => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0 || val > externalWalletBalance) return;

    setDepositStatus('APPROVING');
    await new Promise(resolve => setTimeout(resolve, 1500));
    setDepositStatus('DEPOSITING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    onDeposit(val);
    setDepositStatus('SUCCESS');

    setTimeout(() => {
        setDepositStatus('IDLE');
        setDepositAmount('');
        setView('MAIN');
    }, 1500);
  };

  const handleWeb3Withdraw = async () => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= 0 || val > balance) return;

    setWithdrawStatus('WITHDRAWING');
    await new Promise(resolve => setTimeout(resolve, 2000));

    const success = onWithdraw(val);
    if (success) {
        setWithdrawStatus('SUCCESS');
        setTimeout(() => {
            setWithdrawStatus('IDLE');
            setWithdrawAmount('');
            setView('MAIN');
        }, 1500);
    } else {
        setWithdrawStatus('IDLE');
    }
  };

  // Login Flow Handlers
  const handleWalletSelect = (wallet: typeof WALLETS[0]) => {
      setSelectedWallet(wallet);
      setLoginStep('CONNECTING');
      // Simulate connection delay
      setTimeout(() => {
          setLoginStep('SIGNING');
      }, 1500);
  };

  const handleSignMessage = () => {
      setLoginStep('VERIFYING');
      // Simulate signing and verification delay
      setTimeout(() => {
          onConnect();
          // Reset internal state after success (though component might unmount or change view)
          setTimeout(() => {
             setLoginStep('INITIAL');
             setSelectedWallet(null);
          }, 500);
      }, 1500);
  };

  // --- Connect Wallet Screen & Login Flow ---
  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-6 dark:bg-slate-900 bg-slate-50 relative overflow-hidden">
        {/* Background Decoration */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
            <div className="absolute top-[-10%] right-[-10%] w-64 h-64 bg-indigo-500/10 rounded-full blur-3xl"></div>
            <div className="absolute bottom-[-10%] left-[-10%] w-64 h-64 bg-amber-500/10 rounded-full blur-3xl"></div>
        </div>

        {/* Initial Connect Screen */}
        {loginStep === 'INITIAL' && (
             <div className="flex flex-col items-center justify-center animate-in fade-in zoom-in duration-500 z-10 w-full max-w-sm">
                <div className="w-24 h-24 bg-gradient-to-tr from-indigo-500/20 to-amber-500/20 rounded-3xl flex items-center justify-center mb-8 border border-white/10 shadow-2xl backdrop-blur-sm relative">
                    <Wallet size={48} className="text-indigo-500 relative z-10" />
                    <div className="absolute inset-0 bg-white/5 rounded-3xl animate-pulse"></div>
                </div>
                <h1 className="text-3xl font-bold dark:text-white text-slate-900 mb-3 tracking-tight">{t.connect}</h1>
                <p className="dark:text-slate-400 text-slate-600 text-center mb-12 text-sm leading-relaxed">
                   {t.connection.desc}
                </p>

                <button
                    onClick={() => setLoginStep('SELECT_WALLET')}
                    className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-600/20 transition-all active:scale-95 flex items-center justify-center gap-2 group"
                >
                    {t.connect}
                    <ChevronRight size={18} className="group-hover:translate-x-1 transition-transform" />
                </button>
                <div className="mt-6 flex items-center gap-2 text-[10px] text-slate-400">
                    <Shield size={12} />
                    <span>{t.connection.secureInfo}</span>
                </div>
            </div>
        )}

        {/* Wallet Selection Modal (Bottom Sheet Style) */}
        {loginStep === 'SELECT_WALLET' && (
            <div className="absolute inset-0 z-20 flex items-end justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-t-3xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.connection.selectWallet}</h2>
                        <button onClick={() => setLoginStep('INITIAL')} className="p-1 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 dark:text-slate-400">
                            <X size={20} />
                        </button>
                    </div>
                    <div className="space-y-3 pb-8">
                        {WALLETS.map((wallet) => (
                            <button 
                                key={wallet.id}
                                onClick={() => handleWalletSelect(wallet)}
                                className="w-full flex items-center justify-between p-4 rounded-xl border dark:border-slate-700 border-slate-100 dark:bg-slate-700/50 bg-slate-50 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors group"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-lg flex items-center justify-center bg-white shadow-sm border border-slate-100">
                                        {wallet.icon}
                                    </div>
                                    <span className="font-bold dark:text-slate-200 text-slate-800">{wallet.name}</span>
                                </div>
                                <ChevronRight size={18} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {/* Connecting Loader */}
        {loginStep === 'CONNECTING' && selectedWallet && (
             <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-200">
                <div className="text-center">
                    <div className="relative w-20 h-20 mx-auto mb-6">
                         <div className="absolute inset-0 rounded-full border-4 border-slate-700"></div>
                         <div className="absolute inset-0 rounded-full border-4 border-t-indigo-500 border-r-transparent border-b-transparent border-l-transparent animate-spin"></div>
                         <div className="absolute inset-0 flex items-center justify-center">
                             <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm p-1">
                                {selectedWallet.icon}
                             </div>
                         </div>
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">{t.connection.connecting}...</h3>
                    <p className="text-slate-400 text-sm">{t.connection.approveIn} {selectedWallet.name}</p>
                </div>
             </div>
        )}

        {/* Signature Request */}
        {(loginStep === 'SIGNING' || loginStep === 'VERIFYING') && selectedWallet && (
            <div className="absolute inset-0 z-30 flex items-end sm:items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95 duration-300 relative overflow-hidden border dark:border-slate-700">

                    {/* Header */}
                    <div className="flex items-center gap-3 mb-6 border-b dark:border-slate-700 pb-4">
                         <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-sm border border-slate-100">
                             {selectedWallet.icon}
                         </div>
                         <div>
                             <h3 className="font-bold dark:text-white text-slate-900 text-sm">{t.connection.sigRequest}</h3>
                             <p className="text-[10px] text-slate-500">{selectedWallet.name}</p>
                         </div>
                    </div>

                    {/* Message Content */}
                    <div className="bg-slate-50 dark:bg-slate-900 rounded-xl p-4 mb-6 border dark:border-slate-700 font-mono text-xs">
                        <div className="text-slate-500 mb-2">{t.connection.msgToSign}:</div>
                        <div className="dark:text-slate-300 text-slate-700 leading-relaxed break-words">
                            Welcome to GoldenDex. By signing this message, you agree to the Terms of Service.
                            <br/><br/>
                            Nonce: {Date.now()}
                            <br/>
                            Timestamp: {new Date().toISOString()}
                        </div>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-3">
                         <button 
                            onClick={() => {
                                setLoginStep('INITIAL');
                                setSelectedWallet(null);
                            }}
                            disabled={loginStep === 'VERIFYING'}
                            className="flex-1 py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500 dark:text-slate-400 text-sm"
                         >
                            {t.connection.reject}
                         </button>
                         <button 
                            onClick={handleSignMessage}
                            disabled={loginStep === 'VERIFYING'}
                            className="flex-1 py-3 rounded-xl bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-600/20 text-sm flex items-center justify-center gap-2"
                         >
                             {loginStep === 'VERIFYING' ? (
                                 <>
                                    <Loader2 size={16} className="animate-spin" />
                                    {t.connection.verifying}
                                 </>
                             ) : (
                                 <>
                                    <Lock size={16} />
                                    {t.connection.sign}
                                 </>
                             )}
                         </button>
                    </div>

                    {loginStep === 'VERIFYING' && (
                        <div className="absolute inset-0 bg-white/50 dark:bg-slate-900/50 z-10 cursor-not-allowed"></div>
                    )}
                </div>
            </div>
        )}

      </div>
    );
  }

  const renderDepositView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-300">
      <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
          <ChevronLeft size={24} className="text-slate-500" />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.depositVaultTitle}</h2>
      </div>

      <div className="p-6">
        <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border dark:border-slate-700 border-slate-100 mb-6">
          <div className="flex justify-between mb-4">
            <span className="text-sm text-slate-500">{t.walletBalance}</span>
            <span className="text-sm font-mono dark:text-white text-slate-900">{externalWalletBalance.toFixed(2)} USDC</span>
          </div>
          <div className="relative mb-6">
            <input
              type="text"
              value={depositAmount}
              onChange={handleDepositChange}
              placeholder="0.00"
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-4 text-2xl font-mono outline-none focus:border-indigo-500 dark:text-white"
            />
            <button
              onClick={() => setDepositAmount(externalWalletBalance.toString())}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-bold text-indigo-500"
            >
              {t.max}
            </button>
          </div>

          <button
            onClick={handleWeb3Deposit}
            disabled={depositStatus !== 'IDLE' || !depositAmount || parseFloat(depositAmount) <= 0 || parseFloat(depositAmount) > externalWalletBalance}
            className={`w-full py-4 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${
              depositStatus === 'IDLE' && depositAmount && parseFloat(depositAmount) > 0 && parseFloat(depositAmount) <= externalWalletBalance
              ? 'bg-indigo-600 text-white shadow-indigo-600/20'
              : 'bg-slate-200 dark:bg-slate-700 text-slate-400 cursor-not-allowed'
            }`}
          >
            {depositStatus === 'APPROVING' && <><Loader2 size={18} className="animate-spin" /> {t.approving}</>}
            {depositStatus === 'DEPOSITING' && <><Loader2 size={18} className="animate-spin" /> {t.depositing}</>}
            {depositStatus === 'SUCCESS' && <><CheckCircle size={18} /> {t.depositSuccess}</>}
            {depositStatus === 'IDLE' && t.confirm}
          </button>
        </div>
      </div>
    </div>
  );

  const renderWithdrawView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-300">
      <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
          <ChevronLeft size={24} className="text-slate-500" />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.withdrawVaultTitle}</h2>
      </div>

      <div className="p-6">
        <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border dark:border-slate-700 border-slate-100 mb-6">
          <div className="flex justify-between mb-4">
            <span className="text-sm text-slate-500">{t.avail} (USDC)</span>
            <span className="text-sm font-mono dark:text-white text-slate-900">{balance.toFixed(2)} USDC</span>
          </div>
          <div className="relative mb-6">
            <input
              type="text"
              value={withdrawAmount}
              onChange={handleWithdrawChange}
              placeholder="0.00"
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-4 text-2xl font-mono outline-none focus:border-indigo-500 dark:text-white"
            />
            <button
              onClick={() => setWithdrawAmount(balance.toString())}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-bold text-indigo-500"
            >
              {t.max}
            </button>
          </div>

          <button
            onClick={handleWeb3Withdraw}
            disabled={withdrawStatus !== 'IDLE' || !withdrawAmount || parseFloat(withdrawAmount) <= 0 || parseFloat(withdrawAmount) > balance}
            className={`w-full py-4 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${
              withdrawStatus === 'IDLE' && withdrawAmount && parseFloat(withdrawAmount) > 0 && parseFloat(withdrawAmount) <= balance
              ? 'bg-indigo-600 text-white shadow-indigo-600/20'
              : 'bg-slate-200 dark:bg-slate-700 text-slate-400 cursor-not-allowed'
            }`}
          >
            {withdrawStatus === 'WITHDRAWING' && <><Loader2 size={18} className="animate-spin" /> {t.withdrawing}</>}
            {withdrawStatus === 'SUCCESS' && <><CheckCircle size={18} /> {t.withdrawSuccess}</>}
            {withdrawStatus === 'IDLE' && t.confirm}
          </button>
        </div>
      </div>
    </div>
  );

  const renderFillHistoryView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-300">
      <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
          <ChevronLeft size={24} className="text-slate-500" />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.history}</h2>
      </div>
      <div className="flex-1 p-4 space-y-3 overflow-y-auto no-scrollbar">
        {fillHistory.map((fill) => (
          <div key={fill.id} className="bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm">
            <div className="flex justify-between items-start mb-2">
              <div className="flex items-center gap-2">
                <span className={`text-sm font-bold ${fill.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}`}>
                  {fill.side === Side.LONG ? t.longLabel : t.shortLabel} {fill.symbol}
                </span>
              </div>
              <span className="text-[10px] text-slate-400">{new Date(fill.timestamp).toLocaleString()}</span>
            </div>
            <div className="grid grid-cols-2 gap-2 text-xs">
              <div className="text-slate-500">{t.tradeHistoryFields.price}: <span className="font-mono dark:text-slate-200 text-slate-800">{fill.price.toFixed(2)}</span></div>
              <div className="text-slate-500 text-right">{t.tradeHistoryFields.qty}: <span className="font-mono dark:text-slate-200 text-slate-800">{fill.size.toFixed(4)}</span></div>
              <div className="text-slate-500">{t.tradeHistoryFields.fee}: <span className="font-mono dark:text-slate-200 text-slate-800">{fill.fee.toFixed(2)}</span></div>
              <div className="text-slate-500 text-right">{t.tradeHistoryFields.realizedPnl}: <span className={`font-mono font-bold ${fill.realizedPnl >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>{fill.realizedPnl.toFixed(2)}</span></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderTransferHistoryView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-300">
      <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
          <ChevronLeft size={24} className="text-slate-500" />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.transfers}</h2>
      </div>
      <div className="flex-1 p-4 space-y-3 overflow-y-auto no-scrollbar">
        {transferHistory.map((tx) => (
          <div key={tx.id} className="bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm">
            <div className="flex justify-between items-center mb-2">
              <div className="flex items-center gap-2">
                <div className={`p-1.5 rounded-full ${tx.type === 'DEPOSIT' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                  {tx.type === 'DEPOSIT' ? <ArrowDownLeft size={16} /> : <ArrowUpRight size={16} />}
                </div>
                <span className="font-bold dark:text-white text-slate-900">{tx.type === 'DEPOSIT' ? t.deposit : t.withdraw}</span>
              </div>
              <span className={`text-[10px] px-2 py-0.5 rounded font-bold ${
                tx.status === 'COMPLETED' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-slate-100 dark:bg-slate-700 text-slate-500'
              }`}>
                {t.transferStatuses[tx.status]}
              </span>
            </div>
            <div className="flex justify-between items-end">
              <div className="text-xs text-slate-500">
                <div className="mb-1">{tx.network}</div>
                <div>{new Date(tx.timestamp).toLocaleString()}</div>
              </div>
              <div className="text-right">
                <div className="font-mono font-bold dark:text-white text-slate-900">{tx.amount.toFixed(2)} USDC</div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderSettingsView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-300">
      <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
          <ChevronLeft size={24} className="text-slate-500" />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.settings}</h2>
      </div>

      <div className="p-4 space-y-6">
        {/* Language */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">{t.language}</label>
          <div className="grid grid-cols-3 gap-2">
            {(['en', 'zh-CN', 'zh-TW'] as Language[]).map((lang) => (
              <button
                key={lang}
                onClick={() => setLanguage(lang)}
                className={`py-3 rounded-xl text-xs font-bold transition-all border ${
                  language === lang 
                  ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400'
                }`}
              >
                {lang === 'en' ? 'English' : lang === 'zh-CN' ? '简体中文' : '繁體中文'}
              </button>
            ))}
          </div>
        </div>

        {/* Theme */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">{t.theme}</label>
          <div className="grid grid-cols-2 gap-2">
            {(['light', 'dark'] as Theme[]).map((thm) => (
              <button
                key={thm}
                onClick={() => setTheme(thm)}
                className={`py-3 rounded-xl text-xs font-bold transition-all border flex items-center justify-center gap-2 ${
                  theme === thm 
                  ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400'
                }`}
              >
                {thm === 'light' ? <Sun size={14} /> : <Moon size={14} />}
                {t[thm]}
              </button>
            ))}
          </div>
        </div>

        {/* Position Mode */}
        <div className="space-y-3">
          <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">{t.positionMode}</label>
          <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
             {(['ONE_WAY', 'HEDGE'] as PositionMode[]).map((mode) => (
               <button
                 key={mode}
                 onClick={() => onSetPositionMode(mode)}
                 className={`w-full p-4 flex items-center justify-between text-left transition-colors ${
                   positionMode === mode ? 'bg-indigo-50 dark:bg-indigo-900/20' : ''
                 } border-b last:border-b-0 border-slate-100 dark:border-slate-700`}
               >
                 <div>
                    <div className={`text-sm font-bold ${positionMode === mode ? 'text-indigo-500' : 'dark:text-white text-slate-900'}`}>
                      {mode === 'ONE_WAY' ? t.oneWayMode : t.hedgeMode}
                    </div>
                 </div>
                 {positionMode === mode && <CheckCircle size={18} className="text-indigo-500" />}
               </button>
             ))}
          </div>
        </div>
      </div>
    </div>
  );

  const renderCashFlowHistoryView = () => (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in duration-200">
      <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10">
        <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
          <ChevronLeft size={24} className="text-slate-500" />
        </button>
        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.funding}</h2>
      </div>

      <div className="flex-1 p-4 space-y-3 overflow-y-auto no-scrollbar">
        {cashFlowHistory
          .filter(cf => cashFlowFilter === 'ALL' || cf.type === cashFlowFilter)
          .map((cf) => (
          <div key={cf.id} className="bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm">
            <div className="flex justify-between items-center">
              <div>
                <div className="text-xs font-bold dark:text-white text-slate-900 mb-1">{t.cashFlowTypes[cf.type]}</div>
                <div className="text-[10px] text-slate-500">{cf.symbol}</div>
              </div>
              <div className="text-right">
                <div className={`font-mono font-bold ${cf.amount >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                  {cf.amount >= 0 ? '+' : ''}{cf.amount.toFixed(2)} USDC
                </div>
                <div className="text-[10px] text-slate-400">{new Date(cf.timestamp).toLocaleString()}</div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  // Switch between sub-views based on ViewState
  if (view === 'DEPOSIT') return renderDepositView();
  if (view === 'WITHDRAW') return renderWithdrawView();
  if (view === 'FILL_HISTORY') return renderFillHistoryView();
  if (view === 'TRANSFER_HISTORY') return renderTransferHistoryView();
  if (view === 'SETTINGS') return renderSettingsView();
  if (view === 'CASH_FLOW_HISTORY') return renderCashFlowHistoryView();

  return (
    <div className="p-4 h-full pb-24 overflow-y-auto no-scrollbar animate-in fade-in duration-200 bg-slate-50 dark:bg-slate-900">
      <div className="flex items-center justify-between mb-6 pt-2">
         <div className="flex items-center gap-3">
             <div className="w-10 h-10 rounded-full dark:bg-slate-700 bg-slate-200 border dark:border-slate-600 border-slate-300 flex items-center justify-center dark:text-slate-300 text-slate-500">
                <User size={20} />
             </div>
             <div>
                <div className="flex items-center gap-2">
                   <span className="font-bold dark:text-white text-slate-900">{walletAddress}</span>
                   <button onClick={handleCopy} className="text-slate-400 hover:text-indigo-500 transition-colors">
                      {copied ? <CheckCircle size={14} className="text-emerald-500" /> : <Copy size={14} />}
                   </button>
                </div>
                <div className="flex items-center gap-1.5 mt-0.5">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-[10px] text-emerald-500 font-medium">Connected to {selectedWallet?.name || 'Wallet'}</span>
                </div>
             </div>
         </div>
      </div>

      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl p-6 shadow-xl mb-6 text-white relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-10"><Shield size={100} /></div>
        <div className="relative z-10">
          <p className="text-indigo-200 text-sm mb-1">{t.totalEquity} (USD)</p>
          <h1 className="text-3xl font-mono font-bold tracking-tight mb-4">${equity.toFixed(2)}</h1>
          <div className="grid grid-cols-3 gap-2 border-t border-white/10 pt-4">
             <div><p className="text-indigo-200 text-xs whitespace-nowrap">{t.avail}</p><p className="font-mono font-medium text-sm mt-0.5">${balance.toFixed(2)}</p></div>
             <div><p className="text-indigo-200 text-xs whitespace-nowrap">{t.unrealizedPnL}</p><p className={`font-mono font-medium text-sm mt-0.5 ${(equity - balance) >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{(equity - balance) >= 0 ? '+' : ''}{(equity - balance).toFixed(2)}</p></div>
