             <path d="M16 6L22 12L16 18L10 12L16 6Z" fill="#F0B90B"/>
             <path d="M10 12L4 18L10 24L16 18L10 12Z" fill="#F0B90B"/>
             <path d="M22 12L28 18L22 24L16 18L22 12Z" fill="#F0B90B"/>
             <path d="M16 18L22 24L16 30L10 24L16 18Z" fill="#F0B90B"/>
