export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, 
  equity, 
  totalPositionValue,
  externalWalletBalance,
  fillHistory, 
  transferHistory,
  cashFlowHistory,
  onDeposit,
  onWithdraw,
  isConnected,
  onConnect,
  onDisconnect,
  language,
  setLanguage,
  theme,
  setTheme,
  positionMode,
  onSetPositionMode
}) => {
  const [view, setView] = useState<ViewState>('MAIN');
  const [loginStep, setLoginStep] = useState<LoginStep>('INITIAL');
  const [selectedWallet, setSelectedWallet] = useState<typeof WALLETS[0] | null>(null);

  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [copied, setCopied] = useState(false);
  const [depositStatus, setDepositStatus] = useState<'IDLE' | 'APPROVING' | 'DEPOSITING' | 'SUCCESS'>('IDLE');
  const [withdrawStatus, setWithdrawStatus] = useState<'IDLE' | 'WITHDRAWING' | 'SUCCESS'>('IDLE');

  const [cashFlowFilter, setCashFlowFilter] = useState<CashFlowType | 'ALL'>('ALL');

  const t = TRANSLATIONS[language];
  const walletAddress = "0x71C7...9A23";

  useEffect(() => {
    if (!isConnected) {
        setLoginStep('INITIAL');
        setSelectedWallet(null);
    }
  }, [isConnected]);

  const handleCopy = () => {
    navigator.clipboard.writeText("0x71C762B34567890123456789A23"); 
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDepositChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setDepositAmount(value);
  };

  const handleWithdrawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setWithdrawAmount(value);
  };

  const handleWeb3Deposit = async () => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0 || val > externalWalletBalance) return;
    setDepositStatus('APPROVING');
    await new Promise(resolve => setTimeout(resolve, 1500));
    setDepositStatus('DEPOSITING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    onDeposit(val);
    setDepositStatus('SUCCESS');
    setTimeout(() => { setDepositStatus('IDLE'); setDepositAmount(''); setView('MAIN'); }, 1500);
  };

  const handleWeb3Withdraw = async () => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= 0 || val > balance) return;
    setWithdrawStatus('WITHDRAWING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    const success = onWithdraw(val);
    if (success) {
        setWithdrawStatus('SUCCESS');
        setTimeout(() => { setWithdrawStatus('IDLE'); setWithdrawAmount(''); setView('MAIN'); }, 1500);
    } else setWithdrawStatus('IDLE');
  };

  const handleWalletSelect = (wallet: typeof WALLETS[0]) => {
      setSelectedWallet(wallet);
      setLoginStep('CONNECTING');
      setTimeout(() => setLoginStep('SIGNING'), 1500);
  };

  const handleSignMessage = () => {
      setLoginStep('VERIFYING');
      setTimeout(() => {
          onConnect();
          setTimeout(() => { setLoginStep('INITIAL'); setSelectedWallet(null); }, 500);
      }, 1500);
  };

  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-6 dark:bg-slate-900 bg-slate-50 overflow-hidden">
        {loginStep === 'INITIAL' && (
             <div className="flex flex-col items-center animate-in fade-in zoom-in duration-500 w-full max-w-sm">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-2xl flex items-center justify-center mb-8 border border-indigo-500/20">
                    <Wallet size={40} className="text-indigo-500" />
                </div>
                <h1 className="text-2xl font-bold dark:text-white text-slate-900 mb-2">{t.connect}</h1>
                <p className="dark:text-slate-400 text-slate-500 text-center mb-10 text-sm leading-relaxed">{t.connection.desc}</p>
                <button onClick={() => setLoginStep('SELECT_WALLET')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-600/20 active:scale-95 transition-all">{t.connect}</button>
                <div className="mt-6 flex items-center gap-2 text-[10px] text-slate-400">
                    <Shield size={12} /><span>{t.connection.secureInfo}</span>
                </div>
            </div>
        )}

        {loginStep === 'SELECT_WALLET' && (
            <div className="absolute inset-0 z-20 flex items-end justify-center bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full rounded-t-2xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                    <div className="flex justify-between items-center mb-6">
                        <h2 className="text-lg font-bold dark:text-white text-slate-900">{t.connection.selectWallet}</h2>
                        <button onClick={() => setLoginStep('INITIAL')} className="p-1 dark:text-slate-400"><X size={20}/></button>
                    </div>
                    <div className="space-y-3 pb-8">
                        {WALLETS.map((w) => (
                            <button key={w.id} onClick={() => handleWalletSelect(w)} className="w-full flex items-center justify-between p-4 rounded-xl border dark:border-slate-700 border-slate-100 dark:bg-slate-700/50 bg-slate-50 hover:bg-slate-100 transition-colors">
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-lg flex items-center justify-center bg-white shadow-sm border border-slate-100">{w.icon}</div>
                                    <span className="font-bold dark:text-slate-200 text-slate-800">{w.name}</span>
                                </div>
                                <ChevronRight size={18} className="text-slate-400" />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {loginStep === 'CONNECTING' && selectedWallet && (
             <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-900/80 backdrop-blur-md animate-in fade-in">
                <div className="text-center">
                    <div className="relative w-16 h-16 mx-auto mb-6">
                         <div className="absolute inset-0 rounded-full border-4 border-slate-700"></div>
                         <div className="absolute inset-0 rounded-full border-4 border-t-indigo-500 animate-spin"></div>
                    </div>
                    <h3 className="text-lg font-bold text-white mb-2">{t.connection.connecting}...</h3>
                    <p className="text-slate-400 text-sm">{t.connection.approveIn} {selectedWallet.name}</p>
                </div>
             </div>
        )}

        {(loginStep === 'SIGNING' || loginStep === 'VERIFYING') && selectedWallet && (
            <div className="absolute inset-0 z-30 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full max-w-xs rounded-2xl p-6 shadow-2xl animate-in zoom-in-95 duration-300">
                    <div className="flex items-center gap-3 mb-4 pb-4 border-b dark:border-slate-700">
                         <div className="w-8 h-8 rounded-full border p-1 bg-white">{selectedWallet.icon}</div>
                         <h3 className="font-bold dark:text-white text-sm">{t.connection.sigRequest}</h3>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-900 rounded-lg p-3 mb-6 font-mono text-[10px] dark:text-slate-400">
                        {t.connection.msgToSign}:<br/>Welcome to GoldenDex. By signing this message, you agree to the Terms of Service.
                    </div>
                    <div className="flex gap-3">
                         <button onClick={() => setLoginStep('INITIAL')} className="flex-1 py-3 rounded-xl border dark:border-slate-700 text-slate-500 text-sm font-bold">{t.connection.reject}</button>
                         <button onClick={handleSignMessage} className="flex-1 py-3 rounded-xl bg-indigo-600 text-white font-bold text-sm flex items-center justify-center gap-2">{loginStep === 'VERIFYING' ? <Loader2 size={14} className="animate-spin"/> : <Lock size={14}/>}{loginStep === 'VERIFYING' ? t.connection.verifying : t.connection.sign}</button>
                    </div>
                </div>
            </div>
        )}
      </div>
    );
  }

  const renderHeader = (title: string) => (
    <div className="px-4 py-4 border-b dark:border-slate-800 border-slate-200 flex items-center gap-3 sticky top-0 bg-white dark:bg-slate-900 z-10">
      <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors">
        <ChevronLeft size={24} className="dark:text-white" />
      </button>
      <h2 className="text-lg font-bold dark:text-white text-slate-900">{title}</h2>
    </div>
  );

  if (view === 'DEPOSIT') return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.deposit)}
      <div className="p-6 space-y-6">
        <div><label className="text-xs font-bold text-slate-500 uppercase mb-2 block">{t.avail} (Wallet)</label><div className="text-2xl font-mono font-bold dark:text-white">{externalWalletBalance.toFixed(2)} USDC</div></div>
        <div><label className="text-xs font-bold text-slate-500 uppercase mb-2 block">{t.amount}</label><div className="relative"><input type="text" value={depositAmount} onChange={handleDepositChange} placeholder="0.00" className="w-full bg-slate-50 dark:bg-slate-800 border dark:border-slate-700 rounded-xl p-4 text-xl font-mono outline-none focus:border-indigo-500 dark:text-white" /><button onClick={() => setDepositAmount(externalWalletBalance.toString())} className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-bold text-indigo-500">{t.max}</button></div></div>
        <button onClick={handleWeb3Deposit} disabled={depositStatus !== 'IDLE' || !depositAmount} className={`w-full py-4 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${depositStatus === 'IDLE' ? 'bg-indigo-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500 cursor-not-allowed'}`}>{depositStatus === 'IDLE' ? t.confirm : <Loader2 size={18} className="animate-spin" />}</button>
      </div>
    </div>
  );

  if (view === 'WITHDRAW') return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.withdraw)}
      <div className="p-6 space-y-6">
        <div><label className="text-xs font-bold text-slate-500 uppercase mb-2 block">{t.avail} (Perp)</label><div className="text-2xl font-mono font-bold dark:text-white">{balance.toFixed(2)} USDC</div></div>
        <div><label className="text-xs font-bold text-slate-500 uppercase mb-2 block">{t.amount}</label><div className="relative"><input type="text" value={withdrawAmount} onChange={handleWithdrawChange} placeholder="0.00" className="w-full bg-slate-50 dark:bg-slate-800 border dark:border-slate-700 rounded-xl p-4 text-xl font-mono outline-none focus:border-indigo-500 dark:text-white" /><button onClick={() => setWithdrawAmount(balance.toString())} className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-bold text-indigo-500">{t.max}</button></div></div>
        <button onClick={handleWeb3Withdraw} disabled={withdrawStatus !== 'IDLE' || !withdrawAmount} className={`w-full py-4 rounded-xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${withdrawStatus === 'IDLE' ? 'bg-indigo-600 text-white' : 'bg-slate-200 dark:bg-slate-800 text-slate-500 cursor-not-allowed'}`}>{withdrawStatus === 'IDLE' ? t.confirm : <Loader2 size={18} className="animate-spin" />}</button>
      </div>
    </div>
  );

  if (view === 'FILL_HISTORY') return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900">
      {renderHeader(t.history)}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {fillHistory.map(f => (
          <div key={f.id} className="border-b dark:border-slate-800 pb-4 last:border-0"><div className="flex justify-between mb-1"><span className={`font-bold text-sm ${f.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}`}>{f.side} {f.symbol}</span><span className="text-[10px] text-slate-500">{new Date(f.timestamp).toLocaleDateString()}</span></div><div className="grid grid-cols-2 text-xs text-slate-500"><span>Price: {f.price.toFixed(2)}</span><span className="text-right">Qty: {f.size.toFixed(4)}</span><span>PnL: <span className={f.realizedPnl >= 0 ? 'text-emerald-500' : 'text-rose-500'}>{f.realizedPnl.toFixed(2)}</span></span><span className="text-right">Fee: {f.fee.toFixed(2)}</span></div></div>
        ))}
      </div>
    </div>
  );

  if (view === 'TRANSFER_HISTORY') return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900">
      {renderHeader(t.transfers)}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {transferHistory.map(tx => (
          <div key={tx.id} className="flex justify-between items-center border-b dark:border-slate-800 pb-4"><div><div className="font-bold text-sm dark:text-white uppercase">{tx.type} USDC</div><div className="text-[10px] text-slate-500">{new Date(tx.timestamp).toLocaleString()}</div></div><div className="text-right"><div className="font-mono font-bold dark:text-white">{tx.amount.toFixed(2)}</div><div className="text-[10px] text-emerald-500 font-bold uppercase">{tx.status}</div></div></div>
        ))}
      </div>
    </div>
  );

  if (view === 'CASH_FLOW_HISTORY') return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900">
      {renderHeader(t.funding)}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {cashFlowHistory.filter(cf => cashFlowFilter === 'ALL' || cf.type === cashFlowFilter).map(cf => (
          <div key={cf.id} className="flex justify-between items-center border-b dark:border-slate-800 pb-4"><div><div className="text-xs font-bold dark:text-white">{t.cashFlowTypes[cf.type]}</div><div className="text-[10px] text-slate-500">{cf.symbol}</div></div><div className="text-right"><div className={`font-mono font-bold ${cf.amount >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>{cf.amount.toFixed(4)}</div><div className="text-[10px] text-slate-500">{new Date(cf.timestamp).toLocaleTimeString()}</div></div></div>
        ))}
      </div>
    </div>
  );

  if (view === 'SETTINGS') return (
    <div className="flex flex-col h-full bg-white dark:bg-slate-900">
      {renderHeader(t.settings)}
      <div className="p-4 space-y-8">
        <section>
          <h3 className="text-xs font-bold text-slate-400 uppercase mb-3 px-1">{t.language}</h3>
          <div className="bg-slate-50 dark:bg-slate-800 rounded-xl overflow-hidden">
            {['en', 'zh-CN', 'zh-TW'].map((l) => (
              <button key={l} onClick={() => setLanguage(l as Language)} className={`w-full p-4 text-left border-b last:border-0 dark:border-slate-700 flex justify-between items-center ${language === l ? 'text-indigo-500' : 'dark:text-white'}`}><span>{l === 'en' ? 'English' : l === 'zh-CN' ? '简体中文' : '繁體中文'}</span>{language === l && <CheckCircle size={18}/>}</button>
            ))}
          </div>
        </section>
        <section>
          <h3 className="text-xs font-bold text-slate-400 uppercase mb-3 px-1">{t.theme}</h3>
          <div className="flex bg-slate-50 dark:bg-slate-800 rounded-xl p-1">
            <button onClick={() => setTheme('light')} className={`flex-1 py-3 rounded-lg flex items-center justify-center gap-2 font-bold ${theme === 'light' ? 'bg-white shadow text-indigo-500' : 'text-slate-400'}`}><Sun size={16}/>{t.light}</button>
            <button onClick={() => setTheme('dark')} className={`flex-1 py-3 rounded-lg flex items-center justify-center gap-2 font-bold ${theme === 'dark' ? 'dark:bg-slate-700 shadow text-indigo-400' : 'text-slate-400'}`}><Moon size={16}/>{t.dark}</button>
          </div>
        </section>
      </div>
    </div>
  );

  return (
    <div className="p-4 h-full pb-24 overflow-y-auto no-scrollbar bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      <div className="flex items-center gap-3 mb-6 pt-2">
         <div className="w-10 h-10 rounded-full dark:bg-slate-800 bg-slate-200 flex items-center justify-center dark:text-slate-300 text-slate-500"><User size={20} /></div>
         <div className="flex-1 overflow-hidden">
            <div className="flex items-center gap-2 font-bold dark:text-white text-slate-900 truncate">{walletAddress}<button onClick={handleCopy} className="text-slate-400 hover:text-indigo-500">{copied ? <CheckCircle size={14}/> : <Copy size={14}/>}</button></div>
            <div className="text-[10px] text-emerald-500 font-medium">Connected</div>
         </div>
      </div>

      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl p-6 shadow-xl mb-6 text-white">
        <p className="text-indigo-200 text-xs mb-1 uppercase tracking-wider">{t.totalEquity} (USD)</p>
        <h1 className="text-3xl font-mono font-bold tracking-tight mb-4">${equity.toFixed(2)}</h1>
        <div className="grid grid-cols-2 gap-4 border-t border-white/10 pt-4">
           <div><p className="text-indigo-200 text-[10px] uppercase">{t.avail}</p><p className="font-mono font-bold">${balance.toFixed(2)}</p></div>
           <div className="text-right"><p className="text-indigo-200 text-[10px] uppercase">{t.unrealizedPnL}</p><p className={`font-mono font-bold ${(equity - balance) >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{(equity - balance).toFixed(2)}</p></div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-6">
        <button onClick={() => setView('DEPOSIT')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm"><CreditCard size={18} className="text-indigo-500"/>{t.deposit}</button>
        <button onClick={() => setView('WITHDRAW')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm"><ArrowRightLeft size={18} className="text-indigo-500"/>{t.withdraw}</button>
      </div>

      <div className="dark:bg-slate-800 bg-white rounded-xl overflow-hidden border dark:border-slate-700 shadow-sm">
        <button onClick={() => setView('FILL_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700"><div className="flex items-center gap-3"><History size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.history}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('TRANSFER_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700"><div className="flex items-center gap-3"><ArrowRightLeft size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.transfers}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('CASH_FLOW_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700"><div className="flex items-center gap-3"><Coins size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.funding}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('SETTINGS')} className="w-full flex items-center justify-between p-4"><div className="flex items-center gap-3"><Settings size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.settings}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
      </div>
      <button onClick={onDisconnect} className="w-full py-4 mt-6 text-rose-500 font-bold bg-rose-500/5 rounded-xl border border-rose-500/10 transition-all flex items-center justify-center gap-2"><LogOut size={18}/>{t.disconnect}</button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, FillRecord, TransferRecord, MarginMode, Language, Theme, CashFlowRecord, MarketTrade, Timeframe, PositionMode, MarketInfo } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL, TRANSLATIONS, MOCK_MARKETS } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';
import { CheckCircle, AlertTriangle, Bell, X } from 'lucide-react';

interface InternalNotification {
  id: string;
  title: string;
  content: string;
}

const NotificationOverlay = ({ notifications, onRemove }: { notifications: InternalNotification[], onRemove: (id: string) => void }) => {
  return (
    <div className="fixed top-4 left-1/2 -translate-x-1/2 w-[90%] max-w-sm z-[100] space-y-3 pointer-events-none">
      {notifications.map((n) => (
        <div 
          key={n.id} 
          className="pointer-events-auto bg-slate-900/95 backdrop-blur-md border border-slate-700 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-top duration-300 relative group"
        >
           <button onClick={() => onRemove(n.id)} className="absolute top-3 right-3 text-slate-500 hover:text-white transition-colors opacity-0 group-hover:opacity-100">
             <X size={14} />
           </button>
           <div className="flex items-start gap-3">
              <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center shrink-0 text-indigo-500">
                <Bell size={16} />
              </div>
              <div className="flex-1 overflow-hidden">
                <h4 className="text-sm font-bold text-white mb-1">{n.title}</h4>
                <p className="text-xs text-slate-400 leading-relaxed whitespace-pre-line">{n.content}</p>
              </div>
           </div>
        </div>
      ))}
    </div>
  );
};

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [fillHistory, setFillHistory] = useState<FillRecord[]>([]);
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([]);
  const [cashFlowHistory, setCashFlowHistory] = useState<CashFlowRecord[]>([]);
  const [orderHistory, setOrderHistory] = useState<Order[]>([]);
  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });
  const [notifications, setNotifications] = useState<InternalNotification[]>([]);

  const t = TRANSLATIONS[language];

  const triggerNotification = (title: string, content: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [{ id, title, content }, ...prev].slice(0, 3));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 6000);
  };

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, visible: true, type });
    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
  };

  useEffect(() => {
    const now = Date.now();
    setFillHistory([
      { id: 'f1', symbol: 'XAUUSDC', side: Side.LONG, price: 2015.42, size: 0.5, value: 1007.71, fee: -0.50, realizedPnl: 12.50, timestamp: now - 3600000 * 2 },
      { id: 'f2', symbol: 'BTCUSDC', side: Side.SHORT, price: 65200.10, size: 0.01, value: 652.00, fee: -0.32, realizedPnl: -5.20, timestamp: now - 3600000 * 5 },
      { id: 'f3', symbol: 'ETHUSDC', side: Side.LONG, price: 3410.55, size: 0.1, value: 341.05, fee: -0.17, realizedPnl: 8.40, timestamp: now - 3600000 * 24 },
    ]);
    setTransferHistory([
      { id: 't1', type: 'DEPOSIT', amount: 1000.00, timestamp: now - 3600000 * 48, status: 'COMPLETED', network: 'Arbitrum One' },
      { id: 't2', type: 'WITHDRAW', amount: 200.00, timestamp: now - 3600000 * 72, status: 'COMPLETED', network: 'Arbitrum One' },
      { id: 't3', type: 'DEPOSIT', amount: 5000.00, timestamp: now - 3600000 * 120, status: 'COMPLETED', network: 'Arbitrum One' },
    ]);
  }, []);

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const m = MOCK_MARKETS.find(mk => mk.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(m.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]);
  };

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;
      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const move = (Math.random() - 0.5) * 0.8;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), { ...lastCandle, close: newPrice, high: Math.max(lastCandle.high, newPrice), low: Math.min(lastCandle.low, newPrice) }];
      });
      setCurrentPrice(newPrice);

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            const initialMargin = (order.amount * order.price) / 20;
            setPositions(prev => [{ id: Date.now().toString() + Math.random(), symbol: activeSymbol, side: order.side, size: order.amount, entryPrice: order.price, leverage: 20, unrealizedPnL: 0, marginMode: order.marginMode, isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);

            const fee = (order.amount * order.price * 0.0005);
            triggerNotification(
                t.appNotifications.limitFilled.title,
                t.appNotifications.limitFilled.content
                    .replace('{side}', order.side === Side.LONG ? t.long.split('/')[0] : t.short.split('/')[0])
                    .replace('{size}', order.amount.toString())
                    .replace('{price}', order.price.toFixed(2))
                    .replace('{fee}', `$${fee.toFixed(2)}`)
            );
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol, language]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPos: Position = { id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined };
      setPositions(prev => [newPos, ...prev]);
      const fee = (size * price * 0.0005);
      triggerNotification(
        t.appNotifications.marketFilled.title,
        t.appNotifications.marketFilled.content
            .replace('{side}', side === Side.LONG ? t.long.split('/')[0] : t.short.split('/')[0])
            .replace('{size}', size.toString())
            .replace('{price}', price.toFixed(2))
            .replace('{fee}', `$${fee.toFixed(2)}`)
      );
    } else {
      const newOrder: Order = { id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode };
      setOrders(prev => [newOrder, ...prev]);
      triggerNotification(
        t.appNotifications.orderSuccess.title,
        t.appNotifications.orderSuccess.content
            .replace('{symbol}', activeSymbol)
            .replace('{side}', side === Side.LONG ? t.longLabel : t.shortLabel)
            .replace('{type}', t.limit)
            .replace('{price}', price.toFixed(2))
            .replace('{size}', size.toString())
            .replace('{leverage}', leverage.toString())
      );
    }
  };

  const handleClosePosition = (id: string, amountToClose: number, executionPrice: number, type: 'MARKET' | 'LIMIT') => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === 'LIMIT') {
        const limitOrder: Order = { id: `cl-${Date.now()}`, symbol: pos.symbol, side: pos.side === Side.LONG ? Side.SHORT : Side.LONG, type: 'LIMIT', price: executionPrice, amount: amountToClose, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode: pos.marginMode };
        setOrders(prev => [limitOrder, ...prev]);
        showToast(TRANSLATIONS[language].notifications.orderPlaced);
        return;
    }

    const priceDiff = executionPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? priceDiff * amountToClose : -priceDiff * amountToClose;
    let marginToReturn = (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) ? (pos.isolatedMargin * (amountToClose / pos.size)) : (pos.entryPrice * amountToClose) / pos.leverage;
    setBalance(prev => prev + marginToReturn + pnl);

    if (amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        triggerNotification(
            t.appNotifications.posClosed.title,
            t.appNotifications.posClosed.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toString())
                .replace('{pnl}', pnl.toFixed(2))
        );
    } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose, isolatedMargin: p.isolatedMargin ? p.isolatedMargin * ((p.size - amountToClose) / p.size) : undefined } : p));
        triggerNotification(
            t.appNotifications.posReduced.title,
            t.appNotifications.posReduced.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toString())
                .replace('{remaining}', (pos.size - amountToClose).toString())
                .replace('{pnl}', pnl.toFixed(2))
        );
    }
  };

  const handleDeposit = (amount: number) => {
    if (amount > externalWalletBalance) return;
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.deposit.title,
        t.appNotifications.deposit.content.replace('{amount}', amount.toLocaleString())
    );
  };

  const handleWithdraw = (amount: number) => {
    if (balance < amount) return false;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.withdraw.title,
        t.appNotifications.withdraw.content.replace('{amount}', amount.toLocaleString()).replace('{address}', '0x71C7...9A23')
    );
    return true;
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);
  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0);
  const equity = balance + marginLocked + orderMargin + totalUnrealizedPnL;
  const totalPosValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPosValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <NotificationOverlay notifications={notifications} onRemove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView symbol={activeSymbol} currentMarket={currentMarket} onSymbolChange={handleSymbolChange} candles={candles} currentPrice={currentPrice} balance={balance} marketTrades={marketTrades} onPlaceOrder={handlePlaceOrder} lang={language} timeframe={timeframe} onTimeframeChange={setTimeframe} />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={() => {}} onCloseAllPositions={() => {}} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))} onCancelAllOrders={() => setOrders([])} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView balance={balance} equity={equity} totalPositionValue={totalPosValue} externalWalletBalance={externalWalletBalance} fillHistory={fillHistory} transferHistory={transferHistory} cashFlowHistory={cashFlowHistory} onDeposit={handleDeposit} onWithdraw={handleWithdraw} isConnected={isWalletConnected} onConnect={() => setIsWalletConnected(true)} onDisconnect={() => setIsWalletConnected(false)} language={language} setLanguage={setLanguage} theme={theme} setTheme={setTheme} positionMode={positionMode} onSetPositionMode={setPositionMode} />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={setActiveTab} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Wallet, CreditCard, ArrowRightLeft, Shield, Settings, History, ChevronLeft, Copy, CheckCircle, ExternalLink, ArrowDownLeft, ArrowUpRight, LogOut, User, Coins, Moon, Sun, Loader2, X, ChevronRight, Lock, Filter, Sliders, ArrowRight, ArrowLeftRight } from 'lucide-react';
