  balance, 
  equity, 
  totalPositionValue,
  externalWalletBalance,
  fillHistory, 
  transferHistory,
  cashFlowHistory,
  onDeposit,
  onWithdraw,
  isConnected,
  onConnect,
  onDisconnect,
  language,
  setLanguage,
  theme,
  setTheme,
  positionMode,
  onSetPositionMode
}) => {
