const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // Mock fill history
  const [fillHistory] = useState<FillRecord[]>([
    { id: 'f1', symbol: 'XAUUSDC', side: Side.LONG, price: 2015.42, size: 0.5, value: 1007.71, fee: -0.50, realizedPnl: 12.50, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'f2', symbol: 'BTCUSDC', side: Side.SHORT, price: 65200.10, size: 0.01, value: 652.00, fee: -0.32, realizedPnl: -5.20, timestamp: new Date('2025/12/22 04:36:43').getTime() },
    { id: 'f3', symbol: 'ETHUSDC', side: Side.LONG, price: 3410.55, size: 0.1, value: 341.05, fee: -0.17, realizedPnl: 8.40, timestamp: new Date('2025/12/21 09:36:43').getTime() }
  ]);

  // Initial transfer history mock data
  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([
    { id: 't1', type: 'DEPOSIT', amount: 1000.00, timestamp: new Date('2025/12/20 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
    { id: 't2', type: 'WITHDRAW', amount: 200.00, timestamp: new Date('2025/12/19 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
    { id: 't3', type: 'DEPOSIT', amount: 5000.00, timestamp: new Date('2025/12/17 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' }
  ]);

  const [cashFlowHistory] = useState<CashFlowRecord[]>([]);
  const [orderHistory, setOrderHistory] = useState<Order[]>([]);
  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });
  const [notifications, setNotifications] = useState<InternalNotification[]>([]);

  const t = TRANSLATIONS[language];

  const triggerNotification = (title: string, content: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [{ id, title, content }, ...prev].slice(0, 3));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 6000);
  };

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, visible: true, type });
    setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
  };

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const newMarket = MOCK_MARKETS.find(m => m.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(newMarket.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]); // Reset trades when symbol changes
  };

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  // Main Market Simulation Loop
  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;

      // Update Candles
      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const move = (Math.random() - 0.5) * 0.8;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), { ...lastCandle, close: newPrice, high: Math.max(lastCandle.high, newPrice), low: Math.min(lastCandle.low, newPrice) }];
      });
      setCurrentPrice(newPrice);

      // Add a random market trade for "Recent Trades" view
      if (Math.random() > 0.6) {
        setMarketTrades(prev => [
          {
            id: Date.now().toString(),
            price: newPrice + (Math.random() - 0.5) * 0.2,
            size: Math.random() * 2 + 0.01,
            side: Math.random() > 0.5 ? Side.LONG : Side.SHORT,
            time: new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })
          },
          ...prev.slice(0, 19)
        ]);
      }

      // Order Execution Logic
      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            const initialMargin = (order.amount * order.price) / 20;
            setPositions(prev => [{ id: Date.now().toString() + Math.random(), symbol: activeSymbol, side: order.side, size: order.amount, entryPrice: order.price, leverage: 20, unrealizedPnL: 0, marginMode: order.marginMode, isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);

            const fee = (order.amount * order.price * 0.0005);
            triggerNotification(
                t.appNotifications.limitFilled.title,
                t.appNotifications.limitFilled.content
                    .replace('{side}', order.side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
                    .replace('{size}', order.amount.toString())
                    .replace('{price}', order.price.toFixed(2))
                    .replace('{fee}', `$${fee.toFixed(2)}`)
            );
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol, language, t]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPos: Position = { id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined };
      setPositions(prev => [newPos, ...prev]);
      const fee = (size * price * 0.0005);
      triggerNotification(
        t.appNotifications.marketFilled.title,
        t.appNotifications.marketFilled.content
            .replace('{side}', side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
            .replace('{size}', size.toString())
            .replace('{price}', price.toFixed(2))
            .replace('{fee}', `$${fee.toFixed(2)}`)
      );
    } else {
      const newOrder: Order = { id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode };
      setOrders(prev => [newOrder, ...prev]);
      triggerNotification(
        t.appNotifications.orderSuccess.title,
        t.appNotifications.orderSuccess.content
            .replace('{symbol}', activeSymbol)
            .replace('{side}', side === Side.LONG ? t.longLabel : t.shortLabel)
            .replace('{type}', t.limit)
            .replace('{price}', price.toFixed(2))
            .replace('{size}', size.toString())
            .replace('{leverage}', leverage.toString())
      );
    }
  };

  const handleClosePosition = (id: string, amountToClose: number, executionPrice: number, type: 'MARKET' | 'LIMIT') => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === 'LIMIT') {
        const limitOrder: Order = { id: `cl-${Date.now()}`, symbol: pos.symbol, side: pos.side === Side.LONG ? Side.SHORT : Side.LONG, type: 'LIMIT', price: executionPrice, amount: amountToClose, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode: pos.marginMode };
        setOrders(prev => [limitOrder, ...prev]);
        showToast(TRANSLATIONS[language].notifications.orderPlaced);
        return;
    }

    const priceDiff = executionPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? priceDiff * amountToClose : -priceDiff * amountToClose;
    let marginToReturn = (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) ? (pos.isolatedMargin * (amountToClose / pos.size)) : (pos.entryPrice * amountToClose) / pos.leverage;
    setBalance(prev => prev + marginToReturn + pnl);

    if (amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        triggerNotification(
            t.appNotifications.posClosed.title,
            t.appNotifications.posClosed.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose, isolatedMargin: p.isolatedMargin ? p.isolatedMargin * ((p.size - amountToClose) / p.size) : undefined } : p));
        triggerNotification(
            t.appNotifications.posReduced.title,
            t.appNotifications.posReduced.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{remaining}', (pos.size - amountToClose).toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    }
  };

  const handleDeposit = (amount: number) => {
    if (amount > externalWalletBalance) return;
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.deposit.title,
        t.appNotifications.deposit.content.replace('{amount}', amount.toLocaleString())
    );
  };

  const handleWithdraw = (amount: number) => {
    if (balance < amount) return false;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.withdraw.title,
        t.appNotifications.withdraw.content.replace('{amount}', amount.toLocaleString()).replace('{address}', '0x71C7...9A23')
    );
    return true;
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);
  const orderMargin = orders.reduce((acc, ord) => acc + ((ord.price * ord.amount) / 20), 0);
  const equity = balance + marginLocked + orderMargin + totalUnrealizedPnL;
  const totalPosValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPosValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <NotificationOverlay notifications={notifications} onRemove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView symbol={activeSymbol} currentMarket={currentMarket} onSymbolChange={handleSymbolChange} candles={candles} currentPrice={currentPrice} balance={balance} marketTrades={marketTrades} onPlaceOrder={handlePlaceOrder} lang={language} timeframe={timeframe} onTimeframeChange={setTimeframe} />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={() => {}} onCloseAllPositions={() => {}} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={(id) => setOrders(o => o.filter(x => x.id !== id))} onCancelAllOrders={() => setOrders([])} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView balance={balance} equity={equity} totalPositionValue={totalPosValue} externalWalletBalance={externalWalletBalance} fillHistory={fillHistory} transferHistory={transferHistory} cashFlowHistory={cashFlowHistory} onDeposit={handleDeposit} onWithdraw={handleWithdraw} isConnected={isWalletConnected} onConnect={() => setIsWalletConnected(true)} onDisconnect={() => setIsWalletConnected(false)} language={language} setLanguage={setLanguage} theme={theme} setTheme={setTheme} positionMode={positionMode} onSetPositionMode={setPositionMode} />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={setActiveTab} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Wallet, CreditCard, ArrowRightLeft, Shield, Settings, History, ChevronLeft, Copy, CheckCircle, ExternalLink, ArrowDownLeft, ArrowUpRight, LogOut, User, Coins, Moon, Sun, Loader2, X, ChevronRight, Lock, Info } from 'lucide-react';
import { FillRecord, TransferRecord, Side, Language, Theme, CashFlowRecord, CashFlowType, PositionMode } from '../types';
import { TRANSLATIONS } from '../constants';

interface AccountViewProps {
  balance: number;
  equity: number;
  totalPositionValue: number;
  externalWalletBalance: number;
  fillHistory: FillRecord[];
  transferHistory: TransferRecord[];
  cashFlowHistory: CashFlowRecord[];
  onDeposit: (amount: number) => void;
  onWithdraw: (amount: number) => boolean;
  isConnected: boolean;
  onConnect: () => void;
  onDisconnect: () => void;
  language: Language;
  setLanguage: (lang: Language) => void;
  theme: Theme;
  setTheme: (theme: Theme) => void;
  positionMode: PositionMode;
  onSetPositionMode: (mode: PositionMode) => void;
}

type ViewState = 'MAIN' | 'DEPOSIT' | 'WITHDRAW' | 'FILL_HISTORY' | 'TRANSFER_HISTORY' | 'SETTINGS' | 'CASH_FLOW_HISTORY';
type LoginStep = 'INITIAL' | 'SELECT_WALLET' | 'CONNECTING' | 'SIGNING' | 'VERIFYING';

const WALLETS = [
  { id: 'metamask', name: 'MetaMask', color: '#F6851B', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><path d="M27.5 2.5L25.5 5.5L28.5 10.5L30.5 4.5L27.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M4.5 2.5L7.5 5.5L3.5 10.5L1.5 4.5L4.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M16 23.5L9 28.5L23 28.5L16 23.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M9 11.5L5 17.5L9 28.5L16 23.5L23 28.5L27 17.5L23 11.5L16 16.5L9 11.5Z" fill="#F6851B" stroke="#F6851B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg> },
  { id: 'walletconnect', name: 'WalletConnect', color: '#3B99FC', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><path d="M26 11C23 8 19 6 16 6C13 6 9 8 6 11" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/><circle cx="8" cy="18" r="3" fill="#3B99FC"/><circle cx="24" cy="18" r="3" fill="#3B99FC"/><path d="M16 21V26" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/></svg> },
  { id: 'okx', name: 'OKX Wallet', color: '#000000', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><rect width="32" height="32" rx="6" fill="currentColor" className="text-black dark:text-white"/><path d="M8 8H12V12H8V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 8H24V12H20V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M8 20H12V24H8V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 20H24V24H20V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M14 14H18V18H14V14Z" fill="currentColor" className="text-white dark:text-black"/></svg> },
  { id: 'binance', name: 'Binance Wallet', color: '#F0B90B', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><path d="M16 6L22 12L16 18L10 12L16 6Z" fill="#F0B90B"/><path d="M10 12L4 18L10 24L16 18L10 12Z" fill="#F0B90B"/><path d="M22 12L28 18L22 24L16 18L22 12Z" fill="#F0B90B"/><path d="M16 18L22 24L16 30L10 24L16 18Z" fill="#F0B90B"/><circle cx="16" cy="18" r="2" fill="#1e293b"/></svg> }
];

export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, equity, totalPositionValue, externalWalletBalance, fillHistory, transferHistory, cashFlowHistory, onDeposit, onWithdraw, isConnected, onConnect, onDisconnect, language, setLanguage, theme, setTheme, positionMode, onSetPositionMode
}) => {
  const [view, setView] = useState<ViewState>('MAIN');
  const [loginStep, setLoginStep] = useState<LoginStep>('INITIAL');
  const [selectedWallet, setSelectedWallet] = useState<typeof WALLETS[0] | null>(null);

  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [copied, setCopied] = useState(false);
  const [depositStatus, setDepositStatus] = useState<'IDLE' | 'APPROVING' | 'DEPOSITING' | 'SUCCESS'>('IDLE');
  const [withdrawStatus, setWithdrawStatus] = useState<'IDLE' | 'WITHDRAWING' | 'SUCCESS'>('IDLE');

  const [cashFlowFilter] = useState<CashFlowType | 'ALL'>('ALL');

  const t = TRANSLATIONS[language];
  const walletAddress = "0x71C7...9A23";

  useEffect(() => {
    if (!isConnected) { setLoginStep('INITIAL'); setSelectedWallet(null); }
  }, [isConnected]);

  const handleCopy = () => {
    navigator.clipboard.writeText("0x71C762B34567890123456789A23"); 
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDepositChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setDepositAmount(value);
  };

  const handleWithdrawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setWithdrawAmount(value);
  };

  const handleWeb3Deposit = async () => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0 || val > externalWalletBalance) return;
    setDepositStatus('APPROVING');
    await new Promise(resolve => setTimeout(resolve, 1500));
    setDepositStatus('DEPOSITING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    onDeposit(val);
    setDepositStatus('SUCCESS');
    setTimeout(() => { setDepositStatus('IDLE'); setDepositAmount(''); setView('MAIN'); }, 1500);
  };

  const handleWeb3Withdraw = async () => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= 0 || val > balance) return;
    setWithdrawStatus('WITHDRAWING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    const success = onWithdraw(val);
    if (success) {
        setWithdrawStatus('SUCCESS');
        setTimeout(() => { setWithdrawStatus('IDLE'); setWithdrawAmount(''); setView('MAIN'); }, 1500);
    } else setWithdrawStatus('IDLE');
  };

  const isDepositValid = !isNaN(parseFloat(depositAmount)) && parseFloat(depositAmount) > 0 && parseFloat(depositAmount) <= externalWalletBalance;
  const isWithdrawValid = !isNaN(parseFloat(withdrawAmount)) && parseFloat(withdrawAmount) > 0 && parseFloat(withdrawAmount) <= balance;

  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-6 dark:bg-slate-900 bg-slate-50 overflow-hidden">
        {loginStep === 'INITIAL' && (
             <div className="flex flex-col items-center animate-in fade-in zoom-in duration-500 w-full max-w-sm">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-2xl flex items-center justify-center mb-8 border border-indigo-500/20"><Wallet size={40} className="text-indigo-500" /></div>
                <h1 className="text-2xl font-bold dark:text-white text-slate-900 mb-2">{t.connect}</h1>
                <p className="dark:text-slate-400 text-slate-500 text-center mb-10 text-sm leading-relaxed">{t.connection.desc}</p>
                <button onClick={() => setLoginStep('SELECT_WALLET')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-600/20 active:scale-95 transition-all">{t.connect}</button>
            </div>
        )}
        {loginStep === 'SELECT_WALLET' && (
            <div className="absolute inset-0 z-20 flex items-end justify-center bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full rounded-t-2xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                    <div className="flex justify-between items-center mb-6"><h2 className="text-lg font-bold dark:text-white text-slate-900">{t.connection.selectWallet}</h2><button onClick={() => setLoginStep('INITIAL')} className="p-1 dark:text-slate-400"><X size={20}/></button></div>
                    <div className="space-y-3 pb-8">
                        {WALLETS.map((w) => (
                            <button key={w.id} onClick={() => { setSelectedWallet(w); setLoginStep('CONNECTING'); setTimeout(() => setLoginStep('SIGNING'), 1500); }} className="w-full flex items-center justify-between p-4 rounded-xl border dark:border-slate-700 border-slate-100 dark:bg-slate-700/50 bg-slate-50">
                                <div className="flex items-center gap-4"><div className="w-10 h-10 rounded-lg flex items-center justify-center bg-white shadow-sm border">{w.icon}</div><span className="font-bold dark:text-slate-200 text-slate-800">{w.name}</span></div><ChevronRight size={18} className="text-slate-400" />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}
        {loginStep === 'SIGNING' && selectedWallet && (
            <div className="absolute inset-0 z-30 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full max-w-xs rounded-2xl p-6 shadow-2xl border dark:border-slate-700">
                    <div className="flex items-center gap-3 mb-4 pb-4 border-b dark:border-slate-700"><div className="w-8 h-8 rounded-full border p-1 bg-white">{selectedWallet.icon}</div><h3 className="font-bold dark:text-white text-sm">{t.connection.sigRequest}</h3></div>
                    <div className="bg-slate-50 dark:bg-slate-900 rounded-lg p-3 mb-6 font-mono text-[10px] dark:text-slate-400">{t.connection.msgToSign}:<br/>Welcome to GoldenDex. By signing this message, you agree to the Terms of Service.</div>
                    <div className="flex gap-3"><button onClick={() => setLoginStep('INITIAL')} className="flex-1 py-3 rounded-xl border text-slate-500 text-sm font-bold">{t.cancel}</button><button onClick={() => { setLoginStep('VERIFYING'); setTimeout(() => { onConnect(); setLoginStep('INITIAL'); setSelectedWallet(null); }, 1500); }} className="flex-1 py-3 rounded-xl bg-indigo-600 text-white font-bold text-sm">{t.connection.sign}</button></div>
                </div>
            </div>
        )}
      </div>
    );
  }

  const renderHeader = (title: string) => (
    <div className="px-4 py-4 flex items-center gap-3 sticky top-0 bg-white dark:bg-slate-900 z-10 border-b dark:border-slate-800 border-slate-200">
      <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"><ChevronLeft size={24} className="dark:text-white" /></button>
      <h2 className="text-lg font-bold dark:text-white text-slate-900">{title}</h2>
    </div>
  );

  if (view === 'DEPOSIT') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.depositVaultTitle)}
      <div className="p-4 space-y-6 pb-24">
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.network}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-blue-500 border-4 border-slate-800"></div><span className="font-bold dark:text-white text-slate-900">Arbitrum One</span></div><CheckCircle size={16} className="text-emerald-500" /></div></div>
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.currency}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center gap-3"><div className="w-8 h-8 rounded-full bg-indigo-500/10 flex items-center justify-center text-indigo-500"><Coins size={16} /></div><span className="font-bold dark:text-white text-slate-900">USDC</span></div></div>
        <div className="space-y-3"><div className="flex justify-between items-center"><label className="text-xs font-bold text-slate-500 uppercase">{t.amount}</label><span className="text-[11px] text-slate-500">{t.walletBalance}: <span className="dark:text-white text-slate-900 font-mono font-bold">{externalWalletBalance.toFixed(2)}</span></span></div><div className="relative"><input type="text" value={depositAmount} onChange={handleDepositChange} placeholder={t.quantity} className="w-full bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-2xl p-4 pr-24 text-sm font-mono outline-none focus:border-indigo-500 dark:text-white" /><div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-3"><button onClick={() => setDepositAmount(externalWalletBalance.toString())} className="text-xs font-bold text-indigo-500">{t.max}</button><span className="text-xs font-bold text-slate-500 uppercase">USDC</span></div></div></div>
        <button onClick={handleWeb3Deposit} disabled={!isDepositValid || depositStatus !== 'IDLE'} className={`w-full py-4 mt-4 rounded-2xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${isDepositValid && depositStatus === 'IDLE' ? 'bg-[#2D3748] dark:bg-slate-800 text-white' : 'bg-slate-200 dark:bg-slate-700/30 text-slate-400 cursor-not-allowed shadow-none'}`}>{depositStatus === 'IDLE' ? <><Wallet size={18} /> {t.confirm}</> : <Loader2 size={18} className="animate-spin" />}</button>
      </div>
    </div>
  );

  if (view === 'WITHDRAW') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.withdrawVaultTitle)}
      <div className="p-4 space-y-6 pb-24">
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.network}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-blue-500 border-4 border-slate-800"></div><span className="font-bold dark:text-white text-slate-900">Arbitrum One</span></div><CheckCircle size={16} className="text-emerald-500" /></div></div>
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.currency}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center gap-3"><div className="w-8 h-8 rounded-full bg-indigo-500/10 flex items-center justify-center text-indigo-500"><Coins size={16} /></div><span className="font-bold dark:text-white text-slate-900">USDC</span></div></div>
        <div className="space-y-3"><div className="flex justify-between items-center"><label className="text-xs font-bold text-slate-500 uppercase">{t.amount}</label><span className="text-[11px] text-slate-500">{t.avail}: <span className="dark:text-white text-slate-900 font-mono font-bold">{balance.toFixed(2)}</span></span></div><div className="relative"><input type="text" value={withdrawAmount} onChange={handleWithdrawChange} placeholder={t.quantity} className="w-full bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-2xl p-4 pr-16 text-sm font-mono outline-none focus:border-indigo-500 dark:text-white" /><button onClick={() => setWithdrawAmount(balance.toString())} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-indigo-500">{t.max}</button></div></div>
        <button onClick={handleWeb3Withdraw} disabled={!isWithdrawValid || withdrawStatus !== 'IDLE'} className={`w-full py-4 mt-4 rounded-2xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${isWithdrawValid && withdrawStatus === 'IDLE' ? 'bg-[#2D3748] dark:bg-slate-800 text-white' : 'bg-slate-200 dark:bg-slate-700/30 text-slate-400 cursor-not-allowed shadow-none'}`}>{withdrawStatus === 'IDLE' ? <><ArrowRightLeft size={18} /> {t.confirm}</> : <Loader2 size={18} className="animate-spin" />}</button>
      </div>
    </div>
  );

  if (view === 'TRANSFER_HISTORY') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.transfers)}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar pb-24">
        {transferHistory.map(tx => {
          const isDeposit = tx.type === 'DEPOSIT';
          return (
            <div key={tx.id} className="dark:bg-slate-800/40 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 shadow-sm">
              <div className="flex justify-between items-start mb-4">
                 <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${isDeposit ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                       {isDeposit ? <ArrowDownLeft size={20} /> : <ArrowUpRight size={20} />}
                    </div>
                    <div>
                       <div className="font-bold dark:text-white text-slate-900 text-sm">
                          {isDeposit ? t.deposit : t.withdraw} USDC
                       </div>
                       <div className="text-[10px] text-slate-500 font-mono mt-0.5">
                          {new Date(tx.timestamp).toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).replace(/-/g, '/')}
                       </div>
                    </div>
                 </div>
                 <div className="text-right">
                    <div className={`font-mono font-bold text-sm ${isDeposit ? 'text-white dark:text-white' : 'text-slate-900 dark:text-white'}`}>
                       {isDeposit ? '+' : '-'}{tx.amount.toFixed(2)}
                    </div>
                    <div className="text-[10px] text-emerald-500 font-medium mt-0.5">已完成</div>
                 </div>
              </div>
              <div className="flex justify-between items-center border-t dark:border-slate-700/50 pt-3">
                 <div className="px-2 py-0.5 rounded bg-slate-200 dark:bg-slate-700 text-[10px] text-slate-500 dark:text-slate-400 font-bold">Arbitrum One</div>
                 <button className="flex items-center gap-1 text-[10px] text-indigo-500 font-bold hover:underline">
                    Explorer <ExternalLink size={10} />
                 </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  if (view === 'FILL_HISTORY') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.history)}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar pb-24">
        {fillHistory.map(f => (
          <div key={f.id} className="dark:bg-slate-800/40 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-5 shadow-sm">
            <div className="flex justify-between items-center mb-1"><div className="flex items-center gap-3"><span className="font-bold dark:text-white text-slate-900 text-lg uppercase tracking-tight">{f.symbol}</span><span className={`text-[10px] font-bold px-2 py-0.5 rounded ${f.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>{f.side === Side.LONG ? '买入' : '卖出'}</span></div></div>
            <div className="text-[11px] text-slate-500 mb-4 font-mono">{new Date(f.timestamp).toLocaleString()}</div>
            <div className="grid grid-cols-2 gap-y-3">
              <div className="flex justify-between pr-4 items-center"><span className="text-[11px] text-slate-500">价格</span><span className="font-mono font-bold dark:text-slate-200 text-slate-800">{f.price.toFixed(2)}</span></div>
              <div className="flex justify-between pl-4 items-center border-l dark:border-slate-700/50"><span className="text-[11px] text-slate-500">数量</span><span className="font-mono font-bold dark:text-slate-200 text-slate-800">{f.size}</span></div>
              <div className="flex justify-between pr-4 items-center"><span className="text-[11px] text-slate-500">金额</span><span className="font-mono font-bold dark:text-slate-200 text-slate-800">{f.value.toFixed(2)}</span></div>
              <div className="flex justify-between pl-4 items-center border-l dark:border-slate-700/50"><span className="text-[11px] text-slate-500">费用</span><span className="font-mono font-bold dark:text-slate-400 text-slate-600">{f.fee.toFixed(2)}</span></div>
              <div className="flex justify-between pr-4 items-center"><span className="text-[11px] text-slate-500">盈亏</span><span className={`font-mono font-bold ${f.realizedPnl >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>{f.realizedPnl >= 0 ? '+' : ''}{f.realizedPnl.toFixed(2)}</span></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="p-4 h-full pb-24 overflow-y-auto no-scrollbar bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      <div className="flex items-center gap-3 mb-6 pt-2">
         <div className="w-10 h-10 rounded-full dark:bg-slate-800 bg-slate-200 flex items-center justify-center text-slate-500"><User size={20} /></div>
         <div className="flex-1 overflow-hidden"><div className="flex items-center gap-2 font-bold dark:text-white text-slate-900 truncate">{walletAddress}<button onClick={handleCopy} className="text-slate-400 hover:text-indigo-500">{copied ? <CheckCircle size={14}/> : <Copy size={14}/>}</button></div><div className="text-[10px] text-emerald-500 font-medium">Connected</div></div>
      </div>
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl p-6 shadow-xl mb-6 text-white">
        <p className="text-indigo-200 text-xs mb-1 uppercase tracking-wider">{t.totalEquity} (USD)</p>
        <h1 className="text-3xl font-mono font-bold tracking-tight mb-4">${equity.toFixed(2)}</h1>
        <div className="grid grid-cols-3 gap-2 border-t border-white/10 pt-4">
           <div><p className="text-indigo-200 text-[9px] uppercase">{t.avail}</p><p className="font-mono font-bold text-xs">${balance.toFixed(2)}</p></div>
           <div className="text-center"><p className="text-indigo-200 text-[9px] uppercase">{t.unrealizedPnL}</p><p className={`font-mono font-bold text-xs ${(equity - balance - (orderMargin + marginLocked)) >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{(equity - balance - (orderMargin + marginLocked)).toFixed(2)}</p></div>
           <div className="text-right"><p className="text-indigo-200 text-[9px] uppercase">持仓总价值</p><p className="font-mono font-bold text-xs">${totalPositionValue.toFixed(2)}</p></div>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 mb-6"><button onClick={() => setView('DEPOSIT')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm transition-transform active:scale-95"><CreditCard size={18} className="text-indigo-500"/>{t.deposit}</button><button onClick={() => setView('WITHDRAW')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm transition-transform active:scale-95"><ArrowRightLeft size={18} className="text-indigo-500"/>{t.withdraw}</button></div>
      <div className="dark:bg-slate-800 bg-white rounded-xl overflow-hidden border dark:border-slate-700 shadow-sm"><button onClick={() => setView('FILL_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-50"><div className="flex items-center gap-3"><History size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.history}</span></div><ChevronRight size={16} className="text-slate-500"/></button><button onClick={() => setView('TRANSFER_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-50"><div className="flex items-center gap-3"><ArrowRightLeft size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.transfers}</span></div><ChevronRight size={16} className="text-slate-500"/></button><button onClick={() => setView('SETTINGS')} className="w-full flex items-center justify-between p-4 hover:bg-slate-50"><div className="flex items-center gap-3"><Settings size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.settings}</span></div><ChevronRight size={16} className="text-slate-500"/></button></div>
      <button onClick={onDisconnect} className="w-full py-4 mt-6 text-rose-500 font-bold bg-rose-500/5 rounded-xl border border-rose-500/10 transition-all active:scale-95 flex items-center justify-center gap-2"><LogOut size={18}/>{t.disconnect}</button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Wallet, CreditCard, ArrowRightLeft, Shield, Settings, History, ChevronLeft, Copy, CheckCircle, ExternalLink, ArrowDownLeft, ArrowUpRight, LogOut, User, Coins, Moon, Sun, Loader2, X, ChevronRight, Lock, Info } from 'lucide-react';
import { FillRecord, TransferRecord, Side, Language, Theme, CashFlowRecord, CashFlowType, PositionMode } from '../types';
import { TRANSLATIONS } from '../constants';

interface AccountViewProps {
  balance: number;
  equity: number;
  // Use unrealizedPnL directly from App state
  unrealizedPnL: number;
  totalPositionValue: number;
  externalWalletBalance: number;
  fillHistory: FillRecord[];
  transferHistory: TransferRecord[];
  cashFlowHistory: CashFlowRecord[];
  onDeposit: (amount: number) => void;
  onWithdraw: (amount: number) => boolean;
  isConnected: boolean;
  onConnect: () => void;
  onDisconnect: () => void;
  language: Language;
  setLanguage: (lang: Language) => void;
  theme: Theme;
  setTheme: (theme: Theme) => void;
  positionMode: PositionMode;
  onSetPositionMode: (mode: PositionMode) => void;
}

type ViewState = 'MAIN' | 'DEPOSIT' | 'WITHDRAW' | 'FILL_HISTORY' | 'TRANSFER_HISTORY' | 'SETTINGS' | 'CASH_FLOW_HISTORY';
type LoginStep = 'INITIAL' | 'SELECT_WALLET' | 'CONNECTING' | 'SIGNING' | 'VERIFYING';

const WALLETS = [
  { id: 'metamask', name: 'MetaMask', color: '#F6851B', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><path d="M27.5 2.5L25.5 5.5L28.5 10.5L30.5 4.5L27.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M4.5 2.5L7.5 5.5L3.5 10.5L1.5 4.5L4.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M16 23.5L9 28.5L23 28.5L16 23.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M9 11.5L5 17.5L9 28.5L16 23.5L23 28.5L27 17.5L23 11.5L16 16.5L9 11.5Z" fill="#F6851B" stroke="#F6851B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg> },
  { id: 'walletconnect', name: 'WalletConnect', color: '#3B99FC', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><path d="M26 11C23 8 19 6 16 6C13 6 9 8 6 11" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/><circle cx="8" cy="18" r="3" fill="#3B99FC"/><circle cx="24" cy="18" r="3" fill="#3B99FC"/><path d="M16 21V26" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/></svg> },
  { id: 'okx', name: 'OKX Wallet', color: '#000000', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><rect width="32" height="32" rx="6" fill="currentColor" className="text-black dark:text-white"/><path d="M8 8H12V12H8V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 8H24V12H20V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M8 20H12V24H8V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 20H24V24H20V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M14 14H18V18H14V14Z" fill="currentColor" className="text-white dark:text-black"/></svg> },
  { id: 'binance', name: 'Binance Wallet', color: '#F0B90B', icon: <svg viewBox="0 0 32 32" className="w-6 h-6" fill="none"><path d="M16 6L22 12L16 18L10 12L16 6Z" fill="#F0B90B"/><path d="M10 12L4 18L10 24L16 18L10 12Z" fill="#F0B90B"/><path d="M22 12L28 18L22 24L16 18L22 12Z" fill="#F0B90B"/><path d="M16 18L22 24L16 30L10 24L16 18Z" fill="#F0B90B"/><circle cx="16" cy="18" r="2" fill="#1e293b"/></svg> }
];

export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, equity, unrealizedPnL, totalPositionValue, externalWalletBalance, fillHistory, transferHistory, cashFlowHistory, onDeposit, onWithdraw, isConnected, onConnect, onDisconnect, language, setLanguage, theme, setTheme, positionMode, onSetPositionMode
}) => {
  const [view, setView] = useState<ViewState>('MAIN');
  const [loginStep, setLoginStep] = useState<LoginStep>('INITIAL');
  const [selectedWallet, setSelectedWallet] = useState<typeof WALLETS[0] | null>(null);

  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [copied, setCopied] = useState(false);
  const [depositStatus, setDepositStatus] = useState<'IDLE' | 'APPROVING' | 'DEPOSITING' | 'SUCCESS'>('IDLE');
  const [withdrawStatus, setWithdrawStatus] = useState<'IDLE' | 'WITHDRAWING' | 'SUCCESS'>('IDLE');

  const [cashFlowFilter] = useState<CashFlowType | 'ALL'>('ALL');

  const t = TRANSLATIONS[language];
  const walletAddress = "0x71C7...9A23";

  useEffect(() => {
    if (!isConnected) { setLoginStep('INITIAL'); setSelectedWallet(null); }
  }, [isConnected]);

  const handleCopy = () => {
    navigator.clipboard.writeText("0x71C762B34567890123456789A23"); 
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDepositChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setDepositAmount(value);
  };

  const handleWithdrawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setWithdrawAmount(value);
  };

  const handleWeb3Deposit = async () => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0 || val > externalWalletBalance) return;
    setDepositStatus('APPROVING');
    await new Promise(resolve => setTimeout(resolve, 1500));
    setDepositStatus('DEPOSITING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    onDeposit(val);
    setDepositStatus('SUCCESS');
    setTimeout(() => { setDepositStatus('IDLE'); setDepositAmount(''); setView('MAIN'); }, 1500);
  };

  const handleWeb3Withdraw = async () => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= 0 || val > balance) return;
    setWithdrawStatus('WITHDRAWING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    const success = onWithdraw(val);
    if (success) {
        setWithdrawStatus('SUCCESS');
        setTimeout(() => { setWithdrawStatus('IDLE'); setWithdrawAmount(''); setView('MAIN'); }, 1500);
    } else setWithdrawStatus('IDLE');
  };

  const isDepositValid = !isNaN(parseFloat(depositAmount)) && parseFloat(depositAmount) > 0 && parseFloat(depositAmount) <= externalWalletBalance;
  const isWithdrawValid = !isNaN(parseFloat(withdrawAmount)) && parseFloat(withdrawAmount) > 0 && parseFloat(withdrawAmount) <= balance;

  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center h-full p-6 dark:bg-slate-900 bg-slate-50 overflow-hidden">
        {loginStep === 'INITIAL' && (
             <div className="flex flex-col items-center animate-in fade-in zoom-in duration-500 w-full max-w-sm">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-2xl flex items-center justify-center mb-8 border border-indigo-500/20"><Wallet size={40} className="text-indigo-500" /></div>
                <h1 className="text-2xl font-bold dark:text-white text-slate-900 mb-2">{t.connect}</h1>
                <p className="dark:text-slate-400 text-slate-500 text-center mb-10 text-sm leading-relaxed">{t.connection.desc}</p>
                <button onClick={() => setLoginStep('SELECT_WALLET')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-600/20 active:scale-95 transition-all">{t.connect}</button>
            </div>
        )}
        {loginStep === 'SELECT_WALLET' && (
            <div className="absolute inset-0 z-20 flex items-end justify-center bg-black/60 backdrop-blur-sm">
