                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">保证金比率</div><div className="flex-1 text-center font-mono">{metrics.currentRatio.toFixed(2)}%</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newRatio.toFixed(2)}%</div></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.estLiqPrice}</div><div className="flex-1 text-center font-mono text-orange-500">{metrics.currentLiq.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-orange-500">{metrics.newLiq.toFixed(2)}</div></div>
                </div>
                <div className="grid grid-cols-2 gap-3"><button onClick={() => setEditingPosId(null)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">{t.cancel}</button><button onClick={handleConfirmMargin} disabled={!isMarginInputValid()} className={`py-3 rounded-xl font-bold shadow-lg transition-all ${isMarginInputValid() ? 'bg-indigo-600 text-white shadow-indigo-500/20' : 'bg-slate-300 text-slate-500 cursor-not-allowed'}`}>{t.confirmAction}</button></div>
             </div>
          </div>
      )}

      {showCloseAllConfirm && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
             <div className="bg-white dark:bg-slate-800 w-full max-w-xs rounded-2xl p-6 shadow-2xl text-center border dark:border-slate-700">
                <AlertTriangle size={48} className="text-rose-500 mx-auto mb-4" />
                <h3 className="font-bold text-lg dark:text-white text-slate-900 mb-2">{t.confirmCloseAll}</h3>
                <div className="grid grid-cols-2 gap-3 mt-6">
                    <button onClick={() => setShowCloseAllConfirm(false)} className="py-2.5 rounded-xl border font-bold text-slate-500">{t.cancel}</button>
                    <button onClick={() => { onCloseAllPositions(); setShowCloseAllConfirm(false); }} className="py-2.5 rounded-xl bg-rose-600 text-white font-bold">{t.confirmAction}</button>
                </div>
             </div>
          </div>
      )}
    </div>
  );
};

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export enum PositionMode {
  ONE_WAY = 'ONE_WAY',
  HEDGE = 'HEDGE'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';
export type ChartType = 'line' | 'candle' | 'depth';
export type Timeframe = '1m' | '3m' | '5m' | '15m' | '30m' | '1H' | '2H' | '4H' | '8H' | '12H' | '1D' | '3D' | '1W' | '1M';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  filled: number;
  status: 'OPEN' | 'FILLED' | 'CANCELLED' | 'PARTIAL_FILLED';
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketInfo {
  symbol: string;
  name: string;
  lastPrice: number;
  change24h: number;
  volume24h: number;
  fundingRate: number;
  leverage: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

export interface FillRecord {
  id: string;
  symbol: string;
  side: Side;
  price: number;
  size: number;
  value: number;
  fee: number;
  realizedPnl: number;
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING' | 'REJECTED' | 'CANCELLED';
  network: string;
}

export type CashFlowType = 'TRANSACTION_FEE' | 'FUNDING_FEE' | 'REALIZED_PNL' | 'LIQUIDATION_FEE';

export interface CashFlowRecord {
  id: string;
  type: CashFlowType;
  symbol: string;
  amount: number;
  timestamp: number;
}

export interface MarketTrade {
  id: string;
  price: number;
  size: number;
  side: Side;
  time: string;
}

