              <div className="flex justify-between pr-4 items-center"><span className="text-[11px] text-slate-500">金额</span><span className="font-mono font-bold dark:text-slate-200 text-slate-800">{f.value.toFixed(2)}</span></div>
              <div className="flex justify-between pl-4 items-center border-l dark:border-slate-700/50"><span className="text-[11px] text-slate-500">费用</span><span className="font-mono font-bold dark:text-slate-400 text-slate-600">{f.fee.toFixed(2)}</span></div>
              <div className="flex justify-between pr-4 items-center"><span className="text-[11px] text-slate-500">盈亏</span><span className={`font-mono font-bold ${f.realizedPnl >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>{f.realizedPnl >= 0 ? '+' : ''}{f.realizedPnl.toFixed(2)}</span></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="p-4 h-full pb-24 overflow-y-auto no-scrollbar bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      <div className="flex items-center gap-3 mb-6 pt-2">
         <div className="w-10 h-10 rounded-full dark:bg-slate-800 bg-slate-200 flex items-center justify-center text-slate-500"><User size={20} /></div>
         <div className="flex-1 overflow-hidden"><div className="flex items-center gap-2 font-bold dark:text-white text-slate-900 truncate">{walletAddress}<button onClick={handleCopy} className="text-slate-400 hover:text-indigo-500">{copied ? <CheckCircle size={14}/> : <Copy size={14}/>}</button></div><div className="text-[10px] text-emerald-500 font-medium">Connected</div></div>
      </div>
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl p-6 shadow-xl mb-6 text-white">
        <p className="text-indigo-200 text-xs mb-1 uppercase tracking-wider">{t.totalEquity} (USD)</p>
        <h1 className="text-3xl font-mono font-bold tracking-tight mb-4">${equity.toFixed(2)}</h1>
        <div className="grid grid-cols-3 gap-2 border-t border-white/10 pt-4">
           <div><p className="text-indigo-200 text-[9px] uppercase">{t.avail}</p><p className="font-mono font-bold text-xs">${balance.toFixed(2)}</p></div>
           <div className="text-center"><p className="text-indigo-200 text-[9px] uppercase">{t.unrealizedPnL}</p><p className={`font-mono font-bold text-xs ${unrealizedPnL >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{unrealizedPnL.toFixed(2)}</p></div>
           <div className="text-right"><p className="text-indigo-200 text-[9px] uppercase">持仓总价值</p><p className="font-mono font-bold text-xs">${totalPositionValue.toFixed(2)}</p></div>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 mb-6"><button onClick={() => setView('DEPOSIT')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm transition-transform active:scale-95"><CreditCard size={18} className="text-indigo-500"/>{t.deposit}</button><button onClick={() => setView('WITHDRAW')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm transition-transform active:scale-95"><ArrowRightLeft size={18} className="text-indigo-500"/>{t.withdraw}</button></div>
      <div className="dark:bg-slate-800 bg-white rounded-xl overflow-hidden border dark:border-slate-700 shadow-sm">
        <button onClick={() => setView('FILL_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-50 transition-colors"><div className="flex items-center gap-3"><History size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.history}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('TRANSFER_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-50 transition-colors"><div className="flex items-center gap-3"><ArrowRightLeft size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.transfers}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('CASH_FLOW_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-50 transition-colors"><div className="flex items-center gap-3"><Coins size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.funding}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('SETTINGS')} className="w-full flex items-center justify-between p-4 hover:bg-slate-50 transition-colors"><div className="flex items-center gap-3"><Settings size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.settings}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
      </div>
      <button onClick={onDisconnect} className="w-full py-4 mt-6 text-rose-500 font-bold bg-rose-500/5 rounded-xl border border-rose-500/10 transition-all active:scale-95 flex items-center justify-center gap-2"><LogOut size={18}/>{t.disconnect}</button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Position, Side, MarginMode, Language } from '../types';
import { TrendingUp, TrendingDown, AlertTriangle, Plus, Minus, X, Trash2, ArrowRight, ArrowRightLeft, ChevronDown } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface PositionsViewProps {
  positions: Position[];
  currentPrice: number;
  equity: number;
  balance: number;
  maintenanceMargin: number;
  marginRatio: number;
  onClosePosition: (id: string, amount: number, price: number, type: 'MARKET' | 'LIMIT') => void;
  onUpdateMargin: (id: string, amount: number, type: 'ADD' | 'REMOVE') => void;
  onCloseAllPositions: () => void;
  lang: Language;
}

export const PositionsView: React.FC<PositionsViewProps> = ({ 
  positions, 
  currentPrice, 
  equity,
  balance,
  maintenanceMargin,
  marginRatio,
  onClosePosition,
  onUpdateMargin,
  onCloseAllPositions,
  lang
}) => {
  const t = TRANSLATIONS[lang];
  const [editingPosId, setEditingPosId] = useState<string | null>(null);
  const [marginAction, setMarginAction] = useState<'ADD' | 'REMOVE'>('ADD');

  // Close Position Modal State
  const [closingPosId, setClosingPosId] = useState<string | null>(null);
  const [closeOrderType, setCloseOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [closePrice, setClosePrice] = useState<string>('');
  const [closeAmount, setCloseAmount] = useState<string>('');
  const [closePercent, setClosePercent] = useState<number>(100);
  const [closeUnit, setCloseUnit] = useState<'XAU' | 'USDC'>('XAU');

  // Independent states for Add and Remove inputs
  const [addMarginInput, setAddMarginInput] = useState<string>('');
  const [removeMarginInput, setRemoveMarginInput] = useState<string>('');

  const [showCloseAllConfirm, setShowCloseAllConfirm] = useState(false);

  // Helper to get correct input state
  const currentMarginInput = marginAction === 'ADD' ? addMarginInput : removeMarginInput;
  const setMarginInput = (val: string) => {
      if (marginAction === 'ADD') setAddMarginInput(val);
      else setRemoveMarginInput(val);
  };

  const handleConfirmMargin = () => {
    if (editingPosId && currentMarginInput) {
        onUpdateMargin(editingPosId, parseFloat(currentMarginInput), marginAction);
        setEditingPosId(null);
        setAddMarginInput('');
        setRemoveMarginInput('');
    }
  };

  const closingPos = positions.find(p => p.id === closingPosId);

  // Handle Close Modal Price/Amount logic
  useEffect(() => {
    if (closingPos) {
       const maxInXAU = closingPos.size;
       const targetXAU = maxInXAU * closePercent / 100;

       if (closeUnit === 'XAU') {
          setCloseAmount(targetXAU.toFixed(4));
       } else {
          setCloseAmount((targetXAU * currentPrice).toFixed(2));
       }

       if (closeOrderType === 'MARKET') {
          setClosePrice('');
       } else if (!closePrice) {
          setClosePrice(currentPrice.toFixed(2));
       }
    }
  }, [closingPosId, closePercent, closeOrderType, currentPrice, closeUnit]);

  const handleExecuteClose = () => {
    if (closingPosId && closingPos && closeAmount) {
       let xauAmount = parseFloat(closeAmount);
       if (closeUnit === 'USDC') {
          xauAmount = xauAmount / currentPrice;
       }
       const executionPrice = closeOrderType === 'MARKET' ? currentPrice : (parseFloat(closePrice) || currentPrice);
       onClosePosition(closingPosId, xauAmount, executionPrice, closeOrderType);
       setClosingPosId(null);
    }
  };

  // Close Button Validation
  const closeNum = parseFloat(closeAmount);
  const maxInUnit = closingPos ? (closeUnit === 'XAU' ? closingPos.size : closingPos.size * currentPrice) : 0;
  const isCloseValid = !isNaN(closeNum) && closeNum > 0 && closeNum <= (maxInUnit + 0.0001);

  const getPositionMetrics = () => {
      const pos = positions.find(p => p.id === editingPosId);
      if (!pos || !pos.isolatedMargin) return null;

      const inputVal = parseFloat(currentMarginInput) || 0;
      const change = marginAction === 'ADD' ? inputVal : -inputVal;
      const currentMarginValue = pos.isolatedMargin;
      const newMarginValue = Math.max(0, currentMarginValue + change);

      const posValue = pos.entryPrice * pos.size;
      const currentLeverage = posValue / currentMarginValue;
      const newLeverage = newMarginValue > 0 ? posValue / newMarginValue : 0;

      const maintMarginReq = posValue * 0.01; 
      const currentRatio = (maintMarginReq / currentMarginValue) * 100;
      const newRatio = newMarginValue > 0 ? (maintMarginReq / newMarginValue) * 100 : 0;

      let currentLiq = pos.side === Side.LONG ? pos.entryPrice - (currentMarginValue / pos.size) : pos.entryPrice + (currentMarginValue / pos.size);
      let newLiq = pos.side === Side.LONG ? pos.entryPrice - (newMarginValue / pos.size) : pos.entryPrice + (newMarginValue / pos.size);

      const maxRemove = Math.max(0, currentMarginValue - maintMarginReq);

      return { currentMarginValue, newMarginValue, currentLeverage, newLeverage, currentLiq, newLiq, currentRatio, newRatio, maxRemove };
  };

  const metrics = editingPosId ? getPositionMetrics() : null;

  const isMarginInputValid = () => {
      const val = parseFloat(currentMarginInput);
      if (isNaN(val) || val <= 0) return false;
      return marginAction === 'ADD' ? val <= balance : val <= (metrics?.maxRemove || 0);
  };

  const renderRiskHeader = () => (
    <div className="dark:bg-slate-800/50 bg-white/80 border-b dark:border-slate-800 border-slate-200 p-4 sticky top-0 backdrop-blur-md z-10">
      <div className="grid grid-cols-3 gap-2">
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginRatio}</div>
           <div className={`font-mono font-bold text-sm ${marginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>{marginRatio.toFixed(2)}%</div>
        </div>
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.maintMargin}</div>
           <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${maintenanceMargin.toFixed(2)}</div>
        </div>
        <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
           <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginBal}</div>
           <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${equity.toFixed(2)}</div>
        </div>
      </div>
    </div>
  );

  if (positions.length === 0) {
    return (
      <div className="h-full flex flex-col">
        {renderRiskHeader()}
        <div className="flex-1 flex flex-col items-center justify-center dark:text-slate-500 text-slate-400">
          <div className="dark:bg-slate-800 bg-white p-4 rounded-full mb-4 shadow-sm border dark:border-slate-700 border-slate-200">
             <TrendingUp size={32} className="opacity-50" />
          </div>
          <p>{t.noPositions}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col dark:bg-slate-900 bg-slate-50 relative">
      {renderRiskHeader()}
      <div className="flex-1 p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar">
        <div className="flex justify-between items-center mb-2">
           <h2 className="dark:text-slate-400 text-slate-500 text-xs uppercase font-bold tracking-wider">{t.openPositions} ({positions.length})</h2>
           <button onClick={() => setShowCloseAllConfirm(true)} className="text-xs bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 px-2 py-1 rounded border border-rose-500/20 flex items-center gap-1"><Trash2 size={12} />{t.closeAll}</button>
        </div>

        {positions.map((pos) => {
          const priceDiff = currentPrice - pos.entryPrice;
          const pnl = pos.side === Side.LONG ? priceDiff * pos.size : -priceDiff * pos.size;
          const marginUsed = pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin ? pos.isolatedMargin : (pos.entryPrice * pos.size) / pos.leverage;
          const liquidationPrice = pos.side === Side.LONG ? pos.entryPrice - (marginUsed / pos.size) : pos.entryPrice + (marginUsed / pos.size);
          const isProfit = pnl >= 0;

          return (
            <div key={pos.id} className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded ${pos.side === Side.LONG ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                    {pos.side === Side.LONG ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                  </div>
                  <div>
                    <h3 className="font-bold dark:text-white text-slate-900 flex items-center gap-2">
                      {pos.symbol}
                      <span className="text-[9px] dark:bg-slate-700 bg-slate-200 dark:text-slate-300 text-slate-600 px-1.5 py-0.5 rounded uppercase font-normal tracking-wide border dark:border-slate-600 border-slate-300">
                        {pos.marginMode === MarginMode.ISOLATED ? t.isolated : t.cross}
                      </span>
                    </h3>
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 inline-block ${pos.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                      {pos.leverage}x {pos.side === Side.LONG ? t.longLabel : t.shortLabel}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-lg font-mono font-bold ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>{isProfit ? '+' : ''}{pnl.toFixed(2)}</div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-y-2 text-xs mb-4">
                <div className="dark:text-slate-400 text-slate-500">{t.size} (XAU)</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.size.toFixed(4)}</div>
                <div className="dark:text-slate-400 text-slate-500">{t.liqPrice}</div>
                <div className="text-right text-orange-500 font-mono font-bold">{liquidationPrice > 0 ? liquidationPrice.toFixed(2) : '0.00'}</div>
                <div className="dark:text-slate-400 text-slate-500">{t.margin}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono flex items-center justify-end gap-2">
                    {marginUsed.toFixed(2)}
                    {pos.marginMode === MarginMode.ISOLATED && (
                        <button onClick={() => { setEditingPosId(pos.id); setMarginAction('ADD'); }} className="bg-indigo-500/20 text-indigo-500 p-0.5 rounded hover:bg-indigo-500/30"><Plus size={10} /></button>
                    )}
                </div>
              </div>
              <button onClick={() => { setClosingPosId(pos.id); setClosePercent(100); }} className="w-full py-2.5 dark:bg-slate-700 bg-slate-100 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2">{t.closePos}</button>
            </div>
          );
        })}
      </div>

      {/* Redesigned Close Position Modal to match screenshot */}
      {closingPos && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in">
             <div className="bg-[#1b2331] w-full max-w-sm rounded-[24px] p-6 shadow-2xl border border-slate-700/50">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-xl text-white">{t.closePos}</h3>
                    <button onClick={() => setClosingPosId(null)} className="text-slate-400 hover:text-white transition-colors">
                      <X size={24}/>
                    </button>
                </div>

                <div className="flex justify-between items-start mb-6">
                    <div>
                      <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mb-1">{t.tradeHistoryFields.pair}</p>
                      <div className="flex items-center gap-2">
                        <span className="text-xl font-bold text-indigo-400 uppercase tracking-tight">{closingPos.symbol}</span>
                        <span className="text-xl font-bold text-slate-500">/</span>
                        <span className={`text-xl font-bold ${closingPos.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}`}>
                          {closingPos.side === Side.LONG ? t.longLabel : t.shortLabel}
                        </span>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-[10px] text-slate-500 font-medium mb-1">
                        {t.entryPrice}: <span className="text-slate-200 font-mono ml-1">{closingPos.entryPrice.toFixed(2)}</span>
                      </div>
                      <div className="text-[10px] text-slate-500 font-medium">
                        {t.markPrice}: <span className="text-slate-200 font-mono ml-1">{currentPrice.toFixed(2)}</span>
                      </div>
                    </div>
                </div>

                <div className="w-full h-px bg-slate-700/50 mb-6"></div>

                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.price}</label>
                        <div className="w-full bg-[#131a26] border border-slate-700/80 rounded-xl px-4 py-3 text-sm font-mono text-white flex items-center justify-center h-14">
                           {closeOrderType === 'MARKET' ? t.market : (
                             <input 
                                type="text" 
                                value={closePrice} 
                                onChange={(e) => setClosePrice(e.target.value)} 
                                className="bg-transparent border-none outline-none w-full text-center" 
                             />
                           )}
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.mode}</label>
                        <div className="w-full bg-[#131a26] border border-slate-700/80 rounded-xl px-4 py-3 flex items-center justify-between cursor-pointer h-14" onClick={() => setOrderType(closeOrderType === 'MARKET' ? 'LIMIT' : 'MARKET')}>
                            <span className="text-sm text-white font-medium">{closeOrderType === 'MARKET' ? t.market : t.limit}</span>
                            <ArrowRightLeft size={16} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                <div className="space-y-1.5 mb-8">
                    <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.size}</label>
                    <div className="relative group">
                        <input 
                           type="number" 
                           value={closeAmount} 
                           onChange={(e) => setCloseAmount(e.target.value)} 
                           className="w-full bg-[#131a26] border border-slate-700/80 group-focus-within:border-indigo-500/50 rounded-xl px-4 py-4 text-lg font-mono text-white outline-none h-14" 
                        />
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center">
                           <span className="text-[10px] font-bold text-slate-200 mr-1 uppercase">XAU</span>
                           <ChevronDown size={14} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                {/* Percentage Slider to match screenshot */}
                <div className="mb-10 px-1 relative h-6 flex items-center group">
                   <div className="absolute inset-x-0 h-1 bg-slate-700/50 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-500 transition-all" style={{ width: `${closePercent}%` }} />
                   </div>
                   <input 
                      type="range" 
                      min="0" 
                      max="100" 
                      step="1" 
                      value={closePercent} 
                      onChange={(e) => setClosePercent(parseInt(e.target.value))} 
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" 
                   />
                   <div 
                      className="absolute h-6 w-6 bg-indigo-500 border-2 border-[#1b2331] shadow-[0_0_10px_rgba(99,102,241,0.5)] rounded-full flex items-center justify-center z-10 pointer-events-none transition-transform group-active:scale-110" 
                      style={{ left: `${closePercent}%`, transform: 'translateX(-50%)' }}
                   >
                     <div className="absolute bottom-[30px] bg-indigo-600 text-white text-[9px] font-bold py-1 px-1.5 rounded-md shadow-lg after:content-[''] after:absolute after:top-full after:left-1/2 after:-translate-x-1/2 after:border-4 after:border-transparent after:border-t-indigo-600">
                        {closePercent}%
                     </div>
                   </div>
                </div>

                {/* Summary Info Area to match screenshot */}
                <div className="bg-[#131a26]/50 border border-slate-700/30 rounded-2xl p-5 mb-8">
                   <div className="flex justify-between items-center mb-3">
                      <span className="text-xs text-slate-500 font-medium">{t.closeOperation.positionSize}</span>
                      <span className="text-sm font-bold text-white font-mono">{closingPos.size.toFixed(4)} XAU</span>
                   </div>
                   <div className="flex justify-between items-center">
                      <span className="text-xs text-slate-500 font-medium">{t.closeOperation.estPnL}</span>
                      <span className={`text-sm font-bold font-mono ${((currentPrice - closingPos.entryPrice) * (parseFloat(closeAmount) || 0) * (closingPos.side === Side.LONG ? 1 : -1)) >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                         {((currentPrice - closingPos.entryPrice) * (parseFloat(closeAmount) || 0) * (closingPos.side === Side.LONG ? 1 : -1)).toFixed(2)} USDC
                      </span>
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <button 
                       onClick={() => setClosingPosId(null)} 
                       className="py-4 rounded-xl border border-slate-700 font-bold text-slate-400 hover:bg-slate-800 hover:text-white transition-all active:scale-95"
                    >
                      {t.cancel}
                    </button>
                    <button 
                       onClick={handleExecuteClose} 
                       disabled={!isCloseValid} 
                       className={`py-4 rounded-xl font-bold text-white shadow-[0_4px_20px_rgba(79,70,229,0.3)] transition-all active:scale-95 ${isCloseValid ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-slate-700 text-slate-500 cursor-not-allowed'}`}
                    >
                      {t.confirm}
                    </button>
                </div>
             </div>
          </div>
      )}

      {editingPosId && metrics && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
             <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-2xl p-6 shadow-2xl border dark:border-slate-700 border-slate-200">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg dark:text-white text-slate-900">{t.addMargin}</h3>
                    <button onClick={() => setEditingPosId(null)} className="dark:text-slate-400 text-slate-500"><X size={20}/></button>
                </div>
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1 mb-4">
                    <button onClick={() => setMarginAction('ADD')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'ADD' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.add}</button>
                    <button onClick={() => setMarginAction('REMOVE')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'REMOVE' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.remove}</button>
                </div>
                <div className="mb-4">
                    <div className="flex justify-between mb-1">
                        <label className="text-xs text-slate-500 block">{t.amount} (USDC)</label>
                        <span className="text-xs text-slate-500">{marginAction === 'ADD' ? t.avail : t.maxRemove}: <span className="font-mono">{marginAction === 'ADD' ? balance.toFixed(2) : metrics.maxRemove.toFixed(2)}</span></span>
                    </div>
                    <div className="relative">
                        <input type="number" value={currentMarginInput} onChange={(e) => setMarginInput(e.target.value)} placeholder={t.quantity} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-3 pr-16 font-mono text-lg outline-none focus:border-indigo-500 dark:text-white" />
                        <button onClick={() => setMarginInput((marginAction === 'ADD' ? balance : metrics.maxRemove).toFixed(2))} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-indigo-500">{t.max}</button>
                    </div>
                </div>
                {/* 4 Comparison Metrics */}
                <div className="bg-slate-50 dark:bg-slate-900 border dark:border-slate-700 border-slate-200 rounded-xl p-3 mb-6 space-y-3 text-[11px]">
                   <div className="flex items-center gap-2 mb-2"><span className="font-bold text-slate-400 flex-1 text-center">{t.before}</span><ArrowRight size={12} className="text-slate-400" /><span className="font-bold text-indigo-500 flex-1 text-center">{t.after}</span></div>

                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.margin}</div><div className="flex-1 text-center font-mono">{metrics.currentMarginValue.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newMarginValue.toFixed(2)}</div></div>

                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.leverage}</div><div className="flex-1 text-center font-mono">{metrics.currentLeverage.toFixed(1)}x</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newLeverage.toFixed(1)}x</div></div>

                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.marginRatio}</div><div className="flex-1 text-center font-mono">{metrics.currentRatio.toFixed(2)}%</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newRatio.toFixed(2)}%</div></div>

                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.estLiqPrice}</div><div className="flex-1 text-center font-mono text-orange-500">{metrics.currentLiq.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-orange-500">{metrics.newLiq.toFixed(2)}</div></div>
                </div>
                <div className="grid grid-cols-2 gap-3"><button onClick={() => setEditingPosId(null)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">{t.cancel}</button><button onClick={handleConfirmMargin} disabled={!isMarginInputValid()} className={`py-3 rounded-xl font-bold shadow-lg transition-all ${isMarginInputValid() ? 'bg-indigo-600 text-white shadow-indigo-500/20' : 'bg-slate-300 text-slate-500 cursor-not-allowed'}`}>{t.confirmAction}</button></div>
             </div>
          </div>
      )}

      {/* Redesigned Market Close All Confirmation Modal to match screenshot */}
      {showCloseAllConfirm && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in zoom-in-95 duration-200">
             <div className="bg-[#1b2331] w-full max-w-[320px] rounded-[24px] p-8 shadow-2xl border border-slate-700/50 text-center">
                <div className="w-16 h-16 bg-rose-500/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-rose-500/20">
                   <AlertTriangle size={32} className="text-rose-500" />
                </div>
                <h3 className="text-white text-xl font-bold mb-3">{t.confirmCloseAll}</h3>
                <p className="text-slate-400 text-sm leading-relaxed mb-10">{t.confirmCloseAllMsg}</p>
                <div className="grid grid-cols-2 gap-4">
                    <button 
                       onClick={() => setShowCloseAllConfirm(false)} 
                       className="py-4 rounded-2xl border border-slate-700 font-bold text-slate-400 hover:bg-slate-800 transition-all active:scale-95"
                    >
                      {t.cancel}
                    </button>
                    <button 
                       onClick={() => { onCloseAllPositions(); setShowCloseAllConfirm(false); }} 
                       className="py-4 rounded-2xl bg-rose-500 hover:bg-rose-600 text-white font-bold shadow-[0_4px_15px_rgba(244,63,94,0.3)] transition-all active:scale-95"
                    >
                      {t.confirm}
                    </button>
                </div>
             </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Wallet, CreditCard, ArrowRightLeft, Shield, Settings, History, ChevronLeft, Copy, CheckCircle, ExternalLink, ArrowDownLeft, ArrowUpRight, LogOut, User, Coins, Moon, Sun, Loader2, X, ChevronRight, Lock, Info, Filter, ArrowRight, ChevronDown } from 'lucide-react';
import { FillRecord, TransferRecord, Side, Language, Theme, CashFlowRecord, CashFlowType, PositionMode } from '../types';
import { TRANSLATIONS } from '../constants';

interface AccountViewProps {
  balance: number;
  equity: number;
  unrealizedPnL: number;
  totalPositionValue: number;
  externalWalletBalance: number;
  fillHistory: FillRecord[];
  transferHistory: TransferRecord[];
  cashFlowHistory: CashFlowRecord[];
  onDeposit: (amount: number) => void;
  onWithdraw: (amount: number) => boolean;
  isConnected: boolean;
  onConnect: () => void;
  onDisconnect: () => void;
  language: Language;
  setLanguage: (lang: Language) => void;
  theme: Theme;
  setTheme: (theme: Theme) => void;
  positionMode: PositionMode;
  onSetPositionMode: (mode: PositionMode) => void;
}

type ViewState = 'MAIN' | 'DEPOSIT' | 'WITHDRAW' | 'FILL_HISTORY' | 'TRANSFER_HISTORY' | 'SETTINGS' | 'CASH_FLOW_HISTORY';
type LoginStep = 'INITIAL' | 'SELECT_WALLET' | 'CONNECTING' | 'SIGNING' | 'VERIFYING';

const WALLETS = [
  { id: 'metamask', name: 'MetaMask', color: '#F6851B', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><path d="M27.5 2.5L25.5 5.5L28.5 10.5L30.5 4.5L27.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M4.5 2.5L7.5 5.5L3.5 10.5L1.5 4.5L4.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M16 23.5L9 28.5L23 28.5L16 23.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M9 11.5L5 17.5L9 28.5L16 23.5L23 28.5L27 17.5L23 11.5L16 16.5L9 11.5Z" fill="#F6851B" stroke="#F6851B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg> },
  { id: 'walletconnect', name: 'WalletConnect', color: '#3B99FC', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><path d="M26 11C23 8 19 6 16 6C13 6 9 8 6 11" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/><circle cx="8" cy="18" r="3" fill="#3B99FC"/><circle cx="24" cy="18" r="3" fill="#3B99FC"/><path d="M16 21V26" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/></svg> },
  { id: 'okx', name: 'OKX Wallet', color: '#000000', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><rect width="32" height="32" rx="6" fill="currentColor" className="text-black dark:text-white"/><path d="M8 8H12V12H8V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 8H24V12H20V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M8 20H12V24H8V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 20H24V24H20V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M14 14H18V18H14V14Z" fill="currentColor" className="text-white dark:text-black"/></svg> },
  { id: 'binance', name: 'Binance Wallet', color: '#F0B90B', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><path d="M16 6L22 12L16 18L10 12L16 6Z" fill="#F0B90B"/><path d="M10 12L4 18L10 24L16 18L10 12Z" fill="#F0B90B"/><path d="M22 12L28 18L22 24L16 18L22 12Z" fill="#F0B90B"/><path d="M16 18L22 24L16 30L10 24L16 18Z" fill="#F0B90B"/><circle cx="16" cy="18" r="2" fill="#1e293b"/></svg> }
];

export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, equity, unrealizedPnL, totalPositionValue, externalWalletBalance, fillHistory, transferHistory, cashFlowHistory, onDeposit, onWithdraw, isConnected, onConnect, onDisconnect, language, setLanguage, theme, setTheme, positionMode, onSetPositionMode
}) => {
  const [view, setView] = useState<ViewState>('MAIN');
  const [loginStep, setLoginStep] = useState<LoginStep>('INITIAL');
  const [selectedWallet, setSelectedWallet] = useState<typeof WALLETS[0] | null>(null);

  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [copied, setCopied] = useState(false);
  const [depositStatus, setDepositStatus] = useState<'IDLE' | 'APPROVING' | 'DEPOSITING' | 'SUCCESS'>('IDLE');
  const [withdrawStatus, setWithdrawStatus] = useState<'IDLE' | 'WITHDRAWING' | 'SUCCESS'>('IDLE');

  const [cashFlowFilter, setCashFlowFilter] = useState<CashFlowType | 'ALL'>('ALL');
  const [showFilterDropdown, setShowFilterDropdown] = useState(false);

  const t = TRANSLATIONS[language];
  const walletAddress = "0x71C7...9A23";

  useEffect(() => {
    if (!isConnected) { setLoginStep('INITIAL'); setSelectedWallet(null); }
  }, [isConnected]);

  const handleCopy = () => {
    navigator.clipboard.writeText("0x71C762B34567890123456789A23"); 
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDepositChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setDepositAmount(value);
  };

  const handleWithdrawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setWithdrawAmount(value);
  };

  const handleWeb3Deposit = async () => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0 || val > externalWalletBalance) return;
    setDepositStatus('APPROVING');
    await new Promise(resolve => setTimeout(resolve, 1500));
    setDepositStatus('DEPOSITING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    onDeposit(val);
    setDepositStatus('SUCCESS');
    setTimeout(() => { setDepositStatus('IDLE'); setDepositAmount(''); setView('MAIN'); }, 1500);
  };

  const handleWeb3Withdraw = async () => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= 0 || val > balance) return;
    setWithdrawStatus('WITHDRAWING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    const success = onWithdraw(val);
    if (success) {
        setWithdrawStatus('SUCCESS');
        setTimeout(() => { setWithdrawStatus('IDLE'); setWithdrawAmount(''); setView('MAIN'); }, 1500);
    } else setWithdrawStatus('IDLE');
  };

  const isDepositValid = !isNaN(parseFloat(depositAmount)) && parseFloat(depositAmount) > 0 && parseFloat(depositAmount) <= externalWalletBalance;
  const isWithdrawValid = !isNaN(parseFloat(withdrawAmount)) && parseFloat(withdrawAmount) > 0 && parseFloat(withdrawAmount) <= balance;

  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center h-full dark:bg-slate-900 bg-slate-50 overflow-hidden relative">
        {loginStep === 'INITIAL' && (
             <div className="flex flex-col items-center animate-in fade-in zoom-in duration-500 w-full max-w-sm p-6">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-2xl flex items-center justify-center mb-8 border border-indigo-500/20"><Wallet size={40} className="text-indigo-500" /></div>
                <h1 className="text-2xl font-bold dark:text-white text-slate-900 mb-2">{t.connect}</h1>
                <p className="dark:text-slate-400 text-slate-500 text-center mb-10 text-sm leading-relaxed">{t.connection.desc}</p>
                <button onClick={() => setLoginStep('SELECT_WALLET')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-600/20 active:scale-95 transition-all">{t.connect}</button>
            </div>
        )}

        {loginStep === 'SELECT_WALLET' && (
            <div className="absolute inset-0 z-20 flex items-end justify-center bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full rounded-t-[24px] p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                    <div className="flex justify-between items-center mb-6"><h2 className="text-lg font-bold dark:text-white text-slate-900">{t.connection.selectWallet}</h2><button onClick={() => setLoginStep('INITIAL')} className="p-1 dark:text-slate-400"><X size={20}/></button></div>
                    <div className="space-y-3 pb-8">
                        {WALLETS.map((w) => (
                            <button key={w.id} onClick={() => { setSelectedWallet(w); setLoginStep('CONNECTING'); setTimeout(() => setLoginStep('SIGNING'), 2500); }} className="w-full flex items-center justify-between p-4 rounded-xl border dark:border-slate-700 border-slate-100 dark:bg-slate-700/50 bg-slate-50 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                                <div className="flex items-center gap-4"><div className="w-10 h-10 rounded-lg flex items-center justify-center bg-white shadow-sm border p-1.5">{w.icon}</div><span className="font-bold dark:text-slate-200 text-slate-800">{w.name}</span></div><ChevronRight size={18} className="text-slate-400" />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {loginStep === 'CONNECTING' && selectedWallet && (
            <div className="flex flex-col items-center animate-in fade-in duration-500">
                <div className="relative mb-10">
                    <div className="w-32 h-32 rounded-full border-4 border-slate-800 border-b-indigo-500 animate-spin"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-lg p-3 overflow-hidden">
                            {selectedWallet.icon}
                        </div>
                    </div>
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">{t.connection.connecting}...</h2>
                <p className="text-slate-400 text-sm">{t.connection.approveIn} {selectedWallet.name}</p>
            </div>
        )}

        {(loginStep === 'SIGNING' || loginStep === 'VERIFYING') && selectedWallet && (
            <div className="absolute inset-0 z-30 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full max-w-xs rounded-2xl p-6 shadow-2xl border dark:border-slate-700">
                    <div className="flex items-center gap-3 mb-4 pb-4 border-b dark:border-slate-700">
                        <div className="w-8 h-8 rounded-full border p-1.5 bg-white flex items-center justify-center">{selectedWallet.icon}</div>
                        <h3 className="font-bold dark:text-white text-sm">{t.connection.sigRequest}</h3>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-900 rounded-lg p-3 mb-6 font-mono text-[10px] dark:text-slate-400 leading-relaxed">
                        {t.connection.msgToSign}:<br/>
                        Welcome to GoldenDex.<br/>By signing this message, you agree to the Terms of Service.
                    </div>
                    <div className="flex gap-3">
                        <button onClick={() => setLoginStep('INITIAL')} className="flex-1 py-3 rounded-xl border text-slate-500 text-sm font-bold">{t.cancel}</button>
                        <button 
                            onClick={() => { setLoginStep('VERIFYING'); setTimeout(() => { onConnect(); setLoginStep('INITIAL'); setSelectedWallet(null); }, 2000); }} 
                            className="flex-1 py-3 rounded-xl bg-indigo-600 text-white font-bold text-sm flex items-center justify-center gap-2"
                        >
                            {loginStep === 'VERIFYING' ? <><Loader2 size={16} className="animate-spin" /> {t.connection.verifying}</> : t.connection.sign}
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
    );
  }

  const renderHeader = (title: string) => (
    <div className="px-4 py-4 flex items-center gap-3 sticky top-0 bg-white dark:bg-slate-900 z-10 border-b dark:border-slate-800 border-slate-200">
      <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"><ChevronLeft size={24} className="dark:text-white" /></button>
      <h2 className="text-lg font-bold dark:text-white text-slate-900">{title}</h2>
    </div>
  );

  if (view === 'DEPOSIT') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.depositVaultTitle)}
      <div className="p-4 space-y-6 pb-24">
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.network}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-blue-500 border-4 border-slate-800"></div><span className="font-bold dark:text-white text-slate-900">Arbitrum One</span></div><CheckCircle size={16} className="text-emerald-500" /></div></div>
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.currency}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center gap-3"><div className="w-8 h-8 rounded-full bg-indigo-500/10 flex items-center justify-center text-indigo-500"><Coins size={16} /></div><span className="font-bold dark:text-white text-slate-900">USDC</span></div></div>
        <div className="space-y-3"><div className="flex justify-between items-center"><label className="text-xs font-bold text-slate-500 uppercase">{t.amount}</label><span className="text-[11px] text-slate-500">{t.walletBalance}: <span className="dark:text-white text-slate-900 font-mono font-bold">{externalWalletBalance.toFixed(2)}</span></span></div><div className="relative"><input type="text" value={depositAmount} onChange={handleDepositChange} placeholder={t.quantity} className="w-full bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-2xl p-4 pr-24 text-sm font-mono outline-none focus:border-indigo-500 dark:text-white" /><div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-3"><button onClick={() => setDepositAmount(externalWalletBalance.toString())} className="text-xs font-bold text-indigo-500">{t.max}</button><span className="text-xs font-bold text-slate-500 uppercase">USDC</span></div></div></div>
        <button onClick={handleWeb3Deposit} disabled={!isDepositValid || depositStatus !== 'IDLE'} className={`w-full py-4 mt-4 rounded-2xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${isDepositValid && depositStatus === 'IDLE' ? 'bg-[#2D3748] dark:bg-slate-800 text-white' : 'bg-slate-200 dark:bg-slate-700/30 text-slate-400 cursor-not-allowed shadow-none'}`}>{depositStatus === 'IDLE' ? <><Wallet size={18} /> {t.confirm}</> : <Loader2 size={18} className="animate-spin" />}</button>
      </div>
    </div>
  );

  if (view === 'WITHDRAW') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.withdrawVaultTitle)}
      <div className="p-4 space-y-6 pb-24">
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.network}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-blue-500 border-4 border-slate-800"></div><span className="font-bold dark:text-white text-slate-900">Arbitrum One</span></div><CheckCircle size={16} className="text-emerald-500" /></div></div>
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.currency}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center gap-3"><div className="w-8 h-8 rounded-full bg-indigo-500/10 flex items-center justify-center text-indigo-500"><Coins size={16} /></div><span className="font-bold dark:text-white text-slate-900">USDC</span></div></div>
        <div className="space-y-3"><div className="flex justify-between items-center"><label className="text-xs font-bold text-slate-500 uppercase">{t.amount}</label><span className="text-[11px] text-slate-500">{t.avail}: <span className="dark:text-white text-slate-900 font-mono font-bold">{balance.toFixed(2)}</span></span></div><div className="relative"><input type="text" value={withdrawAmount} onChange={handleWithdrawChange} placeholder={t.quantity} className="w-full bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-2xl p-4 pr-16 text-sm font-mono outline-none focus:border-indigo-500 dark:text-white" /><button onClick={() => setWithdrawAmount(balance.toString())} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-indigo-500">{t.max}</button></div></div>
        <button onClick={handleWeb3Withdraw} disabled={!isWithdrawValid || withdrawStatus !== 'IDLE'} className={`w-full py-4 mt-4 rounded-2xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${isWithdrawValid && withdrawStatus === 'IDLE' ? 'bg-[#2D3748] dark:bg-slate-800 text-white' : 'bg-slate-200 dark:bg-slate-700/30 text-slate-400 cursor-not-allowed shadow-none'}`}>{withdrawStatus === 'IDLE' ? <><ArrowRightLeft size={18} /> {t.confirm}</> : <Loader2 size={18} className="animate-spin" />}</button>
      </div>
    </div>
  );

  if (view === 'TRANSFER_HISTORY') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.transfers)}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar pb-24">
        {transferHistory.map(tx => {
          const isDeposit = tx.type === 'DEPOSIT';
          return (
