        <div className="grid grid-cols-3 gap-2 border-t border-white/10 pt-4">
           <div><p className="text-indigo-200 text-[9px] uppercase">{t.avail}</p><p className="font-mono font-bold text-xs">${balance.toFixed(2)}</p></div>
           <div className="text-center"><p className="text-indigo-200 text-[9px] uppercase">{t.unrealizedPnL}</p><p className={`font-mono font-bold text-xs ${unrealizedPnL >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{unrealizedPnL.toFixed(2)}</p></div>
           <div className="text-right"><p className="text-indigo-200 text-[9px] uppercase">{t.totalPerpValue}</p><p className="font-mono font-bold text-xs">${totalPositionValue.toFixed(2)}</p></div>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 mb-6"><button onClick={() => setView('DEPOSIT')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm transition-transform active:scale-95"><CreditCard size={18} className="text-indigo-500"/>{t.deposit}</button><button onClick={() => setView('WITHDRAW')} className="flex items-center justify-center gap-2 dark:bg-slate-800 bg-white py-4 rounded-xl text-sm font-bold border dark:border-slate-700 shadow-sm transition-transform active:scale-95"><ArrowRightLeft size={18} className="text-indigo-500"/>{t.withdraw}</button></div>
      <div className="dark:bg-slate-800 bg-white rounded-xl overflow-hidden border dark:border-slate-700 shadow-sm">
        <button onClick={() => setView('FILL_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700/50 transition-colors"><div className="flex items-center gap-3"><History size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.history}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('TRANSFER_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700/50 transition-colors"><div className="flex items-center gap-3"><ArrowRightLeft size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.transfers}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('CASH_FLOW_HISTORY')} className="w-full flex items-center justify-between p-4 border-b dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-700/50 transition-colors"><div className="flex items-center gap-3"><Coins size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.funding}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
        <button onClick={() => setView('SETTINGS')} className="w-full flex items-center justify-between p-4 hover:bg-slate-100 dark:hover:bg-slate-700/50 transition-colors"><div className="flex items-center gap-3"><Settings size={18} className="text-slate-400"/><span className="text-sm font-medium dark:text-slate-200">{t.settings}</span></div><ChevronRight size={16} className="text-slate-500"/></button>
      </div>
      <button onClick={onDisconnect} className="w-full py-4 mt-6 text-rose-500 font-bold bg-rose-500/5 rounded-xl border border-rose-500/10 transition-all active:scale-95 flex items-center justify-center gap-2"><LogOut size={18}/>{t.disconnect}</button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, FillRecord, TransferRecord, MarginMode, Language, Theme, CashFlowRecord, MarketTrade, Timeframe, PositionMode, MarketInfo } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL, TRANSLATIONS, MOCK_MARKETS } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';
import { CheckCircle, AlertTriangle, Bell, X } from 'lucide-react';

interface InternalNotification {
  id: string;
  title: string;
  content: string;
}

const NotificationOverlay = ({ notifications, onRemove }: { notifications: InternalNotification[], onRemove: (id: string) => void }) => {
  return (
    <div className="fixed top-4 left-1/2 -translate-x-1/2 w-[90%] max-w-sm z-[100] space-y-3 pointer-events-none">
      {notifications.map((n) => (
        <div 
          key={n.id} 
          className="pointer-events-auto bg-slate-900/95 backdrop-blur-md border border-slate-700 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-top duration-300 relative group"
        >
           <button onClick={() => onRemove(n.id)} className="absolute top-3 right-3 text-slate-500 hover:text-white transition-colors opacity-0 group-hover:opacity-100">
             <X size={14} />
           </button>
           <div className="flex items-start gap-3">
              <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center shrink-0 text-indigo-500">
                <Bell size={16} />
              </div>
              <div className="flex-1 overflow-hidden">
                <h4 className="text-sm font-bold text-white mb-1">{n.title}</h4>
                <p className="text-xs text-slate-400 leading-relaxed whitespace-pre-line">{n.content}</p>
              </div>
           </div>
        </div>
      ))}
    </div>
  );
};

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  const [orderHistory, setOrderHistory] = useState<Order[]>([
    { id: 'oh1', symbol: 'XAUUSDC', side: Side.LONG, type: 'LIMIT', price: 2010.50, amount: 2.0, filled: 0.8, status: 'PARTIAL_FILLED', timestamp: Date.now() - 3600000, marginMode: MarginMode.CROSS },
    { id: 'oh2', symbol: 'BTCUSDC', side: Side.SHORT, type: 'LIMIT', price: 68500.00, amount: 0.1, filled: 0.1, status: 'FILLED', timestamp: Date.now() - 7200000, marginMode: MarginMode.ISOLATED },
    { id: 'oh3', symbol: 'ETHUSDC', side: Side.LONG, type: 'LIMIT', price: 3200.00, amount: 5.0, filled: 0, status: 'CANCELLED', timestamp: Date.now() - 10800000, marginMode: MarginMode.CROSS },
    { id: 'oh4', symbol: 'XAUUSDC', side: Side.SHORT, type: 'LIMIT', price: 2050.25, amount: 1.5, filled: 1.5, status: 'FILLED', timestamp: Date.now() - 14400000, marginMode: MarginMode.CROSS }
  ]);

  const [fillHistory] = useState<FillRecord[]>([
    { id: 'f1', symbol: 'XAUUSDC', side: Side.LONG, price: 2015.42, size: 0.5, value: 1007.71, fee: -0.50, realizedPnl: 12.50, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'f2', symbol: 'BTCUSDC', side: Side.SHORT, price: 65200.10, size: 0.01, value: 652.00, fee: -0.32, realizedPnl: -5.20, timestamp: new Date('2025/12/22 04:36:43').getTime() }
  ]);

  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([
    { id: 't1', type: 'DEPOSIT', amount: 1000.00, timestamp: new Date('2025/12/20 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
    { id: 't2', type: 'WITHDRAW', amount: 200.00, timestamp: new Date('2025/12/19 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
  ]);

  const [cashFlowHistory] = useState<CashFlowRecord[]>([
    { id: 'cf1', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.1200, timestamp: new Date('2025/12/22 08:36:43').getTime() },
    { id: 'cf2', type: 'TRANSACTION_FEE', symbol: 'XAUUSDC', amount: -0.5000, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'cf3', type: 'REALIZED_PNL', symbol: 'XAUUSDC', amount: 12.5000, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'cf4', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.1100, timestamp: new Date('2025/12/22 00:36:43').getTime() },
    { id: 'cf5', type: 'LIQUIDATION_FEE', symbol: 'SOLUSDC', amount: -4.2000, timestamp: new Date('2025/12/21 21:36:43').getTime() },
    { id: 'cf6', type: 'REALIZED_PNL', symbol: 'ETHUSDC', amount: -8.4500, timestamp: new Date('2025/12/21 18:12:43').getTime() },
    { id: 'cf7', type: 'TRANSACTION_FEE', symbol: 'BTCUSDC', amount: -0.3200, timestamp: new Date('2025/12/21 14:05:43').getTime() }
  ]);

  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });
  const [notifications, setNotifications] = useState<InternalNotification[]>([]);

  const t = TRANSLATIONS[language];

  const triggerNotification = (title: string, content: string) => {
    const id = Date.now().toString();
    setNotifications(prev => [{ id, title, content }, ...prev].slice(0, 3));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 6000);
  };

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const newMarket = MOCK_MARKETS.find(m => m.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(newMarket.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]); 
  };

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;

      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const move = (Math.random() - 0.5) * 0.8;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), { ...lastCandle, close: newPrice, high: Math.max(lastCandle.high, newPrice), low: Math.min(lastCandle.low, newPrice) }];
      });
      setCurrentPrice(newPrice);

      if (Math.random() > 0.6) {
        setMarketTrades(prev => [
          {
            id: Date.now().toString(),
            price: newPrice + (Math.random() - 0.5) * 0.2,
            size: Math.random() * 2 + 0.01,
            side: Math.random() > 0.5 ? Side.LONG : Side.SHORT,
            time: new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })
          },
          ...prev.slice(0, 19)
        ]);
      }

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            const initialMargin = (order.amount * order.price) / 20;
            setPositions(prev => [{ id: Date.now().toString() + Math.random(), symbol: activeSymbol, side: order.side, size: order.amount, entryPrice: order.price, leverage: 20, unrealizedPnL: 0, marginMode: order.marginMode, isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);

            const fee = (order.amount * order.price * 0.0005);
            triggerNotification(
                t.appNotifications.limitFilled.title,
                t.appNotifications.limitFilled.content
                    .replace('{side}', order.side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
                    .replace('{size}', order.amount.toString())
                    .replace('{price}', order.price.toFixed(2))
                    .replace('{fee}', `$${fee.toFixed(2)}`)
            );
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol, language, t]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPos: Position = { id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined };
      setPositions(prev => [newPos, ...prev]);
      const fee = (size * price * 0.0005);
      triggerNotification(
        t.appNotifications.marketFilled.title,
        t.appNotifications.marketFilled.content
            .replace('{side}', side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
            .replace('{size}', size.toString())
            .replace('{price}', price.toFixed(2))
            .replace('{fee}', `$${fee.toFixed(2)}`)
      );
    } else {
      const newOrder: Order = { id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode };
      setOrders(prev => [newOrder, ...prev]);
      triggerNotification(
        t.appNotifications.orderSuccess.title,
        t.appNotifications.orderSuccess.content
            .replace('{symbol}', activeSymbol)
            .replace('{side}', side === Side.LONG ? t.longLabel : t.shortLabel)
            .replace('{type}', t.limit)
            .replace('{price}', price.toFixed(2))
            .replace('{size}', size.toString())
            .replace('{leverage}', leverage.toString())
      );
    }
  };

  const handleClosePosition = (id: string, amountToClose: number, executionPrice: number, type: 'MARKET' | 'LIMIT') => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === 'LIMIT') {
        const limitOrder: Order = { id: `cl-${Date.now()}`, symbol: pos.symbol, side: pos.side === Side.LONG ? Side.SHORT : Side.LONG, type: 'LIMIT', price: executionPrice, amount: amountToClose, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode: pos.marginMode };
        setOrders(prev => [limitOrder, ...prev]);
        triggerNotification(
            t.appNotifications.orderSuccess.title,
            t.appNotifications.orderSuccess.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.shortLabel : t.longLabel)
                .replace('{type}', t.limit)
                .replace('{price}', executionPrice.toFixed(2))
                .replace('{size}', amountToClose.toString())
                .replace('{leverage}', pos.leverage.toString())
        );
        return;
    }

    const priceDiff = executionPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? priceDiff * amountToClose : -priceDiff * amountToClose;
    let marginToReturn = (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) ? (pos.isolatedMargin * (amountToClose / pos.size)) : (pos.entryPrice * amountToClose) / pos.leverage;
    setBalance(prev => prev + marginToReturn + pnl);

    if (amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        triggerNotification(
            t.appNotifications.posClosed.title,
            t.appNotifications.posClosed.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose, isolatedMargin: p.isolatedMargin ? p.isolatedMargin * ((p.size - amountToClose) / p.size) : undefined } : p));
        triggerNotification(
            t.appNotifications.posReduced.title,
            t.appNotifications.posReduced.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{remaining}', (pos.size - amountToClose).toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    }
  };

  const handleUpdateMargin = (id: string, amount: number, type: 'ADD' | 'REMOVE') => {
      const pos = positions.find(p => p.id === id);
      if (!pos || !pos.isolatedMargin) return;

      if (type === 'ADD') {
          if (amount > balance) return;
          setBalance(prev => prev - amount);
          setPositions(prev => prev.map(p => p.id === id ? { ...p, isolatedMargin: (p.isolatedMargin || 0) + amount } : p));
      } else {
          const maintMargin = (pos.entryPrice * pos.size) * 0.01;
          const maxRemovable = pos.isolatedMargin - maintMargin;
          if (amount > maxRemovable) return;
          setBalance(prev => prev + amount);
          setPositions(prev => prev.map(p => p.id === id ? { ...p, isolatedMargin: (p.isolatedMargin || 0) - amount } : p));
      }

      triggerNotification(
          t.appNotifications.marginUpdated.title,
          t.appNotifications.marginUpdated.content
              .replace('{symbol}', pos.symbol)
              .replace('{amount}', (type === 'ADD' ? '+' : '-') + amount.toFixed(2))
      );
  };

  const handleDeposit = (amount: number) => {
    if (amount > externalWalletBalance) return;
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.deposit.title,
        t.appNotifications.deposit.content.replace('{amount}', amount.toLocaleString())
    );
  };

  const handleWithdraw = (amount: number) => {
    const WITHDRAW_FEE = 0.5;
    if (balance < amount) return false;
    const actualReceived = amount - WITHDRAW_FEE;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + actualReceived);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.withdraw.title,
        t.appNotifications.withdraw.content.replace('{amount}', actualReceived.toLocaleString()).replace('{address}', '0x71C7...9A23')
    );
    return true;
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => {
        const order = prev.find(o => o.id === id);
        if (order) {
            triggerNotification(
                language === 'en' ? 'Order Cancelled' : '订单已取消',
                language === 'en' 
                  ? `Successfully cancelled ${order.symbol} ${order.side} order.` 
                  : `已成功撤销 ${order.symbol} ${order.side === Side.LONG ? '买入' : '卖出'} 挂单。`
            );
        }
        return prev.filter(o => o.id !== id);
    });
  };

  const handleCancelAllOrders = () => {
    if (orders.length > 0) {
        setOrders([]);
        triggerNotification(
            language === 'en' ? 'All Orders Cancelled' : '全部订单已取消',
            language === 'en' ? 'Successfully cancelled all open orders.' : '已成功撤销所有当前挂单。'
        );
    }
  };

  const handleCloseAllPositions = () => {
    const count = positions.length;
    if (count === 0) return;
    setPositions([]);
    triggerNotification(
        language === 'en' ? 'All Positions Closed' : '全部持仓已平',
        language === 'en' 
          ? `Successfully closed all ${count} positions at market price.` 
          : `已成功以市价平掉所有当前持仓（共 ${count} 个）。`
    );
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);

  // Update Equity calculation to strictly include: available balance, unrealized PnL, and position margin.
  const equity = balance + marginLocked + totalUnrealizedPnL;

  const totalPosValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPosValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <NotificationOverlay notifications={notifications} onRemove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView symbol={activeSymbol} currentMarket={currentMarket} onSymbolChange={handleSymbolChange} candles={candles} currentPrice={currentPrice} balance={balance} marketTrades={marketTrades} onPlaceOrder={handlePlaceOrder} lang={language} timeframe={timeframe} onTimeframeChange={setTimeframe} positions={positions} />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={handleUpdateMargin} onCloseAllPositions={handleCloseAllPositions} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={handleCancelOrder} onCancelAllOrders={handleCancelAllOrders} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView balance={balance} equity={equity} unrealizedPnL={totalUnrealizedPnL} totalPositionValue={totalPosValue} externalWalletBalance={externalWalletBalance} fillHistory={fillHistory} transferHistory={transferHistory} cashFlowHistory={cashFlowHistory} onDeposit={handleDeposit} onWithdraw={handleWithdraw} isConnected={isWalletConnected} onConnect={() => setIsWalletConnected(true)} onDisconnect={() => setIsWalletConnected(false)} language={language} setLanguage={setLanguage} theme={theme} setTheme={setTheme} positionMode={positionMode} onSetPositionMode={setPositionMode} />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={setActiveTab} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Settings2, Info, X, BarChart2, TrendingUp, Layers, ChevronDown, Edit2, Search } from 'lucide-react';
import { CandleChart } from './CandleChart';
import { OrderBook } from './OrderBook';
import { DepthChart } from './DepthChart';
import { Candle, Side, MarginMode, Language, ChartType, MarketTrade, Timeframe, MarketInfo, Position } from '../types';
import { TRANSLATIONS, MOCK_MARKETS } from '../constants';

interface TradeViewProps {
  symbol: string;
  currentMarket: MarketInfo;
  onSymbolChange: (symbol: string) => void;
  candles: Candle[];
  currentPrice: number;
  balance: number;
  marketTrades?: MarketTrade[];
  onPlaceOrder: (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => void;
  lang: Language;
  timeframe: Timeframe;
  onTimeframeChange: (tf: Timeframe) => void;
  positions: Position[];
}

const TIMEFRAMES: Timeframe[] = ['1m', '3m', '5m', '15m', '30m', '1H', '2H', '4H', '8H', '12H', '1D', '3D', '1W', '1M'];

export const TradeView: React.FC<TradeViewProps> = ({ 
  symbol,
  currentMarket,
  onSymbolChange,
  candles, 
  currentPrice, 
  balance, 
  marketTrades = [], 
  onPlaceOrder, 
  lang,
  timeframe,
  onTimeframeChange,
  positions
}) => {
  const t = TRANSLATIONS[lang];
  const [orderType, setOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [marginMode, setMarginMode] = useState<MarginMode>(MarginMode.CROSS);
  const [chartType, setChartType] = useState<ChartType>('line');
  const [amount, setAmount] = useState<string>('');
  const [sizeUnit, setSizeUnit] = useState<'XAU' | 'USDC'>('XAU');
  const [limitPrice, setLimitPrice] = useState<string>(currentPrice.toFixed(2));
  const [leverage, setLeverage] = useState<number>(20);
  const [showFundingModal, setShowFundingModal] = useState(false);
  const [showLeverageModal, setShowLeverageModal] = useState(false);
  const [showMarketSelector, setShowMarketSelector] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [tempLeverage, setTempLeverage] = useState(20);
  const [activeBookTab, setActiveBookTab] = useState<'book' | 'trades'>('book');
  const [sizeSliderValue, setSizeSliderValue] = useState<number>(0);

  // Validation states
  const [amountError, setAmountError] = useState(false);
  const [priceError, setPriceError] = useState(false);

  const [countdown, setCountdown] = useState<string>('00:59:59');

  const changePercent = ((currentPrice - currentMarket.lastPrice * 0.98) / (currentMarket.lastPrice * 0.98)) * 100;
  const isPositiveChange = changePercent >= 0;

  const currentSymbolPositionValue = positions
    .filter(p => p.symbol === symbol)
    .reduce((acc, p) => acc + (p.size * currentPrice), 0);

  const filteredMarkets = useMemo(() => {
    return MOCK_MARKETS.filter(m => 
      m.symbol.toLowerCase().includes(searchQuery.toLowerCase()) || 
      m.name.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [searchQuery]);

  const formatVolume = (num: number) => {
    return Intl.NumberFormat('en-US', { notation: "compact", maximumFractionDigits: 2 }).format(num);
  };

  useEffect(() => {
    const timer = setInterval(() => {
        const now = new Date();
        const nextHour = new Date(now);
        nextHour.setHours(now.getHours() + 1, 0, 0, 0);
        const diff = nextHour.getTime() - now.getTime();
        const m = Math.floor((diff / (1000 * 60)) % 60).toString().padStart(2, '0');
        const s = Math.floor((diff / 1000) % 60).toString().padStart(2, '0');
        setCountdown(`00:${m}:${s}`);
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const executionPrice = orderType === 'LIMIT' ? (parseFloat(limitPrice) || currentPrice) : currentPrice;
  const maxBuyXAU = executionPrice > 0 ? (balance * leverage) / executionPrice : 0;
  const maxBuyUSDC = balance * leverage;

  const handleTrade = (side: Side) => {
    let hasError = false;

    // Validate Price (Limit only)
    if (orderType === 'LIMIT' && (!limitPrice || isNaN(parseFloat(limitPrice)) || parseFloat(limitPrice) <= 0)) {
      setPriceError(true);
      hasError = true;
    }

    // Validate Amount
    if (!amount || isNaN(parseFloat(amount)) || parseFloat(amount) <= 0) {
      setAmountError(true);
      hasError = true;
    }

    if (hasError) return;

    let size = parseFloat(amount);
    if (sizeUnit === 'USDC') size = size / executionPrice;
    onPlaceOrder(side, size, executionPrice, orderType, marginMode);
    setAmount('');
    setSizeSliderValue(0);
    setAmountError(false);
    setPriceError(false);
  };

  const longLiqPrice = executionPrice * (1 - 1/leverage);
  const shortLiqPrice = executionPrice * (1 + 1/leverage);
  const marginRequired = amount ? ((sizeUnit === 'XAU' ? parseFloat(amount) : parseFloat(amount)/executionPrice) * executionPrice / leverage) : 0;

  return (
    <div className="flex flex-col h-full pb-20 overflow-y-auto no-scrollbar dark:bg-slate-900 bg-slate-50 relative">
      <div className="dark:bg-slate-900 bg-white border-b dark:border-slate-800 border-slate-200 sticky top-0 z-30 shadow-sm">
          <div className="px-4 py-3 flex justify-between items-center">
            <div 
              className="flex items-center gap-2 cursor-pointer group"
              onClick={() => setShowMarketSelector(true)}
            >
              <div className="w-8 h-8 rounded-full border dark:border-slate-700 border-slate-200 flex items-center justify-center bg-slate-50 dark:bg-slate-800 overflow-hidden">
                  <div className="w-full h-full flex items-center justify-center font-bold text-indigo-500 bg-indigo-500/10">
                    {symbol.charAt(0)}
                  </div>
              </div>
              <div>
                <div className="flex items-center gap-1.5">
                  <h1 className="text-lg font-bold dark:text-white text-slate-900 leading-tight uppercase">{symbol}</h1>
                  <ChevronDown size={14} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
                </div>
                <span className="text-[10px] text-slate-400 font-medium tracking-wider">Perp</span>
              </div>
            </div>

            <div className="text-right">
              <div className={`text-xl font-mono font-bold ${isPositiveChange ? 'text-emerald-500' : 'text-rose-500'}`}>
                {currentPrice.toFixed(2)}
              </div>
              <div className="flex items-center justify-end gap-1.5 text-[10px]">
                <span className={`font-mono font-medium ${isPositiveChange ? 'text-emerald-500' : 'text-rose-500'}`}>
                   {isPositiveChange ? '+' : ''}{changePercent.toFixed(2)}%
                </span>
              </div>
            </div>
          </div>

          <div className="px-4 py-2 flex items-center justify-between gap-6 overflow-x-auto no-scrollbar whitespace-nowrap text-[10px] dark:bg-slate-800/50 bg-slate-50 border-t dark:border-slate-800 border-slate-100">
             <div className="flex flex-col shrink-0">
                <span className="text-slate-400 mb-0.5">{t.totalPerpValue}</span>
                <span className="font-mono dark:text-slate-200 text-slate-700 font-bold">{currentSymbolPositionValue.toFixed(2)}</span>
             </div>
             <div className="flex flex-col shrink-0">
                <span className="text-slate-400 mb-0.5">{t.vol24h}</span>
                <span className="font-mono dark:text-slate-200 text-slate-700">{formatVolume(currentMarket.volume24h)}</span>
             </div>
             <div 
                className="flex flex-col text-center cursor-pointer group shrink-0"
                onClick={() => setShowFundingModal(true)}
             >
                <span className="text-slate-400 mb-0.5 group-hover:text-indigo-500 border-b border-dashed border-slate-400/50 group-hover:border-indigo-500 transition-colors">{t.fundingRate}</span>
                <span className={`font-mono ${currentMarket.fundingRate >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>{currentMarket.fundingRate.toFixed(4)}%</span>
             </div>
             <div className="flex flex-col text-right shrink-0">
                <span className="text-slate-400 mb-0.5">{t.countdown}</span>
                <span className="font-mono dark:text-slate-200 text-slate-700">{countdown}</span>
             </div>
          </div>
      </div>

      {showMarketSelector && (
          <div className="fixed top-0 bottom-0 left-1/2 -translate-x-1/2 w-full max-w-md z-50 flex flex-col bg-white dark:bg-slate-900 animate-in fade-in slide-in-from-top duration-300 shadow-2xl border-x dark:border-slate-800 border-slate-200">
              <div className="p-4 flex items-center gap-3 border-b dark:border-slate-800 border-slate-100">
                  <div className="flex-1 relative">
                    <input 
                      type="text"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder={t.searchPlaceholder}
                      className="w-full bg-slate-100 dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-lg py-2 pl-4 pr-10 text-sm outline-none focus:ring-1 focus:ring-indigo-500 dark:text-white"
                      autoFocus
                    />
                    <Search size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  </div>
                  <button onClick={() => setShowMarketSelector(false)} className="text-slate-500 font-medium text-sm">{t.cancel}</button>
              </div>

              <div className="px-4 py-3 grid grid-cols-5 text-[10px] dark:text-slate-500 text-slate-400 font-bold uppercase tracking-wider border-b dark:border-slate-800/50 border-slate-50">
                  <span className="col-span-1">{t.marketList.contract}</span>
                  <span className="text-right">{t.marketList.lastPrice}</span>
                  <span className="text-right">{t.marketList.change}</span>
                  <span className="text-right">{t.marketList.volume}</span>
                  <span className="text-right">{t.marketList.funding}</span>
              </div>

              <div className="flex-1 overflow-y-auto no-scrollbar">
                  {filteredMarkets.map((m) => (
                      <div 
                        key={m.symbol}
                        onClick={() => {
                            onSymbolChange(m.symbol);
                            setShowMarketSelector(false);
                        }}
                        className={`px-4 py-4 grid grid-cols-5 items-center hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors border-b dark:border-slate-800/30 border-slate-50 ${m.symbol === symbol ? 'bg-slate-100 dark:bg-slate-800/50' : ''}`}
                      >
                          <div className="col-span-1 flex items-center gap-2">
                              <div className="w-6 h-6 rounded-full flex items-center justify-center font-bold text-[10px] bg-indigo-500/10 text-indigo-500">
                                {m.symbol.charAt(0)}
                              </div>
                              <div className="flex flex-col overflow-hidden">
                                  <span className="font-bold dark:text-white text-slate-900 text-xs truncate uppercase">{m.symbol}</span>
                                  <span className="text-[9px] bg-slate-200 dark:bg-slate-700 dark:text-slate-400 text-slate-600 rounded px-1 w-fit mt-0.5">{m.leverage}x</span>
                              </div>
                          </div>
                          <div className="text-right text-xs font-mono font-bold dark:text-slate-200 text-slate-700">
                              {m.lastPrice.toFixed(2)}
                          </div>
                          <div className={`text-right text-xs font-mono font-bold ${m.change24h >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                              {m.change24h >= 0 ? '+' : ''}{m.change24h.toFixed(2)}%
                          </div>
                          <div className="text-right text-[10px] font-mono dark:text-slate-400 text-slate-500">
                              {formatVolume(m.volume24h)}
                          </div>
                          <div className={`text-right text-[10px] font-mono ${m.fundingRate >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                              {m.fundingRate >= 0 ? '+' : ''}{m.fundingRate.toFixed(4)}%
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      )}

      <div className="relative border-b dark:border-slate-800 border-slate-200 dark:bg-slate-900 bg-white min-h-[290px]">
        <div className="flex items-center gap-1 overflow-x-auto no-scrollbar px-2 py-2 border-b dark:border-slate-800 border-slate-100 touch-pan-x">
           {TIMEFRAMES.map((tf) => (
               <button key={tf} onClick={() => onTimeframeChange(tf)} className={`text-[10px] font-bold px-2 py-1 rounded-md whitespace-nowrap transition-colors flex-shrink-0 ${timeframe === tf ? 'bg-indigo-500/10 text-indigo-500' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-300'}`}>{tf}</button>
           ))}
        </div>
        {chartType === 'depth' ? <DepthChart currentPrice={currentPrice} /> : <CandleChart data={candles} type={chartType} />}
        <div className="absolute top-10 right-2 bg-slate-100 dark:bg-slate-800 rounded-lg p-0.5 flex border dark:border-slate-700 border-slate-200 shadow-sm z-10">
            <button onClick={() => setChartType('line')} className={`p-1.5 rounded-md ${chartType === 'line' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}><TrendingUp size={14} /></button>
            <button onClick={() => setChartType('candle')} className={`p-1.5 rounded-md ${chartType === 'candle' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}><BarChart2 size={14} /></button>
            <button onClick={() => setChartType('depth')} className={`p-1.5 rounded-md ${chartType === 'depth' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}><Layers size={14} /></button>
        </div>
      </div>

      <div className="flex flex-1 min-h-[420px] dark:bg-slate-900 bg-white">
          <div className="w-[42%] border-r dark:border-slate-800 border-slate-200 flex flex-col">
             <div className="flex border-b dark:border-slate-800 border-slate-200">
                <button onClick={() => setActiveBookTab('book')} className={`flex-1 py-2 text-[10px] font-bold transition-colors border-b-2 ${activeBookTab === 'book' ? 'border-indigo-500 text-indigo-500' : 'border-transparent text-slate-400'}`}>{t.tabOrderBook}</button>
                <button onClick={() => setActiveBookTab('trades')} className={`flex-1 py-2 text-[10px] font-bold transition-colors border-b-2 ${activeBookTab === 'trades' ? 'border-indigo-500 text-indigo-500' : 'border-transparent text-slate-400'}`}>{t.tabRecentTrades}</button>
             </div>
             <div className="flex-1 overflow-hidden p-1">
                {activeBookTab === 'book' ? <OrderBook currentPrice={currentPrice} lang={lang} onPriceSelect={(p) => { setLimitPrice(p); setPriceError(false); }} markPrice={currentPrice * 1.0001} /> : (
                   <div className="h-full overflow-y-auto no-scrollbar px-1">
                      <div className="grid grid-cols-2 text-[9px] dark:text-slate-500 text-slate-400 mb-1"><span>{t.price}</span><span className="text-right">{t.qty}</span></div>
                      {marketTrades.map((trade) => (
                          <div key={trade.id} className="grid grid-cols-2 text-[9px] font-mono py-0.5"><span className={trade.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}>{trade.price.toFixed(2)}</span><span className="text-right dark:text-slate-300 text-slate-700">{trade.size.toFixed(4)}</span></div>
                      ))}
                   </div>
                )}
             </div>
          </div>

          <div className="w-[58%] p-3 flex flex-col">
              <div className="flex gap-2 mb-3">
                 <div className="flex-1 bg-slate-100 dark:bg-slate-800 rounded-md p-0.5 flex">
                    <button onClick={() => setMarginMode(MarginMode.CROSS)} className={`flex-1 text-[10px] font-bold rounded py-1.5 transition-all ${marginMode === MarginMode.CROSS ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}>{t.cross}</button>
                    <button onClick={() => setMarginMode(MarginMode.ISOLATED)} className={`flex-1 text-[10px] font-bold rounded py-1.5 transition-all ${marginMode === MarginMode.ISOLATED ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-400'}`}>{t.isolated}</button>
                 </div>
                 <button onClick={() => { setTempLeverage(leverage); setShowLeverageModal(true); }} className="flex-1 bg-slate-100 dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-md py-2 text-[10px] font-bold dark:text-white text-slate-900 flex items-center justify-center gap-1">{leverage}x <Edit2 size={8} /></button>
              </div>

              <div className="flex dark:bg-slate-800 bg-slate-100 rounded-lg p-0.5 mb-3">
                 <button onClick={() => { setOrderType('MARKET'); setPriceError(false); }} className={`flex-1 py-1 text-[10px] font-bold rounded-md ${orderType === 'MARKET' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500'}`}>{t.market}</button>
                 <button onClick={() => setOrderType('LIMIT')} className={`flex-1 py-1 text-[10px] font-bold rounded-md ${orderType === 'LIMIT' ? 'dark:bg-slate-600 bg-white dark:text-white text-slate-900 shadow' : 'text-slate-500'}`}>{t.limit}</button>
              </div>

              <div className="mb-3">
                 <label className="text-[10px] text-slate-500 block mb-1">{t.price}</label>
                 <div className="relative">
                     <input 
                        type="text" 
                        value={orderType === 'MARKET' ? `${t.market}` : limitPrice} 
                        onChange={(e) => {
                          setLimitPrice(e.target.value);
                          setPriceError(false);
                        }} 
                        disabled={orderType === 'MARKET'} 
                        className={`w-full dark:bg-slate-800 bg-slate-50 border rounded-lg py-2.5 px-3 text-sm font-mono outline-none transition-colors ${priceError ? 'border-rose-500 ring-1 ring-rose-500' : 'dark:border-slate-700 border-slate-200 focus:border-indigo-500'} ${orderType === 'MARKET' ? 'text-slate-400' : 'dark:text-white text-slate-900'}`} 
                      />
                     {orderType === 'LIMIT' && <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-slate-500">USDC</span>}
                 </div>
              </div>

              <div className="mb-6">
                 <div className="flex justify-between mb-1"><label className="text-[10px] text-slate-500">{t.size}</label><span className="text-[10px] text-slate-500">{t.avail}: <span className="dark:text-white text-slate-900 font-mono">{balance.toFixed(2)}</span> USDC</span></div>
                 <div className="relative">
                     <input 
                        type="number" 
                        value={amount} 
                        onChange={(e) => {
                          setAmount(e.target.value);
                          setAmountError(false);
                        }} 
                        placeholder={t.quantity} 
                        className={`w-full dark:bg-slate-800 bg-slate-50 border rounded-lg py-2.5 pl-3 pr-16 text-sm font-mono dark:text-white text-slate-900 outline-none transition-colors ${amountError ? 'border-rose-500 ring-1 ring-rose-500' : 'dark:border-slate-700 border-slate-200 focus:border-indigo-500'}`} 
                      />
                     <div className="absolute right-0 top-0 bottom-0 flex items-center pr-2">
                        <select value={sizeUnit} onChange={(e) => setSizeUnit(e.target.value as any)} className="bg-transparent border-none text-[10px] font-bold focus:ring-0 cursor-pointer dark:text-white text-slate-900"><option value="XAU">XAU</option><option value="USDC">USDC</option></select>
                     </div>
                 </div>
              </div>

              <div className="mb-4 px-2 relative h-10 flex items-center">
                 <div className="absolute inset-x-0 h-1 bg-slate-200 dark:bg-slate-700 rounded-lg"><div className="h-full bg-indigo-500 rounded-l-lg" style={{ width: `${sizeSliderValue}%` }} /></div>
                 <input type="range" min="0" max="100" step="1" value={sizeSliderValue} onChange={(e) => {
                    const val = parseInt(e.target.value);
                    setSizeSliderValue(val);
                    setAmountError(false);
                    if (val === 0) setAmount('');
                    else setAmount(((sizeUnit === 'XAU' ? maxBuyXAU : maxBuyUSDC) * val / 100).toFixed(4));
                 }} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
                 <div className="absolute h-8 w-8 bg-white dark:bg-slate-800 border-2 border-indigo-500 shadow-md rounded-full flex items-center justify-center z-10 pointer-events-none transition-transform" style={{ left: `${sizeSliderValue}%`, transform: 'translateX(-50%)' }}><span className="text-[10px] font-bold text-indigo-600 font-mono">{Math.round(sizeSliderValue)}%</span></div>
              </div>

              <div className="flex gap-2">
                  <button onClick={() => handleTrade(Side.LONG)} className="flex-1 py-3 rounded-lg bg-emerald-600 text-white font-bold text-sm shadow-lg shadow-emerald-900/10 active:scale-95 transition-transform">{t.long.split('/')[1]}</button>
                  <button onClick={() => handleTrade(Side.SHORT)} className="flex-1 py-3 rounded-lg bg-rose-600 text-white font-bold text-sm shadow-lg shadow-rose-900/10 active:scale-95 transition-transform">{t.short.split('/')[1]}</button>
              </div>

              <div className="mt-4 grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                     <div className="flex justify-between text-[10px]"><span className="text-slate-500">{t.estLiqPrice}</span><span className="font-mono text-orange-500">{longLiqPrice.toFixed(2)}</span></div>
                     <div className="flex justify-between text-[10px]"><span className="text-slate-500">{t.margin}</span><span className="font-mono dark:text-slate-300 text-slate-700">{marginRequired.toFixed(1)}</span></div>
                     <div className="flex justify-between text-[10px]"><span className="text-slate-500">{t.max}</span><span className="font-mono dark:text-slate-300 text-slate-700">{maxBuyXAU.toFixed(2)}</span></div>
                  </div>
                  <div className="space-y-1.5 border-l dark:border-slate-800 pl-3">
                     <div className="flex justify-between text-[10px]"><span className="text-slate-500">{t.estLiqPrice}</span><span className="font-mono text-orange-500">{shortLiqPrice.toFixed(2)}</span></div>
                     <div className="flex justify-between text-[10px]"><span className="text-slate-500">{t.margin}</span><span className="font-mono dark:text-slate-300 text-slate-700">{marginRequired.toFixed(1)}</span></div>
                     <div className="flex justify-between text-[10px]"><span className="text-slate-500">{t.max}</span><span className="font-mono dark:text-slate-300 text-slate-700">{maxBuyXAU.toFixed(2)}</span></div>
                  </div>
              </div>
          </div>
      </div>

      {showLeverageModal && (
        <div className="absolute inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
             <div className="bg-white dark:bg-slate-800 rounded-xl w-full max-w-sm p-6 shadow-2xl animate-in zoom-in-95 duration-200">
                 <div className="flex justify-between items-center mb-6"><h3 className="text-lg font-bold dark:text-white text-slate-900">{t.leverage}</h3><button onClick={() => setShowLeverageModal(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><X size={20}/></button></div>
                 <div className="mb-8 text-center"><div className="text-4xl font-mono font-bold text-indigo-500 mb-2">{tempLeverage}x</div><div className="text-xs text-slate-500">{t.maxPosition}: ${(balance * tempLeverage).toLocaleString()}</div></div>
                 <div className="mb-6 px-2"><input type="range" min="1" max="100" step="1" value={tempLeverage} onChange={(e) => setTempLeverage(parseInt(e.target.value))} className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500" /><div className="flex justify-between text-xs text-slate-400 mt-2 font-mono"><span>1x</span><span>25x</span><span>50x</span><span>75x</span><span>100x</span></div></div>
                 <div className="grid grid-cols-2 gap-3"><button onClick={() => setShowLeverageModal(false)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700">{t.cancel}</button><button onClick={() => { setLeverage(tempLeverage); setShowLeverageModal(false); if (amount && parseFloat(amount) > 0) { const newMax = (balance * tempLeverage) / executionPrice; const newPct = Math.min(100, (parseFloat(amount) / newMax) * 100); setSizeSliderValue(newPct); } }} className="py-3 rounded-xl bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-500/20 hover:bg-indigo-500">{t.confirmAction}</button></div>
             </div>
        </div>
      )}

      {showFundingModal && (
         <div className="absolute inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
             <div className="bg-white dark:bg-slate-800 rounded-xl w-full max-w-sm p-5 shadow-2xl animate-in zoom-in-95 duration-200">
                 <div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold dark:text-white text-slate-900">{t.fundingDetails.title}</h3><button onClick={() => setShowFundingModal(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><X size={20}/></button></div>
                 <div className="space-y-4">
                     <div className="flex justify-between text-sm"><span className="text-slate-500">{t.fundingDetails.interval}</span><span className="font-mono dark:text-slate-200 text-slate-800">{t.fundingDetails.intervalValue}</span></div>
                     <div className="flex justify-between text-sm"><span className="text-slate-500">{t.fundingDetails.direction}</span><span className="font-mono text-emerald-500">{t.fundingDetails.directionValue}</span></div>
                     <div className="border-t dark:border-slate-700 border-slate-100 my-2"></div>
                     <div className="flex justify-between text-sm"><span className="text-slate-500">{t.fundingDetails.interestRate}</span><span className="font-mono dark:text-slate-200 text-slate-800">0.0100%</span></div>
                     <div className="flex justify-between text-sm"><span className="text-slate-500">{t.fundingDetails.estimatedApr}</span><span className="font-mono text-orange-400">1.53%</span></div>
                 </div>
                 <button onClick={() => setShowFundingModal(false)} className="w-full mt-6 py-3 bg-indigo-600 text-white font-bold rounded-lg shadow-lg shadow-indigo-500/20">{t.confirmAction}</button>
             </div>
         </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Wallet, CreditCard, ArrowRightLeft, Shield, Settings, History, ChevronLeft, Copy, CheckCircle, ExternalLink, ArrowDownLeft, ArrowUpRight, LogOut, User, Coins, Moon, Sun, Loader2, X, ChevronRight, Lock, Info, Filter, ArrowRight, ChevronDown } from 'lucide-react';
import { FillRecord, TransferRecord, Side, Language, Theme, CashFlowRecord, CashFlowType, PositionMode } from '../types';
import { TRANSLATIONS } from '../constants';

interface AccountViewProps {
  balance: number;
  equity: number;
  unrealizedPnL: number;
  totalPositionValue: number;
  externalWalletBalance: number;
  fillHistory: FillRecord[];
  transferHistory: TransferRecord[];
  cashFlowHistory: CashFlowRecord[];
  onDeposit: (amount: number) => void;
  onWithdraw: (amount: number) => boolean;
  isConnected: boolean;
  onConnect: () => void;
  onDisconnect: () => void;
  language: Language;
  setLanguage: (lang: Language) => void;
  theme: Theme;
  setTheme: (theme: Theme) => void;
  positionMode: PositionMode;
  onSetPositionMode: (mode: PositionMode) => void;
}

type ViewState = 'MAIN' | 'DEPOSIT' | 'WITHDRAW' | 'FILL_HISTORY' | 'TRANSFER_HISTORY' | 'SETTINGS' | 'CASH_FLOW_HISTORY';
type LoginStep = 'INITIAL' | 'SELECT_WALLET' | 'CONNECTING' | 'SIGNING' | 'VERIFYING';

const WITHDRAW_FEE = 0.5;

const WALLETS = [
  { id: 'metamask', name: 'MetaMask', color: '#F6851B', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><path d="M27.5 2.5L25.5 5.5L28.5 10.5L30.5 4.5L27.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M4.5 2.5L7.5 5.5L3.5 10.5L1.5 4.5L4.5 2.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M16 23.5L9 28.5L23 28.5L16 23.5Z" fill="#E17726" stroke="#E17726" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/><path d="M9 11.5L5 17.5L9 28.5L16 23.5L23 28.5L27 17.5L23 11.5L16 16.5L9 11.5Z" fill="#F6851B" stroke="#F6851B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg> },
  { id: 'walletconnect', name: 'WalletConnect', color: '#3B99FC', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><path d="M26 11C23 8 19 6 16 6C13 6 9 8 6 11" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/><circle cx="8" cy="18" r="3" fill="#3B99FC"/><circle cx="24" cy="18" r="3" fill="#3B99FC"/><path d="M16 21V26" stroke="#3B99FC" strokeWidth="3" strokeLinecap="round"/></svg> },
  { id: 'okx', name: 'OKX Wallet', color: '#000000', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><rect width="32" height="32" rx="6" fill="currentColor" className="text-black dark:text-white"/><path d="M8 8H12V12H8V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 8H24V12H20V8Z" fill="currentColor" className="text-white dark:text-black"/><path d="M8 20H12V24H8V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M20 20H24V24H20V20Z" fill="currentColor" className="text-white dark:text-black"/><path d="M14 14H18V18H14V14Z" fill="currentColor" className="text-white dark:text-black"/></svg> },
  { id: 'binance', name: 'Binance Wallet', color: '#F0B90B', icon: <svg viewBox="0 0 32 32" className="w-12 h-12" fill="none"><path d="M16 6L22 12L16 18L10 12L16 6Z" fill="#F0B90B"/><path d="M10 12L4 18L10 24L16 18L10 12Z" fill="#F0B90B"/><path d="M22 12L28 18L22 24L16 18L22 12Z" fill="#F0B90B"/><path d="M16 18L22 24L16 30L10 24L16 18Z" fill="#F0B90B"/><circle cx="16" cy="18" r="2" fill="#1e293b"/></svg> }
];

const CURRENCIES = [
  { id: 'USDC', name: 'USDC', color: 'indigo', icon: <Coins size={16} /> },
  { id: 'USDT', name: 'USDT', color: 'emerald', icon: <Coins size={16} /> },
  { id: 'ETH', name: 'ETH', color: 'blue', icon: <Coins size={16} /> },
  { id: 'ARB', name: 'ARB', color: 'sky', icon: <Coins size={16} /> },
];

const EXCHANGE_RATES: Record<string, number> = {
  'USDC': 1.0,
  'USDT': 1.0,
  'ETH': 2500.0,
  'ARB': 0.85
};

export const AccountView: React.FC<AccountViewProps> = ({ 
  balance, equity, unrealizedPnL, totalPositionValue, externalWalletBalance, fillHistory, transferHistory, cashFlowHistory, onDeposit, onWithdraw, isConnected, onConnect, onDisconnect, language, setLanguage, theme, setTheme, positionMode, onSetPositionMode
}) => {
  const [view, setView] = useState<ViewState>('MAIN');
  const [loginStep, setLoginStep] = useState<LoginStep>('INITIAL');
  const [selectedWallet, setSelectedWallet] = useState<typeof WALLETS[0] | null>(null);

  const [depositAmount, setDepositAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [copied, setCopied] = useState(false);
  const [depositStatus, setDepositStatus] = useState<'IDLE' | 'APPROVING' | 'DEPOSITING' | 'SWAPPING' | 'SUCCESS'>('IDLE');
  const [withdrawStatus, setWithdrawStatus] = useState<'IDLE' | 'WITHDRAWING' | 'SUCCESS'>('IDLE');

  const [cashFlowFilter, setCashFlowFilter] = useState<CashFlowType | 'ALL'>('ALL');
  const [showFilterDropdown, setShowFilterDropdown] = useState(false);

  const [depositCurrency, setDepositCurrency] = useState(CURRENCIES[0]);
  const [showCurrencyDropdown, setShowCurrencyDropdown] = useState(false);

  const t = TRANSLATIONS[language];
  const walletAddress = "0x71C7...9A23";

  // Mock currency balances based on the prop for USDC
  const mockBalances = useMemo(() => ({
    'USDC': externalWalletBalance,
    'USDT': 2450.50,
    'ETH': 1.258,
    'ARB': 850.00
  }), [externalWalletBalance]);

  const currentDepositBalance = mockBalances[depositCurrency.id as keyof typeof mockBalances] || 0;

  // Reactively calculate estimated USDC for Deposit
  const estimatedUsdc = useMemo(() => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0) return 0;
    const rate = EXCHANGE_RATES[depositCurrency.id] || 1.0;
    return val * rate;
  }, [depositAmount, depositCurrency]);

  // Calculate estimated received for Withdraw
  const estWithdrawReceived = useMemo(() => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= WITHDRAW_FEE) return 0;
    return val - WITHDRAW_FEE;
  }, [withdrawAmount]);

  useEffect(() => {
    if (!isConnected) { setLoginStep('INITIAL'); setSelectedWallet(null); }
  }, [isConnected]);

  const handleCopy = () => {
    navigator.clipboard.writeText("0x71C762B34567890123456789A23"); 
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDepositChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setDepositAmount(value);
  };

  const handleWithdrawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (/^\d*\.?\d*$/.test(value)) setWithdrawAmount(value);
  };

  const handleWeb3Deposit = async () => {
    const val = parseFloat(depositAmount);
    if (isNaN(val) || val <= 0 || val > currentDepositBalance) return;

    // ETH doesn't require approval
    if (depositCurrency.id !== 'ETH') {
        setDepositStatus('APPROVING');
        await new Promise(resolve => setTimeout(resolve, 1500));
    }

    if (depositCurrency.id !== 'USDC') {
        setDepositStatus('SWAPPING');
        await new Promise(resolve => setTimeout(resolve, 2000));
    }

    setDepositStatus('DEPOSITING');
    await new Promise(resolve => setTimeout(resolve, 2000));

    onDeposit(estimatedUsdc);

    setDepositStatus('SUCCESS');
    setTimeout(() => { setDepositStatus('IDLE'); setDepositAmount(''); setView('MAIN'); }, 1500);
  };

  const handleWeb3Withdraw = async () => {
    const val = parseFloat(withdrawAmount);
    if (isNaN(val) || val <= WITHDRAW_FEE || val > balance) return;
    setWithdrawStatus('WITHDRAWING');
    await new Promise(resolve => setTimeout(resolve, 2000));
    const success = onWithdraw(val);
    if (success) {
        setWithdrawStatus('SUCCESS');
        setTimeout(() => { setWithdrawStatus('IDLE'); setWithdrawAmount(''); setView('MAIN'); }, 1500);
    } else setWithdrawStatus('IDLE');
  };

  const isDepositValid = !isNaN(parseFloat(depositAmount)) && parseFloat(depositAmount) > 0 && parseFloat(depositAmount) <= currentDepositBalance;
  const isWithdrawValid = !isNaN(parseFloat(withdrawAmount)) && parseFloat(withdrawAmount) > WITHDRAW_FEE && parseFloat(withdrawAmount) <= balance;

  if (!isConnected) {
    return (
      <div className="flex flex-col items-center justify-center h-full dark:bg-slate-900 bg-slate-50 overflow-hidden relative">
        {loginStep === 'INITIAL' && (
             <div className="flex flex-col items-center animate-in fade-in zoom-in duration-500 w-full max-w-sm p-6">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-2xl flex items-center justify-center mb-8 border border-indigo-500/20"><Wallet size={40} className="text-indigo-500" /></div>
                <h1 className="text-2xl font-bold dark:text-white text-slate-900 mb-2">{t.connect}</h1>
                <p className="dark:text-slate-400 text-slate-500 text-center mb-10 text-sm leading-relaxed">{t.connection.desc}</p>
                <button onClick={() => setLoginStep('SELECT_WALLET')} className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-600/20 active:scale-95 transition-all">{t.connect}</button>
            </div>
        )}

        {loginStep === 'SELECT_WALLET' && (
            <div className="absolute inset-0 z-20 flex items-end justify-center bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full rounded-t-[24px] p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
                    <div className="flex justify-between items-center mb-6"><h2 className="text-lg font-bold dark:text-white text-slate-900">{t.connection.selectWallet}</h2><button onClick={() => setLoginStep('INITIAL')} className="p-1 dark:text-slate-400"><X size={20}/></button></div>
                    <div className="space-y-3 pb-8">
                        {WALLETS.map((w) => (
                            <button key={w.id} onClick={() => { setSelectedWallet(w); setLoginStep('CONNECTING'); setTimeout(() => setLoginStep('SIGNING'), 2500); }} className="w-full flex items-center justify-between p-4 rounded-xl border dark:border-slate-700 border-slate-100 dark:bg-slate-700/50 bg-slate-50 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors">
                                <div className="flex items-center gap-4"><div className="w-10 h-10 rounded-lg flex items-center justify-center bg-white shadow-sm border p-1.5">{w.icon}</div><span className="font-bold dark:text-slate-200 text-slate-800">{w.name}</span></div><ChevronRight size={18} className="text-slate-400" />
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        )}

        {loginStep === 'CONNECTING' && selectedWallet && (
            <div className="flex flex-col items-center animate-in fade-in duration-500">
                <div className="relative mb-10">
                    <div className="w-32 h-32 rounded-full border-4 border-slate-800 border-b-indigo-500 animate-spin"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-lg p-3 overflow-hidden">
                            {selectedWallet.icon}
                        </div>
                    </div>
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">{t.connection.connecting}...</h2>
                <p className="text-slate-400 text-sm">{t.connection.approveIn} {selectedWallet.name}</p>
            </div>
        )}

        {(loginStep === 'SIGNING' || loginStep === 'VERIFYING') && selectedWallet && (
            <div className="absolute inset-0 z-30 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                <div className="bg-white dark:bg-slate-800 w-full max-w-xs rounded-2xl p-6 shadow-2xl border dark:border-slate-700">
                    <div className="flex items-center gap-3 mb-4 pb-4 border-b dark:border-slate-700">
                        <div className="w-8 h-8 rounded-full border p-1.5 bg-white flex items-center justify-center">{selectedWallet.icon}</div>
                        <h3 className="font-bold dark:text-white text-sm">{t.connection.sigRequest}</h3>
                    </div>
                    <div className="bg-slate-50 dark:bg-slate-900 rounded-lg p-3 mb-6 font-mono text-[10px] dark:text-slate-400 female-relaxed">
                        {t.connection.msgToSign}:<br/>
                        Welcome to GoldenDex.<br/>By signing this message, you agree to the Terms of Service.
                    </div>
                    <div className="flex gap-3">
                        <button onClick={() => setLoginStep('INITIAL')} className="flex-1 py-3 rounded-xl border text-slate-500 text-sm font-bold">{t.cancel}</button>
                        <button 
                            onClick={() => { setLoginStep('VERIFYING'); setTimeout(() => { onConnect(); setLoginStep('INITIAL'); setSelectedWallet(null); }, 2000); }} 
                            className="flex-1 py-3 rounded-xl bg-indigo-600 text-white font-bold text-sm flex items-center justify-center gap-2"
                        >
                            {loginStep === 'VERIFYING' ? <><Loader2 size={16} className="animate-spin" /> {t.connection.verifying}</> : t.connection.sign}
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
    );
  }

  const renderHeader = (title: string) => (
    <div className="px-4 py-4 flex items-center gap-3 sticky top-0 bg-white dark:bg-slate-900 z-10 border-b dark:border-slate-800 border-slate-200">
      <button onClick={() => setView('MAIN')} className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"><ChevronLeft size={24} className="dark:text-white" /></button>
      <h2 className="text-lg font-bold dark:text-white text-slate-900">{title}</h2>
    </div>
  );

  if (view === 'DEPOSIT') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.depositVaultTitle)}
      <div className="p-4 space-y-6 pb-24">
        <div className="bg-indigo-500/5 border border-indigo-500/20 rounded-2xl p-4 flex gap-3">
          <Info size={18} className="text-indigo-500 shrink-0 mt-0.5" />
          <p className="text-xs text-slate-600 dark:text-slate-400 leading-relaxed">
            {t.depositWarning}
          </p>
        </div>
        <div className="space-y-3"><label className="text-xs font-bold text-slate-500 uppercase">{t.network}</label><div className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-blue-500 border-4 border-slate-800"></div><span className="font-bold dark:text-white text-slate-900">Arbitrum One</span></div><CheckCircle size={16} className="text-emerald-500" /></div></div>

        <div className="space-y-3 relative">
          <label className="text-xs font-bold text-slate-500 uppercase">{t.currency}</label>
          <div 
            onClick={() => setShowCurrencyDropdown(!showCurrencyDropdown)}
            className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-2xl p-4 flex items-center justify-between cursor-pointer active:bg-slate-100 dark:active:bg-slate-700 transition-colors"
          >
            <div className="flex items-center gap-3">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center text-${depositCurrency.color}-500 bg-${depositCurrency.color}-500/10`}>
                {depositCurrency.icon}
              </div>
              <span className="font-bold dark:text-white text-slate-900">{depositCurrency.name}</span>
            </div>
            <ChevronDown size={18} className={`text-slate-400 transition-transform ${showCurrencyDropdown ? 'rotate-180' : ''}`} />
          </div>

          {showCurrencyDropdown && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-xl shadow-xl overflow-hidden z-20 animate-in slide-in-from-top-2 duration-200">
              {CURRENCIES.map(curr => (
                <div 
                  key={curr.id}
                  onClick={() => {
                    setDepositCurrency(curr);
                    setShowCurrencyDropdown(false);
                    setDepositAmount('');
                  }}
                  className={`p-4 flex items-center gap-3 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors cursor-pointer ${depositCurrency.id === curr.id ? 'bg-slate-50 dark:bg-slate-700/50' : ''}`}
                >
                  <div className={`w-6 h-6 rounded-full flex items-center justify-center text-${curr.color}-500 bg-${curr.color}-500/10`}>
                    {curr.icon}
                  </div>
                  <span className={`text-sm font-bold ${depositCurrency.id === curr.id ? 'text-indigo-500' : 'dark:text-white text-slate-900'}`}>{curr.name}</span>
                  {depositCurrency.id === curr.id && <CheckCircle size={16} className="ml-auto text-indigo-500" />}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <label className="text-xs font-bold text-slate-500 uppercase">{t.amount}</label>
            <span className="text-[11px] text-slate-500">{t.walletBalance}: <span className="dark:text-white text-slate-900 font-mono font-bold">{currentDepositBalance.toFixed(depositCurrency.id === 'ETH' ? 4 : 2)}</span></span>
          </div>
          <div className="relative">
            <input 
              type="text" 
              value={depositAmount} 
              onChange={handleDepositChange} 
              placeholder={t.quantity} 
              className="w-full bg-white dark:bg-slate-800 border dark:border-slate-700 border-slate-200 rounded-2xl p-4 pr-24 text-sm font-mono outline-none focus:border-indigo-500 dark:text-white" 
            />
            <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-3">
              <button onClick={() => setDepositAmount(currentDepositBalance.toString())} className="text-xs font-bold text-indigo-500">{t.max}</button>
              <span className="text-xs font-bold text-slate-500 uppercase">{depositCurrency.name}</span>
            </div>
          </div>

          {depositCurrency.id !== 'USDC' && estimatedUsdc > 0 && (
            <div className="px-1 flex items-center justify-between text-xs animate-in fade-in slide-in-from-top-1 duration-300">
               <span className="text-slate-500 font-medium">{t.estReceived}</span>
               <span className="text-indigo-500 font-bold font-mono">{estimatedUsdc.toFixed(2)} USDC</span>
            </div>
          )}
        </div>

        <button 
          onClick={handleWeb3Deposit} 
          disabled={!isDepositValid || depositStatus !== 'IDLE'} 
          className={`w-full py-4 mt-4 rounded-2xl font-bold transition-all shadow-lg flex items-center justify-center gap-3 ${isDepositValid && depositStatus === 'IDLE' ? 'bg-[#2D3748] dark:bg-slate-800 text-white active:scale-95' : 'bg-slate-200 dark:bg-slate-700/30 text-slate-400 cursor-not-allowed shadow-none'}`}
        >
          {depositStatus === 'IDLE' ? (
            <>{depositCurrency.id === 'USDC' ? t.confirm : t.quickSwap}</>
          ) : (
            <div className="flex items-center gap-2">
              <Loader2 size={18} className="animate-spin" />
              <span className="text-xs uppercase tracking-widest">
                {depositStatus === 'APPROVING' ? t.approving.replace('{currency}', depositCurrency.name).split('...')[0] : 
                 depositStatus === 'SWAPPING' ? t.quickSwap : 
                 t.depositing.split('...')[0]}
              </span>
            </div>
          )}
        </button>
      </div>
    </div>
  );

  if (view === 'WITHDRAW') return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-900 animate-in fade-in">
      {renderHeader(t.withdrawVaultTitle)}
      <div className="p-4 space-y-6 pb-24">
        <div className="bg-indigo-500/5 border border-indigo-500/20 rounded-2xl p-4 flex gap-3">
          <Info size={18} className="text-indigo-500 shrink-0 mt-0.5" />
          <p className="text-xs text-slate-600 dark:text-slate-400 leading-relaxed">
