        <div className="space-y-3 overflow-y-auto no-scrollbar pb-24 h-[calc(100vh-180px)]">
          {cashFlowHistory.filter(cf => cashFlowFilter === 'ALL' || cf.type === cashFlowFilter).map(cf => (
