  { 
    id: 'metamask', 
    name: 'MetaMask', 
    color: '#F6851B', 
    icon: <img src="https://upload.wikimedia.org/wikipedia/commons/3/36/MetaMask_Fox.svg" className="w-full h-full object-contain" alt="MetaMask" /> 
