};

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // 账户页面的初始子视图
  const [accountSubView, setAccountSubView] = useState<'MAIN' | 'DEPOSIT' | 'WITHDRAW' | 'FILL_HISTORY' | 'TRANSFER_HISTORY' | 'SETTINGS' | 'CASH_FLOW_HISTORY'>('MAIN');

  // Settings switches
  const [orderConfirmationEnabled, setOrderConfirmationEnabled] = useState<boolean>(true);
  const [popupNotificationsEnabled, setPopupNotificationsEnabled] = useState<boolean>(true);

  const [orderHistory, setOrderHistory] = useState<Order[]>([
    { id: 'oh1', symbol: 'XAUUSDC', side: Side.LONG, type: 'LIMIT', price: 2010.50, amount: 2.0, filled: 0.8, status: 'PARTIAL_FILLED', timestamp: Date.now() - 3600000, marginMode: MarginMode.CROSS },
    { id: 'oh2', symbol: 'BTCUSDC', side: Side.SHORT, type: 'LIMIT', price: 68500.00, amount: 0.1, filled: 0.1, status: 'FILLED', timestamp: Date.now() - 7200000, marginMode: MarginMode.ISOLATED },
    { id: 'oh3', symbol: 'ETHUSDC', side: Side.LONG, type: 'LIMIT', price: 3200.00, amount: 5.0, filled: 0, status: 'CANCELLED', timestamp: Date.now() - 10800000, marginMode: MarginMode.CROSS },
    { id: 'oh4', symbol: 'XAUUSDC', side: Side.SHORT, type: 'LIMIT', price: 2050.25, amount: 1.5, filled: 1.5, status: 'FILLED', timestamp: Date.now() - 14400000, marginMode: MarginMode.CROSS }
  ]);

  const [fillHistory] = useState<FillRecord[]>([
    { id: 'f1', symbol: 'XAUUSDC', side: Side.LONG, price: 2015.42, size: 0.5, value: 1007.71, fee: -0.50, realizedPnl: 12.50, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'f2', symbol: 'BTCUSDC', side: Side.SHORT, price: 65200.10, size: 0.01, value: 652.00, fee: -0.32, realizedPnl: -5.20, timestamp: new Date('2025/12/22 04:36:43').getTime() }
  ]);

  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([
    { id: 't1', type: 'DEPOSIT', amount: 1000.00, timestamp: new Date('2025/12/20 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
    { id: 't2', type: 'WITHDRAW', amount: 200.00, timestamp: new Date('2025/12/19 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
  ]);

  const [cashFlowHistory] = useState<CashFlowRecord[]>([
    { id: 'cf1', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.1200, timestamp: new Date('2025/12/22 08:36:43').getTime() },
    { id: 'cf2', type: 'TRANSACTION_FEE', symbol: 'XAUUSDC', amount: -0.5000, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'cf3', type: 'REALIZED_PNL', symbol: 'XAUUSDC', amount: 12.5000, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'cf4', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.1100, timestamp: new Date('2025/12/22 00:36:43').getTime() },
    { id: 'cf5', type: 'LIQUIDATION_FEE', symbol: 'SOLUSDC', amount: -4.2000, timestamp: new Date('2025/12/21 21:36:43').getTime() },
    { id: 'cf6', type: 'REALIZED_PNL', symbol: 'ETHUSDC', amount: -8.4500, timestamp: new Date('2025/12/21 18:12:43').getTime() },
    { id: 'cf7', type: 'TRANSACTION_FEE', symbol: 'BTCUSDC', amount: -0.3200, timestamp: new Date('2025/12/21 14:05:43').getTime() }
  ]);

  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });
  const [notifications, setNotifications] = useState<InternalNotification[]>([]);

  const t = TRANSLATIONS[language];

  const triggerNotification = (title: string, content: string) => {
    if (!popupNotificationsEnabled) return;
    const id = Date.now().toString();
    setNotifications(prev => [{ id, title, content }, ...prev].slice(0, 3));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 6000);
  };

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const newMarket = MOCK_MARKETS.find(m => m.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(newMarket.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]); 
  };

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;

      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const move = (Math.random() - 0.5) * 0.8;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), { ...lastCandle, close: newPrice, high: Math.max(lastCandle.high, newPrice), low: Math.min(lastCandle.low, newPrice) }];
      });
      setCurrentPrice(newPrice);

      if (Math.random() > 0.6) {
        setMarketTrades(prev => [
          {
            id: Date.now().toString(),
            price: newPrice + (Math.random() - 0.5) * 0.2,
            size: Math.random() * 2 + 0.01,
            side: Math.random() > 0.5 ? Side.LONG : Side.SHORT,
            time: new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })
          },
          ...prev.slice(0, 19)
        ]);
      }

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            const initialMargin = (order.amount * order.price) / 20;
            setPositions(prev => [{ id: Date.now().toString() + Math.random(), symbol: activeSymbol, side: order.side, size: order.amount, entryPrice: order.price, leverage: 20, unrealizedPnL: 0, marginMode: order.marginMode, isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);

            const fee = (order.amount * order.price * 0.0005);
            triggerNotification(
                t.appNotifications.limitFilled.title,
                t.appNotifications.limitFilled.content
                    .replace('{side}', order.side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
                    .replace('{size}', order.amount.toString())
                    .replace('{price}', order.price.toFixed(2))
                    .replace('{fee}', `$${fee.toFixed(2)}`)
            );
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol, language, t]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPos: Position = { id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined };
      setPositions(prev => [newPos, ...prev]);
      const fee = (size * price * 0.0005);
      triggerNotification(
        t.appNotifications.marketFilled.title,
        t.appNotifications.marketFilled.content
            .replace('{side}', side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
            .replace('{size}', size.toString())
            .replace('{price}', price.toFixed(2))
            .replace('{fee}', `$${fee.toFixed(2)}`)
      );
    } else {
      const newOrder: Order = { id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode };
      setOrders(prev => [newOrder, ...prev]);
      triggerNotification(
        t.appNotifications.orderSuccess.title,
        t.appNotifications.orderSuccess.content
            .replace('{symbol}', activeSymbol)
            .replace('{side}', side === Side.LONG ? t.longLabel : t.shortLabel)
            .replace('{type}', t.limit)
            .replace('{price}', price.toFixed(2))
            .replace('{size}', size.toString())
            .replace('{leverage}', leverage.toString())
      );
    }
  };

  const handleClosePosition = (id: string, amountToClose: number, executionPrice: number, type: 'MARKET' | 'LIMIT') => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === 'LIMIT') {
        const limitOrder: Order = { id: `cl-${Date.now()}`, symbol: pos.symbol, side: pos.side === Side.LONG ? Side.SHORT : Side.LONG, type: 'LIMIT', price: executionPrice, amount: amountToClose, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode: pos.marginMode };
        setOrders(prev => [limitOrder, ...prev]);
        triggerNotification(
            t.appNotifications.orderSuccess.title,
            t.appNotifications.orderSuccess.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.shortLabel : t.longLabel)
                .replace('{type}', t.limit)
                .replace('{price}', executionPrice.toFixed(2))
                .replace('{size}', amountToClose.toString())
                .replace('{leverage}', pos.leverage.toString())
        );
        return;
    }

    const priceDiff = executionPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? priceDiff * amountToClose : -priceDiff * amountToClose;
    let marginToReturn = (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) ? (pos.isolatedMargin * (amountToClose / pos.size)) : (pos.entryPrice * amountToClose) / pos.leverage;
    setBalance(prev => prev + marginToReturn + pnl);

    if (amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        triggerNotification(
            t.appNotifications.posClosed.title,
            t.appNotifications.posClosed.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose, isolatedMargin: p.isolatedMargin ? p.isolatedMargin * ((p.size - amountToClose) / p.size) : undefined } : p));
        triggerNotification(
            t.appNotifications.posReduced.title,
            t.appNotifications.posReduced.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{remaining}', (pos.size - amountToClose).toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    }
  };

  const handleUpdateMargin = (id: string, amount: number, type: 'ADD' | 'REMOVE') => {
      const pos = positions.find(p => p.id === id);
      if (!pos || !pos.isolatedMargin) return;

      if (type === 'ADD') {
          if (amount > balance) return;
          setBalance(prev => prev - amount);
          setPositions(prev => prev.map(p => p.id === id ? { ...p, isolatedMargin: (p.isolatedMargin || 0) + amount } : p));
      } else {
          const maintMargin = (pos.entryPrice * pos.size) * 0.01;
          const maxRemovable = pos.isolatedMargin - maintMargin;
          if (amount > maxRemovable) return;
          setBalance(prev => prev + amount);
          setPositions(prev => prev.map(p => p.id === id ? { ...p, isolatedMargin: (p.isolatedMargin || 0) - amount } : p));
      }

      triggerNotification(
          t.appNotifications.marginUpdated.title,
          t.appNotifications.marginUpdated.content
              .replace('{symbol}', pos.symbol)
              .replace('{amount}', (type === 'ADD' ? '+' : '-') + amount.toFixed(2))
      );
  };

  const handleDeposit = (amount: number) => {
    if (amount > externalWalletBalance) return;
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.deposit.title,
        t.appNotifications.deposit.content.replace('{amount}', amount.toLocaleString())
    );
  };

  const handleWithdraw = (amount: number) => {
    const WITHDRAW_FEE = 0.5;
    if (balance < amount) return false;
    const actualReceived = amount - WITHDRAW_FEE;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + actualReceived);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.withdraw.title,
        t.appNotifications.withdraw.content.replace('{amount}', actualReceived.toLocaleString()).replace('{address}', '0x71C7...9A23')
    );
    return true;
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => {
        const order = prev.find(o => o.id === id);
        if (order) {
            triggerNotification(
                language === 'en' ? 'Order Cancelled' : '订单已取消',
                language === 'en' 
                  ? `Successfully cancelled ${order.symbol} ${order.side} order.` 
                  : `已成功撤销 ${order.symbol} ${order.side === Side.LONG ? '买入' : '卖出'} 挂单。`
            );
        }
        return prev.filter(o => o.id !== id);
    });
  };

  const handleCancelAllOrders = () => {
    if (orders.length > 0) {
        setOrders([]);
        triggerNotification(
            language === 'en' ? 'All Orders Cancelled' : '全部订单已取消',
            language === 'en' ? 'Successfully cancelled all open orders.' : '已成功撤销所有当前挂单。'
        );
    }
  };

  const handleCloseAllPositions = () => {
    const count = positions.length;
    if (count === 0) return;
    setPositions([]);
    triggerNotification(
        language === 'en' ? 'All Positions Closed' : '全部持仓已平',
        language === 'en' 
          ? `Successfully closed all ${count} positions at market price.` 
          : `已成功以市价平掉所有当前持仓（共 ${count} 个）。`
    );
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);

  const equity = balance + marginLocked + totalUnrealizedPnL;

  const totalPosValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPosValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <NotificationOverlay notifications={notifications} onRemove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            symbol={activeSymbol} 
            currentMarket={currentMarket} 
            onSymbolChange={handleSymbolChange} 
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance} 
            marketTrades={marketTrades} 
            onPlaceOrder={handlePlaceOrder} 
            lang={language} 
            timeframe={timeframe} 
            onTimeframeChange={setTimeframe} 
            positions={positions}
            orderConfirmationEnabled={orderConfirmationEnabled}
            setOrderConfirmationEnabled={setOrderConfirmationEnabled}
            isConnected={isWalletConnected}
            onDepositClick={() => {
              setAccountSubView('DEPOSIT');
              setActiveTab(Tab.ACCOUNT);
            }}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={handleUpdateMargin} onCloseAllPositions={handleCloseAllPositions} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={handleCancelOrder} onCancelAllOrders={handleCancelAllOrders} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView 
            balance={balance} 
            equity={equity} 
            unrealizedPnL={totalUnrealizedPnL} 
            totalPositionValue={totalPosValue} 
            externalWalletBalance={externalWalletBalance} 
            fillHistory={fillHistory} 
            transferHistory={transferHistory} 
            cashFlowHistory={cashFlowHistory} 
            onDeposit={handleDeposit} 
            onWithdraw={handleWithdraw} 
            isConnected={isWalletConnected} 
            onConnect={() => setIsWalletConnected(true)} 
            onDisconnect={() => setIsWalletConnected(false)} 
            language={language} 
            setLanguage={setLanguage} 
            theme={theme} 
            setTheme={setTheme} 
            positionMode={positionMode} 
            onSetPositionMode={setPositionMode}
            orderConfirmationEnabled={orderConfirmationEnabled}
            setOrderConfirmationEnabled={setOrderConfirmationEnabled}
            popupNotificationsEnabled={popupNotificationsEnabled}
            setPopupNotificationsEnabled={setPopupNotificationsEnabled}
            initialView={accountSubView}
            onViewChanged={(v) => {
              // 当进入具体页面后，重置请求状态，避免下次手动切换 Tab 时重复进入
              if (v === 'MAIN') setAccountSubView('MAIN');
            }}
          />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={(tab) => {
        // 如果是手动切换到账户页，确保从主页开始
        if (tab === Tab.ACCOUNT) setAccountSubView('MAIN');
        setActiveTab(tab);
      }} ordersCount={orders.length} positionsCount={positions.length} lang={language} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Position, Side, MarginMode, Language } from '../types';
import { TrendingUp, TrendingDown, AlertTriangle, Plus, Minus, X, Trash2, ArrowRight, ArrowRightLeft, ChevronDown } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface PositionsViewProps {
  positions: Position[];
  currentPrice: number;
  equity: number;
  balance: number;
  maintenanceMargin: number;
  marginRatio: number;
  onClosePosition: (id: string, amount: number, price: number, type: 'MARKET' | 'LIMIT') => void;
  onUpdateMargin: (id: string, amount: number, type: 'ADD' | 'REMOVE') => void;
  onCloseAllPositions: () => void;
  lang: Language;
}

export const PositionsView: React.FC<PositionsViewProps> = ({ 
  positions, 
  currentPrice, 
  equity,
  balance,
  maintenanceMargin,
  marginRatio,
  onClosePosition,
  onUpdateMargin,
  onCloseAllPositions,
  lang
}) => {
  const t = TRANSLATIONS[lang];
  const [editingPosId, setEditingPosId] = useState<string | null>(null);
  const [marginAction, setMarginAction] = useState<'ADD' | 'REMOVE'>('ADD');

  // Close Position Modal State
  const [closingPosId, setClosingPosId] = useState<string | null>(null);
  const [closeOrderType, setCloseOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [closePrice, setClosePrice] = useState<string>('');
  const [closeAmount, setCloseAmount] = useState<string>('');
  const [closePercent, setClosePercent] = useState<number>(100);
  const [closeUnit, setCloseUnit] = useState<'XAU' | 'USDC'>('XAU');

  // Independent states for Add and Remove inputs
  const [addMarginInput, setAddMarginInput] = useState<string>('');
  const [removeMarginInput, setRemoveMarginInput] = useState<string>('');

  const [showCloseAllConfirm, setShowCloseAllConfirm] = useState(false);

  // 判断是否存在全仓仓位
  const hasCrossPositions = positions.some(p => p.marginMode === MarginMode.CROSS);

  // Helper to get correct input state
  const currentMarginInput = marginAction === 'ADD' ? addMarginInput : removeMarginInput;
  const setMarginInput = (val: string) => {
      if (marginAction === 'ADD') setAddMarginInput(val);
      else setRemoveMarginInput(val);
  };

  const handleConfirmMargin = () => {
    if (editingPosId && currentMarginInput) {
        onUpdateMargin(editingPosId, parseFloat(currentMarginInput), marginAction);
        setEditingPosId(null);
        setAddMarginInput('');
        setRemoveMarginInput('');
    }
  };

  const closingPos = positions.find(p => p.id === closingPosId);

  // Handle Close Modal Price/Amount logic
  useEffect(() => {
    if (closingPos) {
       const maxInXAU = closingPos.size;
       const targetXAU = maxInXAU * closePercent / 100;

       if (closeUnit === 'XAU') {
          setCloseAmount(targetXAU.toFixed(4));
       } else {
          setCloseAmount((targetXAU * currentPrice).toFixed(2));
       }

       if (closeOrderType === 'MARKET') {
          setClosePrice('');
       } else if (!closePrice) {
          setClosePrice(currentPrice.toFixed(2));
       }
    }
  }, [closingPosId, closePercent, closeOrderType, currentPrice, closeUnit]);

  const handleExecuteClose = () => {
    if (closingPosId && closingPos && closeAmount) {
       let xauAmount = parseFloat(closeAmount);
       if (closeUnit === 'USDC') {
          xauAmount = xauAmount / currentPrice;
       }
       const executionPrice = closeOrderType === 'MARKET' ? currentPrice : (parseFloat(closePrice) || currentPrice);
       onClosePosition(closingPosId, xauAmount, executionPrice, closeOrderType);
       setClosingPosId(null);
    }
  };

  // Close Button Validation
  const closeNum = parseFloat(closeAmount);
  const maxInUnit = closingPos ? (closeUnit === 'XAU' ? closingPos.size : closingPos.size * currentPrice) : 0;
  const isCloseValid = !isNaN(closeNum) && closeNum > 0 && closeNum <= (maxInUnit + 0.0001);

  const getPositionMetrics = () => {
      const pos = positions.find(p => p.id === editingPosId);
      if (!pos || !pos.isolatedMargin) return null;

      const inputVal = parseFloat(currentMarginInput) || 0;
      const change = marginAction === 'ADD' ? inputVal : -inputVal;
      const currentMarginValue = pos.isolatedMargin;
      const newMarginValue = Math.max(0, currentMarginValue + change);

      const posValue = pos.entryPrice * pos.size;
      const currentLeverage = posValue / currentMarginValue;
      const newLeverage = newMarginValue > 0 ? posValue / newMarginValue : 0;

      const maintMarginReq = posValue * 0.01; 
      const currentRatio = (maintMarginReq / currentMarginValue) * 100;
      const newRatio = newMarginValue > 0 ? (maintMarginReq / newMarginValue) * 100 : 0;

      let currentLiq = pos.side === Side.LONG ? pos.entryPrice - (currentMarginValue / pos.size) : pos.entryPrice + (currentMarginValue / pos.size);
      let newLiq = pos.side === Side.LONG ? pos.entryPrice - (newMarginValue / pos.size) : pos.entryPrice + (newMarginValue / pos.size);

      const maxRemove = Math.max(0, currentMarginValue - maintMarginReq);

      return { currentMarginValue, newMarginValue, currentLeverage, newLeverage, currentLiq, newLiq, currentRatio, newRatio, maxRemove };
  };

  const metrics = editingPosId ? getPositionMetrics() : null;

  const isMarginInputValid = () => {
      const val = parseFloat(currentMarginInput);
      if (isNaN(val) || val <= 0) return false;
      return marginAction === 'ADD' ? val <= balance : val <= (metrics?.maxRemove || 0);
  };

  const renderRiskHeader = () => {
    // 只有全仓模式时才显示顶部的汇总栏
    if (!hasCrossPositions) return null;

    return (
      <div className="dark:bg-slate-800/50 bg-white/80 border-b dark:border-slate-800 border-slate-200 p-4 sticky top-0 backdrop-blur-md z-10 animate-in fade-in duration-300">
        <div className="grid grid-cols-3 gap-2">
          <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
             <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginRatio}</div>
             <div className={`font-mono font-bold text-sm ${marginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>{marginRatio.toFixed(2)}%</div>
          </div>
          <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
             <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.maintMargin}</div>
             <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${maintenanceMargin.toFixed(2)}</div>
          </div>
          <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
             <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginBal}</div>
             <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${equity.toFixed(2)}</div>
          </div>
        </div>
      </div>
    );
  };

  if (positions.length === 0) {
    return (
      <div className="h-full flex flex-col">
        {renderRiskHeader()}
        <div className="flex-1 flex flex-col items-center justify-center dark:text-slate-500 text-slate-400">
          <div className="dark:bg-slate-800 bg-white p-4 rounded-full mb-4 shadow-sm border dark:border-slate-700 border-slate-200">
             <TrendingUp size={32} className="opacity-50" />
          </div>
          <p>{t.noPositions}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col dark:bg-slate-900 bg-slate-50 relative">
      {renderRiskHeader()}
      <div className="flex-1 p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar">
        <div className="flex justify-between items-center mb-2">
           <h2 className="dark:text-slate-400 text-slate-500 text-xs uppercase font-bold tracking-wider">{t.openPositions} ({positions.length})</h2>
           <button onClick={() => setShowCloseAllConfirm(true)} className="text-xs bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 px-2 py-1 rounded border border-rose-500/20 flex items-center gap-1"><Trash2 size={12} />{t.closeAll}</button>
        </div>

        {positions.map((pos) => {
          const priceDiff = currentPrice - pos.entryPrice;
          const pnl = pos.side === Side.LONG ? priceDiff * pos.size : -priceDiff * pos.size;
          const marginUsed = pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin ? pos.isolatedMargin : (pos.entryPrice * pos.size) / pos.leverage;
          const liquidationPrice = pos.side === Side.LONG ? pos.entryPrice - (marginUsed / pos.size) : pos.entryPrice + (marginUsed / pos.size);
          const isProfit = pnl >= 0;
          const roi = (pnl / marginUsed) * 100;

          // 逐仓数据计算
          const posValue = pos.entryPrice * pos.size;
          const posMaintMargin = posValue * 0.01;
          const posMarginRatio = (posMaintMargin / marginUsed) * 100;
          const posMarginBal = marginUsed + pnl;

          return (
            <div key={pos.id} className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded ${pos.side === Side.LONG ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                    {pos.side === Side.LONG ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                  </div>
                  <div>
                    <h3 className="font-bold dark:text-white text-slate-900 flex items-center gap-2">
                      {pos.symbol}
                      <span className="text-[9px] dark:bg-slate-700 bg-slate-200 dark:text-slate-300 text-slate-600 px-1.5 py-0.5 rounded uppercase font-normal tracking-wide border dark:border-slate-600 border-slate-300">
                        {pos.marginMode === MarginMode.ISOLATED ? t.isolated : t.cross}
                      </span>
                    </h3>
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 inline-block ${pos.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                      {pos.leverage}x {pos.side === Side.LONG ? t.longLabel : t.shortLabel}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-lg font-mono font-bold leading-tight ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {isProfit ? '+' : ''}{pnl.toFixed(2)}
                  </div>
                  <div className={`text-[10px] font-bold font-mono mt-0.5 ${isProfit ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {isProfit ? '+' : ''}{roi.toFixed(2)}%
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-y-2 text-xs mb-4">
                <div className="dark:text-slate-400 text-slate-500">{t.size} (XAU)</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.size.toFixed(4)}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.entryPrice}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.entryPrice.toFixed(2)}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.liqPrice}</div>
                <div className="text-right text-orange-500 font-mono font-bold">{liquidationPrice > 0 ? liquidationPrice.toFixed(2) : '0.00'}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.margin}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono flex items-center justify-end gap-2">
                    {marginUsed.toFixed(2)}
                    {pos.marginMode === MarginMode.ISOLATED && (
                        <button onClick={() => { setEditingPosId(pos.id); setMarginAction('ADD'); }} className="bg-indigo-500/20 text-indigo-500 p-0.5 rounded hover:bg-indigo-500/30"><Plus size={10} /></button>
                    )}
                </div>
              </div>

              {/* 逐仓模式专属独立统计区 */}
              {pos.marginMode === MarginMode.ISOLATED && (
                <div className="animate-in fade-in duration-500">
                  <div className="w-full h-px bg-slate-200 dark:bg-slate-700 mb-3 opacity-50"></div>
                  <div className="grid grid-cols-3 gap-2 mb-4">
                    <div className="space-y-1">
                      <div className="text-[9px] dark:text-slate-500 text-slate-400 uppercase">{t.marginRatio}</div>
                      <div className={`font-mono text-[11px] font-bold ${posMarginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>{posMarginRatio.toFixed(2)}%</div>
                    </div>
                    <div className="space-y-1 border-l dark:border-slate-700 pl-2">
                      <div className="text-[9px] dark:text-slate-500 text-slate-400 uppercase">{t.maintMargin}</div>
                      <div className="font-mono text-[11px] dark:text-slate-300 text-slate-700">${posMaintMargin.toFixed(2)}</div>
                    </div>
                    <div className="space-y-1 border-l dark:border-slate-700 pl-2">
                      <div className="text-[9px] dark:text-slate-500 text-slate-400 uppercase">{t.marginBal}</div>
                      <div className="font-mono text-[11px] dark:text-slate-300 text-slate-700">${posMarginBal.toFixed(2)}</div>
                    </div>
                  </div>
                </div>
              )}

              <button onClick={() => { setClosingPosId(pos.id); setClosePercent(100); }} className="w-full py-2.5 dark:bg-slate-700 bg-slate-100 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2">{t.closePos}</button>
            </div>
          );
        })}
      </div>

      {/* 平仓 Modal 代码保持不变 */}
      {closingPos && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in">
             <div className="bg-[#1b2331] w-full max-w-sm rounded-[24px] p-6 shadow-2xl border border-slate-700/50">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-xl text-white">{t.closePos}</h3>
                    <button onClick={() => setClosingPosId(null)} className="text-slate-400 hover:text-white transition-colors">
                      <X size={24}/>
                    </button>
                </div>

                <div className="flex justify-between items-start mb-6">
                    <div>
                      <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mb-1">{t.tradeHistoryFields.pair}</p>
                      <div className="flex items-center gap-2">
                        <span className="text-xl font-bold text-indigo-400 uppercase tracking-tight">{closingPos.symbol}</span>
                        <span className="text-xl font-bold text-slate-500">/</span>
                        <span className={`text-xl font-bold ${closingPos.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}`}>
                          {closingPos.side === Side.LONG ? t.longLabel : t.shortLabel}
                        </span>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-[10px] text-slate-500 font-medium mb-1">
                        {t.entryPrice}: <span className="text-slate-200 font-mono ml-1">{closingPos.entryPrice.toFixed(2)}</span>
                      </div>
                      <div className="text-[10px] text-slate-500 font-medium">
                        {t.markPrice}: <span className="text-slate-200 font-mono ml-1">{currentPrice.toFixed(2)}</span>
                      </div>
                    </div>
                </div>

                <div className="w-full h-px bg-slate-700/50 mb-6"></div>

                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.price}</label>
                        <div className="w-full bg-[#131a26] border border-slate-700/80 rounded-xl px-4 py-3 text-sm font-mono text-white flex items-center justify-center h-14">
                           {closeOrderType === 'MARKET' ? t.market : (
                             <input 
                                type="text" 
                                value={closePrice} 
                                onChange={(e) => setClosePrice(e.target.value)} 
                                className="bg-transparent border-none outline-none w-full text-center" 
                             />
                           )}
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.mode}</label>
                        <div className="w-full bg-[#131a26] border border-slate-700/80 rounded-xl px-4 py-3 flex items-center justify-between cursor-pointer h-14" onClick={() => setCloseOrderType(closeOrderType === 'MARKET' ? 'LIMIT' : 'MARKET')}>
                            <span className="text-sm text-white font-medium">{closeOrderType === 'MARKET' ? t.market : t.limit}</span>
                            <ArrowRightLeft size={16} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                <div className="space-y-1.5 mb-8">
                    <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.size}</label>
                    <div className="relative group">
                        <input 
                           type="number" 
                           value={closeAmount} 
                           onChange={(e) => setCloseAmount(e.target.value)} 
                           className="w-full bg-[#131a26] border border-slate-700/80 group-focus-within:border-indigo-500/50 rounded-xl px-4 py-4 text-lg font-mono text-white outline-none h-14" 
                        />
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center">
                           <span className="text-[10px] font-bold text-slate-200 mr-1 uppercase">XAU</span>
                           <ChevronDown size={14} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                <div className="mb-10 px-1 relative h-6 flex items-center group">
                   <div className="absolute inset-x-0 h-1 bg-slate-700/50 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-500 transition-all" style={{ width: `${closePercent}%` }} />
                   </div>
                   <input 
                      type="range" 
                      min="0" 
                      max="100" 
                      step="1" 
                      value={closePercent} 
                      onChange={(e) => setClosePercent(parseInt(e.target.value))} 
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" 
                   />
                   <div 
                      className="absolute h-6 w-6 bg-indigo-500 border-2 border-[#1b2331] shadow-[0_0_10px_rgba(99,102,241,0.5)] rounded-full flex items-center justify-center z-10 pointer-events-none transition-transform group-active:scale-110" 
                      style={{ left: `${closePercent}%`, transform: 'translateX(-50%)' }}
                   >
                     <div className="absolute bottom-[30px] bg-indigo-600 text-white text-[9px] font-bold py-1 px-1.5 rounded-md shadow-lg after:content-[''] after:absolute after:top-full after:left-1/2 after:-translate-x-1/2 after:border-4 after:border-transparent after:border-t-indigo-600">
                        {closePercent}%
                     </div>
                   </div>
                </div>

                <div className="bg-[#131a26]/50 border border-slate-700/30 rounded-2xl p-5 mb-8">
                   <div className="flex justify-between items-center mb-3">
                      <span className="text-xs text-slate-500 font-medium">{t.closeOperation.positionSize}</span>
                      <span className="text-sm font-bold text-white font-mono">{closingPos.size.toFixed(4)} XAU</span>
                   </div>
                   <div className="flex justify-between items-center">
                      <span className="text-xs text-slate-500 font-medium">{t.closeOperation.estPnL}</span>
                      <span className={`text-sm font-bold font-mono ${((currentPrice - closingPos.entryPrice) * (parseFloat(closeAmount) || 0) * (closingPos.side === Side.LONG ? 1 : -1)) >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                         {((currentPrice - closingPos.entryPrice) * (parseFloat(closeAmount) || 0) * (closingPos.side === Side.LONG ? 1 : -1)).toFixed(2)} USDC
                      </span>
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <button 
                       onClick={() => setClosingPosId(null)} 
                       className="py-4 rounded-xl border border-slate-700 font-bold text-slate-400 hover:bg-slate-800 hover:text-white transition-all active:scale-95"
                    >
                      {t.cancel}
                    </button>
                    <button 
                       onClick={handleExecuteClose} 
                       disabled={!isCloseValid} 
                       className={`py-4 rounded-xl font-bold text-white shadow-[0_4px_20px_rgba(79,70,229,0.3)] transition-all active:scale-95 ${isCloseValid ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-slate-700 text-slate-500 cursor-not-allowed'}`}
                    >
                      {t.confirm}
                    </button>
                </div>
             </div>
          </div>
      )}

      {/* 调整保证金 Modal 代码保持不变 */}
      {editingPosId && metrics && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
             <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-2xl p-6 shadow-2xl border dark:border-slate-700 border-slate-200">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg dark:text-white text-slate-900">{t.addMargin}</h3>
                    <button onClick={() => setEditingPosId(null)} className="dark:text-slate-400 text-slate-500"><X size={20}/></button>
                </div>
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1 mb-4">
                    <button onClick={() => setMarginAction('ADD')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'ADD' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.add}</button>
                    <button onClick={() => setMarginAction('REMOVE')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'REMOVE' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.remove}</button>
                </div>
                <div className="mb-4">
                    <div className="flex justify-between mb-1">
                        <label className="text-xs text-slate-500 block">{t.amount} (USDC)</label>
                        <span className="text-xs text-slate-500">{marginAction === 'ADD' ? t.avail : t.maxRemove}: <span className="font-mono">{marginAction === 'ADD' ? balance.toFixed(2) : metrics.maxRemove.toFixed(2)}</span></span>
                    </div>
                    <div className="relative">
                        <input type="number" value={currentMarginInput} onChange={(e) => setMarginInput(e.target.value)} placeholder={t.quantity} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-3 pr-16 font-mono text-lg outline-none focus:border-indigo-500 dark:text-white" />
                        <button onClick={() => setMarginInput((marginAction === 'ADD' ? balance : metrics.maxRemove).toFixed(2))} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-indigo-500">{t.max}</button>
                    </div>
                </div>
                <div className="bg-slate-50 dark:bg-slate-900 border dark:border-slate-700 border-slate-200 rounded-xl p-3 mb-6 space-y-3 text-[11px]">
                   <div className="flex items-center gap-2 mb-2"><span className="font-bold text-slate-400 flex-1 text-center">{t.before}</span><ArrowRight size={12} className="text-slate-400" /><span className="font-bold text-indigo-500 flex-1 text-center">{t.after}</span></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.margin}</div><div className="flex-1 text-center font-mono">{metrics.currentMarginValue.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newMarginValue.toFixed(2)}</div></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.leverage}</div><div className="flex-1 text-center font-mono">{metrics.currentLeverage.toFixed(1)}x</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newLeverage.toFixed(1)}x</div></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.marginRatio}</div><div className="flex-1 text-center font-mono">{metrics.currentRatio.toFixed(2)}%</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newRatio.toFixed(2)}%</div></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.estLiqPrice}</div><div className="flex-1 text-center font-mono text-orange-500">{metrics.currentLiq.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-orange-500">{metrics.newLiq.toFixed(2)}</div></div>
                </div>
                <div className="grid grid-cols-2 gap-3"><button onClick={() => setEditingPosId(null)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">{t.cancel}</button><button handleConfirmMargin={handleConfirmMargin} disabled={!isMarginInputValid()} className={`py-3 rounded-xl font-bold shadow-lg transition-all ${isMarginInputValid() ? 'bg-indigo-600 text-white shadow-indigo-500/20' : 'bg-slate-300 text-slate-500 cursor-not-allowed'}`}>{t.confirmAction}</button></div>
             </div>
          </div>
      )}

      {/* 全部平仓确认 Modal 代码保持不变 */}
      {showCloseAllConfirm && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in zoom-in-95 duration-200">
             <div className="bg-[#1b2331] w-full max-w-[320px] rounded-[24px] p-8 shadow-2xl border border-slate-700/50 text-center">
                <div className="w-16 h-16 bg-rose-500/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-rose-500/20">
                   <AlertTriangle size={32} className="text-rose-500" />
                </div>
                <h3 className="text-white text-xl font-bold mb-3">{t.confirmCloseAll}</h3>
                <p className="text-slate-400 text-sm leading-relaxed mb-10">{t.confirmCloseAllMsg}</p>
                <div className="grid grid-cols-2 gap-4">
                    <button 
                       onClick={() => setShowCloseAllConfirm(false)} 
                       className="py-4 rounded-2xl border border-slate-700 font-bold text-slate-400 hover:bg-slate-800 transition-all active:scale-95"
                    >
                      {t.cancel}
                    </button>
                    <button 
                       onClick={() => { onCloseAllPositions(); setShowCloseAllConfirm(false); }} 
                       className="py-4 rounded-2xl bg-rose-500 hover:bg-rose-600 text-white font-bold shadow-[0_4px_15px_rgba(244,63,94,0.3)] transition-all active:scale-95"
                    >
                      {t.confirm}
                    </button>
                </div>
             </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Position, Side, MarginMode, Language } from '../types';
import { TrendingUp, TrendingDown, AlertTriangle, Plus, Minus, X, Trash2, ArrowRight, ArrowRightLeft, ChevronDown } from 'lucide-react';
import { TRANSLATIONS } from '../constants';

interface PositionsViewProps {
  positions: Position[];
  currentPrice: number;
  equity: number;
  balance: number;
  maintenanceMargin: number;
  marginRatio: number;
  onClosePosition: (id: string, amount: number, price: number, type: 'MARKET' | 'LIMIT') => void;
  onUpdateMargin: (id: string, amount: number, type: 'ADD' | 'REMOVE') => void;
  onCloseAllPositions: () => void;
  lang: Language;
}

export const PositionsView: React.FC<PositionsViewProps> = ({ 
  positions, 
  currentPrice, 
  equity,
  balance,
  maintenanceMargin,
  marginRatio,
  onClosePosition,
  onUpdateMargin,
  onCloseAllPositions,
  lang
}) => {
  const t = TRANSLATIONS[lang];
  const [editingPosId, setEditingPosId] = useState<string | null>(null);
  const [marginAction, setMarginAction] = useState<'ADD' | 'REMOVE'>('ADD');

  // Close Position Modal State
  const [closingPosId, setClosingPosId] = useState<string | null>(null);
  const [closeOrderType, setCloseOrderType] = useState<'MARKET' | 'LIMIT'>('MARKET');
  const [closePrice, setClosePrice] = useState<string>('');
  const [closeAmount, setCloseAmount] = useState<string>('');
  const [closePercent, setClosePercent] = useState<number>(100);
  const [closeUnit, setCloseUnit] = useState<'XAU' | 'USDC'>('XAU');

  // Independent states for Add and Remove inputs
  const [addMarginInput, setAddMarginInput] = useState<string>('');
  const [removeMarginInput, setRemoveMarginInput] = useState<string>('');

  const [showCloseAllConfirm, setShowCloseAllConfirm] = useState(false);

  // 判断是否存在全仓仓位
  const hasCrossPositions = positions.some(p => p.marginMode === MarginMode.CROSS);

  // Helper to get correct input state
  const currentMarginInput = marginAction === 'ADD' ? addMarginInput : removeMarginInput;
  const setMarginInput = (val: string) => {
      if (marginAction === 'ADD') setAddMarginInput(val);
      else setRemoveMarginInput(val);
  };

  const handleConfirmMargin = () => {
    if (editingPosId && currentMarginInput) {
        onUpdateMargin(editingPosId, parseFloat(currentMarginInput), marginAction);
        setEditingPosId(null);
        setAddMarginInput('');
        setRemoveMarginInput('');
    }
  };

  const closingPos = positions.find(p => p.id === closingPosId);

  // Handle Close Modal Price/Amount logic
  useEffect(() => {
    if (closingPos) {
       const maxInXAU = closingPos.size;
       const targetXAU = maxInXAU * closePercent / 100;

       if (closeUnit === 'XAU') {
          setCloseAmount(targetXAU.toFixed(4));
       } else {
          setCloseAmount((targetXAU * currentPrice).toFixed(2));
       }

       if (closeOrderType === 'MARKET') {
          setClosePrice('');
       } else if (!closePrice) {
          setClosePrice(currentPrice.toFixed(2));
       }
    }
  }, [closingPosId, closePercent, closeOrderType, currentPrice, closeUnit]);

  const handleExecuteClose = () => {
    if (closingPosId && closingPos && closeAmount) {
       let xauAmount = parseFloat(closeAmount);
       if (closeUnit === 'USDC') {
          xauAmount = xauAmount / currentPrice;
       }
       const executionPrice = closeOrderType === 'MARKET' ? currentPrice : (parseFloat(closePrice) || currentPrice);
       onClosePosition(closingPosId, xauAmount, executionPrice, closeOrderType);
       setClosingPosId(null);
    }
  };

  // Close Button Validation
  const closeNum = parseFloat(closeAmount);
  const maxInUnit = closingPos ? (closeUnit === 'XAU' ? closingPos.size : closingPos.size * currentPrice) : 0;
  const isCloseValid = !isNaN(closeNum) && closeNum > 0 && closeNum <= (maxInUnit + 0.0001);

  const getPositionMetrics = () => {
      const pos = positions.find(p => p.id === editingPosId);
      if (!pos || !pos.isolatedMargin) return null;

      const inputVal = parseFloat(currentMarginInput) || 0;
      const change = marginAction === 'ADD' ? inputVal : -inputVal;
      const currentMarginValue = pos.isolatedMargin;
      const newMarginValue = Math.max(0, currentMarginValue + change);

      const posValue = pos.entryPrice * pos.size;
      const maintMarginReq = posValue * 0.01; 
      const currentRatio = (maintMarginReq / currentMarginValue) * 100;
      const newRatio = newMarginValue > 0 ? (maintMarginReq / newMarginValue) * 100 : 0;

      let currentLiq = pos.side === Side.LONG ? pos.entryPrice - (currentMarginValue / pos.size) : pos.entryPrice + (currentMarginValue / pos.size);
      let newLiq = pos.side === Side.LONG ? pos.entryPrice - (newMarginValue / pos.size) : pos.entryPrice + (newMarginValue / pos.size);

      const maxRemove = Math.max(0, currentMarginValue - maintMarginReq);

      return { currentMarginValue, newMarginValue, currentLiq, newLiq, currentRatio, newRatio, maxRemove };
  };

  const metrics = editingPosId ? getPositionMetrics() : null;

  const isMarginInputValid = () => {
      const val = parseFloat(currentMarginInput);
      if (isNaN(val) || val <= 0) return false;
      return marginAction === 'ADD' ? val <= balance : val <= (metrics?.maxRemove || 0);
  };

  const renderRiskHeader = () => {
    // 只有全仓模式时才显示顶部的汇总栏
    if (!hasCrossPositions) return null;

    return (
      <div className="dark:bg-slate-800/50 bg-white/80 border-b dark:border-slate-800 border-slate-200 p-4 sticky top-0 backdrop-blur-md z-10 animate-in fade-in duration-300">
        <div className="grid grid-cols-3 gap-2">
          <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
             <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginRatio}</div>
             <div className={`font-mono font-bold text-sm ${marginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>{marginRatio.toFixed(2)}%</div>
          </div>
          <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
             <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.maintMargin}</div>
             <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${maintenanceMargin.toFixed(2)}</div>
          </div>
          <div className="dark:bg-slate-800 bg-white rounded-lg p-2 border dark:border-slate-700 border-slate-200 shadow-sm">
             <div className="text-[10px] dark:text-slate-500 text-slate-400 mb-1">{t.marginBal}</div>
             <div className="font-mono font-bold text-sm dark:text-slate-200 text-slate-800">${equity.toFixed(2)}</div>
          </div>
        </div>
      </div>
    );
  };

  if (positions.length === 0) {
    return (
      <div className="h-full flex flex-col">
        {renderRiskHeader()}
        <div className="flex-1 flex flex-col items-center justify-center dark:text-slate-500 text-slate-400 mt-20">
          <div className="dark:bg-slate-800 bg-white p-4 rounded-full mb-4 shadow-sm border dark:border-slate-700 border-slate-200">
             <TrendingUp size={32} className="opacity-50" />
          </div>
          <p>{t.noPositions}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col dark:bg-slate-900 bg-slate-50 relative">
      {renderRiskHeader()}
      <div className="flex-1 p-4 space-y-3 pb-24 overflow-y-auto no-scrollbar">
        <div className="flex justify-between items-center mb-2">
           <h2 className="dark:text-slate-400 text-slate-500 text-xs uppercase font-bold tracking-wider">{t.openPositions} ({positions.length})</h2>
           <button onClick={() => setShowCloseAllConfirm(true)} className="text-xs bg-rose-500/10 hover:bg-rose-500/20 text-rose-500 px-2 py-1 rounded border border-rose-500/20 flex items-center gap-1"><Trash2 size={12} />{t.closeAll}</button>
        </div>

        {positions.map((pos) => {
          const priceDiff = currentPrice - pos.entryPrice;
          const pnl = pos.side === Side.LONG ? priceDiff * pos.size : -priceDiff * pos.size;
          const marginUsed = pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin ? pos.isolatedMargin : (pos.entryPrice * pos.size) / pos.leverage;
          const liquidationPrice = pos.side === Side.LONG ? pos.entryPrice - (marginUsed / pos.size) : pos.entryPrice + (marginUsed / pos.size);
          const isProfit = pnl >= 0;
          const roi = (pnl / marginUsed) * 100;

          // 逐仓数据计算
          const posValue = pos.entryPrice * pos.size;
          const posMaintMargin = posValue * 0.01;
          const posMarginRatio = (posMaintMargin / marginUsed) * 100;
          const posMarginBal = marginUsed + pnl;

          return (
            <div key={pos.id} className="dark:bg-slate-800 bg-white border dark:border-slate-700 border-slate-200 rounded-xl p-4 shadow-sm animate-in slide-in-from-bottom-2 duration-300">
              <div className="flex justify-between items-start mb-3">
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded ${pos.side === Side.LONG ? 'bg-emerald-500/20 text-emerald-500' : 'bg-rose-500/20 text-rose-500'}`}>
                    {pos.side === Side.LONG ? <TrendingUp size={16} /> : <TrendingDown size={16} />}
                  </div>
                  <div>
                    <h3 className="font-bold dark:text-white text-slate-900 flex items-center gap-2">
                      {pos.symbol}
                      <span className="text-[9px] dark:bg-slate-700 bg-slate-200 dark:text-slate-300 text-slate-600 px-1.5 py-0.5 rounded uppercase font-normal tracking-wide border dark:border-slate-600 border-slate-300">
                        {pos.marginMode === MarginMode.ISOLATED ? t.isolated : t.cross}
                      </span>
                    </h3>
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded mt-1 inline-block ${pos.side === Side.LONG ? 'bg-emerald-500/10 text-emerald-500' : 'bg-rose-500/10 text-rose-500'}`}>
                      {pos.leverage}x {pos.side === Side.LONG ? t.longLabel : t.shortLabel}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <div className={`text-lg font-mono font-bold leading-tight ${isProfit ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {isProfit ? '+' : ''}{pnl.toFixed(2)}
                  </div>
                  <div className={`text-[10px] font-bold font-mono mt-0.5 ${isProfit ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {isProfit ? '+' : ''}{roi.toFixed(2)}%
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-y-2 text-xs mb-4">
                <div className="dark:text-slate-400 text-slate-500">{t.size} (XAU)</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.size.toFixed(4)}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.entryPrice}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono">{pos.entryPrice.toFixed(2)}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.liqPrice}</div>
                <div className="text-right text-orange-500 font-mono font-bold">{liquidationPrice > 0 ? liquidationPrice.toFixed(2) : '0.00'}</div>

                <div className="dark:text-slate-400 text-slate-500">{t.margin}</div>
                <div className="text-right dark:text-slate-200 text-slate-800 font-mono flex items-center justify-end gap-2">
                    {marginUsed.toFixed(2)}
                    {pos.marginMode === MarginMode.ISOLATED && (
                        <button onClick={() => { setEditingPosId(pos.id); setMarginAction('ADD'); }} className="bg-indigo-500/20 text-indigo-500 p-0.5 rounded hover:bg-indigo-500/30"><Plus size={10} /></button>
                    )}
                </div>
              </div>

              {/* 逐仓模式专属独立统计区 */}
              {pos.marginMode === MarginMode.ISOLATED && (
                <div className="animate-in fade-in duration-500">
                  <div className="w-full h-px bg-slate-200 dark:bg-slate-700 mb-3 opacity-50"></div>
                  <div className="grid grid-cols-3 gap-2 mb-4">
                    <div className="space-y-1">
                      <div className="text-[9px] dark:text-slate-500 text-slate-400 uppercase">{t.marginRatio}</div>
                      <div className={`font-mono text-[11px] font-bold ${posMarginRatio > 80 ? 'text-rose-500' : 'text-emerald-500'}`}>{posMarginRatio.toFixed(2)}%</div>
                    </div>
                    <div className="space-y-1 border-l dark:border-slate-700 pl-2">
                      <div className="text-[9px] dark:text-slate-500 text-slate-400 uppercase">{t.maintMargin}</div>
                      <div className="font-mono text-[11px] dark:text-slate-300 text-slate-700">${posMaintMargin.toFixed(2)}</div>
                    </div>
                    <div className="space-y-1 border-l dark:border-slate-700 pl-2">
                      <div className="text-[9px] dark:text-slate-500 text-slate-400 uppercase">{t.marginBal}</div>
                      <div className="font-mono text-[11px] dark:text-slate-300 text-slate-700">${posMarginBal.toFixed(2)}</div>
                    </div>
                  </div>
                </div>
              )}

              <button onClick={() => { setClosingPosId(pos.id); setClosePercent(100); }} className="w-full py-2.5 dark:bg-slate-700 bg-slate-100 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2">{t.closePos}</button>
            </div>
          );
        })}
      </div>

      {closingPos && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in">
             <div className="bg-[#1b2331] w-full max-w-sm rounded-[24px] p-6 shadow-2xl border border-slate-700/50">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-xl text-white">{t.closePos}</h3>
                    <button onClick={() => setClosingPosId(null)} className="text-slate-400 hover:text-white transition-colors">
                      <X size={24}/>
                    </button>
                </div>

                <div className="flex justify-between items-start mb-6">
                    <div>
                      <p className="text-[10px] text-slate-500 uppercase font-bold tracking-wider mb-1">{t.tradeHistoryFields.pair}</p>
                      <div className="flex items-center gap-2">
                        <span className="text-xl font-bold text-indigo-400 uppercase tracking-tight">{closingPos.symbol}</span>
                        <span className="text-xl font-bold text-slate-500">/</span>
                        <span className={`text-xl font-bold ${closingPos.side === Side.LONG ? 'text-emerald-500' : 'text-rose-500'}`}>
                          {closingPos.side === Side.LONG ? t.longLabel : t.shortLabel}
                        </span>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-[10px] text-slate-500 font-medium mb-1">
                        {t.entryPrice}: <span className="text-slate-200 font-mono ml-1">{closingPos.entryPrice.toFixed(2)}</span>
                      </div>
                      <div className="text-[10px] text-slate-500 font-medium">
                        {t.markPrice}: <span className="text-slate-200 font-mono ml-1">{currentPrice.toFixed(2)}</span>
                      </div>
                    </div>
                </div>

                <div className="w-full h-px bg-slate-700/50 mb-6"></div>

                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.price}</label>
                        <div className="w-full bg-[#131a26] border border-slate-700/80 rounded-xl px-4 py-3 text-sm font-mono text-white flex items-center justify-center h-14">
                           {closeOrderType === 'MARKET' ? t.market : (
                             <input 
                                type="text" 
                                value={closePrice} 
                                onChange={(e) => setClosePrice(e.target.value)} 
                                className="bg-transparent border-none outline-none w-full text-center" 
                             />
                           )}
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.mode}</label>
                        <div className="w-full bg-[#131a26] border border-slate-700/80 rounded-xl px-4 py-3 flex items-center justify-between cursor-pointer h-14" onClick={() => setCloseOrderType(closeOrderType === 'MARKET' ? 'LIMIT' : 'MARKET')}>
                            <span className="text-sm text-white font-medium">{closeOrderType === 'MARKET' ? t.market : t.limit}</span>
                            <ArrowRightLeft size={16} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                <div className="space-y-1.5 mb-8">
                    <label className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{t.size}</label>
                    <div className="relative group">
                        <input 
                           type="number" 
                           value={closeAmount} 
                           onChange={(e) => setCloseAmount(e.target.value)} 
                           className="w-full bg-[#131a26] border border-slate-700/80 group-focus-within:border-indigo-500/50 rounded-xl px-4 py-4 text-lg font-mono text-white outline-none h-14" 
                        />
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center">
                           <span className="text-[10px] font-bold text-slate-200 mr-1 uppercase">XAU</span>
                           <ChevronDown size={14} className="text-slate-500" />
                        </div>
                    </div>
                </div>

                <div className="mb-10 px-1 relative h-6 flex items-center group">
                   <div className="absolute inset-x-0 h-1 bg-slate-700/50 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-500 transition-all" style={{ width: `${closePercent}%` }} />
                   </div>
                   <input 
                      type="range" 
                      min="0" 
                      max="100" 
                      step="1" 
                      value={closePercent} 
                      onChange={(e) => setClosePercent(parseInt(e.target.value))} 
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" 
                   />
                   <div 
                      className="absolute h-6 w-6 bg-indigo-500 border-2 border-[#1b2331] shadow-[0_0_10px_rgba(99,102,241,0.5)] rounded-full flex items-center justify-center z-10 pointer-events-none transition-transform group-active:scale-110" 
                      style={{ left: `${closePercent}%`, transform: 'translateX(-50%)' }}
                   >
                     <div className="absolute bottom-[30px] bg-indigo-600 text-white text-[9px] font-bold py-1 px-1.5 rounded-md shadow-lg after:content-[''] after:absolute after:top-full after:left-1/2 after:-translate-x-1/2 after:border-4 after:border-transparent after:border-t-indigo-600">
                        {closePercent}%
                     </div>
                   </div>
                </div>

                <div className="bg-[#131a26]/50 border border-slate-700/30 rounded-2xl p-5 mb-8">
                   <div className="flex justify-between items-center mb-3">
                      <span className="text-xs text-slate-500 font-medium">{t.closeOperation.positionSize}</span>
                      <span className="text-sm font-bold text-white font-mono">{closingPos.size.toFixed(4)} XAU</span>
                   </div>
                   <div className="flex justify-between items-center">
                      <span className="text-xs text-slate-500 font-medium">{t.closeOperation.estPnL}</span>
                      <span className={`text-sm font-bold font-mono ${((currentPrice - closingPos.entryPrice) * (parseFloat(closeAmount) || 0) * (closingPos.side === Side.LONG ? 1 : -1)) >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                         {((currentPrice - closingPos.entryPrice) * (parseFloat(closeAmount) || 0) * (closingPos.side === Side.LONG ? 1 : -1)).toFixed(2)} USDC
                      </span>
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <button 
                       onClick={() => setClosingPosId(null)} 
                       className="py-4 rounded-xl border border-slate-700 font-bold text-slate-400 hover:bg-slate-800 hover:text-white transition-all active:scale-95"
                    >
                      {t.cancel}
                    </button>
                    <button 
                       onClick={handleExecuteClose} 
                       disabled={!isCloseValid} 
                       className={`py-4 rounded-xl font-bold text-white shadow-[0_4px_20px_rgba(79,70,229,0.3)] transition-all active:scale-95 ${isCloseValid ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-slate-700 text-slate-500 cursor-not-allowed'}`}
                    >
                      {t.confirm}
                    </button>
                </div>
             </div>
          </div>
      )}

      {/* 调整保证金 Modal */}
      {editingPosId && metrics && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
             <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-2xl p-6 shadow-2xl border dark:border-slate-700 border-slate-200">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-lg dark:text-white text-slate-900">{t.addMargin}</h3>
                    <button onClick={() => setEditingPosId(null)} className="dark:text-slate-400 text-slate-500"><X size={20}/></button>
                </div>
                <div className="flex bg-slate-100 dark:bg-slate-700 rounded-lg p-1 mb-4">
                    <button onClick={() => setMarginAction('ADD')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'ADD' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.add}</button>
                    <button onClick={() => setMarginAction('REMOVE')} className={`flex-1 py-2 text-sm font-bold rounded-md transition-all ${marginAction === 'REMOVE' ? 'bg-white dark:bg-slate-600 shadow text-indigo-500' : 'text-slate-500'}`}>{t.remove}</button>
                </div>
                <div className="mb-4">
                    <div className="flex justify-between mb-1">
                        <label className="text-xs text-slate-500 block">{t.amount} (USDC)</label>
                        <span className="text-xs text-slate-500">{marginAction === 'ADD' ? t.avail : t.maxRemove}: <span className="font-mono">{marginAction === 'ADD' ? balance.toFixed(2) : metrics.maxRemove.toFixed(2)}</span></span>
                    </div>
                    <div className="relative">
                        <input type="number" value={currentMarginInput} onChange={(e) => setMarginInput(e.target.value)} placeholder={t.quantity} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-3 pr-16 font-mono text-lg outline-none focus:border-indigo-500 dark:text-white" />
                        <button onClick={() => setMarginInput((marginAction === 'ADD' ? balance : metrics.maxRemove).toFixed(2))} className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-bold text-indigo-500">{t.max}</button>
                    </div>
                </div>
                <div className="bg-slate-50 dark:bg-slate-900 border dark:border-slate-700 border-slate-200 rounded-xl p-3 mb-6 space-y-3 text-[11px]">
                   <div className="flex items-center gap-2 mb-2"><span className="font-bold text-slate-400 flex-1 text-center">{t.before}</span><ArrowRight size={12} className="text-slate-400" /><span className="font-bold text-indigo-500 flex-1 text-center">{t.after}</span></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.margin}</div><div className="flex-1 text-center font-mono">{metrics.currentMarginValue.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newMarginValue.toFixed(2)}</div></div>
                   {/* 移除杠杆变化显示，满足用户需求：调整保证金不会影响（显示）杠杆倍数变化 */}
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.marginRatio}</div><div className="flex-1 text-center font-mono">{metrics.currentRatio.toFixed(2)}%</div><div className="flex-1 text-center font-mono font-bold text-indigo-500">{metrics.newRatio.toFixed(2)}%</div></div>
                   <div className="flex items-center"><div className="flex-1 text-center text-slate-400">{t.estLiqPrice}</div><div className="flex-1 text-center font-mono text-orange-500">{metrics.currentLiq.toFixed(2)}</div><div className="flex-1 text-center font-mono font-bold text-orange-500">{metrics.newLiq.toFixed(2)}</div></div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => setEditingPosId(null)} className="py-3 rounded-xl border border-slate-200 dark:border-slate-700 font-bold text-slate-500">{t.cancel}</button>
                  <button onClick={handleConfirmMargin} disabled={!isMarginInputValid()} className={`py-3 rounded-xl font-bold shadow-lg transition-all ${isMarginInputValid() ? 'bg-indigo-600 text-white shadow-indigo-500/20' : 'bg-slate-300 text-slate-500 cursor-not-allowed'}`}>{t.confirmAction}</button>
                </div>
             </div>
          </div>
      )}

      {showCloseAllConfirm && (
          <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-in fade-in zoom-in-95 duration-200">
             <div className="bg-[#1b2331] w-full max-w-[320px] rounded-[24px] p-8 shadow-2xl border border-slate-700/50 text-center">
                <div className="w-16 h-16 bg-rose-500/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-rose-500/20">
                   <AlertTriangle size={32} className="text-rose-500" />
                </div>
                <h3 className="text-white text-xl font-bold mb-3">{t.confirmCloseAll}</h3>
                <p className="text-slate-400 text-sm leading-relaxed mb-10">{t.confirmCloseAllMsg}</p>
                <div className="grid grid-cols-2 gap-4">
                    <button 
                       onClick={() => setShowCloseAllConfirm(false)} 
                       className="py-4 rounded-2xl border border-slate-700 font-bold text-slate-400 hover:bg-slate-800 transition-all active:scale-95"
                    >
                      {t.cancel}
                    </button>
                    <button 
                       onClick={() => { onCloseAllPositions(); setShowCloseAllConfirm(false); }} 
                       className="py-4 rounded-2xl bg-rose-500 hover:bg-rose-600 text-white font-bold shadow-[0_4px_15px_rgba(244,63,94,0.3)] transition-all active:scale-95"
                    >
                      {t.confirm}
                    </button>
                </div>
             </div>
          </div>
      )}
    </div>
  );
};

export enum Tab {
  TRADE = 'TRADE',
  POSITIONS = 'POSITIONS',
  ORDERS = 'ORDERS',
  ACCOUNT = 'ACCOUNT'
}

export enum Side {
  LONG = 'LONG',
  SHORT = 'SHORT'
}

export enum MarginMode {
  CROSS = 'CROSS',
  ISOLATED = 'ISOLATED'
}

export enum PositionMode {
  ONE_WAY = 'ONE_WAY',
  HEDGE = 'HEDGE'
}

export type Language = 'en' | 'zh-CN' | 'zh-TW';
export type Theme = 'dark' | 'light';
export type ChartType = 'line' | 'candle' | 'depth';
export type Timeframe = '1m' | '3m' | '5m' | '15m' | '30m' | '1H' | '2H' | '4H' | '8H' | '12H' | '1D' | '3D' | '1W' | '1M';

export interface Position {
  id: string;
  symbol: string;
  side: Side;
  size: number;
  entryPrice: number;
  leverage: number;
  unrealizedPnL: number;
  marginMode: MarginMode;
  isolatedMargin?: number;
}

export interface Order {
  id: string;
  symbol: string;
  side: Side;
  type: 'LIMIT' | 'MARKET';
  price: number;
  amount: number;
  filled: number;
  status: 'OPEN' | 'FILLED' | 'CANCELLED' | 'PARTIAL_FILLED' | 'EXPIRED';
  timestamp: number;
  marginMode: MarginMode;
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketInfo {
  symbol: string;
  name: string;
  lastPrice: number;
  change24h: number;
  volume24h: number;
  fundingRate: number;
  leverage: number;
}

export interface Wallet {
  balance: number;
  equity: number;
}

export interface FillRecord {
  id: string;
  symbol: string;
  side: Side;
  price: number;
  size: number;
  value: number;
  fee: number;
  realizedPnl: number;
  timestamp: number;
}

export interface TransferRecord {
  id: string;
  type: 'DEPOSIT' | 'WITHDRAW';
  amount: number;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING' | 'REJECTED' | 'CANCELLED';
  network: string;
}

export type CashFlowType = 'TRANSACTION_FEE' | 'FUNDING_FEE' | 'REALIZED_PNL' | 'LIQUIDATION_FEE';

export interface CashFlowRecord {
  id: string;
  type: CashFlowType;
  symbol: string;
  amount: number;
  timestamp: number;
}

export interface MarketTrade {
  id: string;
  price: number;
  size: number;
  side: Side;
  time: string;
}

import React, { useState, useEffect } from 'react';
import { Tab, Side, Position, Order, Candle, FillRecord, TransferRecord, MarginMode, Language, Theme, CashFlowRecord, MarketTrade, Timeframe, PositionMode, MarketInfo } from './types';
import { generateInitialData, INITIAL_BALANCE, SYMBOL, TRANSLATIONS, MOCK_MARKETS } from './constants';
import { BottomNav } from './components/BottomNav';
import { TradeView } from './components/TradeView';
import { PositionsView } from './components/PositionsView';
import { OrdersView } from './components/OrdersView';
import { AccountView } from './components/AccountView';
import { CheckCircle, AlertTriangle, Bell, X } from 'lucide-react';

interface InternalNotification {
  id: string;
  title: string;
  content: string;
}

const NotificationOverlay = ({ notifications, onRemove }: { notifications: InternalNotification[], onRemove: (id: string) => void }) => {
  return (
    <div className="fixed top-4 left-1/2 -translate-x-1/2 w-[90%] max-w-sm z-[100] space-y-3 pointer-events-none">
      {notifications.map((n) => (
        <div 
          key={n.id} 
          className="pointer-events-auto bg-slate-900/95 backdrop-blur-md border border-slate-700 rounded-2xl p-4 shadow-2xl animate-in slide-in-from-top duration-300 relative group"
        >
           <button onClick={() => onRemove(n.id)} className="absolute top-3 right-3 text-slate-500 hover:text-white transition-colors opacity-0 group-hover:opacity-100">
             <X size={14} />
           </button>
           <div className="flex items-start gap-3">
              <div className="w-8 h-8 rounded-full bg-indigo-500/20 flex items-center justify-center shrink-0 text-indigo-500">
                <Bell size={16} />
              </div>
              <div className="flex-1 overflow-hidden">
                <h4 className="text-sm font-bold text-white mb-1">{n.title}</h4>
                <p className="text-xs text-slate-400 leading-relaxed whitespace-pre-line">{n.content}</p>
              </div>
           </div>
        </div>
      ))}
    </div>
  );
};

const Toast = ({ message, visible, type = 'success' }: { message: string, visible: boolean, type?: 'success' | 'error' }) => (
  <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full shadow-lg border z-50 transition-all duration-300 flex items-center gap-2 ${visible ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'} ${type === 'error' ? 'bg-rose-900/90 border-rose-700 text-white' : 'bg-slate-800 border-slate-700 text-white'}`}>
    {type === 'error' ? <AlertTriangle size={18} className="text-white" /> : <CheckCircle size={18} className="text-emerald-500" />}
    <span className="text-sm font-medium">{message}</span>
  </div>
);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.TRADE);
  const [language, setLanguage] = useState<Language>('zh-CN');
  const [theme, setTheme] = useState<Theme>('dark');
  const [timeframe, setTimeframe] = useState<Timeframe>('15m');
  const [positionMode, setPositionMode] = useState<PositionMode>(PositionMode.ONE_WAY);
  const [activeSymbol, setActiveSymbol] = useState<string>(SYMBOL);
  const currentMarket = MOCK_MARKETS.find(m => m.symbol === activeSymbol) || MOCK_MARKETS[0];
  const [isWalletConnected, setIsWalletConnected] = useState<boolean>(false);
  const [externalWalletBalance, setExternalWalletBalance] = useState<number>(5000.00); 
  const [candles, setCandles] = useState<Candle[]>(generateInitialData(50, '15m'));
  const [currentPrice, setCurrentPrice] = useState<number>(currentMarket.lastPrice);
  const [marketTrades, setMarketTrades] = useState<MarketTrade[]>([]);
  const [balance, setBalance] = useState<number>(INITIAL_BALANCE);
  const [positions, setPositions] = useState<Position[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  // 账户页面的初始子视图
  const [accountSubView, setAccountSubView] = useState<'MAIN' | 'DEPOSIT' | 'WITHDRAW' | 'FILL_HISTORY' | 'TRANSFER_HISTORY' | 'SETTINGS' | 'CASH_FLOW_HISTORY'>('MAIN');

  // Settings switches
  const [orderConfirmationEnabled, setOrderConfirmationEnabled] = useState<boolean>(true);
  const [popupNotificationsEnabled, setPopupNotificationsEnabled] = useState<boolean>(true);

  const [orderHistory, setOrderHistory] = useState<Order[]>([
    { id: 'oh1', symbol: 'XAUUSDC', side: Side.LONG, type: 'LIMIT', price: 2010.50, amount: 2.0, filled: 0.8, status: 'PARTIAL_FILLED', timestamp: Date.now() - 3600000, marginMode: MarginMode.CROSS },
    { id: 'oh2', symbol: 'BTCUSDC', side: Side.SHORT, type: 'LIMIT', price: 68500.00, amount: 0.1, filled: 0.1, status: 'FILLED', timestamp: Date.now() - 7200000, marginMode: MarginMode.ISOLATED },
    { id: 'oh3', symbol: 'ETHUSDC', side: Side.LONG, type: 'LIMIT', price: 3200.00, amount: 5.0, filled: 0, status: 'CANCELLED', timestamp: Date.now() - 10800000, marginMode: MarginMode.CROSS },
    { id: 'oh4', symbol: 'XAUUSDC', side: Side.SHORT, type: 'LIMIT', price: 2050.25, amount: 1.5, filled: 1.5, status: 'FILLED', timestamp: Date.now() - 14400000, marginMode: MarginMode.CROSS },
    { id: 'oh5', symbol: 'SOLUSDC', side: Side.LONG, type: 'LIMIT', price: 135.50, amount: 10.0, filled: 3.5, status: 'PARTIAL_FILLED', timestamp: Date.now() - 18000000, marginMode: MarginMode.CROSS },
    { id: 'oh6', symbol: 'XAUUSDC', side: Side.LONG, type: 'LIMIT', price: 1950.00, amount: 5.0, filled: 0, status: 'EXPIRED', timestamp: Date.now() - 25200000, marginMode: MarginMode.CROSS }
  ]);

  const [fillHistory] = useState<FillRecord[]>([
    { id: 'f1', symbol: 'XAUUSDC', side: Side.LONG, price: 2015.42, size: 0.5, value: 1007.71, fee: -0.50, realizedPnl: 12.50, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'f2', symbol: 'BTCUSDC', side: Side.SHORT, price: 65200.10, size: 0.01, value: 652.00, fee: -0.32, realizedPnl: -5.20, timestamp: new Date('2025/12/22 04:36:43').getTime() }
  ]);

  const [transferHistory, setTransferHistory] = useState<TransferRecord[]>([
    { id: 't1', type: 'DEPOSIT', amount: 1000.00, timestamp: new Date('2025/12/20 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
    { id: 't2', type: 'WITHDRAW', amount: 200.00, timestamp: new Date('2025/12/19 09:36:43').getTime(), status: 'COMPLETED', network: 'Arbitrum One' },
  ]);

  const [cashFlowHistory] = useState<CashFlowRecord[]>([
    { id: 'cf1', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.1200, timestamp: new Date('2025/12/22 08:36:43').getTime() },
    { id: 'cf2', type: 'TRANSACTION_FEE', symbol: 'XAUUSDC', amount: -0.5000, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'cf3', type: 'REALIZED_PNL', symbol: 'XAUUSDC', amount: 12.5000, timestamp: new Date('2025/12/22 07:36:43').getTime() },
    { id: 'cf4', type: 'FUNDING_FEE', symbol: 'XAUUSDC', amount: -0.1100, timestamp: new Date('2025/12/22 00:36:43').getTime() },
    { id: 'cf5', type: 'LIQUIDATION_FEE', symbol: 'SOLUSDC', amount: -4.2000, timestamp: new Date('2025/12/21 21:36:43').getTime() },
    { id: 'cf6', type: 'REALIZED_PNL', symbol: 'ETHUSDC', amount: -8.4500, timestamp: new Date('2025/12/21 18:12:43').getTime() },
    { id: 'cf7', type: 'TRANSACTION_FEE', symbol: 'BTCUSDC', amount: -0.3200, timestamp: new Date('2025/12/21 14:05:43').getTime() }
  ]);

  const [toast, setToast] = useState<{ message: string, visible: boolean, type?: 'success' | 'error' }>({ message: '', visible: false, type: 'success' });
  const [notifications, setNotifications] = useState<InternalNotification[]>([]);

  const t = TRANSLATIONS[language];

  const triggerNotification = (title: string, content: string) => {
    if (!popupNotificationsEnabled) return;
    const id = Date.now().toString();
    setNotifications(prev => [{ id, title, content }, ...prev].slice(0, 3));
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 6000);
  };

  const handleSymbolChange = (symbol: string) => {
    setActiveSymbol(symbol);
    const newMarket = MOCK_MARKETS.find(m => m.symbol === symbol) || MOCK_MARKETS[0];
    setCurrentPrice(newMarket.lastPrice);
    setCandles(generateInitialData(50, timeframe));
    setMarketTrades([]); 
  };

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [theme]);

  useEffect(() => {
    const interval = setInterval(() => {
      let newPrice = currentPrice;

      setCandles(prevCandles => {
        const lastCandle = prevCandles[prevCandles.length - 1];
        const move = (Math.random() - 0.5) * 0.8;
        newPrice = Math.max(0.01, lastCandle.close + move);
        return [...prevCandles.slice(0, -1), { ...lastCandle, close: newPrice, high: Math.max(lastCandle.high, newPrice), low: Math.min(lastCandle.low, newPrice) }];
      });
      setCurrentPrice(newPrice);

      if (Math.random() > 0.6) {
        setMarketTrades(prev => [
          {
            id: Date.now().toString(),
            price: newPrice + (Math.random() - 0.5) * 0.2,
            size: Math.random() * 2 + 0.01,
            side: Math.random() > 0.5 ? Side.LONG : Side.SHORT,
            time: new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' })
          },
          ...prev.slice(0, 19)
        ]);
      }

      setOrders(prevOrders => {
        const remainingOrders: Order[] = [];
        let ordersExecuted = false;
        prevOrders.forEach(order => {
          let executed = (order.side === Side.LONG && newPrice <= order.price) || (order.side === Side.SHORT && newPrice >= order.price);
          if (executed) {
            ordersExecuted = true;
            const initialMargin = (order.amount * order.price) / 20;
            setPositions(prev => [{ id: Date.now().toString() + Math.random(), symbol: activeSymbol, side: order.side, size: order.amount, entryPrice: order.price, leverage: 20, unrealizedPnL: 0, marginMode: order.marginMode, isolatedMargin: order.marginMode === MarginMode.ISOLATED ? initialMargin : undefined }, ...prev]);
            setOrderHistory(prev => [{ ...order, filled: order.amount, status: 'FILLED' }, ...prev]);

            const fee = (order.amount * order.price * 0.0005);
            triggerNotification(
                t.appNotifications.limitFilled.title,
                t.appNotifications.limitFilled.content
                    .replace('{side}', order.side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
                    .replace('{size}', order.amount.toString())
                    .replace('{price}', order.price.toFixed(2))
                    .replace('{fee}', `$${fee.toFixed(2)}`)
            );
          } else remainingOrders.push(order);
        });
        return ordersExecuted ? remainingOrders : prevOrders;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [currentPrice, activeSymbol, language, t]); 

  const handlePlaceOrder = (side: Side, size: number, price: number, type: 'MARKET' | 'LIMIT', marginMode: MarginMode) => {
    if (!isWalletConnected) { setActiveTab(Tab.ACCOUNT); return; }
    const leverage = 20;
    const requiredMargin = (price * size) / leverage; 
    if (requiredMargin > balance) return;
    setBalance(prev => prev - requiredMargin);

    if (type === 'MARKET') {
      const newPos: Position = { id: Date.now().toString(), symbol: activeSymbol, side, size, entryPrice: price, leverage, unrealizedPnL: 0, marginMode, isolatedMargin: marginMode === MarginMode.ISOLATED ? requiredMargin : undefined };
      setPositions(prev => [newPos, ...prev]);
      const fee = (size * price * 0.0005);
      triggerNotification(
        t.appNotifications.marketFilled.title,
        t.appNotifications.marketFilled.content
            .replace('{side}', side === Side.LONG ? (language === 'en' ? 'Buy' : '买入') : (language === 'en' ? 'Sell' : '卖出'))
            .replace('{size}', size.toString())
            .replace('{price}', price.toFixed(2))
            .replace('{fee}', `$${fee.toFixed(2)}`)
      );
    } else {
      const newOrder: Order = { id: Date.now().toString(), symbol: activeSymbol, side, type: 'LIMIT', price, amount: size, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode };
      setOrders(prev => [newOrder, ...prev]);
      triggerNotification(
        t.appNotifications.orderSuccess.title,
        t.appNotifications.orderSuccess.content
            .replace('{symbol}', activeSymbol)
            .replace('{side}', side === Side.LONG ? t.longLabel : t.shortLabel)
            .replace('{type}', t.limit)
            .replace('{price}', price.toFixed(2))
            .replace('{size}', size.toString())
            .replace('{leverage}', leverage.toString())
      );
    }
  };

  const handleClosePosition = (id: string, amountToClose: number, executionPrice: number, type: 'MARKET' | 'LIMIT') => {
    const pos = positions.find(p => p.id === id);
    if (!pos) return;

    if (type === 'LIMIT') {
        const limitOrder: Order = { id: `cl-${Date.now()}`, symbol: pos.symbol, side: pos.side === Side.LONG ? Side.SHORT : Side.LONG, type: 'LIMIT', price: executionPrice, amount: amountToClose, filled: 0, status: 'OPEN', timestamp: Date.now(), marginMode: pos.marginMode };
        setOrders(prev => [limitOrder, ...prev]);
        triggerNotification(
            t.appNotifications.orderSuccess.title,
            t.appNotifications.orderSuccess.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.shortLabel : t.longLabel)
                .replace('{type}', t.limit)
                .replace('{price}', executionPrice.toFixed(2))
                .replace('{size}', amountToClose.toString())
                .replace('{leverage}', pos.leverage.toString())
        );
        return;
    }

    const priceDiff = executionPrice - pos.entryPrice;
    const pnl = pos.side === Side.LONG ? priceDiff * amountToClose : -priceDiff * amountToClose;
    let marginToReturn = (pos.marginMode === MarginMode.ISOLATED && pos.isolatedMargin) ? (pos.isolatedMargin * (amountToClose / pos.size)) : (pos.entryPrice * amountToClose) / pos.leverage;
    setBalance(prev => prev + marginToReturn + pnl);

    if (amountToClose >= pos.size) {
        setPositions(prev => prev.filter(p => p.id !== id));
        triggerNotification(
            t.appNotifications.posClosed.title,
            t.appNotifications.posClosed.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    } else {
        setPositions(prev => prev.map(p => p.id === id ? { ...p, size: p.size - amountToClose, isolatedMargin: p.isolatedMargin ? p.isolatedMargin * ((p.size - amountToClose) / p.size) : undefined } : p));
        triggerNotification(
            t.appNotifications.posReduced.title,
            t.appNotifications.posReduced.content
                .replace('{symbol}', pos.symbol)
                .replace('{side}', pos.side === Side.LONG ? t.longLabel : t.shortLabel)
                .replace('{size}', amountToClose.toFixed(2))
                .replace('{remaining}', (pos.size - amountToClose).toFixed(2))
                .replace('{pnl}', pnl.toFixed(2))
        );
    }
  };

  const handleUpdateMargin = (id: string, amount: number, type: 'ADD' | 'REMOVE') => {
      const pos = positions.find(p => p.id === id);
      if (!pos || !pos.isolatedMargin) return;

      if (type === 'ADD') {
          if (amount > balance) return;
          setBalance(prev => prev - amount);
          setPositions(prev => prev.map(p => p.id === id ? { ...p, isolatedMargin: (p.isolatedMargin || 0) + amount } : p));
      } else {
          const maintMargin = (pos.entryPrice * pos.size) * 0.01;
          const maxRemovable = pos.isolatedMargin - maintMargin;
          if (amount > maxRemovable) return;
          setBalance(prev => prev + amount);
          setPositions(prev => prev.map(p => p.id === id ? { ...p, isolatedMargin: (p.isolatedMargin || 0) - amount } : p));
      }

      triggerNotification(
          t.appNotifications.marginUpdated.title,
          t.appNotifications.marginUpdated.content
              .replace('{symbol}', pos.symbol)
              .replace('{amount}', (type === 'ADD' ? '+' : '-') + amount.toFixed(2))
      );
  };

  const handleDeposit = (amount: number) => {
    if (amount > externalWalletBalance) return;
    setExternalWalletBalance(prev => prev - amount);
    setBalance(prev => prev + amount);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'DEPOSIT', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.deposit.title,
        t.appNotifications.deposit.content.replace('{amount}', amount.toLocaleString())
    );
  };

  const handleWithdraw = (amount: number) => {
    const WITHDRAW_FEE = 0.5;
    if (balance < amount) return false;
    const actualReceived = amount - WITHDRAW_FEE;
    setBalance(prev => prev - amount);
    setExternalWalletBalance(prev => prev + actualReceived);
    setTransferHistory(prev => [{ id: `tx-${Date.now()}`, type: 'WITHDRAW', amount, timestamp: Date.now(), status: 'COMPLETED', network: 'Arbitrum One' }, ...prev]);
    triggerNotification(
        t.appNotifications.withdraw.title,
        t.appNotifications.withdraw.content.replace('{amount}', actualReceived.toLocaleString()).replace('{address}', '0x71C7...9A23')
    );
    return true;
  };

  const handleCancelOrder = (id: string) => {
    setOrders(prev => {
        const order = prev.find(o => o.id === id);
        if (order) {
            triggerNotification(
                language === 'en' ? 'Order Cancelled' : '订单已取消',
                language === 'en' 
                  ? `Successfully cancelled ${order.symbol} ${order.side} order.` 
                  : `已成功撤销 ${order.symbol} ${order.side === Side.LONG ? '买入' : '卖出'} 挂单。`
            );
        }
        return prev.filter(o => o.id !== id);
    });
  };

  const handleCancelAllOrders = () => {
    if (orders.length > 0) {
        setOrders([]);
        triggerNotification(
            language === 'en' ? 'All Orders Cancelled' : '全部订单已取消',
            language === 'en' ? 'Successfully cancelled all open orders.' : '已成功撤销所有当前挂单。'
        );
    }
  };

  const handleCloseAllPositions = () => {
    const count = positions.length;
    if (count === 0) return;
    setPositions([]);
    triggerNotification(
        language === 'en' ? 'All Positions Closed' : '全部持仓已平',
        language === 'en' 
          ? `Successfully closed all ${count} positions at market price.` 
          : `已成功以市价平掉所有当前持仓（共 ${count} 个）。`
    );
  };

  const totalUnrealizedPnL = positions.reduce((acc, pos) => acc + (pos.side === Side.LONG ? (currentPrice - pos.entryPrice) * pos.size : (pos.entryPrice - currentPrice) * pos.size), 0);
  const marginLocked = positions.reduce((acc, p) => acc + (p.marginMode === MarginMode.ISOLATED ? (p.isolatedMargin || 0) : (p.entryPrice * p.size / p.leverage)), 0);

  const equity = balance + marginLocked + totalUnrealizedPnL;

  const totalPosValue = positions.reduce((acc, pos) => acc + (pos.entryPrice * pos.size), 0);
  const maintenanceMargin = totalPosValue * 0.01; 
  const marginRatio = equity > 0 ? (maintenanceMargin / equity) * 100 : 0;

  return (
    <div className={`min-h-screen font-sans max-w-md mx-auto border-x shadow-2xl overflow-hidden relative ${theme === 'dark' ? 'bg-slate-900 border-slate-800 text-slate-100' : 'bg-slate-50 border-slate-200 text-slate-900'}`}>
      <NotificationOverlay notifications={notifications} onRemove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
      <Toast message={toast.message} visible={toast.visible} type={toast.type} />
      <main className="h-screen w-full">
        {activeTab === Tab.TRADE && (
          <TradeView 
            symbol={activeSymbol} 
            currentMarket={currentMarket} 
            onSymbolChange={handleSymbolChange} 
            candles={candles} 
            currentPrice={currentPrice} 
            balance={balance} 
            marketTrades={marketTrades} 
            onPlaceOrder={handlePlaceOrder} 
            lang={language} 
            timeframe={timeframe} 
            onTimeframeChange={setTimeframe} 
            positions={positions}
            orderConfirmationEnabled={orderConfirmationEnabled}
            setOrderConfirmationEnabled={setOrderConfirmationEnabled}
            isConnected={isWalletConnected}
            onDepositClick={() => {
              setAccountSubView('DEPOSIT');
              setActiveTab(Tab.ACCOUNT);
            }}
          />
        )}
        {activeTab === Tab.POSITIONS && (
          <PositionsView positions={positions} currentPrice={currentPrice} equity={equity} balance={balance} maintenanceMargin={maintenanceMargin} marginRatio={marginRatio} onClosePosition={handleClosePosition} onUpdateMargin={handleUpdateMargin} onCloseAllPositions={handleCloseAllPositions} lang={language} />
        )}
        {activeTab === Tab.ORDERS && (
          <OrdersView orders={orders} orderHistory={orderHistory} onCancelOrder={handleCancelOrder} onCancelAllOrders={handleCancelAllOrders} lang={language} />
        )}
        {activeTab === Tab.ACCOUNT && (
          <AccountView 
            balance={balance} 
            equity={equity} 
            unrealizedPnL={totalUnrealizedPnL} 
            totalPositionValue={totalPosValue} 
            externalWalletBalance={externalWalletBalance} 
            fillHistory={fillHistory} 
            transferHistory={transferHistory} 
            cashFlowHistory={cashFlowHistory} 
            onDeposit={handleDeposit} 
            onWithdraw={handleWithdraw} 
            isConnected={isWalletConnected} 
            onConnect={() => setIsWalletConnected(true)} 
            onDisconnect={() => setIsWalletConnected(false)} 
            language={language} 
            setLanguage={setLanguage} 
            theme={theme} 
            setTheme={setTheme} 
            positionMode={positionMode} 
            onSetPositionMode={setPositionMode}
            orderConfirmationEnabled={orderConfirmationEnabled}
            setOrderConfirmationEnabled={setOrderConfirmationEnabled}
            popupNotificationsEnabled={popupNotificationsEnabled}
            setPopupNotificationsEnabled={setPopupNotificationsEnabled}
            initialView={accountSubView}
            onViewChanged={(v) => {
              // 当进入具体页面后，重置请求状态，避免下次手动切换 Tab 时重复进入
              if (v === 'MAIN') setAccountSubView('MAIN');
            }}
          />
        )}
      </main>
      <BottomNav currentTab={activeTab} onTabChange={(tab) => {
        // 如果是手动切换到账户页，确保从主页开始
        if (tab === Tab.ACCOUNT) setAccountSubView('MAIN');
        setActiveTab(tab);
